		#region Create New Charge with Related Job Number

		public void TestCreateNewChargeWithRelatedJobNumberWhenImportingIntercompanyInvoiceChargeToGatewayJob()
		{
			CreateGatewayConsolWithShipments(out ForwardingShipment shipment1, out ForwardingShipment shipment2, out Job gatewayJob);

			var apInvoice = CreateAPInvoice("Z1000", Creditor1, AUD, 1m, "APINV1");
			apInvoice.IsConvertedFromARInvoice = true;

			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC1, AUD, 1m, "CC1 charge with shipment 1 related job", 10m, false, shipment1);
			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC1, AUD, 1m, "CC1 charge with shipment 1 related job", 30m, false, shipment1);
			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC2, AUD, 1m, "CC2 charge with shipment 1 related job", 50m, false, shipment1);

			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC1, AUD, 1m, "CC1 charge with shipment 2 related job", 20m, false, shipment2);
			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC1, AUD, 1m, "CC1 charge with shipment 2 related job", 40m, false, shipment2);
			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC2, AUD, 1m, "CC2 charge with shipment 2 related job", 60m, false, shipment2);

			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC1, AUD, 1m, "CC1 charge with empty related job", 70m, false, null);
			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC1, AUD, 1m, "CC1 charge with empty related job", 80m, false, null);
			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC2, AUD, 1m, "CC2 charge with empty related job", 90m, false, null);

			AssertEquals("Precondition : gateway Job should not have any charges", 0, gatewayJob.Charges.Count);

			GetTransformer(Factory).Transform(apInvoice);

			AssertEquals("Gateway job charge count", 9, gatewayJob.Charges.Count);

			var gatewayCharges = gatewayJob.Charges.Cast<Charge>().ToArray();
			var charge1 = AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 10m, 10m, ZGuid.Empty, AUD.RX_Code, 1m, 10m, 10m, true, false, shipment1.JS_UniqueConsignRef);
			AssertEquals(charge1.JR_AL_APLine, apInvoice.Lines[0].PK);

			var charge2 = AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 30m, 30m, ZGuid.Empty, AUD.RX_Code, 1m, 30m, 30m, true, false, shipment1.JS_UniqueConsignRef);
			AssertEquals(charge2.JR_AL_APLine, apInvoice.Lines[1].PK);

			var charge3 = AssertChargesContainsCharge(gatewayCharges, CC2.PK, Creditor1.PK, AUD.RX_Code, 1m, 50m, 50m, ZGuid.Empty, AUD.RX_Code, 1m, 50m, 50m, true, false, shipment1.JS_UniqueConsignRef);
			AssertEquals(charge3.JR_AL_APLine, apInvoice.Lines[2].PK);

			var charge4 = AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 20m, 20m, ZGuid.Empty, AUD.RX_Code, 1m, 20m, 20m, true, false, shipment2.JS_UniqueConsignRef);
			AssertEquals(charge4.JR_AL_APLine, apInvoice.Lines[3].PK);

			var charge5 = AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 40m, 40m, ZGuid.Empty, AUD.RX_Code, 1m, 40m, 40m, true, false, shipment2.JS_UniqueConsignRef);
			AssertEquals(charge5.JR_AL_APLine, apInvoice.Lines[4].PK);

			var charge6 = AssertChargesContainsCharge(gatewayCharges, CC2.PK, Creditor1.PK, AUD.RX_Code, 1m, 60m, 60m, ZGuid.Empty, AUD.RX_Code, 1m, 60m, 60m, true, false, shipment2.JS_UniqueConsignRef);
			AssertEquals(charge6.JR_AL_APLine, apInvoice.Lines[5].PK);

			var charge7 = AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 70m, 70m, ZGuid.Empty, AUD.RX_Code, 1m, 70m, 70m, true, false, ZString.Empty);
			AssertEquals(charge7.JR_AL_APLine, apInvoice.Lines[6].PK);

			var charge8 = AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 80m, 80m, ZGuid.Empty, AUD.RX_Code, 1m, 80m, 80m, true, false, ZString.Empty);
			AssertEquals(charge8.JR_AL_APLine, apInvoice.Lines[7].PK);

			var charge9 = AssertChargesContainsCharge(gatewayCharges, CC2.PK, Creditor1.PK, AUD.RX_Code, 1m, 90m, 90m, ZGuid.Empty, AUD.RX_Code, 1m, 90m, 90m, true, false, ZString.Empty);
			AssertEquals(charge9.JR_AL_APLine, apInvoice.Lines[8].PK);
		}

