		#region Find Associated Charge With Related Job Number

		public void TestFindAssociatedCharge_MatchWithRelatedJobNumberWhenImportingIntercompanyInvoiceChargeToGatewayJob_NoCarryForwardAmount_MatchingChargeExists()
		{
			CreateGatewayConsolWithShipments(out ForwardingShipment shipment1, out ForwardingShipment shipment2, out Job gatewayJob);

			CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with shipment 1 related job", AUD, 10m, Creditor1, AUD, 10m, TestObjectCreator.DebtorSisterOrgProxy, shipment1);
			CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with shipment 2 related job", AUD, 10m, Creditor1, AUD, 10m, TestObjectCreator.DebtorSisterOrgProxy, shipment2);
			CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with empty related job", AUD, 10m, Creditor1, AUD, 10m, TestObjectCreator.DebtorSisterOrgProxy, null);

			CreateChargeWithRelatedJob(gatewayJob, CC2, "CC2 charge with shipment 1 related job", AUD, 20m, Creditor1, AUD, 20m, TestObjectCreator.DebtorSisterOrgProxy, shipment1);
			CreateChargeWithRelatedJob(gatewayJob, CC2, "CC2 charge with shipment 2 related job", AUD, 20m, Creditor1, AUD, 20m, TestObjectCreator.DebtorSisterOrgProxy, shipment2);
			CreateChargeWithRelatedJob(gatewayJob, CC2, "CC2 charge with empty related job", AUD, 20m, Creditor1, AUD, 20m, TestObjectCreator.DebtorSisterOrgProxy, null);

			CreateChargeWithRelatedJob(gatewayJob, CC3, "CC3 charge with shipment 1 related job", AUD, 30m, Creditor1, AUD, 30m, TestObjectCreator.DebtorSisterOrgProxy, shipment1);
			CreateChargeWithRelatedJob(gatewayJob, CC3, "CC3 charge with shipment 2 related job", AUD, 30m, Creditor1, AUD, 30m, TestObjectCreator.DebtorSisterOrgProxy, shipment2);
			CreateChargeWithRelatedJob(gatewayJob, CC3, "CC3 charge with empty related job", AUD, 30m, Creditor1, AUD, 30m, TestObjectCreator.DebtorSisterOrgProxy, null);
			Factory.Save();

			var apInvoice = CreateAPInvoice("Z1000", Creditor1, AUD, 1m, "APINV1");
			apInvoice.IsConvertedFromARInvoice = true;

			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC1, AUD, 1m, "CC1 invoice line with shipment 1 related job", 10m, false, shipment1);
			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC2, AUD, 1m, "CC2 invoice line with shipment 2 related job", 20m, false, shipment2);
			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC3, AUD, 1m, "CC3 invoice line with empty related job", 30m, false, null);

			Assert("Precondition : All gateway job charges are not posted and in database.", gatewayJob.Charges.Cast<Charge>().All(x => !x.IsCostPosted && x.IsInDatabase));

			GetTransformer(Factory).Transform(apInvoice);

			var gatewayCharges = gatewayJob.Charges.Cast<Charge>().ToArray();
			Assert("Postcondition : No new charges created for Gateway job", gatewayCharges.All(x => x.IsInDatabase));
			var charge1 = AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 10m, 10m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 10m, 10m, true, false, shipment1.JS_UniqueConsignRef);
			AssertEquals(charge1.JR_AL_APLine, apInvoice.Lines[0].PK);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 10m, 10m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 10m, 10m, false, false, shipment2.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 10m, 10m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 10m, 10m, false, false, ZString.Empty);

			AssertChargesContainsCharge(gatewayCharges, CC2.PK, Creditor1.PK, AUD.RX_Code, 1m, 20m, 20m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 20m, 20m, false, false, shipment1.JS_UniqueConsignRef);
			var charge2 = AssertChargesContainsCharge(gatewayCharges, CC2.PK, Creditor1.PK, AUD.RX_Code, 1m, 20m, 20m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 20m, 20m, true, false, shipment2.JS_UniqueConsignRef);
			AssertEquals(charge2.JR_AL_APLine, apInvoice.Lines[1].PK);
			AssertChargesContainsCharge(gatewayCharges, CC2.PK, Creditor1.PK, AUD.RX_Code, 1m, 20m, 20m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 20m, 20m, false, false, ZString.Empty);

			AssertChargesContainsCharge(gatewayCharges, CC3.PK, Creditor1.PK, AUD.RX_Code, 1m, 30m, 30m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 30m, 30m, false, false, shipment1.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC3.PK, Creditor1.PK, AUD.RX_Code, 1m, 30m, 30m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 30m, 30m, false, false, shipment2.JS_UniqueConsignRef);
			var charge3 = AssertChargesContainsCharge(gatewayCharges, CC3.PK, Creditor1.PK, AUD.RX_Code, 1m, 30m, 30m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 30m, 30m, true, false, ZString.Empty);
			AssertEquals(charge3.JR_AL_APLine, apInvoice.Lines[2].PK);
		}

		public void TestFindAssociatedCharge_MatchWithRelatedJobNumberWhenImportingIntercompanyInvoiceChargeToGatewayJob_NoCarryForwardAmount_MatchingChargeDoesNotExist()
		{
			CreateGatewayConsolWithShipments(out ForwardingShipment shipment1, out ForwardingShipment shipment2, out Job gatewayJob);

			CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with shipment 2 related job", AUD, 10m, Creditor1, AUD, 10m, TestObjectCreator.DebtorSisterOrgProxy, shipment2);
			CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with empty related job", AUD, 10m, Creditor1, AUD, 10m, TestObjectCreator.DebtorSisterOrgProxy, null);

			CreateChargeWithRelatedJob(gatewayJob, CC2, "CC2 charge with shipment 1 related job", AUD, 20m, Creditor1, AUD, 20m, TestObjectCreator.DebtorSisterOrgProxy, shipment1);
			CreateChargeWithRelatedJob(gatewayJob, CC2, "CC2 charge with empty related job", AUD, 20m, Creditor1, AUD, 20m, TestObjectCreator.DebtorSisterOrgProxy, null);

			CreateChargeWithRelatedJob(gatewayJob, CC3, "CC3 charge with shipment 1 related job", AUD, 30m, Creditor1, AUD, 30m, TestObjectCreator.DebtorSisterOrgProxy, shipment1);
			CreateChargeWithRelatedJob(gatewayJob, CC3, "CC3 charge with shipment 2 related job", AUD, 30m, Creditor1, AUD, 30m, TestObjectCreator.DebtorSisterOrgProxy, shipment2);

			Factory.Save();

			var apInvoice = CreateAPInvoice("Z1000", Creditor1, AUD, 1m, "APINV1");
			apInvoice.IsConvertedFromARInvoice = true;

			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC1, AUD, 1m, "CC1 charge with shipment 1 related job", 10m, false, shipment1);
			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC2, AUD, 1m, "CC2 charge with shipment 2 related job", 20m, false, shipment2);
			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC3, AUD, 1m, "CC3 charge with empty related job", 30m, false, null);

			var gatewayCharges = gatewayJob.Charges.Cast<Charge>().ToArray();
			AssertEquals("Precondition : gateway job charge count", 6, gatewayCharges.Length);
			Assert("Precondition : matching charge does not exist for CC1 + shipment 1 related job", !gatewayCharges.Any(x => x.ChargeCode == CC1 && x.JR_Calc_RelatedJobNumber == shipment1.JS_UniqueConsignRef));
			Assert("Precondition : matching charge does not exist for CC2 + shipment 2 related job", !gatewayCharges.Any(x => x.ChargeCode == CC2 && x.JR_Calc_RelatedJobNumber == shipment2.JS_UniqueConsignRef));
			Assert("Precondition : matching charge does not exist for CC3 + empty related job", !gatewayCharges.Any(x => x.ChargeCode == CC3 && x.JR_Calc_RelatedJobNumber == ZString.Empty));

			GetTransformer(Factory).Transform(apInvoice);

			gatewayCharges = gatewayJob.Charges.Cast<Charge>().ToArray();
			AssertEquals("Postcondition : gateway job charge count (should include three new charges)", 9, gatewayCharges.Length);
			var charge1 = AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 10m, 10m, ZGuid.Empty, AUD.RX_Code, 1m, 10m, 10m, true, false, shipment1.JS_UniqueConsignRef);
			AssertEquals(charge1.JR_AL_APLine, apInvoice.Lines[0].PK);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 10m, 10m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 10m, 10m, false, false, shipment2.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 10m, 10m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 10m, 10m, false, false, ZString.Empty);

			AssertChargesContainsCharge(gatewayCharges, CC2.PK, Creditor1.PK, AUD.RX_Code, 1m, 20m, 20m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 20m, 20m, false, false, shipment1.JS_UniqueConsignRef);
			var charge2 = AssertChargesContainsCharge(gatewayCharges, CC2.PK, Creditor1.PK, AUD.RX_Code, 1m, 20m, 20m, ZGuid.Empty, AUD.RX_Code, 1m, 20m, 20m, true, false, shipment2.JS_UniqueConsignRef);
			AssertEquals(charge2.JR_AL_APLine, apInvoice.Lines[1].PK);
			AssertChargesContainsCharge(gatewayCharges, CC2.PK, Creditor1.PK, AUD.RX_Code, 1m, 20m, 20m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 20m, 20m, false, false, ZString.Empty);

			AssertChargesContainsCharge(gatewayCharges, CC3.PK, Creditor1.PK, AUD.RX_Code, 1m, 30m, 30m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 30m, 30m, false, false, shipment1.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC3.PK, Creditor1.PK, AUD.RX_Code, 1m, 30m, 30m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 30m, 30m, false, false, shipment2.JS_UniqueConsignRef);
			var charge3 = AssertChargesContainsCharge(gatewayCharges, CC3.PK, Creditor1.PK, AUD.RX_Code, 1m, 30m, 30m, ZGuid.Empty, AUD.RX_Code, 1m, 30m, 30m, true, false, ZString.Empty);
			AssertEquals(charge3.JR_AL_APLine, apInvoice.Lines[2].PK);
		}

