		#region Create Carry Forward Charge with Related Job Number

		public void TestCreateCarryForwardChargeWithRelatedJobNumber_SingleMatchingChargeExists_CarryForwardAmountGreaterThanZero_CanNotApplyNegativeAccrualBehaviour()
		{
			CreateGatewayConsolWithShipments(out ForwardingShipment shipment1, out ForwardingShipment shipment2, out Job gatewayJob);

			CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with shipment 1 related job", AUD, 30m, Creditor1, AUD, 10m, TestObjectCreator.DebtorSisterOrgProxy, shipment1);
			CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with shipment 2 related job", AUD, 50m, Creditor1, AUD, 10m, TestObjectCreator.DebtorSisterOrgProxy, shipment2);
			CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with empty related job", AUD, 70m, Creditor1, AUD, 10m, TestObjectCreator.DebtorSisterOrgProxy, null);
			Factory.Save();

			var apInvoice = CreateAPInvoice("Z1000", Creditor1, AUD, 1m, "APINV1");
			apInvoice.IsConvertedFromARInvoice = true;

			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC1, AUD, 1m, "CC1 invoice line with shipment 1 related job", 10m, false, shipment1); //carry forward amount = 30 - 10 = 20
			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC1, AUD, 1m, "CC1 invoice line with shipment 2 related job", 20m, false, shipment2); //carry forward amount = 50 - 20 = 30
			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC1, AUD, 1m, "CC1 invoice line with empty related job", 30m, false, null); //carry forward amount = 70 - 30 = 40

			AssertEquals("Precondition : gateway job charge count", 3, gatewayJob.Charges.Count);

			using (AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetTemporaryValue(Env.CurrentCompanyPK, Guid.Empty, Guid.Empty, false))
			{
				GetTransformer(Factory).Transform(apInvoice);
			}

			AssertEquals("Postcondition : gateway job charge count", 6, gatewayJob.Charges.Count);

			var gatewayCharges = gatewayJob.Charges.Cast<Charge>().ToArray();
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 10m, 10m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 10m, 10m, true, false, shipment1.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 20m, 20m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 10m, 10m, true, false, shipment2.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 30m, 30m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 10m, 10m, true, false, ZString.Empty);

			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 20m, 20m, ZGuid.Empty, AUD.RX_Code, 1m, 0m, 0m, false, false, shipment1.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 30m, 30m, ZGuid.Empty, AUD.RX_Code, 1m, 0m, 0m, false, false, shipment2.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 40m, 40m, ZGuid.Empty, AUD.RX_Code, 1m, 0m, 0m, false, false, ZString.Empty);
		}

		public void TestCreateCarryForwardChargeWithRelatedJobNumber_SingleMatchingChargeExists_CarryForwardAmountLessThanZero_CanApplyNegativeAccrualBehaviour()
		{
			CreateGatewayConsolWithShipments(out ForwardingShipment shipment1, out ForwardingShipment shipment2, out Job gatewayJob);

			CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with shipment 1 related job", AUD, -30m, Creditor1, AUD, 10m, TestObjectCreator.DebtorSisterOrgProxy, shipment1);
			CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with shipment 2 related job", AUD, -50m, Creditor1, AUD, 10m, TestObjectCreator.DebtorSisterOrgProxy, shipment2);
			CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with empty related job", AUD, -70m, Creditor1, AUD, 10m, TestObjectCreator.DebtorSisterOrgProxy, null);
			Factory.Save();

			var apCreditNote = CreateAPCreditNote("Z1000", Creditor1, AUD, 1m, "APCRD1");
			apCreditNote.IsConvertedFromARInvoice = true;

			CreateAPCreditNoteLineWithRelatedJobNumber(apCreditNote, gatewayJob, CC1, AUD, 1m, "CC1 credit note line with shipment 1 related job", 10m, false, shipment1); //carry forward amount = (-30) - (-10) = -20
			CreateAPCreditNoteLineWithRelatedJobNumber(apCreditNote, gatewayJob, CC1, AUD, 1m, "CC1 credit note line with shipment 2 related job", 20m, false, shipment2); //carry forward amount = (-50) - (-20) = -30
			CreateAPCreditNoteLineWithRelatedJobNumber(apCreditNote, gatewayJob, CC1, AUD, 1m, "CC1 credit note line with empty related job", 30m, false, null); //carry forward amount = (-70) - (-30) = -40

			AssertEquals("Precondition : gateway job charge count", 3, gatewayJob.Charges.Count);

			using (AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetTemporaryValue(Env.CurrentCompanyPK, Guid.Empty, Guid.Empty, true))
			{
				GetTransformer(Factory).Transform(apCreditNote);
			}

			AssertEquals("Postcondition : gateway job charge count", 6, gatewayJob.Charges.Count);

			var gatewayCharges = gatewayJob.Charges.Cast<Charge>().ToArray();
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, -10m, -10m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 10m, 10m, true, false, shipment1.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, -20m, -20m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 10m, 10m, true, false, shipment2.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, -30m, -30m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 10m, 10m, true, false, ZString.Empty);

			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, -20m, -20m, ZGuid.Empty, AUD.RX_Code, 1m, 0m, 0m, false, false, shipment1.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, -30m, -30m, ZGuid.Empty, AUD.RX_Code, 1m, 0m, 0m, false, false, shipment2.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, -40m, -40m, ZGuid.Empty, AUD.RX_Code, 1m, 0m, 0m, false, false, ZString.Empty);
		}

		public void TestCreateCarryForwardChargeWithRelatedJobNumber_SingleMatchingChargeExists_CarryForwardAmountLessThanZero_CanNotApplyNegativeAccrualBehaviour_CreateWIPWhenCostIsGreaterThanAccrualRegistryIsOn_MatchingChargeRevenueIsPosted()
		{
			CreateGatewayConsolWithShipments(out ForwardingShipment shipment1, out ForwardingShipment shipment2, out Job gatewayJob);

