		void AssertAmountWrapperIsOnlyOneOSCurrencyAndRateCheckDoNotConsiderRelatedJobNumberWhenNotImportingIntercompanyInvoice(bool isImportingIntercompanyInvoice)
		{
			CreateGatewayConsolWithShipments(out ForwardingShipment shipment1, out ForwardingShipment shipment2, out Job gatewayJob);

			var exchangeRateForUSD = 0.25m;
			TestObjectCreator.CreateExchangeRate(gatewayJob, USD, exchangeRateForUSD);
			Factory.Save();

			var charge1 = CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with shipment 1 related job", USD, 30m, Creditor1, AUD, 10m, TestObjectCreator.DebtorSisterOrgProxy, shipment1);
			var charge2 = CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with shipment 2 related job", AUD, 50m, Creditor1, AUD, 10m, TestObjectCreator.DebtorSisterOrgProxy, shipment2);
			CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with empty related job", USD, 70m, Creditor1, AUD, 10m, TestObjectCreator.DebtorSisterOrgProxy, null);
			Factory.Save();

			var apInvoice = CreateAPInvoice("Z1000", Creditor1, AUD, 1m, "APINV1");
			apInvoice.IsConvertedFromARInvoice = isImportingIntercompanyInvoice;
			if (isImportingIntercompanyInvoice)
			{
				CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC1, USD, exchangeRateForUSD, "CC1 invoice line with shipment 1 related job", 10m, false, shipment1);
				CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC1, AUD, 1m, "CC1 invoice line with shipment 2 related job", 20m, false, shipment2);
			}
			else
			{
				var invoiceLine1 = (InvoicingLineBase)apInvoice.Lines.AddNew();
				apInvoice.ImportJobChargesIntoInvoice(new[] { charge1, charge2 }, invoiceLine1, false);
				var invoiceLine2 = apInvoice.Lines[1];
				AssertNotNull(invoiceLine1);
				AssertNotNull(invoiceLine2);
				invoiceLine1.AL_OSExTaxAmount = 10m;
				invoiceLine2.AL_OSExTaxAmount = 20m;
			}
			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC1, USD, exchangeRateForUSD, "CC1 invoice line with empty related job", 30m, false, null);

			AssertEquals("Precondition : gateway job charge count", 3, gatewayJob.Charges.Count);

			GetTransformer(Factory).Transform(apInvoice);

			AssertEquals("Postcondition : gateway job charge count", 6, gatewayJob.Charges.Count);

			var gatewayCharges = gatewayJob.Charges.Cast<Charge>().ToArray();
			//carry forward amount in USD = (-30) - (-10) = -20
			//carry forward amount in AUD = 50 - 20 = 30
			//carry forward amount in USD = (-70) - (-30) = -40
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, USD.RX_Code, exchangeRateForUSD, 10m, 40m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 10m, 10m, true, false, shipment1.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 20m, 20m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 10m, 10m, true, false, shipment2.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, USD.RX_Code, exchangeRateForUSD, 30m, 120m, TestObjectCreator.DebtorSisterOrgProxy.PK, AUD.RX_Code, 1m, 10m, 10m, true, false, ZString.Empty);

			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, USD.RX_Code, exchangeRateForUSD, 20m, 80m, ZGuid.Empty, USD.RX_Code, exchangeRateForUSD, 0m, 0m, false, false, shipment1.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 30m, 30m, ZGuid.Empty, AUD.RX_Code, 1m, 0m, 0m, false, false, shipment2.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, USD.RX_Code, exchangeRateForUSD, 40m, 160m, ZGuid.Empty, USD.RX_Code, exchangeRateForUSD, 0m, 0m, false, false, ZString.Empty);
		}

