		public void TestInvoicingLineCacheUtilityInitialization()
		{
			var chargeCodePK = TestObjectCreator.CC1.PK;
			var job = TestObjectCreator.CreateJob(TestObjectCreator.Creditor1, 0m, null, 0m);
			Factory.Save();

			var jobCharge = Factory.New<Charge>();
			jobCharge.JR_JH = job.PK;
			jobCharge.JR_AC = chargeCodePK;
			jobCharge.JR_RX_NKCostCurrency = "USD";
			jobCharge.JR_OSCostAmt = 10m;
			jobCharge.JR_LocalCostAmt = 100m;
			jobCharge.JR_OSCostExRate = 0.1m;
			Factory.Save();

			var invoice = TestObjectCreator.CreateAPInvoice<APInvoice>("000001", TestObjectCreator.AUD, 1m, 10m, 0m, 0m, 10m, 0m, 0m, TestObjectCreator.Creditor1);
			var invoiceLineAUD = invoice.Lines[0];
			invoiceLineAUD.AL_AC = chargeCodePK;
			invoiceLineAUD.AL_JH = job.PK;

			var transformer = GetTransformer(Factory);
			var invoicingLineCacheUtility = new Mock<IInvoicingLineCacheUtility>();
			var counter = 0;
			invoicingLineCacheUtility
				.Setup(x => x.GenerateInvoicingLineCache(It.IsAny<IEnumerable<InvoicingLineBase>>()))
				.Callback(() =>
				{
					AssertEquals(0, counter++);
				});
			invoicingLineCacheUtility
				.Setup(x => x.ValidateInvoicingLineCache(It.IsAny<IEnumerable<InvoicingLineBase>>()))
				.Callback(() =>
				{
					AssertEquals(1, counter++);
				});
			Factory.ServiceContainer.RemoveService<IInvoicingLineCacheUtility>();
			Factory.ServiceContainer.AddService(invoicingLineCacheUtility.Object);
			transformer.Transform(invoice);
			AssertEquals(2, counter);
		}

		public void TestInvoiceLineHaveDifferentCurrencyOrExchangeRate()
		{
			AccountingConfigurationRegistry.Instance.EnablePostTransactionCalculatedPropertyCache.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);
			AssertInvoiceLineHaveDifferentCurrencyOrExchangeRate("0000001");

			AccountingConfigurationRegistry.Instance.EnablePostTransactionCalculatedPropertyCache.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, false);
			AssertInvoiceLineHaveDifferentCurrencyOrExchangeRate("0000002");
		}

		void AssertInvoiceLineHaveDifferentCurrencyOrExchangeRate(string invoiceNumber)
		{
			var invoicingLineCacheUtility = new InvoicingLineCacheUtility();

			var chargeCodePK1 = TestObjectCreator.CC1.PK;
			var chargeCodePK2 = TestObjectCreator.CC2.PK;
			var job1 = TestObjectCreator.CreateJob(TestObjectCreator.Creditor1, 0m, null, 0m);
			var job2 = TestObjectCreator.CreateJob(TestObjectCreator.Creditor1, 0m, null, 0m);

			var invoice = TestObjectCreator.CreateAPInvoice<APInvoice>(invoiceNumber, TestObjectCreator.AUD, 1m, 10m, 0m, 0m, 10m, 0m, 0m, TestObjectCreator.Creditor1);

			var invoiceLineUSD1 = invoice.Lines[0];
			InitializeInvoiceLine(invoiceLineUSD1, Env.CurrentBranchPK, Env.CurrentDepartmentPK, chargeCodePK1, job1.PK, "USD", 0.5m);
			var invoiceLineRON1 = invoice.Lines.AddNew() as InvoicingLineBase;
			InitializeInvoiceLine(invoiceLineRON1, Env.CurrentBranchPK, Env.CurrentDepartmentPK, chargeCodePK1, job1.PK, "RON", 0.5m);

			var invoiceLineUSD2 = invoice.Lines.AddNew() as InvoicingLineBase;
			InitializeInvoiceLine(invoiceLineUSD2, Env.CurrentBranchPK, Env.CurrentDepartmentPK, chargeCodePK2, job1.PK, "USD", 0.5m);
			var invoiceLineUSD3 = invoice.Lines.AddNew() as InvoicingLineBase;
			InitializeInvoiceLine(invoiceLineUSD3, Env.CurrentBranchPK, Env.CurrentDepartmentPK, chargeCodePK2, job1.PK, "USD", 0.1m);

			var invoiceLineUSD4 = invoice.Lines.AddNew() as InvoicingLineBase;
			InitializeInvoiceLine(invoiceLineUSD4, Env.CurrentBranchPK, Env.CurrentDepartmentPK, chargeCodePK2, job2.PK, "USD", 0.5m);

			invoicingLineCacheUtility.GenerateInvoicingLineCache(invoice.Lines.OfType<InvoicingLineBase>());
			Factory.ServiceContainer.AddService<IInvoicingLineCacheUtility>(invoicingLineCacheUtility);

			AssertEquals("True due to Currency is different.", true, TransactionLineJobChargeTransformer.AmountWrapper.DoesAnyInvoiceLineHaveDifferentCurrencyOrExchangeRate_ForTestOnly(invoiceLineUSD1));
			AssertEquals("True due to Currency is different.", true, TransactionLineJobChargeTransformer.AmountWrapper.DoesAnyInvoiceLineHaveDifferentCurrencyOrExchangeRate_ForTestOnly(invoiceLineRON1));

			AssertEquals("True due to Exchange Rate is different.", true, TransactionLineJobChargeTransformer.AmountWrapper.DoesAnyInvoiceLineHaveDifferentCurrencyOrExchangeRate_ForTestOnly(invoiceLineUSD2));
			AssertEquals("True due to Exchange Rate is different.", true, TransactionLineJobChargeTransformer.AmountWrapper.DoesAnyInvoiceLineHaveDifferentCurrencyOrExchangeRate_ForTestOnly(invoiceLineUSD3));

			AssertEquals("False due to no any other Invoice in same group have different Exchange Rate or Currency.",
				false, TransactionLineJobChargeTransformer.AmountWrapper.DoesAnyInvoiceLineHaveDifferentCurrencyOrExchangeRate_ForTestOnly(invoiceLineUSD4));
		}

