		void AssertNoInvoiceLineHaveDifferentCurrencyOrExchangeRate(string invoiceNumber)
		{
			var invoicingLineCacheUtility = (new InvoicingLineCacheUtility()) as IInvoicingLineCacheUtility;

			var chargeCodePK1 = TestObjectCreator.CC1.PK;
			var chargeCodePK2 = TestObjectCreator.CC2.PK;
			var job1 = TestObjectCreator.CreateJob(TestObjectCreator.Creditor1, 0m, null, 0m);
			var job2 = TestObjectCreator.CreateJob(TestObjectCreator.Creditor1, 0m, null, 0m);

			var invoice = TestObjectCreator.CreateAPInvoice<APInvoice>(invoiceNumber, TestObjectCreator.AUD, 1m, 10m, 0m, 0m, 10m, 0m, 0m, TestObjectCreator.Creditor1);

			var invoiceLineUSD = invoice.Lines[0];
			InitializeInvoiceLine(invoiceLineUSD, Env.CurrentBranchPK, Env.CurrentDepartmentPK, chargeCodePK1, job1.PK, "USD", 0.5m);

			var invoiceLineUSDWithEmptyChargeCode = invoice.Lines.AddNew() as InvoicingLineBase;
			InitializeInvoiceLine(invoiceLineUSDWithEmptyChargeCode, Env.CurrentBranchPK, Env.CurrentDepartmentPK, ZGuid.Empty, job1.PK, "RON", 0.5m);

			var invoiceLineRON1 = invoice.Lines.AddNew() as InvoicingLineBase;
			InitializeInvoiceLine(invoiceLineRON1, Env.CurrentBranchPK, Env.CurrentDepartmentPK, chargeCodePK2, job1.PK, "RON", 0.5m);

			var invoiceLineRON2 = invoice.Lines.AddNew() as InvoicingLineBase;
			InitializeInvoiceLine(invoiceLineRON2, TestObjectCreator.NonCurrentBranch.PK, Env.CurrentDepartmentPK, chargeCodePK1, job1.PK, "RON", 0.5m);

			var invoiceLineRON3 = invoice.Lines.AddNew() as InvoicingLineBase;
			InitializeInvoiceLine(invoiceLineRON3, Env.CurrentBranchPK, TestObjectCreator.NonCurrentDepartment.PK, chargeCodePK1, job1.PK, "RON", 0.5m);

			var invoiceLineRON4 = invoice.Lines.AddNew() as InvoicingLineBase;
			InitializeInvoiceLine(invoiceLineRON4, Env.CurrentBranchPK, Env.CurrentDepartmentPK, chargeCodePK2, job2.PK, "RON", 0.5m);

			var charge = Factory.New<Charge>();
			var jobChargeTarget = Factory.New<JobChargeTarget>();
			jobChargeTarget.JRT_JR = charge.PK;
			jobChargeTarget.JRT_RelatedJobID = job2.PK;
			var invoiceLineRON5 = invoice.Lines.AddNew() as InvoicingLineBase;
			InitializeInvoiceLine(invoiceLineRON5, Env.CurrentBranchPK, Env.CurrentDepartmentPK, chargeCodePK2, job1.PK, "RON", 0.5m);
			invoiceLineRON5.OriginalJobCharge = charge;

			invoicingLineCacheUtility.GenerateInvoicingLineCache(invoice.Lines.OfType<InvoicingLineBase>());
			var resultMap = invoicingLineCacheUtility.InvoicingLineCache;
			Factory.ServiceContainer.AddService(invoicingLineCacheUtility);

			AssertEquals("False due to Charge Code is empty.", false, TransactionLineJobChargeTransformer.AmountWrapper.DoesAnyInvoiceLineHaveDifferentCurrencyOrExchangeRate_ForTestOnly(invoiceLineUSD));
			AssertEquals("False due to Charge Code is empty.", false, TransactionLineJobChargeTransformer.AmountWrapper.DoesAnyInvoiceLineHaveDifferentCurrencyOrExchangeRate_ForTestOnly(invoiceLineUSDWithEmptyChargeCode));

			AssertNotEquals(resultMap[invoiceLineUSD.PK].ChargeCodePK, resultMap[invoiceLineRON1.PK].ChargeCodePK);
			AssertEquals("False due to Charge Code is different.", false, TransactionLineJobChargeTransformer.AmountWrapper.DoesAnyInvoiceLineHaveDifferentCurrencyOrExchangeRate_ForTestOnly(invoiceLineRON1));

			AssertNotEquals(resultMap[invoiceLineUSD.PK].BranchPK, resultMap[invoiceLineRON2.PK].BranchPK);
			AssertEquals("False due to Branch is different.", false, TransactionLineJobChargeTransformer.AmountWrapper.DoesAnyInvoiceLineHaveDifferentCurrencyOrExchangeRate_ForTestOnly(invoiceLineRON2));

			AssertNotEquals(resultMap[invoiceLineUSD.PK].DepartmentPK, resultMap[invoiceLineRON3.PK].DepartmentPK);
			AssertEquals("False due to Department is different.", false, TransactionLineJobChargeTransformer.AmountWrapper.DoesAnyInvoiceLineHaveDifferentCurrencyOrExchangeRate_ForTestOnly(invoiceLineRON3));

			AssertNotEquals(resultMap[invoiceLineUSD.PK].JobPK, resultMap[invoiceLineRON4.PK].JobPK);
			AssertEquals("False due to Job is different.", false, TransactionLineJobChargeTransformer.AmountWrapper.DoesAnyInvoiceLineHaveDifferentCurrencyOrExchangeRate_ForTestOnly(invoiceLineRON4));

			AssertNotEquals(resultMap[invoiceLineUSD.PK].RelatedJobPK, resultMap[invoiceLineRON5.PK].RelatedJobPK);
			AssertEquals("False due to Related Job is different.", false, TransactionLineJobChargeTransformer.AmountWrapper.DoesAnyInvoiceLineHaveDifferentCurrencyOrExchangeRate_ForTestOnly(invoiceLineRON5));
		}

		void InitializeInvoiceLine(InvoicingLineBase invoiceLine, ZGuid branchPK, ZGuid departmentPK, ZGuid chargeCodePK, ZGuid jobPK, ZString currency, ZDecimal exRate)
		{
			invoiceLine.AL_JH = jobPK;
			invoiceLine.AL_GB = branchPK;
			invoiceLine.AL_GE = departmentPK;
			invoiceLine.AL_AC = chargeCodePK;
			invoiceLine.AL_RX_NKTransactionCurrency = currency;
			invoiceLine.AL_ExchangeRate = exRate;
		}

