		void AssertAssociatedChargeFilterContainsRelatedJobNumberFilter(bool isImportingIntercompanyInvoice)
		{
			CreateGatewayConsolWithShipments(out ForwardingShipment shipment1, out ForwardingShipment shipment2, out Job gatewayJob);

			var chargeWithShipment1RelatedJob = CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with shipment 1 related job", AUD, 10m, Creditor1, AUD, 10m, TestObjectCreator.DebtorSisterOrgProxy, shipment1);
			var chargeWithShipment2RelatedJob = CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with shipment 2 related job", AUD, 10m, Creditor1, AUD, 10m, TestObjectCreator.DebtorSisterOrgProxy, shipment2);
			var chargeWithEmptyRelatedJob = CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with empty related job", AUD, 10m, Creditor1, AUD, 10m, TestObjectCreator.DebtorSisterOrgProxy, null);
			Factory.Save();

			var apInvoice1 = CreateAPInvoice("Z1000", Creditor1, AUD, 1m, "APINV1");
			apInvoice1.IsConvertedFromARInvoice = isImportingIntercompanyInvoice;
			if (isImportingIntercompanyInvoice)
			{
				CreateAPInvoiceLineWithRelatedJob(apInvoice1, gatewayJob, CC1, AUD, 1m, "CC1 invoice line with shipment 1 related job", 10m, false, shipment1);
			}
			else
			{
				var invoiceLine = (InvoicingLineBase)apInvoice1.Lines.AddNew();
				apInvoice1.ImportJobChargesIntoInvoice(new[] { chargeWithShipment1RelatedJob }, invoiceLine, false);
				AssertNotNull(invoiceLine);
			}
			AssertChargesToSearch(apInvoice1, new[] { chargeWithShipment1RelatedJob.PK });

			var apInvoice2 = CreateAPInvoice("Z1001", Creditor1, AUD, 1m, "APINV2");
			apInvoice2.IsConvertedFromARInvoice = isImportingIntercompanyInvoice;
			CreateAPInvoiceLineWithRelatedJob(apInvoice2, gatewayJob, CC1, AUD, 1m, "CC1 invoice line with empty related job", 10m, false, null);
			AssertChargesToSearch(apInvoice2, new[] { chargeWithEmptyRelatedJob.PK });

			var apInvoice3 = CreateAPInvoice("Z1003", Creditor1, AUD, 1m, "APINV3");
			apInvoice3.IsConvertedFromARInvoice = isImportingIntercompanyInvoice;
			if (isImportingIntercompanyInvoice)
			{
				CreateAPInvoiceLineWithRelatedJob(apInvoice3, gatewayJob, CC1, AUD, 1m, "CC1 invoice line with shipment 1 related job", 10m, false, shipment1);
				CreateAPInvoiceLineWithRelatedJob(apInvoice3, gatewayJob, CC1, AUD, 1m, "CC1 invoice line with shipment 2 related job", 10m, false, shipment2);
			}
			else
			{
				var invoiceLine1 = (InvoicingLineBase)apInvoice3.Lines.AddNew();
				apInvoice3.ImportJobChargesIntoInvoice(new[] { chargeWithShipment1RelatedJob, chargeWithShipment2RelatedJob }, invoiceLine1, false);
				var invoiceLine2 = apInvoice3.Lines[1];
				AssertNotNull(invoiceLine1);
				AssertNotNull(invoiceLine2);
			}
			CreateAPInvoiceLineWithRelatedJob(apInvoice3, gatewayJob, CC1, AUD, 1m, "CC1 invoice line with empty related job", 10m, false, null);
			AssertChargesToSearch(apInvoice3, new[] { chargeWithShipment1RelatedJob.PK, chargeWithShipment2RelatedJob.PK, chargeWithEmptyRelatedJob.PK });
		}

		void AssertChargesToSearch(APInvoice invoice, IEnumerable<ZGuid> expectedChargePks)
		{
			var consolCostsToSearch = new ConsolCostListWithStrategy(ConsolCostStrategy.ConsolCostCalculationStrategyWithoutCalculations);
			var chargesToSearch = new TransactionLineJobChargeTransformer.ChargesByPK();
			AssertEquals(0, chargesToSearch.Charges.Count());
			TransactionLineJobChargeTransformer.PopulateCostsAndChargesToSearch(new BusinessObjectFactory(), invoice, chargesToSearch, consolCostsToSearch, null);
			AssertContainsExactElementsInAnyOrder(expectedChargePks, chargesToSearch.Charges.Select(x => x.PK));
		}

