		public void TestCreateWIPWithRelatedJobNumber_SingleMatchingChargeExists_EnableNegativeAccrualBehaviourRegistryOn_CarryForwardAmountNotZero_MatchingChargeCostIsZeroAndRevenuePosted_IsNotFinal()
		{
			CreateGatewayConsolWithShipments(out ForwardingShipment shipment1, out ForwardingShipment shipment2, out Job gatewayJob);
			CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with shipment 1 related job", AUD, 0m, Creditor1, AUD, 100m, TestObjectCreator.Debtor1, shipment1);
			CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with shipment 2 related job", AUD, 0m, Creditor1, AUD, 200m, TestObjectCreator.Debtor1, shipment2);
			CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with empty related job", AUD, 0m, Creditor1, AUD, 300m, TestObjectCreator.Debtor1, null);
			Factory.Save();

			PostChargeRevenues(gatewayJob);

			var apInvoice = CreateAPInvoice("Z1000", Creditor1, AUD, 1m, "APINV1");
			apInvoice.IsConvertedFromARInvoice = true;
			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC1, AUD, 1m, "CC1 invoice line with shipment 1 related job", 60m, false, shipment1); //carry forward amount (AUD) = 0 - 60 = -60
			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC1, AUD, 1m, "CC1 invoice line with shipment 2 related job", -20m, false, shipment2); //carry forward amount (AUD) = 0 - (-20) = 20
			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC1, AUD, 1m, "CC1 invoice line with empty related job", -30m, false, null); //carry forward amount (AUD) = 0 - (-30) = 30

			AssertEquals("Precondition : gateway job charge count", 3, gatewayJob.Charges.Count);

			var gatewayCharges = gatewayJob.Charges.Cast<Charge>().ToArray();
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 0m, 0m, TestObjectCreator.Debtor1.PK, AUD.RX_Code, 1m, 100m, 100m, false, true, shipment1.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 0m, 0m, TestObjectCreator.Debtor1.PK, AUD.RX_Code, 1m, 200m, 200m, false, true, shipment2.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 0m, 0m, TestObjectCreator.Debtor1.PK, AUD.RX_Code, 1m, 300m, 300m, false, true, ZString.Empty);

			using (AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetTemporaryValue(Env.CurrentCompanyPK, Guid.Empty, Guid.Empty, true))
			{
				GetTransformer(Factory).Transform(apInvoice);
			}

			AssertEquals("Postcondition : gateway job charge count", 6, gatewayJob.Charges.Count);

			gatewayCharges = gatewayJob.Charges.Cast<Charge>().ToArray();
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 60m, 60m, TestObjectCreator.Debtor1.PK, AUD.RX_Code, 1m, 100m, 100m, true, true, shipment1.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, -20m, -20m, TestObjectCreator.Debtor1.PK, AUD.RX_Code, 1m, 200m, 200m, true, true, shipment2.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, -30m, -30m, TestObjectCreator.Debtor1.PK, AUD.RX_Code, 1m, 300m, 300m, true, true, ZString.Empty);

			AssertChargesContainsCharge(gatewayCharges, CC1.PK, ZGuid.Empty, AUD.RX_Code, 1m, 0m, 0m, TestObjectCreator.Debtor1.PK, AUD.RX_Code, 1m, 60m, 60m, false, false, shipment1.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, ZGuid.Empty, AUD.RX_Code, 1m, 0m, 0m, TestObjectCreator.Debtor1.PK, AUD.RX_Code, 1m, -20m, -20m, false, false, shipment2.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, ZGuid.Empty, AUD.RX_Code, 1m, 0m, 0m, TestObjectCreator.Debtor1.PK, AUD.RX_Code, 1m, -30m, -30m, false, false, ZString.Empty);
		}

