		public void TestMatchByRelatedJobNumberIfUserHaveChangedInvoiceLineJobToADifferentJobButChangesBackToOriginalGatewayJobLater()
		{
			AssertMatchByRelatedJobNumberIfUserHaveChangedInvoiceLineJobToADifferentJob(true);
		}

		void AssertMatchByRelatedJobNumberIfUserHaveChangedInvoiceLineJobToADifferentJob(bool shouldRevertBackToOriginalGatewayJob)
		{
			CreateGatewayConsolWithShipments(out ForwardingShipment shipment1, out ForwardingShipment shipment2, out Job gatewayJob);

			var gatewayCharge = CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with shipment 1 related job", AUD, 10m, Creditor1, AUD, 10m, TestObjectCreator.Debtor1, shipment1);
			CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with shipment 2 related job", AUD, 10m, Creditor1, AUD, 10m, TestObjectCreator.Debtor1, shipment2);
			var shipment1Job = TestObjectCreator.CreateJob(shipment1, createWithMutex: false);
			var shipmentCharge = CreateChargeWithRelatedJob(shipment1Job, CC1, "CC1 charge", AUD, 10m, Creditor1, AUD, 10m, TestObjectCreator.Debtor1, null);
			Factory.Save();

			var apInvoice = CreateAPInvoice("Z1000", Creditor1, AUD, 1m, "APINV1");
			apInvoice.IsConvertedFromARInvoice = true;
			var invoiceLine1 = CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC1, AUD, 1m, "CC1 invoice line with shipment 1 related job", 10m, false, shipment1);
			invoiceLine1.AL_JH = shipment1Job.PK;
			invoiceLine1.AL_GE = shipmentCharge.JR_GE; //Keep-in sync with charge department setting
			if (shouldRevertBackToOriginalGatewayJob)
			{
				invoiceLine1.AL_JH = gatewayJob.PK;
				invoiceLine1.AL_GE = gatewayCharge.JR_GE; //Keep-in sync with charge department setting
			}

			var gatewayCharges = gatewayJob.Charges.Cast<Charge>().ToArray();
			AssertEquals(2, gatewayCharges.Length);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 10m, 10m, TestObjectCreator.Debtor1.PK, AUD.RX_Code, 1m, 10m, 10m, false, false, shipment1.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 10m, 10m, TestObjectCreator.Debtor1.PK, AUD.RX_Code, 1m, 10m, 10m, false, false, shipment2.JS_UniqueConsignRef);

			var shipmentCharges = shipment1Job.Charges.Cast<Charge>().ToArray();
			AssertEquals(1, shipmentCharges.Length);
			AssertChargesContainsCharge(shipmentCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 10m, 10m, TestObjectCreator.Debtor1.PK, AUD.RX_Code, 1m, 10m, 10m, false, false, ZString.Empty);

			GetTransformer(Factory).Transform(apInvoice);

			gatewayCharges = gatewayJob.Charges.Cast<Charge>().ToArray();
			AssertEquals(2, gatewayCharges.Length);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 10m, 10m, TestObjectCreator.Debtor1.PK, AUD.RX_Code, 1m, 10m, 10m, shouldRevertBackToOriginalGatewayJob, false, shipment1.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 10m, 10m, TestObjectCreator.Debtor1.PK, AUD.RX_Code, 1m, 10m, 10m, false, false, shipment2.JS_UniqueConsignRef);

			shipmentCharges = shipment1Job.Charges.Cast<Charge>().ToArray();
			AssertEquals(1, shipmentCharges.Length);
			AssertChargesContainsCharge(shipmentCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 10m, 10m, TestObjectCreator.Debtor1.PK, AUD.RX_Code, 1m, 10m, 10m, !shouldRevertBackToOriginalGatewayJob, false, ZString.Empty);
		}

