		public void TestMatchManuallyEnteredInvoiceLineToChargeWithEmptyRelatedJobNumber_ChargeWithEmptyRelatedJobNumberNotAvailable()
		{
			AssertMatchManuallyEnteredInvoiceLineToChargeWithEmptyRelatedJobNumber(false);
		}

		void AssertMatchManuallyEnteredInvoiceLineToChargeWithEmptyRelatedJobNumber(bool isChargeWithEmptyRelatedJobNumberAvailable)
		{
			CreateGatewayConsolWithShipments(out ForwardingShipment shipment1, out ForwardingShipment shipment2, out Job gatewayJob);

			CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with shipment 1 related job", AUD, 10m, Creditor1, AUD, 10m, TestObjectCreator.Debtor, shipment1);
			CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with shipment 2 related job", AUD, 20m, Creditor1, AUD, 20m, TestObjectCreator.Debtor, shipment2);
			if (isChargeWithEmptyRelatedJobNumberAvailable)
			{
				CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with empty related job", AUD, 30m, Creditor1, AUD, 30m, TestObjectCreator.Debtor, null);
			}
			Factory.Save();

			var apInvoice = CreateAPInvoice("Z1000", Creditor1, AUD, 1m, "APINV1");
			CreateAPInvoiceLineWithRelatedJob(apInvoice, gatewayJob, CC1, AUD, 1m, "CC1 invoice line with empty related job", 30m, false, null);

			Assert("Precondition : AP Invoice is not imported from sister company.", !apInvoice.IsConvertedFromARInvoice);
			var gatewayCharges = gatewayJob.Charges.Cast<Charge>().ToArray();
			AssertEquals(isChargeWithEmptyRelatedJobNumberAvailable ? 3 : 2, gatewayCharges.Length);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 10m, 10m, TestObjectCreator.Debtor.PK, AUD.RX_Code, 1m, 10m, 10m, false, false, shipment1.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 20m, 20m, TestObjectCreator.Debtor.PK, AUD.RX_Code, 1m, 20m, 20m, false, false, shipment2.JS_UniqueConsignRef);
			if (isChargeWithEmptyRelatedJobNumberAvailable)
			{
				AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 30m, 30m, TestObjectCreator.Debtor.PK, AUD.RX_Code, 1m, 30m, 30m, false, false, ZString.Empty);
			}

			GetTransformer(Factory).Transform(apInvoice);

			gatewayCharges = gatewayJob.Charges.Cast<Charge>().ToArray();
			AssertEquals("There should be 3 gateway charges.", 3, gatewayCharges.Length);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 10m, 10m, TestObjectCreator.Debtor.PK, AUD.RX_Code, 1m, 10m, 10m, false, false, shipment1.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 20m, 20m, TestObjectCreator.Debtor.PK, AUD.RX_Code, 1m, 20m, 20m, false, false, shipment2.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 30m, 30m, isChargeWithEmptyRelatedJobNumberAvailable ? TestObjectCreator.Debtor.PK : ZGuid.Empty, AUD.RX_Code, 1m, 30m, 30m, true, false, ZString.Empty);
		}

		public void TestSetRelatedJobNumberWhenCreatingCarryForwardChargeForInvoiceLineCreatedFromImportedJobCharge()
		{
			CreateGatewayConsolWithShipments(out ForwardingShipment shipment1, out ForwardingShipment shipment2, out Job gatewayJob);
			var charge = CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with shipment 1 related job", AUD, 30m, Creditor1, AUD, 10m, TestObjectCreator.DebtorSisterOrgProxy, shipment1);
			Factory.Save();

			var apInvoice = CreateAPInvoice("Z1000", Creditor1, AUD, 1m, "APINV1");
			var invoiceLine = (InvoicingLineBase)apInvoice.Lines.AddNew();
