		public void TestSetRelatedJobNumberWhenCreatingWIPForInvoiceLineCreatedFromImportedJobCharge()
		{
			CreateGatewayConsolWithShipments(out ForwardingShipment shipment1, out ForwardingShipment shipment2, out Job gatewayJob);
			var charge = CreateChargeWithRelatedJob(gatewayJob, CC1, "CC1 charge with shipment 1 related job", AUD, 5m, Creditor1, AUD, 100m, TestObjectCreator.Debtor1, shipment1);
			Factory.Save();

			PostChargeRevenues(gatewayJob);

			var apInvoice = CreateAPInvoice("Z1000", Creditor1, AUD, 1m, "APINV1");
			var invoiceLine = (InvoicingLineBase)apInvoice.Lines.AddNew();
			apInvoice.ImportJobChargesIntoInvoice(new[] { charge }, invoiceLine, false);
			AssertNotNull(invoiceLine);
			invoiceLine.AL_OSExTaxAmount = 10m; //carry forward amount (AUD) = 5 - 10 = -5

			var gatewayCharges = gatewayJob.Charges.Cast<Charge>().ToArray();
			AssertEquals("Precondition : gateway job charge count", 1, gatewayCharges.Length);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 5m, 5m, TestObjectCreator.Debtor1.PK, AUD.RX_Code, 1m, 100m, 100m, false, true, shipment1.JS_UniqueConsignRef);

			using (AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsGreaterThanAccrual.SetTemporaryValue(Env.CurrentCompanyPK, Guid.Empty, Guid.Empty, true))
			{
				GetTransformer(Factory).Transform(apInvoice);
			}

			gatewayCharges = gatewayJob.Charges.Cast<Charge>().ToArray();
			AssertEquals("Postcondition : gateway job charge count", 2, gatewayCharges.Length);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, Creditor1.PK, AUD.RX_Code, 1m, 10m, 10m, TestObjectCreator.Debtor1.PK, AUD.RX_Code, 1m, 100m, 100m, true, true, shipment1.JS_UniqueConsignRef);
			AssertChargesContainsCharge(gatewayCharges, CC1.PK, ZGuid.Empty, AUD.RX_Code, 1m, 0m, 0m, ZGuid.Empty, AUD.RX_Code, 1m, 5m, 5m, false, false, shipment1.JS_UniqueConsignRef);
		}

		void PostChargeRevenues(Job gatewayJob)
		{
			var arInvoice = TestObjectCreator.CreateInvoice(typeof(ARInvoice), "AR001", TestObjectCreator.AUD, 1m, TestObjectCreator.DebtorSisterOrgProxy);
			foreach (BaseCharge charge in gatewayJob.Charges)
			{
				arInvoice.Lines.Add(TestObjectCreator.CreateRevenueLine(charge, arInvoice.PK));
			}
			Factory.Save();
		}

		void CreateGatewayConsolWithShipments(out ForwardingShipment shipment1, out ForwardingShipment shipment2, out Job gatewayJob)
		{
			var gatewayConsol = TestObjectCreator.CreateGatewayConsol(receivingGatewayCompany: GlbCompany.CurrentCompany);
			shipment1 = TestObjectCreator.CreateShipment("S00001", gatewayConsol);
			shipment2 = TestObjectCreator.CreateShipment("S00002", gatewayConsol);
			gatewayJob = TestObjectCreator.CreateJob(gatewayConsol);
			Factory.Save();
		}

		Charge CreateChargeWithRelatedJob(Job parentJob, AccChargeCode chargeCode, string desc, RefCurrency costCurrency, decimal osCostAmt, OrgHeader creditor, RefCurrency sellCurrency, decimal osSellAmt, OrgHeader debtor, IJobHeaderParent relatedJob)
		{
			var charge = TestObjectCreator.CreateCharge(parentJob, chargeCode, desc, costCurrency, osCostAmt, creditor, null, sellCurrency, osSellAmt, debtor);
			charge.JR_GE = TestObjectCreator.FESDepartment.PK; //Keep-in sync with CreateAPInvoiceLineWithRelatedJob department setting
			if (relatedJob != null)
			{
				charge.JR_Calc_RelatedJobNumber = relatedJob.JobNumber;
			}
			charge.JR_OH_SellAccount = debtor.PK;
			charge.JR_RX_NKCostCurrency = costCurrency.RX_Code;
			return charge;
		}

		APInvoiceLine CreateAPInvoiceLineWithRelatedJob(APInvoice parent, Job job, AccChargeCode chargeCode, RefCurrency currency, decimal exchangeRate, string desc, decimal aH_OSExTaxAmount, bool isFinal, IJobHeaderParent relatedJob)
		{
			var invoiceLine = CreateAPInvoiceLine(parent, job, chargeCode, currency, exchangeRate, desc, aH_OSExTaxAmount, isFinal);
			if (relatedJob != null)
			{
				invoiceLine.RelatedJobFromIntercompanyInvoiceImport = (relatedJob.PK, relatedJob.JobNumber);
			}
			return invoiceLine;
		}

		APCreditNoteLine CreateAPCreditNoteLineWithRelatedJobNumber(APCreditNote parent, Job job, AccChargeCode chargeCode, RefCurrency currency, decimal exchangeRate, string desc, decimal aH_OSExTaxAmount, bool isFinal, IJobHeaderParent relatedJob)
		{
			var creditNoteLine = CreateAPCreditNoteLine(parent, job, chargeCode, currency, exchangeRate, desc, aH_OSExTaxAmount, false, isFinal);
			if (relatedJob != null)
			{
				creditNoteLine.RelatedJobFromIntercompanyInvoiceImport = (relatedJob.PK, relatedJob.JobNumber);
			}
			return creditNoteLine;
		}

