		public void TestNewCarryForwardConsolCostNotCreatedWithZeroLocalAmount()
		{
			var malaysianCompany = TestObjectCreator.CreateNewCompany("CMY", Core.Constants.CountryCodes.Malaysia);
			malaysianCompany.GC_IsReciprocal = true;
			var kualaLumpurBranch = TestObjectCreator.CreateNewBranch(malaysianCompany, "BKL");
			Factory.Save();

			var thaiCurrency = TestObjectCreator.GetCurrency(Constants.CurrencyCodes.Thailand);
			var malaysianCurrency = TestObjectCreator.GetCurrency(Constants.CurrencyCodes.Malaysia);
			var costExchangeRate = 0.12209m;
			var initialOSCostAmount = 19525m;
			var initialLocalCostAmount = 2383.81m;
			var osCostAmountToPost = 19524.99m;
			var localCostAmountToPost = 2383.80m;

			using (Env.SetTemporaryUserContext(Env.CurrentUserPK, kualaLumpurBranch.PK.ToGuid(), Env.CurrentDepartmentPK))
			{
				var consol = TestObjectCreator.CreateConsol();
				var shipment = TestObjectCreator.CreateShipment("S0010", consol);
				var consolCost = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, thaiCurrency, costExchangeRate, initialOSCostAmount, TestObjectCreator.Creditor1);
				Factory.Save();

				AssertEquals(1, consol.GetApportionments().CostsCollection.Count);
				AssertConsolCost(consolCost, thaiCurrency.RX_Code.ToString(), costExchangeRate, initialLocalCostAmount, initialOSCostAmount, false);
				AssertApportionJobCharge(consolCost.ApportionmentCharges[0], TestObjectCreator.Creditor1.PK, thaiCurrency.RX_Code, costExchangeRate, initialLocalCostAmount, initialOSCostAmount, thaiCurrency.RX_Code, 1m, initialOSCostAmount, initialOSCostAmount, false, consolCost.PK);

				var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), malaysianCurrency, 1m, TestObjectCreator.Creditor1);
				invoice.SubmittedFromInvoicingForm = true;
				var apInvoiceConsolCost = TestObjectCreator.CreateConsolCost(invoice, consol, TestObjectCreator.CC1, osCostAmountToPost, TestObjectCreator.Creditor1);
				apInvoiceConsolCost.E6_RX_NKCurrency = thaiCurrency.RX_Code;
				apInvoiceConsolCost.E6_ExchangeRate = costExchangeRate;
				apInvoiceConsolCost.IsFinal = false;
				apInvoiceConsolCost.E6_LocalCostAmount = localCostAmountToPost;

