		public void TestChargesWithZeroLocalCostAmountNotLinkedToNewCarryForwardConsolCost()
		{
			var malaysianCompany = TestObjectCreator.CreateNewCompany("CMY", Core.Constants.CountryCodes.Malaysia);
			malaysianCompany.GC_IsReciprocal = true;
			var kualaLumpurBranch = TestObjectCreator.CreateNewBranch(malaysianCompany, "BKL");
			Factory.Save();

			var thaiCurrency = TestObjectCreator.GetCurrency(Constants.CurrencyCodes.Thailand);
			var malaysianCurrency = TestObjectCreator.GetCurrency(Constants.CurrencyCodes.Malaysia);
			var costExchangeRate = 0.12209m;
			var initialOSCostAmount = 20000m;
			var initialLocalCostAmount = 2441.8m;
			var osCostAmountToPost = 19600m;
			var localCostAmountToPost = 2392.96m;

			using (Env.SetTemporaryUserContext(Env.CurrentUserPK, kualaLumpurBranch.PK.ToGuid(), Env.CurrentDepartmentPK))
			{
				var consol = TestObjectCreator.CreateConsol();
				var shipment1 = TestObjectCreator.CreateShipment("S001001", consol);
				var shipment2 = TestObjectCreator.CreateShipment("S001002", consol);
				var consolCost = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, thaiCurrency, costExchangeRate, initialOSCostAmount, TestObjectCreator.Creditor1);
				consolCost.ApportionmentCharges[0].JR_OSCostAmt = 19525m;
				consolCost.ApportionmentCharges[1].JR_OSCostAmt = 475m;
				Factory.Save();

				AssertEquals(1, consol.GetApportionments().CostsCollection.Count);
				AssertConsolCost(consolCost, thaiCurrency.RX_Code.ToString(), costExchangeRate, initialLocalCostAmount, initialOSCostAmount, false);
				AssertApportionJobCharge(consolCost.ApportionmentCharges[0], TestObjectCreator.Creditor1.PK, thaiCurrency.RX_Code, costExchangeRate, 2383.81m, 19525m, thaiCurrency.RX_Code, 1m, 19525m, 19525m, false, consolCost.PK);
				AssertApportionJobCharge(consolCost.ApportionmentCharges[1], TestObjectCreator.Creditor1.PK, thaiCurrency.RX_Code, costExchangeRate, 57.99m, 475m, thaiCurrency.RX_Code, 1m, 475m, 475m, false, consolCost.PK);

				var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), malaysianCurrency, 1m, TestObjectCreator.Creditor1);
				invoice.SubmittedFromInvoicingForm = true;
				var apInvoiceConsolCost = TestObjectCreator.CreateConsolCost(invoice, consol, TestObjectCreator.CC1, osCostAmountToPost, TestObjectCreator.Creditor1);
				apInvoiceConsolCost.E6_RX_NKCurrency = thaiCurrency.RX_Code;
				apInvoiceConsolCost.E6_ExchangeRate = costExchangeRate;
				apInvoiceConsolCost.IsFinal = false;
				apInvoiceConsolCost.E6_LocalCostAmount = localCostAmountToPost;
				var apportionCharge1 = apInvoiceConsolCost.ApportionmentCharges.Cast<ApportionSplitCharge>().First(x => x.RelatedApportionChargeFromDB.PK == consolCost.ApportionmentCharges[0].PK);
				apportionCharge1.JR_OSCostAmt = 19524.99m;
				var apportionCharge2 = apInvoiceConsolCost.ApportionmentCharges.Cast<ApportionSplitCharge>().First(x => x.RelatedApportionChargeFromDB.PK == consolCost.ApportionmentCharges[1].PK);
				apportionCharge2.JR_OSCostAmt = 75.01m;

				invoice.ImportAllApportionmentsFromCosting();

				AssertEquals(2, invoice.Lines.Count);

				AssertEquals(costExchangeRate, invoice.Lines[0].AL_ExchangeRate);
				AssertEquals(19524.99m, invoice.Lines[0].AL_OSExTaxAmount);
				AssertEquals(2383.80m, invoice.Lines[0].AL_LocalExTaxAmount);
				AssertEquals(false, invoice.Lines[0].AL_IsFinalCharge);

				AssertEquals(costExchangeRate, invoice.Lines[1].AL_ExchangeRate);
				AssertEquals(75.01m, invoice.Lines[1].AL_OSExTaxAmount);
				AssertEquals(9.16m, invoice.Lines[1].AL_LocalExTaxAmount);
				AssertEquals(false, invoice.Lines[1].AL_IsFinalCharge);

				Factory.Save();

				var reloadFactory = new BusinessObjectFactory();
				var reloadedConsol = reloadFactory.Load<ForwardingConsol>(consol.PK);
				AssertEquals("Should create a new consol cost.", 2, reloadedConsol.GetApportionments().CostsCollection.Count);

				var exisitingConsolCost = reloadedConsol.GetApportionments().CostsCollection.Cast<JobConsolCost>().First(x => x.PK == consolCost.PK);
				AssertConsolCost(exisitingConsolCost, thaiCurrency.RX_Code.ToString(), costExchangeRate, localCostAmountToPost, osCostAmountToPost, true);
				var exisitngApportionCharge1 = exisitingConsolCost.ApportionmentCharges.Cast<ApportionSplitCharge>().First(x => x.PK == consolCost.ApportionmentCharges[0].PK);
				AssertApportionJobCharge(exisitngApportionCharge1, TestObjectCreator.Creditor1.PK, thaiCurrency.RX_Code, costExchangeRate, 2383.80m, 19524.99m, thaiCurrency.RX_Code, 1m, 19525m, 19525m, true, consolCost.PK);
				var exisitngApportionCharge2 = exisitingConsolCost.ApportionmentCharges.Cast<ApportionSplitCharge>().First(x => x.PK == consolCost.ApportionmentCharges[1].PK);
				AssertApportionJobCharge(exisitngApportionCharge2, TestObjectCreator.Creditor1.PK, thaiCurrency.RX_Code, costExchangeRate, 9.16m, 75.01m, thaiCurrency.RX_Code, 1m, 475m, 475m, true, consolCost.PK);

				var carryForwardConsolCost = reloadedConsol.GetApportionments().CostsCollection.Cast<JobConsolCost>().First(x => x.PK != consolCost.PK);
				AssertConsolCost(carryForwardConsolCost, thaiCurrency.RX_Code.ToString(), costExchangeRate, 48.83m, 399.99m, false);
				var carryForwardApportionCharge1 = carryForwardConsolCost.ApportionmentCharges.Cast<ApportionSplitCharge>().First(x => x.JR_JH == consolCost.ApportionmentCharges[0].JR_JH);
				AssertApportionJobCharge(carryForwardApportionCharge1, TestObjectCreator.Creditor1.PK, thaiCurrency.RX_Code, costExchangeRate, 0m, 0m, TestObjectCreator.AUD.RX_Code, 1m, 0m, 0m, false, carryForwardConsolCost.PK);
				Assert("Should be a default charge.", !carryForwardApportionCharge1.JR_IsUsedForApportionment);
				var carryForwardApportionCharge2 = carryForwardConsolCost.ApportionmentCharges.Cast<ApportionSplitCharge>().First(x => x.JR_JH == consolCost.ApportionmentCharges[1].JR_JH);
				AssertApportionJobCharge(carryForwardApportionCharge2, TestObjectCreator.Creditor1.PK, thaiCurrency.RX_Code, costExchangeRate, 48.83m, 399.99m, TestObjectCreator.AUD.RX_Code, 1m, 0m, 0m, false, carryForwardConsolCost.PK);
			}
		}

		public void TestTransactionLineJobChargeTransformer_OSAmountisZeroLocalAmountIsNotZero()
		{
			var fRT = TestObjectCreator.CC1.PK;
			var aALSHI = TestObjectCreator.AALSHI.PK;
			var aBIGAS = TestObjectCreator.ABIGAS.PK;

			AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsGreaterThanAccrual.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);

			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			Factory.Save();

			var shipment1 = consol.Shipments.AddNew();

			var appListing = new ApportionmentListing(Factory, consol);
			var consolCost1 = appListing.CostsCollection.TryAddNew();
			consolCost1.E6_OH_Creditor = aALSHI;
			consolCost1.E6_AC_ChargeCode = fRT;
			consolCost1.E6_RX_NKCurrency = USD.RX_Code;
			consolCost1.E6_ExchangeRate = 0.704950m;
			consolCost1.E6_OSCostAmount = 250m;
			consolCost1.E6_ApportionmentMethod = "SHP";
			Factory.Save();

			var consolCost2 = appListing.CostsCollection.TryAddNew();
			consolCost2.E6_OH_Creditor = aALSHI;
			consolCost2.E6_AC_ChargeCode = fRT;
			consolCost2.E6_RX_NKCurrency = USD.RX_Code;
			consolCost2.E6_ExchangeRate = 0.704950m;
			consolCost2.E6_OSCostAmount = 249.05m;
			consolCost2.E6_ApportionmentMethod = "SHP";
			Factory.Save();

			AssertEquals("ConsolCost1 OS Amount plus ConsolCost2 OS Amount is 499.05", 499.05m, consolCost1.E6_OSCostAmount + consolCost2.E6_OSCostAmount);
			AssertEquals("ConsolCost1 Local Amount plus ConsolCost2 Local Amount is 707.93", 707.93m, consolCost1.E6_LocalCostAmount + consolCost2.E6_LocalCostAmount);
			AssertEquals("(ConsolCost1 OS Amount plus ConsolCost2 OS Amount) * exchange rate is 707.92 which is not equal to sum of local amount.", 707.92m, Decimal.Round((consolCost1.E6_OSCostAmount + consolCost2.E6_OSCostAmount) / 0.704950m, 2));

			var shipmentJob = new Job.Loader(shipment1).TryLoadOrCreateWithoutMutexForTestOnly();

			Assert("shipment should have 2 charges now", shipmentJob.Charges.Count == 2);

			var charges = shipmentJob.Charges.ToArray<Charge>();
			charges.ForEach(x => x.JR_OSSellAmt = 0m);
			Factory.Save();

			var invoice = Factory.New<APInvoice>();
			invoice.AH_OH = aALSHI;
			invoice.SubmittedFromInvoicingForm = true;
			invoice.AH_RX_NKTransactionCurrency = USD.RX_Code;
			invoice.AH_ExchangeRate = 0.704950m;

			var invoiceConsolCosting = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			invoiceConsolCosting.IsFinal = false;
			invoiceConsolCosting.E6_AC_ChargeCode = fRT;
			invoiceConsolCosting.E6_OSCostAmount = 499.05m;
			invoiceConsolCosting.E6_ApportionmentMethod = "SHP";
			invoiceConsolCosting.E6_OH_Creditor = aALSHI;

			invoice.ImportSingleCost(invoiceConsolCosting, (InvoicingLineBase)invoice.Lines.AddNew());
			AssertEquals("1 Lines should be imported", 1, invoice.Lines.Count);

			foreach (InvoicingLineBase line in invoice.Lines)
			{
				AssertEquals(line.AL_AC, consolCost1.E6_AC_ChargeCode);
				AssertEquals(line.AL_RX_NKTransactionCurrency, consolCost1.E6_RX_NKCurrency);
				AssertEquals(line.AL_ExchangeRate, consolCost1.E6_ExchangeRate);
				AssertEquals(line.AL_OSExTaxAmount, invoiceConsolCosting.E6_OSCostAmount);
			}

			ErrorReporter.Clear();
			AssertEquals("No error before Transform.", 0, ErrorReporter.ExceptionsThrown.Count);

			new TransactionLineJobChargeTransformer(Factory).Transform(invoice);

			AssertEquals("No error after Transform.", 0, ErrorReporter.ExceptionsThrown.Count);
		}

		#region carryForwardApportionChargePKs and ChargesToSearch out of sync test cases

		public void TestErrorReportedWhenChargeIsAddedToCarryForwardApportionChargePKsButNotInChargesToSearch()
		{
			var consol = TestObjectCreator.CreateConsol();
			TestObjectCreator.CreateShipment("S00001001", consol);
			TestObjectCreator.CreateShipment("S00001002", consol);
			var consolCost = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.FRT, 100m);
			Factory.Save();

			var charge1 = Factory.Load<Charge>(consolCost.ApportionmentCharges[0].PK);
			var transformer1 = new TransactionLineJobChargeTransformer(Factory);
			transformer1.ChargesToSearch.AddCharge(charge1);
			Assert("Precondition", transformer1.ChargesToSearch.Charges.Contains(charge1));
			transformer1.CarryForwardCostCreator.AddTocarryForwardApportionChargePKList(charge1, consol.PK, consolCost.E6_ParentTableCode);

			ErrorReporter.Clear();
			transformer1.CarryForwardCostCreator.Dispose();
			AssertEquals("No Error because charge1 is in ChargesToSearch", 0, ErrorReporter.ExceptionsThrown.Count);
			AssertNullOrEmpty("Should not report error because charge1 is in ChargesToSearch", ErrorReporter.ExceptionsThrown.FirstOrDefault());

			var charge2 = Factory.Load<Charge>(consolCost.ApportionmentCharges[1].PK);
			var transformer2 = new TransactionLineJobChargeTransformer(Factory);
			Assert("Precondition", !transformer2.ChargesToSearch.Charges.Contains(charge2));
			transformer2.CarryForwardCostCreator.AddTocarryForwardApportionChargePKList(charge2, consol.PK, consolCost.E6_ParentTableCode);

			ErrorReporter.Clear();
			transformer2.CarryForwardCostCreator.Dispose();
			var exceptionMessage = ErrorReporter.ExceptionsThrown.FirstOrDefault(msg => msg.Contains("ChargesToSearchAndCarryForwardApportionChargePKsAreOutOfSync"));
			AssertEquals(1, ErrorReporter.ExceptionsThrown.Count(msg => msg.Contains("ChargesToSearchAndCarryForwardApportionChargePKsAreOutOfSync")));

			CombineAssertions("Should report error because charge2 is NOT in ChargesToSearch and error reported Key: TransactionLineJobChargeTransformer_ChargesToSearchAndCarryForwardApportionChargePKsAreOutOfSync",
			() =>
			{
				AssertContains("ChargesToSearchAndCarryForwardApportionChargePKsAreOutOfSync", exceptionMessage);
				AssertContains("Charge added to carryForwardApportionChargePKs, but it is not added to ChargesToSearch.", exceptionMessage);
				AssertContains("Added Charge Details:", exceptionMessage);
				AssertContains("ChargesToSearch collection:", exceptionMessage);
				AssertContains("carryForwardApportionChargePKs collection:", exceptionMessage);
			});

			var transformer3 = new TransactionLineJobChargeTransformer(Factory);
			Assert("Precondition", !transformer3.ChargesToSearch.Charges.Contains(charge2));
			transformer3.CarryForwardCostCreator.AddTocarryForwardApportionChargePKList(charge2, consol.PK, consolCost.E6_ParentTableCode);

			ErrorReporter.Clear();
			transformer3.CarryForwardCostCreator.Dispose();
			exceptionMessage = ErrorReporter.ExceptionsThrown.FirstOrDefault(msg => msg.Contains("Charge added to carryForwardApportionChargePKs, but it is not added to ChargesToSearch."));
			AssertEquals(1, ErrorReporter.ExceptionsThrown.Count(msg => msg.Contains("Charge added to carryForwardApportionChargePKs, but it is not added to ChargesToSearch.")));
			AssertContains("Should report error because charge2 is NOT in ChargesToSearch and error reported Key: TransactionLineJobChargeTransformer_ChargesToSearchAndCarryForwardApportionChargePKsAreOutOfSync",
				"ChargesToSearchAndCarryForwardApportionChargePKsAreOutOfSync:\r\nCharge added to carryForwardApportionChargePKs, but it is not added to ChargesToSearch.", exceptionMessage);
			AssertContains("Added Charge Details:", exceptionMessage);
			ErrorReporter.Clear();
		}

		public void TestErrorReportedWhenChargeIsRemovedFromChargesToSearchButRemainsInCarryForwardApportionChargePKs()
		{
			var consol = TestObjectCreator.CreateConsol();
