			Assert("Precondition", transformer3.CarryForwardCostCreator.IsItACarryForwardApportionCharge(charge2));
			transformer3.ChargesToSearch.RemoveCharge(charge2);

			ErrorReporter.Clear();
			transformer3.CarryForwardCostCreator.Dispose();
			exceptionMessage = ErrorReporter.ExceptionsThrown.FirstOrDefault(msg => msg.Contains("Charge removed from ChargesToSearch, but it is not removed from carryForwardApportionChargePKs."));
			AssertEquals(1, ErrorReporter.ExceptionsThrown.Count(msg => msg.Contains("Charge removed from ChargesToSearch, but it is not removed from carryForwardApportionChargePKs.")));
			AssertContains("Should report error because charge2 is in carryForwardApportionChargePKs and error reported Key: TransactionLineJobChargeTransformer_ChargesToSearchAndCarryForwardApportionChargePKsAreOutOfSync",
				"ChargesToSearchAndCarryForwardApportionChargePKsAreOutOfSync:\r\nCharge removed from ChargesToSearch, but it is not removed from carryForwardApportionChargePKs.", exceptionMessage);
			AssertContains("Removed Charge Details:", exceptionMessage);
			ErrorReporter.Clear();
		}

