		public void TestConsolCostCollectedWhenReorganizeConsolCosts()
		{
			var collector = MasterFiles.Business.Accounting.CriticalValidation.CriticalValidationInfoCollectorService.GetOrCreateService(Factory);
			var consol = TestObjectCreator.CreateConsol();
