			TestObjectCreator.CreateShipment("S00001002", consol);
			var consolCost = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, TestObjectCreator.CNY, 1.0001M, 0.04M, TestObjectCreator.Creditor1);

			AssertEquals(2, consolCost.ApportionmentCharges.Count);
