			transformer1.ChargesToSearch.AddCharge(charge1);
			Assert("Precondition", !transformer1.CarryForwardCostCreator.IsItACarryForwardApportionCharge(charge1));

			transformer1.CarryForwardCostCreator.AddTocarryForwardApportionChargePKList(charge1, consol.PK, consolCost.E6_ParentTableCode);
			transformer1.CarryForwardCostCreator.Dispose();
			AssertContains("This case should not collect consol cost data in ReorganizeConsolCosts", "ReorganizeConsolCosts: There is no data collected for this PK. It might be because data is collected only after first error report. Please look at reports with Seq# >= 1.", collector.GetInfo(consolCost.PK, MasterFiles.Business.Accounting.CriticalValidation.CriticalValidationInfoCollectorServiceKeyType.ReorganizeConsolCosts));

			var transformer2 = new TransactionLineJobChargeTransformer(Factory);
			transformer2.ChargesToSearch.AddCharge(charge1);
			transformer2.CarryForwardCostCreator.AddTocarryForwardApportionChargePKList(charge1, consol.PK, consolCost.E6_ParentTableCode);
			Assert("Precondition", transformer2.CarryForwardCostCreator.IsItACarryForwardApportionCharge(charge1));

			transformer2.CarryForwardCostCreator.AddTocarryForwardApportionChargePKList(charge1, consol.PK, consolCost.E6_ParentTableCode);
			transformer2.CarryForwardCostCreator.Dispose();

			var expectedContainsMessage = "ReorganizeConsolCosts:\r\nConsol cost data before reorgnize:\r\nJob Consol Cost:";
			AssertContains("This case should collect consol cost data in ReorganizeConsolCosts", expectedContainsMessage, collector.GetInfo(consolCost.PK, MasterFiles.Business.Accounting.CriticalValidation.CriticalValidationInfoCollectorServiceKeyType.ReorganizeConsolCosts));

			var apportionCharge1 = consolCost.ApportionmentCharges[0];
			apportionCharge1.JR_LocalCostAmt = 0.04M;
			apportionCharge1.JR_OSCostAmt = 0.03M;

			var apportionCharge2 = consolCost.ApportionmentCharges[1];
			using (apportionCharge2.SuspendAmountsCalculations())
			{
				apportionCharge2.JR_LocalCostAmt = 0M;
				apportionCharge2.JR_OSCostAmt = 0.01M;
			}

			try
			{
				Factory.Save();
			}
			catch (OnSavingCriticalCheckException ex)
			{
				AssertEquals(nameof(CriticalValidationErrorType.JobChargeLinkedToConsolCostInvoiceHasZeroCostAmount_11), ex.ErrorType);
				AssertContains("Consol cost data before reorgnize:", ex.DeveloperErrorMessage);
				AssertContains("Apportion charges mapped to target consol", ex.DeveloperErrorMessage);
				Enterprise.ZArchitecture.Core.Testing.ExceptionReporterTestListener.Instance.Clear();
			}
		}

		public void TestTargetConsolCostSynchroniseUnpostedInvoiceDetailsWhenReorganizeConsolCosts()
		{
			var consol = TestObjectCreator.CreateConsol("AUSYD", "NZAKL", "C00001111");
			var shipment1 = TestObjectCreator.CreateShipment("S00100111", "AUSYD", "NZAKL", consol);
			var shipment2 = TestObjectCreator.CreateShipment("S00100444", "AUSYD", "NZAKL", consol);
			var job1 = TestObjectCreator.CreateJob(shipment1, false);
			var job2 = TestObjectCreator.CreateJob(shipment2, false);
			var consolCost1 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.FRT, 20m, Creditor1);
			var consolCost2 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.FRT, 10m, Creditor1);
			var consolCost3 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.FRT, 8m, Creditor1);

			//We use E6_Sequence to have stable result as it impacts order of consol cost processing
			consolCost1.E6_Sequence = 3;//first consol cost with biggest charge sequence number
			consolCost2.E6_Sequence = 2;
			consolCost3.E6_Sequence = 1;//last consol cost with smallest sequence number

			consolCost2.ApportionmentCharges[1].JR_IsUsedForApportionment = false;
			Factory.Save();

			AssertEquals("Precondition:", job1, consolCost1.ApportionmentCharges[0].Job);
			AssertEquals("Precondition:", job1, consolCost2.ApportionmentCharges[0].Job);
			AssertEquals("Precondition:", job1, consolCost3.ApportionmentCharges[0].Job);

			//We set Display Sequences for charges on first job
			consolCost1.ApportionmentCharges[0].JR_DisplaySequence = 1;
			consolCost2.ApportionmentCharges[0].JR_DisplaySequence = 2;
			consolCost3.ApportionmentCharges[0].JR_DisplaySequence = 3;
			Factory.Save();

			Assert("Precondition: ConsolCosts on consol should be more than or equal to 3", new ApportionmentListing(Factory, consol).CostsCollection.Count >= 3);
			Assert("Precondition: Shipment count on Consol should be more than or equal to 2", consol.CostSupporter.ShipmentsList.Length >= 2);
			AssertEquals("Precondition:", 2, consolCost1.ApportionmentCharges.Count);
			AssertEquals("Precondition:", 1, consolCost2.ApportionmentCharges.Count);
			AssertEquals("Precondition:", 2, consolCost3.ApportionmentCharges.Count);

			AssertEquals("Precondition:", 3, job1.Charges.Count);
			AssertEquals("Precondition: because consolCost2 not using job2-shipment2", 2, job2.Charges.Count);

			AssertEquals("Precondition:", 10m, consolCost1.ApportionmentCharges[0].JR_OSCostAmt);
			AssertEquals("Precondition:", 10m, consolCost1.ApportionmentCharges[1].JR_OSCostAmt);

			AssertEquals("Precondition:", 10m, consolCost2.ApportionmentCharges[0].JR_OSCostAmt);

			AssertEquals("Precondition:", 4m, consolCost3.ApportionmentCharges[0].JR_OSCostAmt);
			AssertEquals("Precondition:", 4m, consolCost3.ApportionmentCharges[1].JR_OSCostAmt);

			AssertEquals("Precondition: JR_DisplaySequence of this Charge should be either 1 or 2, should not be more than 2", (ZShort)1, consolCost1.ApportionmentCharges[0].JR_DisplaySequence);
			AssertEquals("Precondition: JR_DisplaySequence of this Charge should be either 1 or 2, should not be more than 2", (ZShort)2, consolCost2.ApportionmentCharges[0].JR_DisplaySequence);
			AssertEquals("Precondition: JR_DisplaySequence of this Charge should not be 1 or 2, should be more than 2", (ZShort)3, consolCost3.ApportionmentCharges[0].JR_DisplaySequence);

			var apInvoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), AUD, 1m, Creditor1);
			apInvoice.SubmittedFromInvoicingForm = true;

			//To create carry forward Charge, new consol Cost Amount will be set which can be greater than consolCost1 amount-20m and not equal to consolCost2 amount-10m which use only one shipment.
			var apInvoiceConsolCost = TestObjectCreator.CreateConsolCost(apInvoice, consol, TestObjectCreator.FRT, 21m, Creditor1);
			apInvoiceConsolCost.IsFinal = false;

			AssertEquals("Precondition: ", 21m, apInvoiceConsolCost.E6_OSCostAmount);
			Assert("Precondition: Not IsFinal", !apInvoiceConsolCost.IsFinal);
			AssertEquals("Precondition: ", 2, apInvoiceConsolCost.ApportionmentCharges.Count);
			Assert("Precondition: Apportion To Consols > New Consol Cost created for same consol, Charge code and creditor but not from import", !apInvoiceConsolCost.IsInDatabase);

			var apportionCharge1 = apInvoiceConsolCost.ApportionmentCharges[0];
			var apportionCharge2 = apInvoiceConsolCost.ApportionmentCharges[1];
			AssertEquals(10.5m, apportionCharge1.JR_OSCostAmt);
			AssertEquals(10.5m, apportionCharge2.JR_OSCostAmt);

			apInvoice.ImportAllApportionmentsFromCosting();

			AssertEquals("Precondition: Invoice Lines", 2, apInvoice.Lines.Count);
			AssertEquals("Precondition:", false, apInvoice.Lines[0].AL_IsFinalCharge);
			AssertEquals("Precondition:", false, apInvoice.Lines[1].AL_IsFinalCharge);
			AssertEquals(10.5m, apInvoice.Lines[0].AL_OSExTaxAmount);
			AssertEquals(10.5m, apInvoice.Lines[1].AL_OSExTaxAmount);
			Assert("Preconditiom: Lines[0].IsPopulatedFromImportedJobCharge", !apInvoice.Lines[0].IsPopulatedFromImportedJobCharge);
			Assert("Preconditiom: Lines[1].IsPopulatedFromImportedJobCharge", !apInvoice.Lines[1].IsPopulatedFromImportedJobCharge);

			Assert("Precondition: Invoice NOT in DB", !apInvoice.IsInDatabase);
			Assert("Precondition: consolCost1 NOT Posted", !consolCost1.IsPosted);

			ErrorReporter.Clear();
			AssertNoExceptionThrown("OnSavingCriticalCheckException: CriticalValidationErrorType.JobChargeInvoiceDetailsNotEqualConsolCostOnes_8 is not thrown", () => Factory.Save());

			AssertNullOrEmpty("PostCondition: Should not report error", ErrorReporter.ExceptionsThrown.FirstOrDefault());
			AssertEquals("PostCondition: Error Count", 0, ErrorReporter.ExceptionsThrown.Count);

			Assert("PostCondition: Invoice saved in DB", apInvoice.IsInDatabase);
			Assert("PostCondition: consolCost1 Is Posted", consolCost1.IsPosted);
			AssertEquals("PostCondition: consolCost1.E6_OSCostAmount", 21m, consolCost1.E6_OSCostAmount);
		}

		#region TestChargesToSearch

		public void TestChargeIsRemovedFromChargesToSearchWhenDeleted()
		{
			ErrorReporter.Clear();
			var charge = Factory.New<Charge>();
			using (var chargesToSearch = new TransactionLineJobChargeTransformer.ChargesByPK())
			{
				chargesToSearch.AddCharge(charge);
				AssertEquals("PreCondition", 1, chargesToSearch.Charges.Count());
				Assert("PreCondition", charge.HasContext(BusinessContext.ReportDeletingCharges));
				charge.Delete();
				AssertContains("when we do not expect it to be deleted", ErrorReporter.LastMessageReported);
				AssertEquals("Charge removed from the collection", 0, chargesToSearch.Charges.Count());
				AssertEquals("The error is reported only once", 1, ErrorReporter.TotalErrorCount);
				ErrorReporter.Clear();
			}
		}

		public void TestChargeIsRemovedFromChargesToSearchWhenApportionmentChargeIsDeleted()
		{
			ErrorReporter.Clear();
			var creator = new TestObjectCreator(Factory);
			var consol = creator.CreateConsol("AUSYD", "NZAKL", "C0001003");
			var shipment = creator.CreateShipment("S00100191", "AUSYD", "NZAKL", consol);

			using (var job = creator.CreateJob(shipment))
			using (var chargesToSearch = new TransactionLineJobChargeTransformer.ChargesByPK())
			{
				var apps = new ApportionmentListing(Factory, consol);
				var cost = apps.CostsCollection.TryAddNew();
				var apportionedCharge = cost.ApportionmentCharges[0];
				var loadedCharge = Factory.Load<Charge>(apportionedCharge.PK);

				chargesToSearch.AddCharge(loadedCharge);
				AssertEquals("PreCondition", 1, chargesToSearch.Charges.Count());
				Assert("PreCondition", loadedCharge.HasContext(BusinessContext.ReportDeletingCharges));
				AssertEquals("PreCondition", apportionedCharge.HasContext(BusinessContext.ReportDeletingCharges), loadedCharge.HasContext(BusinessContext.ReportDeletingCharges));
				apportionedCharge.Delete();
				AssertContains("when we do not expect it to be deleted", ErrorReporter.LastMessageReported);
				AssertEquals("Charge removed from the collection", 0, chargesToSearch.Charges.Count());
				AssertEquals("The error is reported only once", 1, ErrorReporter.TotalErrorCount);
				ErrorReporter.Clear();
			}
		}

		public void TestNoErrorWhenChargeDeletedAfterRemovedFromChargesToSearch()
		{
			ErrorReporter.Clear();
			var charge = Factory.New<Charge>();
			using (var chargesToSearch = new TransactionLineJobChargeTransformer.ChargesByPK())
			{
				chargesToSearch.AddCharge(charge);
				AssertEquals("PreCondition", 1, chargesToSearch.Charges.Count());
				Assert("PreCondition", charge.HasContext(BusinessContext.ReportDeletingCharges));
				chargesToSearch.RemoveCharge(charge);
				Assert("Charge context removed", !charge.HasContext(BusinessContext.ReportDeletingCharges));
				AssertEquals("Charge removed from the collection", 0, chargesToSearch.Charges.Count());
				charge.Delete();
				AssertEquals("No Error", 0, ErrorReporter.TotalErrorCount);
			}
		}

