		public void TestConsolCostsToSearchForMultipleTransactions()
		{
			var helper = new TestObjectCreator(Factory);
			var consol = helper.CreateConsol();
			var shipment = helper.CreateShipment("S001", consol);
			var consolCost = helper.CreateConsolCost(consol, helper.FRT);
			consolCost.E6_OSCostAmount = 500m;
			consolCost.E6_ApportionmentMethod = "GWT";
			AssertEquals(1, consolCost.ApportionmentCharges.Count);
			Factory.Save();

			var invoice1 = CreateInvoiceWithLineAndCharge(helper, consol, "INV001", helper.GST1, 500m, 50m);
			var invoice2 = CreateInvoiceWithLineAndCharge(helper, consol, "INV002", helper.GSTFREE1, 500m, 0m);

			var transformer = GetTransformer(Factory);
			var propertyInfo = transformer.GetType().GetProperty("ConsolCostsToSearch", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);

			transformer.Transform(invoice1);
			AssertEquals("No consol cost remain after transform.", 0, ((ConsolCostListWithStrategy)propertyInfo.GetValue(transformer)).Count);

			transformer.Transform(invoice2);
			AssertEquals("No consol cost remain after transform.", 0, ((ConsolCostListWithStrategy)propertyInfo.GetValue(transformer)).Count);
		}

		public void TestConcurrencyErrorThrownWhenAssociatedJobChargeIsAlreadyPosted()
		{
			var postedInvoice = TestObjectCreator.CreateAPInvoice<APInvoice>("111", TestObjectCreator.AUD, 1M, 100M, 0M, 0M, 100M, 0M, 0M);

			var shipment = TestObjectCreator.CreateShipment("S001001", false);
			var job = TestObjectCreator.CreateJob(shipment, false);
			var jobCharge = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, 100M, 0M);
			jobCharge.JR_APInvoiceNum = "111";
			Factory.Save();

			var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), "234", TestObjectCreator.AUD, 1M);
			var line = (InvoicingLineBase)invoice.Lines.AddNew();
			line.AL_JH = job.PK;
			invoice.ImportJobChargesIntoInvoice(new[] { jobCharge }.ToList(), line);

			AssertNotNull("Original job charge is not null", line.OriginalJobCharge);

			var transformer = GetTransformer(Factory);
			(line.OriginalJobCharge as BaseCharge).ReverseAccrual(ZDateTime.Today);
			line.OriginalJobCharge.JR_AL_APLine = postedInvoice.Lines[0].PK; //this is not realistic, simply forcefully making original job charge posted
			Assert("Original job charge is posted", line.OriginalJobCharge.IsCostPosted);

			try
			{
				transformer.Transform(invoice);
				Assert("Exception should be thrown while attempting to transform the invoice", false);
			}
			catch (ZSaveConcurrencyException ex)
			{
				var expectedException = "Another user has already posted at least one Charge in this invoice. Please close the form and retry.";
				AssertEquals(expectedException, ex.InnerException.InnerException.Message);
			}
		}

		APInvoice CreateInvoiceWithLineAndCharge(TestObjectCreator helper, ForwardingConsol consol, string invNum, AccTaxRate taxRate, decimal amtExTax, decimal taxAmt)
		{
			var invoice1 = helper.CreateAPInvoice<APInvoice>(invNum, helper.AUD, 1, amtExTax, taxAmt, 0m, amtExTax, taxAmt, 0m);
			invoice1.AH_OH = helper.AALSHI.PK;

			var cost1 = invoice1.ConsolCosting.ConsolCosts.AddNew();
			cost1.SetE6_ParentIDAndE6_ParentTableCodeTogether(consol.CostSupporter.PK, consol.CostSupporter.Type);
			cost1.E6_AC_ChargeCode = helper.FRT.PK;
			cost1.E6_AT_TaxRate = taxRate.PK;
			cost1.E6_OSCostAmount = amtExTax;
			cost1.E6_OSGSTAmount_Calc = taxAmt;
			cost1.E6_ApportionmentMethod = "GWT";
			cost1.SetIsUsedForApportionment();
			invoice1.ImportSingleCost(cost1, (InvoicingLineBase)invoice1.Lines.AddNew());
			invoice1.SetContext(BusinessContext.ImportMultipleInvoicesWithSameTransformer);
			return invoice1;
		}

