		void AssertWIPIsCreatedForConsolCostPostingWhenAZeroCostChargeExists(bool enableNegativeAccrualBehaviors)
		{
			AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, enableNegativeAccrualBehaviors);

			var consol = TestObjectCreator.CreateConsol("AUSYD", "NZAKL", "C0001");
			var shipment = TestObjectCreator.CreateShipment("S001", consol);
			var job = TestObjectCreator.CreateJob(shipment, false);
			var margin100ChargeCode = TestObjectCreator.CC4;
			var originalSellAmount = 10m;
			var charge = TestObjectCreator.CreateCharge(job, margin100ChargeCode, 0, originalSellAmount);
			charge.JR_GE = TestObjectCreator.FESDepartment.PK;
			Factory.Save();

			var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), "INV1", organisation: TestObjectCreator.Creditor1);
			var postedAmount = 100;
			var consolCost = TestObjectCreator.CreateConsolCost(invoice, consol, margin100ChargeCode, postedAmount);
			consolCost.IsFinal = false;
			consolCost.ApportionmentCharges[0].JR_GE = charge.JR_GE;
			invoice.ImportAllApportionmentsFromCosting();

			AssertEquals("Precondition: AC_MarginPercentage", 100M, margin100ChargeCode.AC_MarginPercentage);
			AssertEquals("Precondition: charge code on a line", margin100ChargeCode.PK, invoice.Lines[0].AL_AC);
			AssertEquals("Precondition: charge code on a charge", margin100ChargeCode.PK, charge.JR_AC);
			AssertEquals("Precondition: Lines.Count", 1, invoice.Lines.Count);
			AssertEquals("Precondition: charge cost amount", 0m, charge.JR_LocalCostAmt);
			AssertEquals("Precondition: job charges count", 1, job.Charges.Count);

			GetTransformer(Factory).Transform(invoice);

			var charges = job.Charges.Cast<Charge>().OrderBy(x => x.JR_DisplaySequence).ToArray();
			AssertEquals("Postcondition: job charges count", 2, charges.Length);
			AssertCostChargeValues(charges[0], margin100ChargeCode, charge.JR_Desc, null, false, TestObjectCreator.AUD, 1, 0, 0, null, 0, null, 0, ZString.Empty);
			AssertCostChargeValues(charges[1], margin100ChargeCode, margin100ChargeCode.AC_Desc, TestObjectCreator.Creditor1, true, TestObjectCreator.AUD, 1, postedAmount, postedAmount, TestObjectCreator.GSTFREE1, 0, TestObjectCreator.WHTFREE1, 0, invoice.AH_TransactionNum);
			var expectedSellAmount = postedAmount + originalSellAmount;
			AssertSellChargeValues(charges[0], margin100ChargeCode, charge.JR_Desc, null, false, TestObjectCreator.AUD, 1, expectedSellAmount, expectedSellAmount, null, 0, null, 0);
		}

