		}

		void AssertConsolCostPosting_CarryForwardPostings(bool isCostGreaterThanAccrual, bool isManualJobAccrual, bool shouldCreateWIP = false, bool shouldCreateAccrual = false)
		{
			Assert("Precondition: shouldCreateWIP and shouldCreateAccrual cannot both be true", !shouldCreateWIP || !shouldCreateAccrual);
			AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsGreaterThanAccrual.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);

			var consol = TestObjectCreator.CreateConsol("AUSYD", "NZAKL", "C0001");
			var shipment = TestObjectCreator.CreateShipment("S001", consol);
			var job = TestObjectCreator.CreateJob(shipment, false);
			AssertEquals("Precondition: job charges count", 0, job.Charges.Count);

			AccChargeCode chargeCode;
			if (isManualJobAccrual)
			{
				chargeCode = TestObjectCreator.CreateChargeCode("MJA3", "Manual Job Accrual Charge Code", Core.Constants.ChargeType.ManualJobAccrual, 0, TestObjectCreator.GSTFREE1, TestObjectCreator.WHTFREE1);
			}
			else
			{
				chargeCode = TestObjectCreator.CC4;
			}

			var originalCostAmount = 120m;
			var originalSellAmount = 140m;
			var originalConsolCost = TestObjectCreator.CreateConsolCost(consol, chargeCode, originalCostAmount);
			Factory.Save();

			AssertEquals("Precondition: job charges count", 1, job.Charges.Count);
			var charge = job.Charges[0];
			charge.JR_OSSellAmt = originalSellAmount;
			charge.JR_GE = TestObjectCreator.FESDepartment.PK;

			var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), "INV1", organisation: TestObjectCreator.Creditor1);
			var differenceInCost = 50m;
			var postedAmount = isCostGreaterThanAccrual ? originalCostAmount + differenceInCost : originalCostAmount - differenceInCost;
			var consolCost = TestObjectCreator.CreateConsolCost(invoice, consol, chargeCode, postedAmount);
			consolCost.IsFinal = false;
			consolCost.ApportionmentCharges[0].JR_GE = charge.JR_GE;
			invoice.ImportAllApportionmentsFromCosting();

			AssertEquals("Precondition: charge code on a line", chargeCode.PK, invoice.Lines[0].AL_AC);
			AssertEquals("Precondition: charge code on a charge", chargeCode.PK, charge.JR_AC);
			AssertEquals("Precondition: Lines.Count", 1, invoice.Lines.Count);
			AssertEquals("Precondition: charge cost amount", originalCostAmount, charge.JR_LocalCostAmt);
			AssertEquals("Precondition: job charges count", 1, job.Charges.Count);

			GetTransformer(Factory).Transform(invoice);
			Factory.Save();

			job.Charges.Reload(true);
			var charges = job.Charges.Cast<Charge>().OrderBy(x => x.JR_DisplaySequence).ToArray();
			var expectedChargesCount = (shouldCreateAccrual || shouldCreateWIP) ? 2 : 1;

			AssertEquals("Postcondition: job charges count", expectedChargesCount, charges.Length);

			var originalChargeIndex = 0;

			if (shouldCreateWIP)
			{
				AssertCostChargeValues(charges[1], chargeCode, charge.JR_Desc, null, false, TestObjectCreator.AUD, 1, 0, 0, null, 0, null, 0, ZString.Empty);
				AssertSellChargeValues(charges[1], chargeCode, charge.JR_Desc, null, false, TestObjectCreator.AUD, 1, differenceInCost, differenceInCost, null, 0, null, 0);
			}
			else if (shouldCreateAccrual)
			{
				originalChargeIndex = 1;

				AssertCostChargeValues(charges[0], chargeCode, charge.JR_Desc, TestObjectCreator.Creditor1, false, TestObjectCreator.AUD, 1, differenceInCost, differenceInCost, TestObjectCreator.GSTFREE1, 0, TestObjectCreator.WHTFREE1, 0, ZString.Empty);
				AssertSellChargeValues(charges[0], chargeCode, charge.JR_Desc, null, false, TestObjectCreator.AUD, 1, 0, 0, null, 0, null, 0);
			}

			AssertCostChargeValues(charges[originalChargeIndex], chargeCode, chargeCode.AC_Desc, TestObjectCreator.Creditor1, true, TestObjectCreator.AUD, 1, postedAmount, postedAmount, TestObjectCreator.GSTFREE1, 0, TestObjectCreator.WHTFREE1, 0, invoice.AH_TransactionNum);
			AssertSellChargeValues(charges[originalChargeIndex], chargeCode, chargeCode.AC_Desc, null, false, TestObjectCreator.AUD, 1, originalSellAmount, originalSellAmount, null, 0, null, 0);
		}

