		[DisableZeroExchangeRateOverriding]
		public void TestSetJobExRateForNewCurrencyForConsolCostPosting()
		{
			var consol = TestObjectCreator.CreateConsol("AUSYD", "NZAKL", "C001");
			var shipment = TestObjectCreator.CreateShipment("S001", consol);
			Job job = TestObjectCreator.CreateJob(shipment, false);
			var expectedCurrency = TestObjectCreator.GBP;
			ZDecimal defaultExRate = 1.2;
			TestObjectCreator.CreateExchangeRate(expectedCurrency, defaultExRate);

			var tempJobExRateToCheckSetup = job.ExchangeRates.AddNew();
			tempJobExRateToCheckSetup.JF_RX_NKRateCurrency = expectedCurrency.RX_Code;
			AssertEquals("Precondition: JF_BaseRate", defaultExRate, tempJobExRateToCheckSetup.JF_BaseRate);
			tempJobExRateToCheckSetup.Delete();

			Factory.Save();

			APInvoice invoice = TestObjectCreator.CreateAPInvoice<APInvoice>("001", TestObjectCreator.AUD, 1.0m, 100.00m, 10.00m, 0.00m, 100.00m, 10.00m, 0.00m);
			invoice.Lines.RemoveAndDeleteAll();
			JobConsolCost consolCost = invoice.ConsolCosting.ConsolCosts.AddNew();
			consolCost.E6_AC_ChargeCode = TestObjectCreator.CC1.PK;
			consolCost.SetE6_ParentIDAndE6_ParentTableCodeTogether(consol.PK, consol.TablePrefix);
			consolCost.E6_RX_NKCurrency = expectedCurrency.RX_Code;
			AssertEquals("Precondition: E6_ExchangeRate", defaultExRate, consolCost.E6_ExchangeRate);
			ZDecimal expectedExRate = 2;
			AssertNotEquals("Precondition: E6_ExchangeRate", expectedExRate, defaultExRate);
			consolCost.E6_ExchangeRate = expectedExRate;
			consolCost.E6_OSCostAmount = 100.00m;
			consolCost.E6_ApportionmentMethod = AllocationMethod.Shipment;
			consolCost.IsFinal = false;

			AssertEquals("Precondition: ApportionmentCharges.Count", 1, consolCost.ApportionmentCharges.Count);

			invoice.ImportAllApportionmentsFromCosting();

			AssertEquals("Precondition: Lines.Count", 1, invoice.Lines.Count);
			AssertEquals("Precondition: AL_ExchangeRate", expectedExRate, invoice.Lines[0].AL_ExchangeRate);
			AssertEquals("Precondition: ExchangeRates.Count", 0, job.ExchangeRates.Count);

			GetTransformer(Factory).Transform(invoice);

			AssertEquals("Exchange Rates for cost and revenue should be created", 2, job.ExchangeRates.Count);
			AssertEquals("Cost Exchange Rate should be equal to the consol cost one", expectedExRate, job.ExchangeRates[0].JF_BaseRate);
			AssertEquals("Sell Exchange Rate should be defaulted from configuration", defaultExRate, job.ExchangeRates[1].JF_BaseRate);
		}

