		void AssertJR_EstimatedCostRecalculatedOnDifferentCurrencyPost_ConsolCost(bool withZeroEstCost = false)
		{
			var newFactory = new BusinessObjectFactory();
			var testObjectCreatorInNewFactory = new TestObjectCreator(newFactory);
			var consolInNewFactory = testObjectCreatorInNewFactory.CreateConsol("AUSYD", "USLAX", "C001");
			var shipmentInNewFactory = testObjectCreatorInNewFactory.CreateShipment("S001", consolInNewFactory);
			var jobInNewFactory = testObjectCreatorInNewFactory.CreateJob(shipmentInNewFactory, createWithMutex: false);
			var consolCostInNewFactory = testObjectCreatorInNewFactory.CreateConsolCost(consolInNewFactory, CC1, GBP, 1.5, 100);
			newFactory.Save();
			if (withZeroEstCost)
			{
				jobInNewFactory.Charges[0].JR_EstimatedCost = 0;
				newFactory.Save();
			}

			AssertEquals("Precondition: Charges.Count", 1, jobInNewFactory.Charges.Count);
			var chargeInNewFactory = jobInNewFactory.Charges[0];
			AssertEquals("Precondition: JR_EstimatedCost", withZeroEstCost ? 0 : 150m, chargeInNewFactory.JR_EstimatedCost);
			AssertEquals("Precondition: JR_RX_NKCostCurrency", "GBP", chargeInNewFactory.JR_RX_NKCostCurrency);
			Assert("Precondition: isCostPosted", !chargeInNewFactory.IsCostPosted);

			var job = Factory.Load<Job>(jobInNewFactory.PK);
			var consol = Factory.Load<ForwardingConsol>(consolInNewFactory.PK);
			var invoice = CreateAPInvoice("Z1000", Creditor1, USD, 1.2M, "Invoice Z1000");
			var invoiceConsolCost = TestObjectCreator.CreateConsolCost(invoice, consol, CC1, 50);
			invoice.ImportAllApportionmentsFromCosting();
			GetTransformer(Factory).Transform(invoice);

			AssertEquals("Charges.Count", 1, job.Charges.Count);
			var charge = job.Charges[0];
			Assert("Postcondition: isCostPosted", charge.IsCostPosted);
			Assert("Postcondition: JR_IsApportioned", charge.JR_IsApportioned);
			AssertEquals("Postcondition: JR_OSCostAmt", 50m, charge.JR_OSCostAmt);
			AssertEquals("Postcondition: JR_RX_NKCostCurrency", "USD", charge.JR_RX_NKCostCurrency);
			AssertEquals("JR_EstimatedCost", withZeroEstCost ? 0 : 120m, charge.JR_EstimatedCost);
		}

