		public void TestPopulateCostsAndChargesToSearchCorrectAmountOfDbHits()
		{
			AccTaxRate gSTRate = TestObjectCreator.CreateTaxRate("GST10", "GST 10 Percent", 10);
			AccChargeCode disbursementChargeCode = TestObjectCreator.CreateChargeCode("DSB", "Description", Core.Constants.ChargeType.Disbursement, 100.00m, gSTRate, null, "ALL");

			ForwardingConsol consol = Factory.NewWithValidTestData<ForwardingConsol>();
			Factory.Save();
			ForwardingShipment shipment1 = consol.Shipments.AddNew();
			ForwardingShipment shipment2 = consol.Shipments.AddNew();

			ApportionmentListing apps = new ApportionmentListing(Factory, consol);
			JobConsolCost cost = apps.CostsCollection.TryAddNew();
			cost.E6_AC_ChargeCode = disbursementChargeCode.PK;
			cost.E6_RX_NKCurrency = AUD.RX_Code;
			cost.E6_OSCostAmount = 100m;
			cost.E6_ApportionmentMethod = "SHP";

			JobConsolCost cost2 = apps.CostsCollection.TryAddNew();
			cost2.E6_AC_ChargeCode = disbursementChargeCode.PK;
			cost2.E6_RX_NKCurrency = AUD.RX_Code;
			cost2.E6_OSCostAmount = 50m;
			cost2.E6_ApportionmentMethod = "SHP";

			Charge shipmentLevelCharge = ((Job)shipment1.Job).Charges.AddNew();
			shipmentLevelCharge.JR_AC = disbursementChargeCode.PK;
			shipmentLevelCharge.JR_OSCostAmt = 200.00m;

			Factory.Save();

			APInvoice invoice = CreateAPInvoice("Z1000", Creditor1, AUD, 1M, "Invoice Z1000");
			InvoicingLineBase line = (InvoicingLineBase)invoice.Lines.AddNew();
			CopyKeyValuesToInvoiceLine(shipmentLevelCharge.Accrual, line);
			CopyApportionmentToInvoiceLine(cost.ApportionmentCharges, invoice);
			CopyApportionmentToInvoiceLine(cost.ApportionmentCharges, invoice);

			int chargeHitsBefore = Factory.GetTableHitCount(JobChargeSchema.Constants.TableName);
			GetTransformer(Factory).Transform(invoice);
			int chargeHitsAfter = Factory.GetTableHitCount(JobChargeSchema.Constants.TableName);
			AssertEquals("Should be two Db hit's to JobCharges", 1, chargeHitsAfter - chargeHitsBefore);
		}

		public void TestGetAssociatedChargeFilterCore_CompletingInvoice()
		{
			var invoice = CreateCompletingInvoice();
			PrepareGetAssociatedChargeFilterData(invoice, out var jobCharge1_ForJob1, out var jobCharge1_ForJob2, out var jobCharge2_ForJob2, out var jobCharge3_ForJob2, out var jobCharge4_ForJob2, out var jobCharge1_ForJob3);
			var chargeToSearch = TransactionLineJobChargeTransformer.GetChargeToSearch_ForTestOnly(invoice, invoice.Lines.OfType<InvoicingLineBase>());
			var expectedSQL = string.Format(CultureInfo.InvariantCulture, ExpectSqlForCompletingInvoice, JobConsolCostFilterPartWithAttributeName);
			AssertSqlForGetChargeToSearch(expectedSQL, TransactionLineJobChargeTransformer.SqlForGetChargeToSearch_ForTestOnly);
			AssertEquals(8, chargeToSearch.Count());
			AssertEquals("Include due to Charge's JobHeader same as InvoiceLine's JobHeader", 2, chargeToSearch.Count(x => x.JR_PK == jobCharge1_ForJob1.PK));
			AssertEquals("Include due to Charge is linked with an incomplete invoice (via INV JobChargeAttrib) and linked to OriginalCharge", 2, chargeToSearch.Count(x => x.JR_PK == jobCharge2_ForJob2.PK));
			AssertEquals("Include due to Charge is NOT linked with an incomplete invoice (no INV JobChargeAttrib) and linked to OriginalCharge", 2, chargeToSearch.Count(x => x.JR_PK == jobCharge3_ForJob2.PK));
			AssertEquals("Include due to Charge is NOT linked with an incomplete invoice (no INV JobChargeAttrib) and NOT linked to OriginalCharge", 2, chargeToSearch.Count(x => x.JR_PK == jobCharge4_ForJob2.PK));

			AssertEquals("Not Include due to Charge is linked with an incomplete invoice (via INV JobChargeAttrib) and NOT linked to OriginalCharge", 0, chargeToSearch.Count(x => x.JR_PK == jobCharge1_ForJob2.PK));
			AssertEquals("Not include due to Charge's JobHeader is different to InvoiceLine's JobHeader", 0, chargeToSearch.Count(x => x.JR_PK == jobCharge1_ForJob3.PK));
		}

