		void PrepareApportionmentCharge(out APInvoice invoice, out ApportionSplitCharge apportionSplitCharge, out JobConsolCostAttrib jobConsolCostAttrib, bool isRelatedConsolCost)
		{
			var consol = TestObjectCreator.CreateConsol("AUSYD", "NZAKL", "C00001");

			var shipment = consol.Shipments.AddNew();
			shipment.JS_UniqueConsignRef = "S00001";
			shipment.JS_OH_Creditor = TestObjectCreator.AALSHI.PK;

			var job = new JobHeader.Loader(shipment).TryCreateWithMutex();

			var jobConsolCost = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, TestObjectCreator.AUD, 1m, 100m, TestObjectCreator.AALSHI);
			Factory.Save();

			invoice = (APInvoice)TestObjectCreator.CreateInvoice(typeof(APInvoice), "INV001", TestObjectCreator.AUD, 1M, TestObjectCreator.AALSHI);

			var importer = new InvoicingBaseBulkConsolCostImporter(invoice.ConsolCosting);
			importer.LoadConsolsCollection();
			importer.Import();
			invoice.ImportAllApportionmentsFromCosting();
			invoice.SaveAsIncomplete();

			var apportionmentCharges = jobConsolCost.ApportionmentCharges;
			AssertEquals(1, apportionmentCharges.Count);
			apportionSplitCharge = apportionmentCharges[0];

			var jobConsolCostAttribs = Factory.Load<JobConsolCostAttrib>(new ZQuery(JobConsolCostAttribSchema.E6A_E6_JobConsolCost, jobConsolCost.PK));
			AssertEquals(1, jobConsolCostAttribs.Length);
			jobConsolCostAttrib = jobConsolCostAttribs[0];

			if (!isRelatedConsolCost)
			{
				invoice.Lines.Cast<InvoicingLineBase>().ToList().ForEach(line =>
				{
					if (line.ApportionmentChargeImportedFrom?.ParentConsolCost != null)
					{
						line.ApportionmentChargeImportedFrom.ParentConsolCost.RelatedConsolCostPK = ZGuid.Empty;
					}
				});
			}
		}

