		public void TestSynchroniseCostsSuspendsInvoiceConsolCostsListChanged()
		{
			AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);

			var creator = new TestObjectCreator(Factory);
			var chargeCode = creator.CC1;
			chargeCode.AC_MarginPercentage = 80m;
			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			consol.Shipments.AddNew();

			Factory.Save();

			var apps = new ApportionmentListing(Factory, consol);
			var consolCost = apps.CostsCollection.TryAddNew();
			consolCost.E6_AC_ChargeCode = chargeCode.PK;
			consolCost.E6_OSCostAmount = -100m;

			Factory.Save();

			var apInvoice = (APInvoice)Factory.New(GetInvoiceType());
			apInvoice.SubmittedFromInvoicingForm = true;
			apInvoice.AH_OH = creator.AALSHI.PK;
			apInvoice.AH_TransactionNum = "INV1";
			apInvoice.AH_RX_NKTransactionCurrency = creator.USD.RX_Code;
			apInvoice.AH_ExchangeRate = 0.7m;
			apInvoice.AH_InvoiceDate = ZDateTime.Now;
			apInvoice.AH_DueDate = ZDateTime.Now.AddDays(2);

			var cost = apInvoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			cost.E6_AC_ChargeCode = chargeCode.PK;
			cost.E6_OSCostAmount = 100m;
			cost.E6_ApportionmentMethod = "SHP";
			apInvoice.ImportAllApportionmentsFromCosting();

			int consolConstingConsolCostsListChangedHitCount = 0;
			var consolConstingConsolCostsListChangedHandler = new ListChangedEventHandler(
				(sender, e) =>
				{ consolConstingConsolCostsListChangedHitCount++; }
			);
			((IBindingList)apInvoice.ConsolCosting.ConsolCosts).ListChanged += consolConstingConsolCostsListChangedHandler;

			GetTransformer(Factory).Transform(apInvoice);

			AssertEquals("ListChanged on Invoice.ConsolCosting.ConsolCosts should be called once", 1, consolConstingConsolCostsListChangedHitCount);
		}

		void CopyApportionmentToInvoiceLine(ApportionmentSplitChargeCollection apportionment, InvoicingBase invoice)
		{
			foreach (ApportionSplitCharge charge in apportionment)
			{
				InvoicingLineBase line = (InvoicingLineBase)invoice.Lines.AddNew();
				CopyKeyValuesToInvoiceLine(charge.Accrual, line);
			}
		}

		void CopyKeyValuesToInvoiceLine(Accrual source, InvoicingLineBase line)
		{
			line.AL_JH = source.AL_JH;
			line.AL_AC = source.AL_AC;
			line.AL_GB = source.AL_GB;
			line.AL_GE = source.AL_GE;
			line.AL_OSAmount = source.AL_OSAmount;
		}

