			invoiceCost1.ApportionmentCharges[1].JR_IsUsedForApportionment = true;

			AssertEquals(-100m, invoiceCost1.E6_OSCostAmount);
			AssertEquals(-50m, invoiceCost1.ApportionmentCharges[0].JR_OSCostAmt);
			AssertEquals(-50m, invoiceCost1.ApportionmentCharges[1].JR_OSCostAmt);

			var invoiceCost2 = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			invoiceCost2.E6_AC_ChargeCode = cC2.PK;
			invoiceCost2.E6_OSCostAmount = 200m;
