			invoiceFactory.Save();

			invoiceFactory = new BusinessObjectFactory();
			var cC1LoadedCosts = invoiceFactory.Load<JobConsolCost>(new ZQuery(JobConsolCostSchema.E6_AC_ChargeCode, creator.CC1.PK));
			AssertEquals(2, cC1LoadedCosts.Length);
		}

