		public void TestReverseAccrualsWhenPostAPInvoiceWithConsolApportionmentsToDifferentShipments()
		{
			TestObjectCreator creator = new TestObjectCreator(Factory);
			ForwardingConsol consol = Factory.New<ForwardingConsol>();
			Factory.Save();
			ForwardingShipment shipment1 = consol.Shipments.AddNew();
			ForwardingShipment shipment2 = consol.Shipments.AddNew();
			ApportionmentListing apportionments = new ApportionmentListing(Factory, consol);
			JobConsolCost legacyCost = apportionments.CostsCollection.TryAddNew();
			legacyCost.E6_AC_ChargeCode = creator.CC1.PK;
			legacyCost.E6_OSCostAmount = 10m;
			legacyCost.ApportionmentCharges[0].JR_IsUsedForApportionment = legacyCost.ApportionmentCharges[0].ShipmentInfo.PK == shipment1.PK;
			legacyCost.ApportionmentCharges[1].JR_IsUsedForApportionment = legacyCost.ApportionmentCharges[1].ShipmentInfo.PK != shipment1.PK;
			legacyCost.E6_ApportionmentMethod = ZArchitecture.Core.AllocationMethod.Shipment;
			Factory.Save();

			BaseCharge charge1 = legacyCost.ApportionmentCharges[0];
			BaseCharge charge2 = legacyCost.ApportionmentCharges[1];
			Accrual accrual1 = charge1.Accrual;
			Accrual accrual2 = charge2.Accrual;
			Job job1 = charge1.InvoicingJob;
			Job job2 = charge2.InvoicingJob;

			APInvoice invoice = (APInvoice)Factory.New(GetInvoiceType());
			invoice.AH_TransactionNum = "00001010";
			invoice.AH_OH = creator.AALSHI.PK;
			invoice.SubmittedFromInvoicingForm = true;
			JobConsolCost cost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			cost.E6_AC_ChargeCode = creator.CC1.PK;
			cost.E6_OSCostAmount = 100m;
			cost.ApportionmentCharges[0].JR_IsUsedForApportionment = cost.ApportionmentCharges[0].ShipmentInfo.PK == shipment1.PK;
			cost.ApportionmentCharges[1].JR_IsUsedForApportionment = cost.ApportionmentCharges[1].ShipmentInfo.PK == shipment1.PK;
			cost.E6_ApportionmentMethod = ZArchitecture.Core.AllocationMethod.Shipment;

			invoice.ImportAllApportionmentsFromCosting();

			try
			{
				Factory.Save();
			}
			catch
			{
			}

			job1.Charges.Reload(true);
			AssertEquals("Job1 Charge Count", 2, job1.Charges.Count);
			job2.Charges.Reload(true);
			AssertEquals("Job1 Charge Count", 1, job2.Charges.Count);

			Assert("Accrual 1 must be reversed.", accrual1.IsReversed);
			Assert("Accrual 2 must not be reversed", !accrual2.IsReversed);
			AssertEquals("Only one charge must be in Consol Cost after posting.", 1, legacyCost.ApportionmentCharges.Count);
			if (legacyCost.ApportionmentCharges[0].PK != charge1.PK)
			{
				Assert("The unused charge with nonzero Sell Amount should not be deleted.", !charge1.IsDeleted);
				AssertEquals("Cost Amount must be cleared", ZDecimal.Zero, charge1.JR_OSCostAmt);
				AssertNotEquals("Sell Amount preservs this charge from deleting", ZDecimal.Zero, charge1.JR_OSSellAmt);

				Assert("The charge must not be deleted.", !charge2.IsDeleted);
				Assert("The charge must not be posted.", !charge2.IsCostPosted);
			}
			else
			{
				Assert("The unused charge with nonzero Sell Amount should not be deleted.", !charge2.IsDeleted);
				AssertEquals("Cost Amount must be cleared", ZDecimal.Zero, charge2.JR_OSCostAmt);
				AssertNotEquals("Sell Amount preservs this charge from deleting", ZDecimal.Zero, charge2.JR_OSSellAmt);

				Assert("The charge must not be deleted.", !charge1.IsDeleted);
				Assert("The charge must not be posted.", charge1.IsCostPosted);
			}
		}

