			consolCost.E6_OSCostAmount = 100m;

			Factory.Save();

			var inv2 = Factory.New<APInvoice>();
			inv2.AH_TransactionNum = "002";
			inv2.AH_OH = TestObjectCreator.AALSHI.PK;
			inv2.SubmittedFromInvoicingForm = true;

			var cost2 = inv2.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol2); //import existing ConsolCost
			cost2.E6_AC_ChargeCode = creator.CC1.PK;
			cost2.ApportionmentCharges.Load();
			AssertEquals("Should one new charge be created", 1, cost2.ApportionmentCharges.Count);
			cost2.ApportionmentCharges[0].JR_GE = TestObjectCreator.NonCurrentDepartment.PK;
			cost2.ApportionmentCharges[0].JR_GB = TestObjectCreator.NonCurrentBranch.PK;

			inv2.ImportAllApportionmentsFromCosting();

			Factory.Save();

			var job2 = Factory.LoadTop1<Job>(new ZQuery(JobHeaderSchema.JH_ParentID, shipment2.PK).AddToFilter(JobHeaderSchema.JH_GC, GlbCompany.CurrentCompany.PK));
			AssertEquals("Charge department should be overridden", TestObjectCreator.NonCurrentDepartment.PK, job2.Charges[0].JR_GE);
			AssertEquals("Charge branch should be overridden", TestObjectCreator.NonCurrentBranch.PK, job2.Charges[0].JR_GB);
