		public void TestPostAPInvoiceWithOverriddenTaxAmountAndNewCharge()
		{
			TestObjectCreator creator = new TestObjectCreator(Factory);
			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			Job shipmentJob = Job.CreateWithMutex(Factory, shipment);
			shipmentJob.LocalChargesPK = creator.AALSHI.PK;
			shipmentJob.AgentCollectPK = creator.ABIGAS.PK;
			shipmentJob.PlugInData = shipment;
			shipmentJob.JH_GB = GlbBranch.CurrentBranch.PK;
			shipmentJob.JH_GE = GlbDepartment.CurrentDepartment.PK;
			Charge existingCharge = shipmentJob.Charges.AddNew();
			existingCharge.JR_AC = creator.CC2.PK;
			existingCharge.JR_OSCostAmt = 100m;
			existingCharge.JR_AT_CostGSTRate = creator.GST1.PK;
			AssertEquals("Tax amount should be 10", 10m, existingCharge.JR_OSCostGSTAmt_Calc);
			shipmentJob.Factory.Save();

			shipmentJob = Factory.Load<Job>(shipmentJob.PK);
			APInvoice invoice = (APInvoice)Factory.New(GetInvoiceType());
			invoice.AH_TransactionNum = "00001011";
			invoice.AH_OH = creator.AALSHI.PK;
			invoice.AH_RX_NKTransactionCurrency = creator.USD.RX_Code;
			invoice.AH_ExchangeRate = 0.78m;
			var compatibleLineType = new AccTransactionLinesCompatibilityMatrixTestHelper().GetCompatibleLineType(invoice.AH_Ledger, invoice.AH_TransactionType);
			APInvoiceLine cC1Line = creator.CreateAPInvoiceLine(invoice, shipmentJob, creator.CC1, creator.USD, 0.78m, "desc", 200m);
			cC1Line.AL_OSExTaxAmount = 140m;
			cC1Line.AL_OSTaxAmount = 20m;
			cC1Line.AL_LineType = compatibleLineType;
			APInvoiceLine cC2Line = creator.CreateAPInvoiceLine(invoice, shipmentJob, creator.CC2, creator.USD, 0.78m, "desc", 300m);
			cC2Line.AL_OSExTaxAmount = 300m;
			cC2Line.AL_OSTaxAmount = 20m;
			cC2Line.AL_LineType = compatibleLineType;

			invoice.SubmittedFromInvoicingForm = true;

			Factory.Save();

			Charge newCharge = Factory.Load<Charge>(new ZQuery(JobChargeSchema.PK, SQLComparisonOperator.NotEqual, existingCharge.PK))[0];

			AssertEquals("Should have populated one new charge onto the job", 2, shipmentJob.Charges.Count);

			AssertEquals("Should have set correct cost gst amount on existing charge", 20m, existingCharge.JR_OSCostGSTAmt_Calc);
			AssertEquals("Should have set correct cost gst amount on existing charge", 20m, newCharge.JR_OSCostGSTAmt_Calc);
		}

