		public void TestCarryForwardCorrectAmountWithOneChargeLineAndMultipleInvoiceLines()
		{
			ForwardingConsol consol = Factory.New<ForwardingConsol>();
			ForwardingShipment shipment = consol.Shipments.AddNew();
			Job shipmentJob = Job.CreateWithMutex(Factory, shipment);
			shipmentJob.PlugInData = shipment;
			shipmentJob.JH_GB = GlbBranch.CurrentBranch.PK;
			shipmentJob.JH_GE = GlbDepartment.CurrentDepartment.PK;
			Charge shipmentJobCharge1 = shipmentJob.Charges.AddNew();
			shipmentJobCharge1.JR_AC = TestObjectCreator.CC1.PK;
			shipmentJobCharge1.JR_OSCostAmt = 150m;

			Factory.Save();

			APInvoice invoice = (APInvoice)Factory.New(GetInvoiceType());
			invoice.AH_OH = TestObjectCreator.AALSHI.PK;
			invoice.AH_TransactionNum = "1324";
			APInvoiceLine line1 = (APInvoiceLine)invoice.Lines.AddNew();
			line1.AL_AC = TestObjectCreator.CC1.PK;
			line1.AL_JH = shipmentJob.PK;
			line1.AL_OSExTaxAmount = 20m;

			APInvoiceLine line2 = (APInvoiceLine)invoice.Lines.AddNew();
			line2.AL_AC = TestObjectCreator.CC1.PK;
			line2.AL_JH = shipmentJob.PK;
			line2.AL_OSExTaxAmount = 30m;

			invoice.SubmittedFromInvoicingForm = true;

			Factory.Save();

			AssertEquals("Should be 3 charges", 3, shipmentJob.Charges.Count);
			Charge line1PostedCharge = (Charge)shipmentJob.Charges.Find(new ZQuery(JobChargeSchema.JR_AL_APLine, line1.PK))[0];
			Charge line2PostedCharge = (Charge)shipmentJob.Charges.Find(new ZQuery(JobChargeSchema.JR_AL_APLine, line2.PK))[0];
			ZQuery charge3Filter = new ZQuery(JobChargeSchema.PK, SQLComparisonOperator.NotEqual, line1PostedCharge.PK);
			charge3Filter.AddToFilter(JobChargeSchema.PK, SQLComparisonOperator.NotEqual, line2PostedCharge.PK);
			Charge line3UnpostedCharge = (Charge)shipmentJob.Charges.Find(charge3Filter)[0];

			AssertEquals("Line 1 should have same cost amount as line 1", line1.AL_LineAmount, -line1PostedCharge.JR_OSCostAmt);
			AssertEquals("Line 2 should have same cost amount as line 1", line2.AL_LineAmount, -line2PostedCharge.JR_OSCostAmt);
			AssertEquals("Line 3 should have correct carry forward amount", 100m, line3UnpostedCharge.JR_OSCostAmt);
		}

		public void TestWIPNotCreatedWhenCostEntered_ManualJobAccrualChargeType()
		{
			ForwardingShipment shipment = TestObjectCreator.CreateShipment("S00001");
			Job job = TestObjectCreator.CreateJob(shipment);
			JobCharge charge1 = job.Charges.AddNew();
			charge1.JR_AC = TestObjectCreator.CC1.PK;
			charge1.JR_OSCostAmt = 100m;
			JobCharge charge2 = job.Charges.AddNew();
			charge2.JR_AC = TestObjectCreator.ManualJobAccrualChargeCode.PK;
			charge2.JR_OSCostAmt = 200m;

			APInvoice invoice = (APInvoice)TestObjectCreator.CreateInvoice(typeof(APInvoice), TestObjectCreator.AUD, 1m);
			APInvoiceLine line1 = TestObjectCreator.CreateAPInvoiceLine(invoice, job, TestObjectCreator.CC1, TestObjectCreator.AUD, 1m, "desc", 100m);
			APInvoiceLine line2 = TestObjectCreator.CreateAPInvoiceLine(invoice, job, TestObjectCreator.ManualJobAccrualChargeCode, TestObjectCreator.AUD, 1m, "desc", 200m);

			invoice.SubmittedFromInvoicingForm = true;

			Factory.Save();

			ZQuery queryForAPLine = new ZQuery(AccTransactionLinesSchema.PK, charge1.JR_AL_APLine);
			AccTransactionLines[] apLines = Factory.Load<AccTransactionLines>(queryForAPLine);
			ZQuery queryForARLine = new ZQuery(AccTransactionLinesSchema.PK, charge1.JR_AL_ARLine);
			AccTransactionLines[] arLines = Factory.Load<AccTransactionLines>(queryForARLine);

			AssertEquals("MRG Charge - Cost amount should be 100m as entered", 100m, charge1.JR_OSCostAmt);
			AssertEquals("MRG Charge - Sell amount should get set", 100m, charge1.JR_OSSellAmt);
			AssertNotEquals("MRG Charge - Accrual should get created", ZGuid.Empty, charge1.JR_AL_APLine);
			AssertEquals("MRG Charge - Line type should be ACR", TransactionLineTypes.Accrual, apLines[0].AL_LineType);
			AssertEquals("MRG Charge - Accrual should get created", 1, apLines.Length);
			AssertNotEquals("MRG Charge - WIP should get created", ZGuid.Empty, charge1.JR_AL_ARLine);
			AssertEquals("MRG Charge - WIP should get created", 1, arLines.Length);
			AssertEquals("MRG Charge - Line type should be WIP", TransactionLineTypes.WIP, arLines[0].AL_LineType);

			queryForAPLine = new ZQuery(AccTransactionLinesSchema.PK, charge2.JR_AL_APLine);
			apLines = Factory.Load<AccTransactionLines>(queryForAPLine);
			queryForARLine = new ZQuery(AccTransactionLinesSchema.PK, charge2.JR_AL_ARLine);
			arLines = Factory.Load<AccTransactionLines>(queryForARLine);

			AssertEquals("MJA Charge - Cost amount should be 200m as entered", 200m, charge2.JR_OSCostAmt);
			AssertEquals("MJA Charge - Sell amount should not get set", 0m, charge2.JR_OSSellAmt);
			AssertNotEquals("MJA Charge - Accrual should get created", ZGuid.Empty, charge2.JR_AL_APLine);
			AssertEquals("MJA Charge - Line type should be ACR", TransactionLineTypes.Accrual, apLines[0].AL_LineType);
			AssertEquals("MJA Charge - Accrual should get created", 1, apLines.Length);
			AssertEquals("MJA Charge - WIP should not get created", ZGuid.Empty, charge2.JR_AL_ARLine);
			AssertEquals("MJA Charge - WIP should not get created", 0, arLines.Length);
		}

