		void CostExRateSetWhenNoExchangeRatesExistOnJobHelper(bool isReciprocal)
		{
			var creator = new TestObjectCreator(Factory);
			var backup = creator.SetCurrentCompanyReciprocal(isReciprocal);
			try
			{
				ForwardingConsol consol = Factory.New<ForwardingConsol>();
				ForwardingShipment shipment = consol.Shipments.AddNew();
				Job shipmentJob = Job.CreateWithMutex(Factory, shipment);
				shipmentJob.LocalChargesPK = creator.AALSHI.PK;
				shipmentJob.AgentCollectPK = creator.ABIGAS.PK;
				shipmentJob.PlugInData = shipment;
				shipmentJob.JH_GB = GlbBranch.CurrentBranch.PK;
				shipmentJob.JH_GE = GlbDepartment.CurrentDepartment.PK;
				shipmentJob.Factory.Save();

				shipmentJob = Factory.Load<Job>(shipmentJob.PK);
				APInvoice invoice = (APInvoice)Factory.New(GetInvoiceType());
				invoice.AH_TransactionNum = "00001016";
				invoice.AH_OH = creator.AALSHI.PK;
				invoice.AH_RX_NKTransactionCurrency = creator.USD.RX_Code;
				invoice.AH_ExchangeRate = 0.78m;
				var compatibleLineType = new AccTransactionLinesCompatibilityMatrixTestHelper().GetCompatibleLineType(invoice.AH_Ledger, invoice.AH_TransactionType);
				APInvoiceLine cC1Line = creator.CreateAPInvoiceLine(invoice, shipmentJob, creator.CC1, creator.USD, 0.78m, "desc", 200m);
				cC1Line.Company.GC_IsReciprocal = isReciprocal;
				cC1Line.AL_OSExTaxAmount = 140m;
				cC1Line.AL_OSTaxAmount = 14m;
				cC1Line.AL_LineType = compatibleLineType;
				APInvoiceLine cC2Line = creator.CreateAPInvoiceLine(invoice, shipmentJob, creator.CC2, creator.USD, 0.78m, "desc", 200m);
				cC1Line.Company.GC_IsReciprocal = isReciprocal;
				cC2Line.AL_OSExTaxAmount = 140m;
				cC2Line.AL_OSTaxAmount = 14m;
				cC2Line.AL_LineType = compatibleLineType;

				invoice.SubmittedFromInvoicingForm = true;

				Factory.Save();

				AssertEquals("Should have populated two charges to the job", 2, shipmentJob.Charges.Count);
				Charge cC1Charge = (Charge)shipmentJob.Charges.Find(new ZQuery(JobChargeSchema.JR_AC, creator.CC1.PK))[0];
				Charge cC2Charge = (Charge)shipmentJob.Charges.Find(new ZQuery(JobChargeSchema.JR_AC, creator.CC2.PK))[0];

				AssertEquals("Should have cost ex rate same as invoice line", 0.78m, cC1Charge.JR_OSCostExRate);
				AssertEquals("Should have cost ex rate same as invoice line", 0.78m, cC2Charge.JR_OSCostExRate);
			}
			finally
			{
				creator.SetCurrentCompanyReciprocal(backup);
			}
		}

