			var invoice = newCreator.CreateAPInvoice<APInvoice>("T001", newCreator.AUD, 1m, 0m, 0m, 0m, 0m, 0m, 0m);
			var invoiceLine = newCreator.CreateAPInvoiceLine(invoice, newJob, newCreator.CC2, newCreator.AUD, 1M, "Charge Code 2", 200M);

			using (newJob.ChargesLoadSuspender.GetSuspender())
			{
				var transformer = new TransactionLineJobChargeTransformer(newFactory);
				transformer.CreateNewCharge(invoiceLine, newJob);
