			APInvoice invoice = (APInvoice)Factory.New(GetInvoiceType());
			invoice.AH_JH = job.PK;
			invoice.AH_OH = TestObjectCreator.AALSHI.PK;

			APInvoiceLine invoiceLine = (APInvoiceLine)invoice.Lines.AddNew();
			invoiceLine.AL_GE = GlbDepartment.CurrentDepartment.PK;
			invoiceLine.AL_JH = job.PK;
			invoiceLine.GenericCharge = TestObjectCreator.CC1.PK;
