			AssertCostChargeValues(job2.Charges[2], CC5, "Charge Code 5", Creditor1, true, USD, 0.7m, 150M, 214.29m, GSTFREE1, 0M, WHT1, 7.5M,
				"Z1000", ZDateTime.Today, ZDateTime.Today.AddMonths(1));
			AssertSellChargeValues(job2.Charges[2], CC5, "Charge Code 5", LocalClient, false, USD, 0.665m, 150M, 225.56m, GST1, 15M, WHTFREE1, 0M);
			AssertEquals("Newly created WIP should have Post Date from InvoiceLine", line2.AL_ReverseDate.Date, job2.Charges[2].WIP.AL_PostDate.Date);

			invoice = CreateAPInvoice("Z1001", Creditor1, USD, .7M, "Invoice Z1001");
			line1 = CreateAPInvoiceLine(invoice, job1, CC5, USD, .7M, "Charge Code 5", 200M, false);
			line2 = CreateAPInvoiceLine(invoice, job2, CC5, USD, .7M, "Charge Code 5", 150M, false);
			line1.AL_AT = GSTFREE1.PK;
			line1.AL_AW = WHT1.PK;
			line1.AL_LineType = new AccTransactionLinesCompatibilityMatrixTestHelper().GetCompatibleLineType(invoice.AH_Ledger, invoice.AH_TransactionType);
			line2.AL_AT = GSTFREE1.PK;
			line2.AL_AW = WHT1.PK;
			line1.AL_ReverseDate = ZDateTime.MinSmallDateTimeValue;
			line2.AL_ReverseDate = ZDateTime.MinSmallDateTimeValue;
			line2.AL_LineType = new AccTransactionLinesCompatibilityMatrixTestHelper().GetCompatibleLineType(invoice.AH_Ledger, invoice.AH_TransactionType);

			GetTransformer(Factory).Transform(invoice);
			Factory.Save();

			AssertEquals("Job1 Charge Count", 4, job1.Charges.Count);
			AssertEquals("Job2 Charge Count", 4, job2.Charges.Count);

			AssertEquals("Newly created WIP should have Post Date from InvoiceLine", line1.AL_PostDate.Date, job1.Charges[3].WIP.AL_PostDate.Date);
			AssertEquals("Newly created WIP should have Post Date from InvoiceLine", line2.AL_PostDate.Date, job2.Charges[3].WIP.AL_PostDate.Date);
