		public void TestCreateChargeSetsLocalDescription()
		{
			AccChargeCode chargeCode = Factory.NewWithValidTestData<AccChargeCode>();
			chargeCode.AC_ChargeType = Core.Constants.ChargeType.Margin;
			chargeCode.AC_MarginPercentage = 100m;
			chargeCode.AC_Desc = "IMPORT DUTY";
			chargeCode.AC_LocalLanguageDescription = "LOCAL IMPORT TAX";

			OrgHeader orgHeader = Factory.LoadTop1<OrgHeader>(new ZQuery(OrgHeaderSchema.OH_Code, "ABIGAS"));
			orgHeader.OH_RL_NKClosestPort = "AUBNE";

			ForwardingShipment shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_RL_NKDestination = "AUBNE";
			shipment.JS_RL_NKOrigin = "NZAKL";

			Job job = Factory.NewJobWithValidTestDataForTesting<Job>();
			job.JH_ParentID = shipment.PK;
			job.JH_OA_LocalChargesAddr = orgHeader.MainAddress.PK;
			Factory.Save();

			APInvoice invoice = (APInvoice)Factory.NewWithValidTestData(GetInvoiceType());
			APInvoiceLine line = (APInvoiceLine)invoice.Lines.AddNew();
			line.AL_AC = chargeCode.PK;
			line.AL_JH = job.PK;
			line.AL_RX_NKTransactionCurrency = GlbCompany.CurrentCompany.GC_RX_NKLocalCurrency;

			var transformer = new TransactionLineJobChargeTransformer(Factory);
			AccountingConfigurationRegistry.Instance.EnableLocalChargeCodeDescriptionDefault.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);
			job.Charges.RemoveAll();
			line.AL_Desc = "IMPORT DUTY";
			transformer.CreateNewCharge(line, job);
			AssertEquals("should be LOCAL IMPORT TAX", "LOCAL IMPORT TAX", job.Charges[0].JR_Desc);

			job.Charges.RemoveAll();
			line.AL_Desc = "LOCAL IMPORT TAX";
			transformer.CreateNewCharge(line, job);
			AssertEquals("should be LOCAL IMPORT TAX", "LOCAL IMPORT TAX", job.Charges[0].JR_Desc);

			job.Charges.RemoveAll();
			line.AL_Desc = "CUSTOMIZED DESCRIPTION";
			transformer.CreateNewCharge(line, job);
			AssertEquals("should be CUSTOMIZED DESCRIPTION", "CUSTOMIZED DESCRIPTION", job.Charges[0].JR_Desc);
		}

		#region TEST: Create New Charge JR_OSSellAmt AND JR_LocalSellAmt

		public void TestCreateNewCharge_LineAndChargeLocalAmountAreNotDifferentForSpecificExhangeRate()
		{
			Job job1 = CreateJob("Z00001000", LocalClient, 5M, null, 0M);
			Factory.Save();

			APInvoice invoice = CreateAPInvoice("Z1000", Creditor1, AUD, 1M, "Invoice Z1000");
			invoice.SubmittedFromInvoicingForm = true;

			decimal exchangeRate = 0.8964M;
			APInvoiceLine line1 = CreateAPInvoiceLine(invoice, job1, CC5, USD, exchangeRate, "Charge Code 5", 3514.09M, true);
			line1.AL_AT = GSTFREE1.PK;
			line1.AL_AW = WHTFREE1.PK;
			line1.AL_LineType = new AccTransactionLinesCompatibilityMatrixTestHelper().GetCompatibleLineType(invoice.AH_Ledger, invoice.AH_TransactionType);

			AssertEquals("AL_LocalExTaxAmount has been calculated based on exchange rate", 3920.23M, line1.AL_LocalExTaxAmount);
			AssertEquals("AL_ExchangeRate is what user entered.", exchangeRate, line1.AL_ExchangeRate);

			line1.AL_LocalExTaxAmount = 3920.22M;

			AssertEquals("Precondition: charges are not transformed yet", 0, job1.Charges.Count);
			AssertNoExceptionThrown("No exception should be thrown as Line amount and charge amount is different, because charge and line used different exchange rates.", () => Factory.Save());
			AssertEquals("Charges are transformed from invoice", 1, job1.Charges.Count);

			AssertNotEquals("While saving user entered exchange rate is changed to high-precision exchange rate", exchangeRate, line1.AL_ExchangeRate);

			AssertEquals(3920.22M, line1.AL_LocalExTaxAmount);
			//previously charge local amount was different to line local amount as when line local amount was calculated then high precision exchange rate was used, but while calculating charge local amount user entered exchange rate was used.
			AssertEquals(line1.AL_LocalExTaxAmount, job1.Charges[0].JR_LocalCostAmt);
		}

