		#region TEST: Create Wip for Final AP Invoice

		public void TestCreateWIPWhenCostIsGreaterThanAccrualWithNoAccrualButPositiveCostChargeAmount()
		{
			bool initialRegistryValue = AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsFinal.GetFallBackValueAtAllLevels(EnvProxy.Instance.CurrentCompany.PK, EnvProxy.Instance.CurrentBranch.PK, EnvProxy.Instance.CurrentDepartment.PK);
			var originalAccrualMustHaveCreditor = AccountingConfigurationRegistry.Instance.AccrualMustHaveCreditorCode.Value;
			AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsFinal.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);     // To stop creating ACR on first Factory.Save
			AccountingConfigurationRegistry.Instance.AccrualMustHaveCreditorCode.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);
			try
			{
				Job job1 = CreateJob("Z00001000", LocalClient, 0M, null, 0M);
				var rate = job1.AddCurrency(USD, ExchangeRateValidLedgerEnum.None);
				rate.JF_BaseRate = 0.7m;
				Charge job1Charge1 = CreateCharge(job1, CC5, "Desc", USD, 500m, null, USD, 0m, LocalClient);
				Charge job1Charge2 = CreateCharge(job1, CC6, "Desc", USD, 800m, null, USD, 0m, LocalClient);
				Factory.Save();

				AssertEquals("Job1 Charge Count", 2, job1.Charges.Count);
				Assert(job1Charge1.JR_AL_APLine.IsEmpty);
				Assert(job1Charge2.JR_AL_APLine.IsEmpty);

				APInvoice invoice = CreateAPInvoice("Z1000", Creditor1, USD, .7M, "Invoice Z1000");
				APInvoiceLine line1 = CreateAPInvoiceLine(invoice, job1, CC5, USD, .7M, "Charge Code 5", 200M, true);
				line1.AL_AT = GSTFREE1.PK;
				line1.AL_AW = WHTFREE1.PK;
				line1.AL_LineType = new AccTransactionLinesCompatibilityMatrixTestHelper().GetCompatibleLineType(invoice.AH_Ledger, invoice.AH_TransactionType);

				APInvoiceLine line2 = CreateAPInvoiceLine(invoice, job1, CC6, USD, .7M, "Charge Code 6", 200M, false);
				line2.AL_AT = GSTFREE1.PK;
				line2.AL_AW = WHTFREE1.PK;
				line2.AL_LineType = new AccTransactionLinesCompatibilityMatrixTestHelper().GetCompatibleLineType(invoice.AH_Ledger, invoice.AH_TransactionType);

				GetTransformer(Factory).Transform(invoice);
				AssertEquals("Job1 Charge Count", 3, job1.Charges.Count);
				Factory.Save();

				job1Charge1 = Factory.Load<Charge>(job1Charge1.PK);
				job1Charge2 = Factory.Load<Charge>(job1Charge2.PK);

				ZQuery job1Charge3Query = new ZQuery(JobChargeSchema.JR_AC, CC6.PK);
				job1Charge3Query.AddToFilter(JobChargeSchema.JR_JH, job1.PK);
				job1Charge3Query.AddToFilter(JobChargeSchema.PK, SQLComparisonOperator.NotEqual, job1Charge2.PK);
				Charge job1Charge3 = Factory.LoadTop1<Charge>(job1Charge3Query);
				AssertEquals("Carry Forward Amount Should be Correct", 857.15m, job1Charge3.JR_LocalCostAmt);

				Assert("WIP should still not be created", job1Charge1.JR_AL_ARLine.IsEmpty);
				Assert("WIP should also not be created", job1Charge2.JR_AL_ARLine.IsEmpty);
				Assert("Should be no WIP on carry forward line", job1Charge3.JR_AL_ARLine.IsEmpty);
			}
			finally
			{
				AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsFinal.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, initialRegistryValue);
				AccountingConfigurationRegistry.Instance.AccrualMustHaveCreditorCode.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, originalAccrualMustHaveCreditor);
			}
		}

