				Assert("WIP should NOT be created", job1Charge1.JR_AL_ARLine.IsEmpty);
				Assert("WIP should be created", !job1Charge2.JR_AL_ARLine.IsEmpty);
			}
			finally
			{
				AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsFinal.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, initialRegistryValue);
			}
		}

