		public void ApportionToConsol()
		{
			var creator = new TestObjectCreator(Factory);

			var consol = Factory.New<ForwardingConsol>();
			consol.JK_RL_NKLoadPort = "AUMEL";
			consol.JK_RL_NKDischargePort = "SGSIN";
			Factory.Save();
			var shipment = consol.Shipments.AddNew();

			var inv = Factory.New<APInvoice>();
			inv.AH_TransactionNum = "001";
			inv.AH_OH = creator.AALSHI.PK;
			inv.SubmittedFromInvoicingForm = true;

			var cost1 = inv.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);

			cost1.E6_AC_ChargeCode = creator.CC1.PK;
			cost1.E6_OSCostAmount = 100m;

			AssertEquals("Should be 1 charge created", 1, cost1.ApportionmentCharges.Count);
			cost1.ApportionmentCharges[0].IsFinal = true;
			AssertNull(cost1.ApportionmentCharges[0].WIP);

			inv.ImportAllApportionmentsFromCosting();
			Factory.Save();
		}

