			AssertEquals("OS: SELL amount and COST amount are same", job2.Charges[0].JR_OSCostAmt, job2.Charges[0].JR_OSSellAmt);
			AssertEquals("Local: SELL amount and COST amount are same", job2.Charges[0].JR_LocalCostAmt, job2.Charges[0].JR_LocalSellAmt);
			Assert("WIP should not be created, as cost is posted by an AP Credit Note", job2.Charges[1].JR_AL_ARLine.IsEmpty);
			AssertEquals("OS: SELL amount is Zero", 0M, job2.Charges[1].JR_OSSellAmt);
			AssertEquals("Local: SELL amount is Zero", 0M, job2.Charges[1].JR_LocalSellAmt);
		}

