		void SetupTestCreateWipforFinalAPInvoice(out APInvoice invoice, out APCreditNote creditNote, out Job job1, out Job job2)
		{
			job1 = CreateJob("Z00001000", LocalClient, 5M, null, 0M);
			job2 = CreateJob("C00001000", LocalClient, 5M, null, 0M);
			Factory.Save();

			invoice = CreateAPInvoice("Z1000", Creditor1, USD, .7M, "Invoice Z1000");
			APInvoiceLine line1 = CreateAPInvoiceLine(invoice, job1, CC5, USD, .7M, "Charge Code 5", 200M, true);
			line1.AL_AT = GSTFREE1.PK;
			line1.AL_AW = WHTFREE1.PK;
			line1.AL_LineType = new AccTransactionLinesCompatibilityMatrixTestHelper().GetCompatibleLineType(invoice.AH_Ledger, invoice.AH_TransactionType);

			APInvoiceLine line2 = CreateAPInvoiceLine(invoice, job1, CC6, USD, .7M, "Charge Code 6", 200M, false);
			line2.AL_AT = GSTFREE1.PK;
			line2.AL_AW = WHTFREE1.PK;
			line2.AL_LineType = new AccTransactionLinesCompatibilityMatrixTestHelper().GetCompatibleLineType(invoice.AH_Ledger, invoice.AH_TransactionType);

			creditNote = CreateAPCreditNote("C1000", Creditor1, USD, .7M, "Credit Note C1000");
			APCreditNoteLine creditLine1 = CreateAPCreditNoteLine(creditNote, job2, CC5, USD, .7M, "Charge Code 5", 200M, false);
			creditLine1.AL_IsFinalCharge = true;
			creditLine1.AL_AT = GSTFREE1.PK;
			creditLine1.AL_AW = WHTFREE1.PK;
			creditLine1.AL_LineType = new AccTransactionLinesCompatibilityMatrixTestHelper().GetCompatibleLineType(creditNote.AH_Ledger, creditNote.AH_TransactionType);

			APCreditNoteLine creditLine2 = CreateAPCreditNoteLine(creditNote, job2, CC6, USD, .7M, "Charge Code 6", 200M, false);
			creditLine2.AL_IsFinalCharge = false;
			creditLine2.AL_AT = GSTFREE1.PK;
			creditLine2.AL_AW = WHTFREE1.PK;
			creditLine2.AL_LineType = new AccTransactionLinesCompatibilityMatrixTestHelper().GetCompatibleLineType(creditNote.AH_Ledger, creditNote.AH_TransactionType);
		}

