		void SetupTestCreateWipforFinalAPInvoiceWithApportionedMRGCharge(RefCurrency costCurrency, out Job job1, out Job job2)
		{
			AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsFinal.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);
			AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, false);
			AccountingConfigurationRegistry.Instance.WIPMustHaveDebtorCode.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);

			var creator = new TestObjectCreator(Factory);
			var consol = Factory.New<ForwardingConsol>();
			consol.JK_RL_NKLoadPort = "AUMEL";
			consol.JK_RL_NKDischargePort = "SGSIN";
			var shipment1 = consol.Shipments.AddNew();
			var shipment2 = consol.Shipments.AddNew();
			Factory.Save();

			var invoice = Factory.New<APInvoice>();
			invoice.AH_TransactionNum = "INV 001";
			invoice.AH_OH = TestObjectCreator.AALSHI.PK;
			invoice.SubmittedFromInvoicingForm = true;

			var cost1 = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			cost1.E6_AC_ChargeCode = TestObjectCreator.CC3.PK;
			cost1.E6_OSCostAmount = 100m;
			cost1.E6_RX_NKCurrency = costCurrency.RX_Code;
			cost1.E6_ExchangeRate = 1M;

			AssertEquals("Should be 1 charge created", 2, cost1.ApportionmentCharges.Count);
			cost1.ApportionmentCharges[0].IsFinal = true;
			AssertNull(cost1.ApportionmentCharges[0].WIP);

			invoice.ImportAllApportionmentsFromCosting();

			var creditNote = Factory.New<APCreditNote>();
			creditNote.AH_TransactionNum = "INV 001";
			creditNote.AH_OH = TestObjectCreator.AALSHI.PK;
			creditNote.SubmittedFromInvoicingForm = true;

			var cost2 = creditNote.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			cost2.E6_AC_ChargeCode = TestObjectCreator.CC6.PK;
			cost2.E6_OSCostAmount = 200m;
			cost2.E6_RX_NKCurrency = costCurrency.RX_Code;
			cost2.E6_ExchangeRate = 1M;

			AssertEquals("Should be 1 charge created", 2, cost2.ApportionmentCharges.Count);
			cost2.ApportionmentCharges[0].IsFinal = true;
			AssertNull(cost2.ApportionmentCharges[0].WIP);

			creditNote.ImportAllApportionmentsFromCosting();

			job1 = Factory.Load<Job>(shipment1.InvoicingSupporter.Job.PK);
			job1.JH_OA_LocalChargesAddr = TestObjectCreator.LocalClient.Addresses[0].PK;

			job2 = Factory.Load<Job>(shipment2.InvoicingSupporter.Job.PK);
			job2.JH_OA_LocalChargesAddr = TestObjectCreator.LocalClient.Addresses[0].PK;

			AssertEquals("Charge Type : CC3", "MRG", TestObjectCreator.CC3.AC_ChargeType);
			AssertEquals("Margin % : CC3", 0M, TestObjectCreator.CC3.AC_MarginPercentage);
			AssertEquals("Charge Type : CC6", "MRG", TestObjectCreator.CC6.AC_ChargeType);
			AssertEquals("Margin % : CC6", 100M, TestObjectCreator.CC6.AC_MarginPercentage);
		}

