			line2.AL_AW = WHTFREE1.PK;

			var compatibleLineType = new AccTransactionLinesCompatibilityMatrixTestHelper().GetCompatibleLineType(invoice.AH_Ledger, invoice.AH_TransactionType);
			line1.AL_LineType = compatibleLineType;
			line2.AL_LineType = compatibleLineType;

			creditNote = CreateAPCreditNote("C1000", Creditor1, USD, .7M, "Credit Note C1000");
			APCreditNoteLine creditLine1 = CreateAPCreditNoteLine(creditNote, job2, TestObjectCreator.ManualJobAccrualChargeCode, USD, .7M, "MJA Charge", 200M, false);
			creditLine1.AL_IsFinalCharge = true;
			creditLine1.AL_AT = GSTFREE1.PK;
			creditLine1.AL_AW = WHTFREE1.PK;

			APCreditNoteLine creditLine2 = CreateAPCreditNoteLine(creditNote, job2, TestObjectCreator.ManualJobAccrualChargeCode2, USD, .7M, "MJA Charge", 200M, false);
			creditLine2.AL_IsFinalCharge = false;
			creditLine2.AL_AT = GSTFREE1.PK;
