			compatibleLineType = new AccTransactionLinesCompatibilityMatrixTestHelper().GetCompatibleLineType(creditNote.AH_Ledger, creditNote.AH_TransactionType);
			creditLine1.AL_LineType = compatibleLineType;
			creditLine2.AL_LineType = compatibleLineType;
