			AssertCostChargeValues(job1.Charges[1], CC3, "Charge Code 3", Creditor1, true, AUD, 1m, 200M, 200M, GSTFREE1, 0M, WHT1, 10M,
				"Z1000", ZDateTime.Today, ZDateTime.Today.AddMonths(1));
			AssertSellChargeValues(job1.Charges[1], CC3, "Charge Code 3", LocalClient, false, AUD, 1m, 250m, 250M, GSTFREE1, 0M, WHT1, 12.50M);
		}

