		public void TestDoNotSetChargeSellAccountIfInvalidRelatedChargeDebtor()
		{
			Job job1 = CreateJob("Z00001000", LocalClient, 5M, null, 0M);
			CreateExchangeRate(job1, USD, .7M);
			CreateCharge(job1, CC1, "Charge Code 1", AUD, 100M, null, AUD, 0M, LocalClient);
			TestObjectCreator.ZECTRA.CompanyData.OB_IsDebtor = false;

			ForwardingConsol consol = Factory.NewWithValidTestData<ForwardingConsol>();
			ForwardingShipment shipment1 = consol.Shipments.AddNew();
			Job shipment1Job = Job.CreateWithMutex(Factory, shipment1);
			shipment1Job.PlugInData = shipment1;
			shipment1Job.JH_GE = TestObjectCreator.FESDepartment.PK;

			Factory.Save();

			AccountingConfigurationRegistry.Instance.WIPMustHaveDebtorCode.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);

			APInvoice invoice = CreateAPInvoice("Z1000", Creditor1, AUD, 1M, "Invoice Z1000");
			APInvoiceLine line1 = CreateAPInvoiceLine(invoice, job1, CC3, AUD, 1M, "Charge Code 3", 200M, true);
			APInvoiceLine line2 = CreateAPInvoiceLine(invoice, job1, CC1, AUD, 1M, "Charge Code 1", 100M, true);

			JobConsolCost cost1 = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);

			cost1.E6_AC_ChargeCode = CC1.PK;
			cost1.E6_OSCostAmount = 50m;

			AssertEquals("Should be 1 charge created", 1, cost1.ApportionmentCharges.Count);
			// Set an Invalid Debtor to be pased to the Invoice Line
			cost1.ApportionmentCharges[0].JR_OH_SellAccount = ZGuid.Invalid;
			cost1.ApportionmentCharges[0].IsFinal = true;
			AssertNull(cost1.ApportionmentCharges[0].WIP);

			invoice.ImportAllApportionmentsFromCosting();

			// Set a valid Debtor to the Apportioned Charge
			cost1.ApportionmentCharges[0].JR_OH_SellAccount = LocalClient.PK;

			GetTransformer(Factory).Transform(invoice);

			AssertEquals("Job1 Charge Count", 2, job1.Charges.Count);
			AssertEquals("ShipmentJob Charge Count", 1, shipment1Job.Charges.Count);

			// Invalid Debtor PK should not be copied to the Charge
			AssertSellChargeValues(job1.Charges[0], CC1, "Charge Code 1", LocalClient, false, AUD, 1m, 0M, 0m, GST1, 0M, WHTFREE1, 0M);

			AssertSellChargeValues(job1.Charges[1], CC3, "Charge Code 3", LocalClient, false, AUD, 1m, 0m, 0M, GSTFREE1, 0M, WHT1, 0M);
			// Synchronised from Line but Invalid Debtor was not set
			AssertSellChargeValues(shipment1Job.Charges[0], CC1, "Charge Code 1", null, false, AUD, 1m, 0m, 0M, null, 0M, null, 0M);
		}

