		public void TestCostAmountGreaterThanAccrualAmountWithRegistryFlagSetAndRevenuePosted_ManualJobAccrualChargeType()
		{
			AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsGreaterThanAccrual.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);

			var job1 = CreateJob("Z00001000", LocalClient, 5M, null, 0M);
			var charge1_1 = CreateCharge(job1, TestObjectCreator.ManualJobAccrualChargeCode, "Charge Code 1 - MJA", AUD, 100M, Creditor1, AUD, 10M, LocalClient);
			var charge1_2 = CreateCharge(job1, TestObjectCreator.CC1, "Charge Code 2 - MRG", AUD, 200M, Creditor1, AUD, 300M, LocalClient);
			Factory.Save();

			var revenueInvoice = CreateARInvoice("Z10001", Creditor1, AUD, 1M, "Invoice Z10001");
			var revenueLine1 = CreateARInvoiceLine(revenueInvoice, job1, TestObjectCreator.ManualJobAccrualChargeCode, TestObjectCreator.AUD, 1m, "Charge Code 1 - MJA", 10m);
			var revenueLine2 = CreateARInvoiceLine(revenueInvoice, job1, TestObjectCreator.CC1, TestObjectCreator.AUD, 1m, "desc", 300m);

			((Posting.IReceivablesPostingCharge)charge1_1).SetRevenueTransactionLine(revenueLine1);
			((Posting.IReceivablesPostingCharge)charge1_2).SetRevenueTransactionLine(revenueLine2);

			Assert("Precondition: Revenue is posted charge1", charge1_1.IsRevenuePosted);
			Assert("Precondition: Revenue is posted charge2", charge1_2.IsRevenuePosted);

			var accrual1_1 = charge1_1.Accrual;
			var accrual1_2 = charge1_2.Accrual;

			var invoice = CreateAPInvoice("Z1000", Creditor1, AUD, 1M, "Invoice Z1000");
			var line1 = CreateAPInvoiceLine(invoice, job1, TestObjectCreator.ManualJobAccrualChargeCode, AUD, 1M, "Charge Code 1 - MJA", 120M, false);
			var line2 = CreateAPInvoiceLine(invoice, job1, TestObjectCreator.CC1, AUD, 1M, "Charge Code 2 - MRG", 240M, false);

			GetTransformer(Factory).Transform(invoice);

			AssertEquals("Accrual1_1 Reversed", true, accrual1_1.AL_ReverseDate.IsValid);
			AssertEquals("Accrual1_2 Reversed", true, accrual1_2.AL_ReverseDate.IsValid);
			AssertEquals("Job1 Charge Count", 3, job1.Charges.Count);

			var charges = job1.Charges.Cast<Charge>().OrderBy(x => x.JR_DisplaySequence).ToArray();

			AssertCostChargeValues(charges[0], TestObjectCreator.ManualJobAccrualChargeCode, "Charge Code 1 - MJA", Creditor1, true, AUD, 1m, 120M, 120M, GST1, 12M, WHTFREE1, 0M,
