		#region TEST : Update Charge If Does Exist (Single Charge With Zero Accrual)

		public void TestSingleChargeWithZeroAccrual()
		{
			bool originalCreateWIPFlag = AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsGreaterThanAccrual.GetFallBackValueAtAllLevels(EnvProxy.Instance.CurrentCompany.PK, EnvProxy.Instance.CurrentBranch.PK, EnvProxy.Instance.CurrentDepartment.PK);
			AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsGreaterThanAccrual.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, false);

			try
			{
				Job job1 = CreateJob("Z00001000", LocalClient, 5M, null, 0M);
				CreateExchangeRate(job1, USD, .7M);
				Charge emptyCharge = CreateCharge(job1, CC1, "Empty Charge", AUD, 0m, Creditor1, AUD, 0m, LocalClient);
				Factory.Save();

				APInvoice invoice = CreateAPInvoice("1", Creditor1, AUD, 1m, "Invoice 1");
				APInvoiceLine line1 = CreateAPInvoiceLine(invoice, job1, CC1, AUD, 1m, "Charge 1", 10m, false);
				line1.AL_LineType = new AccTransactionLinesCompatibilityMatrixTestHelper().GetCompatibleLineType(invoice.AH_Ledger, invoice.AH_TransactionType);

				invoice.SubmittedFromInvoicingForm = true;

				Factory.Save();

				job1.Charges.Reload();

				AssertCostChargeValues(job1.Charges[0], CC1, "Empty Charge", Creditor1, true, AUD, 1m, 10M, 10m, GST1, 1M, WHTFREE1, 0M,
					"1", ZDateTime.Today, ZDateTime.Today.AddMonths(1));
				// should create a WIP regardless of the registry flag, because there is no accrual for the charge
				AssertSellChargeValues(job1.Charges[0], CC1, "Empty Charge", LocalClient, false, AUD, 1m, 10M, 10m, GST1, 1M, WHTFREE1, 0M);
			}
			finally
			{
				AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsGreaterThanAccrual.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, originalCreateWIPFlag);
			}
		}

