		public void TestChargeExistsCostAmountInOSCurrencyGreaterThanLocalAccrualAmountWithCarryForward()
		{
			AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsGreaterThanAccrual.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);
			Job job1 = CreateJob("Z00001000", LocalClient, 5M, null, 0M);
			Charge charge1_1 = CreateCharge(job1, CC1, "Charge Code 1", AUD, 50M, null, AUD, 150M, LocalClient);
			Charge charge1_2 = CreateCharge(job1, CC2, "Charge Code 2", AUD, 50M, null, AUD, 50M, LocalClient);
			Factory.Save();

			ARInvoice revenueInvoice = CreateARInvoice("Z10001", Creditor1, AUD, 1M, "Invoice Z10001");
			ARInvoiceLine revenueLine = CreateARInvoiceLine(revenueInvoice, job1, CC2, AUD, 1M, "Charge Code 1", 50M);

			charge1_2.ReverseWIP(ZDateTime.Now);
			charge1_2.JR_AL_ARLine = revenueLine.PK;
			Factory.Save();

			AccTransactionLines accrual1_1 = charge1_1.Accrual;
			AccTransactionLines accrual1_2 = charge1_2.Accrual;

			APInvoice invoice = CreateAPInvoice("Z1000", Creditor1, USD, 0.6M, "Invoice Z1000");
			APInvoiceLine line1 = CreateAPInvoiceLine(invoice, job1, CC1, USD, 0.6M, "Charge Code 1", 40M, false);
			APInvoiceLine line2 = CreateAPInvoiceLine(invoice, job1, CC2, USD, 0.6M, "Charge Code 2", 40M, false);
			line1.AL_ReverseDate = ZDateTime.Now.AddDays(10);
			line2.AL_ReverseDate = line1.AL_ReverseDate;

			GetTransformer(Factory).Transform(invoice);

			AssertEquals("Accrual1_1 Reversed", true, accrual1_1.AL_ReverseDate.IsValid);
			AssertEquals("Accrual1_2 Reversed", true, accrual1_2.AL_ReverseDate.IsValid);
			AssertEquals("Accrual1_1 Reversed Date", line1.AL_ReverseDate.Date, accrual1_1.AL_ReverseDate.Date);
			AssertEquals("Accrual1_2 Reversed Date", line2.AL_ReverseDate.Date, accrual1_2.AL_ReverseDate.Date);
			AssertEquals("Job1 Charge Count", 3, job1.Charges.Count);

			AssertCostChargeValues(job1.Charges[0], CC1, "Charge Code 1", Creditor1, true, USD, 0.6m, 40M, 66.67m, GST1, 4M, WHTFREE1, 0M,
				"Z1000", ZDateTime.Today, ZDateTime.Today.AddMonths(1));
			AssertSellChargeValues(job1.Charges[0], CC1, "Charge Code 1", LocalClient, false, AUD, 1m, 166.67M, 166.67m, GST1, 16.67M, WHTFREE1, 0M);

			AssertCostChargeValues(job1.Charges[1], CC2, "Charge Code 2", Creditor1, true, USD, 0.6m, 40M, 66.67m, GST1, 4M, WHT1, 2M,
				"Z1000", ZDateTime.Today, ZDateTime.Today.AddMonths(1));
			AssertSellChargeValues(job1.Charges[1], CC2, "Charge Code 2", LocalClient, true, AUD, 1m, 50M, 50M, GST1, 5M, WHT1, 2.5M);

			AssertCostChargeValues(job1.Charges[2], CC2, "Charge Code 2", null, false, AUD, 1m, 0M, 0, null, 0M, null, 0M,
				ZString.Empty, ZDateTime.Empty, ZDateTime.Empty);
			AssertSellChargeValues(job1.Charges[2], CC2, "Charge Code 2", LocalClient, false, AUD, 1m, 16.67M, 16.67m, GST1, 1.67M, WHT1, 0.83M);

			line1.AL_ReverseDate = ZDateTime.MinSmallDateTimeValue;
			line2.AL_ReverseDate = line1.AL_ReverseDate;

			charge1_1.Reload();
			charge1_2.Reload();

			GetTransformer(Factory).Transform(invoice);

			AssertEquals("Accrual1_1 Reversed", true, accrual1_1.AL_ReverseDate.IsValid);
			AssertEquals("Accrual1_2 Reversed", true, accrual1_2.AL_ReverseDate.IsValid);
			AssertEquals("Accrual1_1 Reversed Date", line1.AL_PostDate.Date, accrual1_1.AL_ReverseDate.Date);
			AssertEquals("Accrual1_2 Reversed Date", line2.AL_PostDate.Date, accrual1_2.AL_ReverseDate.Date);
			AssertEquals("Job1 Charge Count", 4, job1.Charges.Count);
		}

