		public void TestCostAmountGreaterThanTotalAccrualAmountOnMultipleChargesWithRegistryFlagSetWithRevenuePosted()
		{
			AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsGreaterThanAccrual.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);

			Job job1 = CreateJob("Z00001000", LocalClient, 5M, null, 0M);
			CreateExchangeRate(job1, USD, .7M);
			Charge charge1_1 = CreateCharge(job1, CC1, "Charge Code 1", AUD, 100M, Creditor1, AUD, 150M, LocalClient);
			Charge charge1_2 = CreateCharge(job1, CC1, "Charge Code 1", AUD, 300M, Creditor1, AUD, 400M, LocalClient);
			Factory.Save();

			AccTransactionLines accrual1_1 = charge1_1.Accrual;
			AccTransactionLines accrual1_2 = charge1_2.Accrual;

			// Charge1_1.JR_AL_ARLine = Accrual1_1.PK;

			// new stuff for posting AR Charges
			InvoicingPostManager creator = new InvoicingPostManager(job1);
			TransactionCreatorHashtable transactions = creator.CreateTransactions(JobInvoicingPostingOption.LocalClient);
			Factory.Save();
			// end new stuff

			APInvoice invoice = CreateAPInvoice("Z1000", Creditor1, AUD, 1M, "Invoice Z1000");
			APInvoiceLine line1 = CreateAPInvoiceLine(invoice, job1, CC1, AUD, 1M, "Charge Code 1", 600M, false);
			line1.AL_ReverseDate = ZDateTime.Now.AddDays(10);

			GetTransformer(Factory).Transform(invoice);

			AssertEquals("Accrual1_1 Reversed", true, accrual1_1.AL_ReverseDate.IsValid);
			AssertEquals("Accrual1_2 Reversed", true, accrual1_2.AL_ReverseDate.IsValid);
			AssertEquals("Accrual1_1 Reversed Date", line1.AL_ReverseDate.Date, accrual1_1.AL_ReverseDate.Date);
			AssertEquals("Accrual1_2 Reversed Date", line1.AL_ReverseDate.Date, accrual1_2.AL_ReverseDate.Date);
			AssertEquals("WIP has been created", false, job1.Charges[2].IsRevenuePosted);
			AssertEquals("Charge Count", 3, job1.Charges.Count);
			AssertEquals("WIP has been created with valid Charge Code", true, job1.Charges[2].JR_AC.IsValid);

			Assert("Charge Code for Job Charge should not be empty.", !job1.Charges[0].JR_AC.IsEmpty);
			Assert("Charge Code for Job Charge should not be empty.", !job1.Charges[1].JR_AC.IsEmpty);

			AssertCostChargeValues(charge1_1, CC1, "Charge Code 1", Creditor1, true, AUD, 1m, 600m, 600m, GST1, 60M, WHTFREE1, 0M,
				"Z1000", ZDateTime.Today, ZDateTime.Today.AddMonths(1));
			AssertSellChargeValues(charge1_1, CC1, "Charge Code 1", LocalClient, true, AUD, 1m, 150m, 150M, GST1, 15M, WHTFREE1, 0M, LocalClient.MainAddress);

			AssertCostChargeValues(charge1_2, CC1, "Charge Code 1", null, false, AUD, 1m, 0, 0, null, 0M, null, 0M,
				"", ZDateTime.Empty, ZDateTime.Empty);
			AssertSellChargeValues(charge1_2, CC1, "Charge Code 1", LocalClient, true, AUD, 1m, 400m, 400M, GST1, 40M, WHTFREE1, 0M, LocalClient.MainAddress);

			charge1_1.Reload(); //Reload Charges to make them unposted again.
			charge1_2.Reload();

			line1.AL_ReverseDate = ZDateTime.MinSmallDateTimeValue;

			GetTransformer(Factory).Transform(invoice);

			AssertEquals("Accrual1_1 Reversed", true, accrual1_1.AL_ReverseDate.IsValid);
			AssertEquals("Accrual1_2 Reversed", true, accrual1_2.AL_ReverseDate.IsValid);
			AssertEquals("Accrual1_1 Reversed Date", line1.AL_PostDate.Date, accrual1_1.AL_ReverseDate.Date);
			AssertEquals("Accrual1_2 Reversed Date", line1.AL_PostDate.Date, accrual1_2.AL_ReverseDate.Date);
			AssertEquals("Charge Count", 4, job1.Charges.Count);
		}

