			AssertEquals("Invoice Date should be set on charge", invoice.AH_InvoiceDate.Date, loadedCharge1.JR_APInvoiceDate.Date);
			AssertEquals("Document Received Date should be set on charge", invoice.AH_DocumentReceivedDate.Date, loadedCharge1.JR_APDocumentReceivedDate.Date);
			AssertEquals("Payment Date should be set on charge", invoice.AH_DueDate.Date, loadedCharge1.JR_PaymentDate.Date);
			AssertEquals("Creditor should be set on charge", invoice.AH_OH, loadedCharge1.JR_OH_CostAccount);
			AssertEquals("Supplier Cost Reference should be set on charge", invoice.AH_ChequeOrReference, loadedCharge1.JR_CostReference);

			AssertNotNull("Should have AP line", loadedCharge2.APLine);
			Assert("Should be FK to one of the lines in the invoice", invoice.Lines.Contains(loadedCharge2.APLine.PK));
			AssertEquals("Invoice Number should be set on charge", invoice.AH_TransactionNum, loadedCharge2.JR_APInvoiceNum);
			AssertEquals("Invoice Date should be set on charge", invoice.AH_InvoiceDate.Date, loadedCharge2.JR_APInvoiceDate.Date);
			AssertEquals("Document Received Date should be set on charge", invoice.AH_DocumentReceivedDate.Date, loadedCharge2.JR_APDocumentReceivedDate.Date);
			AssertEquals("Payment Date should be set on charge", invoice.AH_DueDate.Date, loadedCharge2.JR_PaymentDate.Date);
			AssertEquals("Creditor should be set on charge", invoice.AH_OH, loadedCharge2.JR_OH_CostAccount);
			AssertEquals("Supplier Cost Reference should be set on charge", invoice.AH_ChequeOrReference, loadedCharge2.JR_CostReference);

			AssertNotNull("Should have AP line", loadedCharge3.APLine);
			Assert("Should be FK to one of the lines in the invoice", invoice.Lines.Contains(loadedCharge3.APLine.PK));
			AssertEquals("Invoice Number should be set on charge", invoice.AH_TransactionNum, loadedCharge3.JR_APInvoiceNum);
			AssertEquals("Invoice Date should be set on charge", invoice.AH_InvoiceDate.Date, loadedCharge3.JR_APInvoiceDate.Date);
			AssertEquals("Document Received Date should be set on charge", invoice.AH_DocumentReceivedDate.Date, loadedCharge3.JR_APDocumentReceivedDate.Date);
			AssertEquals("Payment Date should be set on charge", invoice.AH_DueDate.Date, loadedCharge3.JR_PaymentDate.Date);
			AssertEquals("Creditor should be set on charge", invoice.AH_OH, loadedCharge3.JR_OH_CostAccount);
			AssertEquals("Supplier Cost Reference should be set on charge", invoice.AH_ChequeOrReference, loadedCharge3.JR_CostReference);
		}

		public void TestUpdateChargesWithApportionmentRelatedChargesFromPositiveAndNegativeCreditNote()
		{
			AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, false);
			ForwardingConsol consol = Factory.NewWithValidTestData<ForwardingConsol>();
			ForwardingShipment shipment = consol.Shipments.AddNew();
			Job job = TestObjectCreator.CreateJob(shipment);

			Charge charge = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.LocalCurrency, -90.00m, LocalClient, TestObjectCreator.LocalCurrency, 0m, null);

			Factory.Save();

			BusinessObjectFactory newFactory = new BusinessObjectFactory();
			APCreditNote creditNote = (APCreditNote)newFactory.New(GetCreditNoteType());
			creditNote.SubmittedFromInvoicingForm = true;
			creditNote.AH_OH = LocalClient.PK;
			creditNote.AH_TransactionNum = "123";

			JobConsolCost invoiceCost = creditNote.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			invoiceCost.E6_AC_ChargeCode = TestObjectCreator.CC1.PK;
			invoiceCost.E6_OSCostAmount = 200m;
			invoiceCost.E6_ApportionmentMethod = "SHP";

			invoiceCost = creditNote.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			invoiceCost.E6_AC_ChargeCode = TestObjectCreator.CC1.PK;
			invoiceCost.E6_OSCostAmount = -90m;
			invoiceCost.E6_ApportionmentMethod = "SHP";
			creditNote.ImportAllApportionmentsFromCosting();

			newFactory.Save();

			AssertEquals(3, job.Charges.Count);

			Charge charge1 = newFactory.Load<Charge>(job.Charges[0].PK);
			Charge charge2 = newFactory.Load<Charge>(job.Charges[1].PK);
			Charge charge3 = newFactory.Load<Charge>(job.Charges[2].PK);

			AssertNotNull("Should have Accrual", charge1.Accrual);
			AssertEquals(110M, charge1.JR_OSCostAmt);

			AssertNotNull("Should have Cost or UACost", charge2.APLine);
			Assert("Should be FK to one of the lines in the invoice", creditNote.Lines.Contains(charge2.APLine.PK));
			AssertEquals(-200M, charge2.JR_OSCostAmt);

			AssertNotNull("Should have Cost or UACost", charge3.APLine);
			Assert("Should be FK to one of the lines in the invoice", creditNote.Lines.Contains(charge3.APLine.PK));
			AssertEquals(90M, charge3.JR_OSCostAmt);
		}

