		public void TestNewApportionmentOnInvoiceUsingUpdatingChargeLine()
		{
			ForwardingConsol consol = Factory.NewWithValidTestData<ForwardingConsol>();
			ForwardingShipment shipment1 = consol.Shipments.AddNew();
			ForwardingShipment shipment2 = consol.Shipments.AddNew();

			TestObjectCreator creator = new TestObjectCreator(Factory);
			AccChargeCode testCode = creator.CC1;
			Job shipment1Job = Job.CreateWithMutex(Factory, shipment1);
			Job shipment2Job = Job.CreateWithMutex(Factory, shipment2);
			shipment1Job.PlugInData = shipment1;
			shipment2Job.PlugInData = shipment2;
			shipment1Job.JH_GE = GlbDepartment.CurrentDepartment.PK;
			shipment2Job.JH_GE = GlbDepartment.CurrentDepartment.PK;
			Charge shipment2ChargeToNotMatch = shipment2Job.Charges.AddNew();
			shipment2ChargeToNotMatch.JR_AC = testCode.PK;
			shipment2ChargeToNotMatch.JR_GE = creator.NonCurrentDepartment.PK;
			shipment2ChargeToNotMatch.JR_OSCostAmt = 600.00m;

			Factory.Save();
			ZGuid localClient2PK = creator.LocalClient2.PK;
			APInvoice invoice = (APInvoice)Factory.New(GetInvoiceType());
			invoice.AH_OH = localClient2PK;
			invoice.AH_TransactionNum = "IMR1";

			var wht = creator.WHT1;
			JobConsolCost cost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			cost.E6_AC_ChargeCode = testCode.PK;
			cost.E6_OSCostAmount = 300m;
			cost.E6_ApportionmentMethod = "SHP";
			cost.E6_AW = wht.PK;
			cost.SetIsUsedForApportionment();
			invoice.ImportAllApportionmentsFromCosting();
			invoice.SubmittedFromInvoicingForm = true;

			Factory.Save();

			shipment1Job.Charges.Reload();
			shipment2Job.Charges.Reload();

			AssertEquals("Should only be 1 charge on shipment1", 1, shipment1Job.Charges.Count);
			Assert("Charge 1 should have been found and should now be indicated as posted", shipment1Job.Charges[0].IsCostPosted);
			AssertEquals("Charge 1 should have correct cost value", 150.00m, shipment1Job.Charges[0].JR_OSCostAmt);
			AssertEquals("Charge 1 should have correct withholding tax rate", wht.PK, shipment1Job.Charges[0].JR_AW_CostWHTRate);

			AssertEquals("Shipment 2 should have 2 charges", 2, shipment2Job.Charges.Count);
			Assert("Charge 2 should remain the same", !shipment2ChargeToNotMatch.IsCostPosted);
			AssertEquals("Charge 2 value should remain the same", 600.00m, shipment2ChargeToNotMatch.JR_OSCostAmt);
			AssertEquals("New charge in shipment 2 should have correct withholding tax rate", wht.PK, shipment2Job.Charges.Cast<JobCharge>().First(x => x.PK != shipment2ChargeToNotMatch.PK).JR_AW_CostWHTRate);
		}

		protected Job GetJobForShipment(ZGuid shipmentPK)
		{
			return Factory.LoadTop1<Job>(new ZQuery(JobHeaderSchema.JH_ParentID, shipmentPK).AddToFilter(JobHeaderSchema.JH_GC, GlbCompany.CurrentCompany.PK));
		}

		protected Job CreateJobWithShipment()
		{
			Job job = TestObjectCreator.CreateJob(null, 0, null, 0);
			job.PlugInData = GetShipment();
			job.JH_GB = GlbBranch.CurrentBranch.PK;
			job.JH_GE = GlbDepartment.CurrentDepartment.PK;
			return job;
		}

		protected InvoicingParam GetShipment()
		{
			InvoicingParam shipment = new InvoicingParam();
			shipment.TableName = "JobShipment";
			shipment.PK = ZGuid.NewZGuid();
			shipment.JobNumber = TestObjectCreator.GetRandomString(10);
			return shipment;
		}

