		public void TestUpdateCarryForwardCharge()
		{
			OrgHeader org = Factory.NewWithValidTestData<OrgHeader>();
			APInvoice aPInv = (APInvoice)Factory.NewWithValidTestData(GetInvoiceType());
			aPInv.AH_OH = org.PK;
			APInvoiceLine aPLine = (APInvoiceLine)aPInv.Lines.AddNew();
			Charge charge = Factory.NewWithValidTestData<Charge>();
			charge.JR_OH_CostAccount = org.PK;

			var transformer = (TransactionLineJobChargeTransformer)GetTransformer(Factory);

			var wrapper = new TransactionLineJobChargeTransformer.AmountWrapper(10m, 10m, false);
			transformer.UpdateCarryForwardCharge(aPLine, charge, wrapper, false);
			Assert("OH Cost Account of Charge should be empty", charge.JR_OH_CostAccount.IsEmpty);

			aPInv = (APInvoice)Factory.NewWithValidTestData(GetInvoiceType());
			aPInv.AH_OH = org.PK;
			aPLine = (APInvoiceLine)aPInv.Lines.AddNew();
			charge = Factory.NewWithValidTestData<Charge>();
			charge.JR_OH_CostAccount = org.PK;

			transformer = (TransactionLineJobChargeTransformer)GetTransformer(Factory);
			transformer.UpdateCarryForwardCharge(aPLine, charge, wrapper, true);
			AssertEquals("OH Cost Account of Charge should be the same as for Invoice Line", org.PK, charge.JR_OH_CostAccount);
		}

