			apportionment.E6_OSCostAmount = 100m;

			Factory.Save();

			Job job = Factory.LoadTop1<Job>(new ZQuery(JobHeaderSchema.JH_ParentID, shipment.PK).AddToFilter(JobHeaderSchema.JH_GC, GlbCompany.CurrentCompany.PK));

			AssertEquals(1, job.Charges.Count);
			AssertEquals(100m, job.Charges[0].JR_LocalCostAmt);
			AssertEquals(125m, job.Charges[0].JR_LocalSellAmt);
			AssertNull("Should be no accrual because Rev Rec set to job close", job.Charges[0].APLine);
			AssertNull("Should be no accrual because Rev Rec set to job close", job.Charges[0].ARLine);

			job.Charges[0].JR_LocalSellAmt = 500m;

			Factory.Save();

			APInvoice invoice = Factory.New<APInvoice>();
