			cost.IsFinal = false;
			cost.E6_AC_ChargeCode = chargeCode.PK;
			cost.E6_OSCostAmount = 100m;
			cost.E6_ApportionmentMethod = "SHP";
			cost.SetIsUsedForApportionment();
			invoice.ImportAllApportionmentsFromCosting();

			newFactory.Save();

			invoice = Factory.Load<APInvoice>(invoice.PK); // reload in a different factory to get AH_InvoiceDate without seconds 
			var charges = Factory.Load<JobCharge>(new ZQuery());
			AssertEquals("Should only have been one charge saved", 1, charges.Length);
			var charge = charges[0];
			AssertEquals("Cost Currency should be USD", creator.USD.RX_Code, charge.JR_RX_NKCostCurrency);
			AssertEquals("Cost should be for 100", 100m, charge.JR_OSCostAmt);
			AssertEquals("Local cost should be the same for local invoice", 142.86m, charge.JR_LocalCostAmt);
			AssertEquals("Should update creditor field", creator.AALSHI.PK, charge.JR_OH_CostAccount);
			AssertEquals("Should update invoice number field", "INV1", charge.JR_APInvoiceNum);
			AssertEquals("Should update invoice date", invoice.AH_InvoiceDate, charge.JR_APInvoiceDate);
			AssertEquals("Should update document received date", invoice.AH_DocumentReceivedDate, charge.JR_APDocumentReceivedDate);
			AssertEquals("Should update payment/due date", invoice.AH_DueDate, charge.JR_PaymentDate);
			AssertEquals("Should update supplier cost reference", invoice.AH_ChequeOrReference, charge.JR_CostReference);
			Assert("Charge should be posted", charge.IsCostPosted);

			AssertEquals("Sell Currency should be USD", creator.USD.RX_Code, charge.JR_RX_NKSellCurrency);
			AssertEquals("Should have populated sell side for 100 as well", 125m, charge.JR_OSSellAmt);
			AssertEquals("Should have populated local sell side for 100 as well", 178.57m, charge.JR_LocalSellAmt);

			var jobs = (Job[])Factory.Load(typeof(Job), new ZQuery());

			AssertEquals("Should only have 1 job", 1, jobs.Length);

			var job = jobs[0];

			AssertEquals("Job should have 2 exchange rate record (for cost and revenue)", 2, job.ExchangeRates.Count);
			var rate = job.ExchangeRates[0];
			AssertEquals("Job Should have currency ", creator.USD.RX_Code, rate.JF_RX_NKRateCurrency);
			AssertEquals("Job Should have cost exchange rate filled in", 0.7m, rate.JF_BaseRate);

			rate = job.ExchangeRates[1];
			AssertEquals("Job Should have currency ", creator.USD.RX_Code, rate.JF_RX_NKRateCurrency);
			AssertEquals("Job Should have sell exchange rate filled in", 0.7m, rate.JF_BaseRate);
		}

