			AssertEquals(-20M, loadedCharge1.JR_OSCostAmt);
			AssertEquals(-2M, loadedCharge1.JR_OSCostGSTAmt_Calc);

			AssertNotNull("Should have AP line", loadedCharge2.APLine);
