			AssertEquals("Invoice Number should be set on charge", aPCreditNote.AH_TransactionNum, loadedCharge2.JR_APInvoiceNum);
			AssertEquals("Invoice Date should be set on charge", aPCreditNote.AH_InvoiceDate.Date, loadedCharge2.JR_APInvoiceDate.Date);
			AssertEquals("Document Received Date should be set on charge", aPCreditNote.AH_DocumentReceivedDate.Date, loadedCharge2.JR_APDocumentReceivedDate.Date);
			AssertEquals("Payment Date should be set on charge", aPCreditNote.AH_DueDate.Date, loadedCharge2.JR_PaymentDate.Date);
			AssertEquals("Creditor should be set on charge", aPCreditNote.AH_OH, loadedCharge2.JR_OH_CostAccount);
			AssertEquals("Supplier Cost Reference should be set on charge", aPCreditNote.AH_ChequeOrReference, loadedCharge2.JR_CostReference);
			AssertEquals(-20M, loadedCharge2.JR_OSCostAmt);
			AssertEquals(-2M, loadedCharge2.JR_OSCostGSTAmt_Calc);

			AssertNotNull("Should have AP line", loadedCharge3.APLine);
			Assert("Should be FK to one of the lines in the invoice", aPCreditNote.Lines.Contains(loadedCharge3.APLine.PK));
			AssertEquals("Invoice Number should be set on charge", aPCreditNote.AH_TransactionNum, loadedCharge3.JR_APInvoiceNum);
			AssertEquals("Invoice Date should be set on charge", aPCreditNote.AH_InvoiceDate.Date, loadedCharge3.JR_APInvoiceDate.Date);
			AssertEquals("Document Received Date should be set on charge", aPCreditNote.AH_DocumentReceivedDate.Date, loadedCharge3.JR_APDocumentReceivedDate.Date);
			AssertEquals("Payment Date should be set on charge", aPCreditNote.AH_DueDate.Date, loadedCharge3.JR_PaymentDate.Date);
			AssertEquals("Creditor should be set on charge", aPCreditNote.AH_OH, loadedCharge3.JR_OH_CostAccount);
			AssertEquals("Supplier Cost Reference should be set on charge", aPCreditNote.AH_ChequeOrReference, loadedCharge3.JR_CostReference);
			AssertEquals(-20M, loadedCharge3.JR_OSCostAmt);
			AssertEquals(-2M, loadedCharge3.JR_OSCostGSTAmt_Calc);

			newFactory = new BusinessObjectFactory();
