			AssertEquals("E6_OSGSTAmount_Calc must be equal to JR_OSCostGSTAmtSum", cost.E6_OSGSTAmount_Calc, cost.ApportionmentCharges.JR_OSCostGSTAmtSum);
			AssertEquals("E6_OSCostAmount must be equal to -AH_InvoiceAmount", cost.E6_OSCostAmount, -aPCreditNote.AH_InvoiceAmount);
			AssertEquals("E6_OSGSTAmount_Calc must be equal to -AH_GSTAmount", cost.E6_OSGSTAmount_Calc, -aPCreditNote.AH_GSTAmount);
		}

		public void TestSynchroniseChargesWithInvoiceDoesNotRecalculateGSTWhenNegatingCreditNoteConsolCosts()
		{
			var consol = TestObjectCreator.CreateConsol("AUSYD", "NZAKL", "C00001234");
			var shipment = TestObjectCreator.CreateShipment("S00001234", consol);

			var apCreditNote = TestObjectCreator.CreateAPCreditNote("00001", TestObjectCreator.AALSHI, TestObjectCreator.AUD, 1m, "Desc");

			var cost1 = apCreditNote.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			cost1.E6_AC_ChargeCode = TestObjectCreator.CC1.PK;
			cost1.E6_OSCostAmount = 1000m;
			AssertEquals("Precondition: E6_OSGSTAmount_Calc has been calculated", 100m, cost1.E6_OSGSTAmount_Calc);
			cost1.E6_OSGSTAmount_Calc = 101m;
			cost1.E6_ApportionmentMethod = "CHG";
			cost1.SetIsUsedForApportionment();

			var cost2 = apCreditNote.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			cost2.E6_AC_ChargeCode = TestObjectCreator.CC3.PK;
			cost2.E6_OSCostAmount = 2000m;
			cost2.E6_ApportionmentMethod = "CHG";
			cost2.SetIsUsedForApportionment();

			apCreditNote.ImportAllApportionmentsFromCosting();
			apCreditNote.SubmittedFromInvoicingForm = true;

			int consolCostingConsolCostsListChangedHitCount = 0;
			var consolCostingConsolCostsListChangedHandler = new ListChangedEventHandler(
				(sender, e) =>
				{ consolCostingConsolCostsListChangedHitCount++; }
			);
			((IBindingList)apCreditNote.ConsolCosting.ConsolCosts).ListChanged += consolCostingConsolCostsListChangedHandler;

			AssertNoExceptionThrown("Should not get critical validation error due to overseas cost tax amount being recalculated to 100.00 (should stay at 101.00)",
				() => Factory.Save());

			// The 2 additional ListChanged triggers do not cause further calls to CheckForChargesDisplaySequenceDuplicates (a time-expensive function)
			AssertEquals("ListChanged on apCreditNote.ConsolCosting.ConsolCosts should be called once, then 2 more times for audit field population (2 times for 2 ConsolCosts)", 3, consolCostingConsolCostsListChangedHitCount);
			AssertEquals("E6_OSCostAmount", -1000m, cost1.E6_OSCostAmount);
			AssertEquals("E6_OSGSTAmount_Calc - should not be recalculated to 100 because it should be negated as-is", -101m, cost1.E6_OSGSTAmount_Calc);
			AssertEquals("E6_OSCostAmount", -2000m, cost2.E6_OSCostAmount);
			AssertEquals("E6_OSGSTAmount_Calc", 0m, cost2.E6_OSGSTAmount_Calc);
		}

		public void TestSynchroniseChargesWithInvoiceUpdatesGovtChargeCode()
		{
			var consol = TestObjectCreator.CreateConsol("AUSYD", "NZAKL", "C00001234");
			var shipment = TestObjectCreator.CreateShipment("S00001234", consol);
			var job = TestObjectCreator.CreateJob(shipment, TestObjectCreator.LocalClient, 0.0M, TestObjectCreator.Agent, 0.0M);
			var cost = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC2, TestObjectCreator.AALSHI, 200M, ZBool.True, "CHG");
			cost.E6_CostGovtChargeCode = "BEFORECC2";
			Factory.Save();

			var apCreditNote = TestObjectCreator.CreateAPCreditNote("00001", TestObjectCreator.AALSHI, TestObjectCreator.AUD, 1m, "Desc");

			//Created job has a matching Charge for this Cost but the job charge is not apportioned
			var cost1 = apCreditNote.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			cost1.E6_AC_ChargeCode = TestObjectCreator.CC1.PK;
			cost1.E6_OSCostAmount = 1000m;
			AssertEquals("Precondition: E6_OSGSTAmount_Calc has been calculated", 100m, cost1.E6_OSGSTAmount_Calc);
			cost1.E6_OSGSTAmount_Calc = 101m;
			cost1.E6_ApportionmentMethod = "CHG";
			cost1.E6_CostGovtChargeCode = "AFTERCC1";
			cost1.SetIsUsedForApportionment();

			//Created job has a matching Charge for this Cost and the job charge is apportioned
			var cost3 = apCreditNote.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			cost3.E6_AC_ChargeCode = TestObjectCreator.CC2.PK;
			cost3.E6_OSCostAmount = 2000m;
			cost3.E6_ApportionmentMethod = "CHG";
			cost3.E6_CostGovtChargeCode = "AFTERCC2";
			cost3.SetIsUsedForApportionment();

			//Created job does not have a matching Charge
			var cost2 = apCreditNote.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			cost2.E6_AC_ChargeCode = TestObjectCreator.CC3.PK;
			cost2.E6_OSCostAmount = 2000m;
			cost2.E6_ApportionmentMethod = "CHG";
			cost2.E6_CostGovtChargeCode = "AFTERCC3";
			cost2.SetIsUsedForApportionment();

			apCreditNote.ImportAllApportionmentsFromCosting();
			apCreditNote.SubmittedFromInvoicingForm = true;

			AssertNoExceptionThrown("Should not get critical validation error due to overseas cost tax amount being recalculated to 100.00 (should stay at 101.00)",
				() => Factory.Save());

			AssertEquals("Charge Count", 3, job.Charges.Count);
			AssertEquals("Charge 1 JR_CostGovtChargeCode", "AFTERCC2", job.Charges[0].JR_CostGovtChargeCode);
			AssertEquals("Charge 2 JR_CostGovtChargeCode", "AFTERCC1", job.Charges[1].JR_CostGovtChargeCode);
			AssertEquals("Charge 3 JR_CostGovtChargeCode", "AFTERCC3", job.Charges[2].JR_CostGovtChargeCode);
		}

		public void TestSynchroniseChargesWithInvoice_ConsolCostAndApportionmentChargesCriticalValidation()
		{
			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			consol.Shipments.AddNew();

			Factory.Save();

			var apportionments = new ApportionmentListing(Factory, consol);
			var originalCost = apportionments.CostsCollection.TryAddNew();
			originalCost.E6_AC_ChargeCode = TestObjectCreator.CC1.PK;
			originalCost.E6_OSCostAmount = 700m;

			Factory.Save();

			var invoice = (APInvoice)Factory.New(GetInvoiceType());
			invoice.SubmittedFromInvoicingForm = true;
			invoice.AH_OH = TestObjectCreator.AALSHI.PK;
			invoice.AH_TransactionNum = "INV1";
			invoice.AH_RX_NKTransactionCurrency = TestObjectCreator.USD.RX_Code;
			invoice.AH_ExchangeRate = 0.7m;
			invoice.AH_InvoiceDate = ZDateTime.Now;
			invoice.AH_DueDate = ZDateTime.Now.AddDays(2);

			var importedCost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			importedCost.E6_AC_ChargeCode = TestObjectCreator.CC1.PK;
			importedCost.E6_OSCostAmount = 700m;
			importedCost.E6_ApportionmentMethod = "SHP";
			invoice.ImportAllApportionmentsFromCosting();

			importedCost.E6_ExchangeRate = 0.8m;
			AssertEquals("Pre-condition: Original E6_LocalCostAmount", 700m, originalCost.E6_LocalCostAmount);
			AssertEquals("Pre-condition: Imported E6_LocalCostAmount", 875m, importedCost.E6_LocalCostAmount);

			GetTransformer(Factory).Transform(invoice);

			var infoCollector = CriticalValidationInfoCollectorService.GetService(Factory);
			var importedCostInfo_BeforeSync = infoCollector.GetInfo(importedCost.PK, CriticalValidationInfoCollectorServiceKeyType.ConsolCostAndApportionmentCharges_BeforeSynchroniseChargesWithInvoice);
			var importedCostInfo_AfterSync = infoCollector.GetInfo(importedCost.PK, CriticalValidationInfoCollectorServiceKeyType.ConsolCostAndApportionmentCharges_AfterSynchroniseChargesWithInvoice);
			AssertContains("E6_LocalCostAmount = 875, Sum of ApportionmentCharges JR_LocalCostAmt = 875", importedCostInfo_BeforeSync);
			AssertContains("Consol Cost: E6_OSCostAmount = 700, E6_LocalCostAmount = 875, E6_RX_NKCurrency = USD, LocalCurrency = AUD, E6_ExchangeRate = 0.8", importedCostInfo_BeforeSync);
			AssertContains("ConsolCostAndApportionmentCharges_AfterSynchroniseChargesWithInvoice: There is no data collected for this key.", importedCostInfo_AfterSync);

			var originalCostInfo_BeforeSync = infoCollector.GetInfo(originalCost.PK, CriticalValidationInfoCollectorServiceKeyType.ConsolCostAndApportionmentCharges_BeforeSynchroniseChargesWithInvoice);
			var originalCostInfo_AfterSync = infoCollector.GetInfo(originalCost.PK, CriticalValidationInfoCollectorServiceKeyType.ConsolCostAndApportionmentCharges_AfterSynchroniseChargesWithInvoice);
			AssertContains("ConsolCostAndApportionmentCharges_BeforeSynchroniseChargesWithInvoice: There is no data collected for this key.", originalCostInfo_BeforeSync);
			AssertContains("E6_LocalCostAmount = 875, Sum of ApportionmentCharges JR_LocalCostAmt = 1000", originalCostInfo_AfterSync);
			AssertContains("Consol Cost: E6_OSCostAmount = 700.0000, E6_LocalCostAmount = 875, E6_RX_NKCurrency = USD, LocalCurrency = AUD, E6_ExchangeRate = 0.8", originalCostInfo_AfterSync);
		}

