		void TestAllLinesApportionedToInAPInvoicePostedAsApportionedWithCusomDate(ZDateTime reverseDate)
		{
			GlbCompany.CurrentCompany.GC_IsWHTRegistered = true;
			TestObjectCreator creator = new TestObjectCreator(Factory);
			var wht1 = creator.WHT1;
			var creditor = creator.AALSHI;
			creditor.CompanyData.OB_APWHTApplicable = true;
			AccChargeCode chargeCode = creator.CC1;
			chargeCode.AC_MarginPercentage = 80m;
			chargeCode.AC_AW_WithholdingTaxRate = wht1.PK;

			ForwardingConsol consol = Factory.New<ForwardingConsol>();
			Factory.Save();
			ForwardingShipment shipment1 = consol.Shipments.AddNew();
			ForwardingShipment shipment2 = consol.Shipments.AddNew();
			ForwardingShipment shipment3 = consol.Shipments.AddNew();

			ApportionmentListing apps = new ApportionmentListing(Factory, consol);
			JobConsolCost cost = apps.CostsCollection.TryAddNew();
			cost.E6_AC_ChargeCode = chargeCode.PK;
			cost.E6_OSCostAmount = 100m;
			cost.E6_ApportionmentMethod = "MAN";
			cost.ApportionmentCharges[0].JR_OSCostAmt = 50m;
			cost.ApportionmentCharges[1].JR_OSCostAmt = 50m;
			cost.ApportionmentCharges[2].JR_OSCostAmt = 0m;

			Factory.Save();
			apps.ReleaseMutexes();

			BusinessObjectFactory invoiceFactory = new BusinessObjectFactory();

			APInvoice invoice = (APInvoice)invoiceFactory.New(GetInvoiceType());
			invoice.SubmittedFromInvoicingForm = true;
			invoice.AH_OH = creditor.PK;
			invoice.AH_TransactionNum = "casdrqwed";

			var wht2 = creator.WHT2;
			JobConsolCost invoiceCost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			invoiceCost.IsFinal = false;
			invoiceCost.E6_AC_ChargeCode = chargeCode.PK;
			invoiceCost.E6_AW = wht2.PK;
			invoiceCost.E6_OSCostAmount = 150m;
			invoiceCost.E6_ApportionmentMethod = "SHP";
			invoice.ImportSingleCost(invoiceCost, (InvoicingLineBase)invoice.Lines.AddNew());
			AssertEquals("Two Lines should be imported", 2, invoice.Lines.Count);
			AssertEquals(wht2.PK, invoice.Lines[0].AL_AW);
			AssertEquals(wht2.PK, invoice.Lines[1].AL_AW);

			invoice.Lines[0].AL_ReverseDate = reverseDate;
			invoice.Lines[1].AL_ReverseDate = invoice.Lines[0].AL_ReverseDate;

			invoiceFactory.Save();
			invoiceCost.CalculationStrategy.ReleaseMutexes();
			invoice.ConsolCosting.ConsolCosts[0].CalculationStrategy.ReleaseMutexes();

			invoiceFactory = new BusinessObjectFactory();

			JobConsolCost[] costs = invoiceFactory.Load<JobConsolCost>(new ZQuery());
			AssertEquals(1, costs.Length);
			AssertEquals(2, costs[0].ApportionmentCharges.Count);
			int index = 0;
			foreach (ApportionSplitCharge charge in costs[0].ApportionmentCharges)
			{
				Assert(charge.IsInDatabase);
				AssertEquals("OS withholding tax changed while importing", wht2.PK, charge.JR_AW_CostWHTRate);
				if (++index == 2)
				{
					AssertEquals("Newly created WIP should have Post Date from InvoiceLine",
						reverseDate == ZDateTime.MinSmallDateTimeValue ? invoice.Lines[1].AL_PostDate.Date : invoice.Lines[0].AL_ReverseDate.Date,
						charge.WIP.AL_PostDate.Date);
				}
			}
		}

		[DisableZeroExchangeRateOverriding]
		public void TestCreateWIPsWhenPostingFromConsol_APCreditNote_WithFinalFlag()
		{
			var creator = new TestObjectCreator(Factory);
			var chargeCode = creator.CC1;
			chargeCode.AC_MarginPercentage = 80m;
			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			consol.JK_RL_NKLoadPort = "AUMEL";
			consol.JK_RL_NKDischargePort = "SGSIN";
			var shipment = consol.Shipments.AddNew();

			Factory.Save();

			var aPCreditNote = (APCreditNote)Factory.New(GetCreditNoteType());
			aPCreditNote.SubmittedFromInvoicingForm = true;
			aPCreditNote.AH_OH = creator.AALSHI.PK;
			aPCreditNote.AH_TransactionNum = "INV1";
			aPCreditNote.AH_RX_NKTransactionCurrency = creator.USD.RX_Code;
			aPCreditNote.AH_ExchangeRate = 0.7m;
			aPCreditNote.AH_InvoiceDate = ZDateTime.Now;
			aPCreditNote.AH_DocumentReceivedDate = ZDateTime.Now;
			aPCreditNote.AH_DueDate = ZDateTime.Now.AddDays(2);
			aPCreditNote.AH_ChequeOrReference = "ABC";

			var cost = aPCreditNote.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			cost.E6_AC_ChargeCode = chargeCode.PK;
			cost.E6_OSCostAmount = 100m;
			cost.E6_ApportionmentMethod = "SHP";
			aPCreditNote.ImportAllApportionmentsFromCosting();

			Factory.Save();

			var charges = Factory.Load<JobCharge>(new ZQuery());
			AssertEquals("Should only have been one charge saved", 1, charges.Length);
			var charge = charges[0];
			AssertEquals("Cost Currency should be USD", creator.USD.RX_Code, charge.JR_RX_NKCostCurrency);
			AssertEquals("Cost should be for 100", -100m, charge.JR_OSCostAmt);
			AssertEquals("Local cost should be the same for local invoice", -142.86m, charge.JR_LocalCostAmt);
			AssertEquals("Should update creditor field", creator.AALSHI.PK, charge.JR_OH_CostAccount);
			AssertEquals("Should update invoice number field", "INV1", charge.JR_APInvoiceNum);
			AssertEquals("Should update invoice date", aPCreditNote.AH_InvoiceDate, charge.JR_APInvoiceDate);
			AssertEquals("Should update document received date", aPCreditNote.AH_DocumentReceivedDate, charge.JR_APDocumentReceivedDate);
			AssertEquals("Should update payment/due date", aPCreditNote.AH_DueDate, charge.JR_PaymentDate);
			AssertEquals("Should update supplier cost reference", aPCreditNote.AH_ChequeOrReference, charge.JR_CostReference);
			Assert("Charge should be posted", charge.IsCostPosted);

			AssertEquals("Sell Currency should be USD", creator.USD.RX_Code, charge.JR_RX_NKSellCurrency);
			AssertEquals("Should have populated sell side for 100 as well", -0m, charge.JR_OSSellAmt);
			AssertEquals("Should have populated local sell side for 100 as well", -0m, charge.JR_LocalSellAmt);

			var jobs = (Job[])Factory.Load(typeof(Job), new ZQuery());

			AssertEquals("Should only have 1 job", 1, jobs.Length);

			var job = jobs[0];

			AssertEquals("Job should have 1 exchange rate record", 2, job.ExchangeRates.Count);
			var rate = job.ExchangeRates[0];
			AssertEquals("Job Should have currency ", creator.USD.RX_Code, rate.JF_RX_NKRateCurrency);
			AssertEquals("Job Should have cost exchange rate filled in", 0.7m, rate.JF_BaseRate);

			rate = job.ExchangeRates[1];
			AssertEquals("Job Should have currency ", creator.USD.RX_Code, rate.JF_RX_NKRateCurrency);
			AssertEquals("Job Should have sell exchange rate filled in", 0.7m, rate.JF_BaseRate);
		}

