		void TestAPInvoiceApportionmentBackPostsAccrualReversalsCorrectlyWithCustomReverseDate(ZDateTime reverseDate)
		{
			TestObjectCreator creator = new TestObjectCreator(Factory);
			AccChargeCode chargeCode = creator.CC1;
			chargeCode.AC_MarginPercentage = 80m;
			ForwardingConsol consol = Factory.NewWithValidTestData<ForwardingConsol>();
			consol.Shipments.AddNew();

			Factory.Save();

			ApportionmentListing apps = new ApportionmentListing(Factory, consol);
			JobConsolCost consolCost = apps.CostsCollection.TryAddNew();
			consolCost.E6_AC_ChargeCode = chargeCode.PK;
			consolCost.E6_OSCostAmount = 100m;

			ZGuid jobPK = consolCost.ApportionmentCharges[0].JR_JH;
			Job job = Factory.Load<Job>(jobPK);

			Factory.Save();

			ZQuery accrualQuery = new ZQuery(AccTransactionLinesSchema.AL_JH, jobPK);
			accrualQuery.AddToFilter(AccTransactionLinesSchema.AL_GC, GlbCompany.CurrentCompany.PK);
			accrualQuery.AddToFilter(
					JoinCondition.And,
					AccTransactionLinesSchema.AL_LineAmount,
					100m);

			Accrual[] accruals = Factory.Load<Accrual>(accrualQuery);
			AssertEquals(1, accruals.Length);
			ZGuid accrualPK = accruals[0].PK;
			AssertEquals(100m, accruals[0].AL_LineAmount);
			AssertEquals(ZDateTime.Empty, accruals[0].AL_ReverseDate);

			ZDateTime postDate = ZDateTime.Now.AddDays(-10);

			APInvoice aPInvoice = (APInvoice)Factory.New(GetInvoiceType());
			aPInvoice.AH_PostDate = postDate;
			aPInvoice.SubmittedFromInvoicingForm = true;
			aPInvoice.AH_OH = creator.AALSHI.PK;
			aPInvoice.AH_TransactionNum = "INV1";
			aPInvoice.AH_RX_NKTransactionCurrency = creator.USD.RX_Code;
			aPInvoice.AH_ExchangeRate = 0.7m;
			aPInvoice.AH_InvoiceDate = ZDateTime.Now;
			aPInvoice.AH_DueDate = ZDateTime.Now.AddDays(2);

			JobConsolCost cost = aPInvoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			cost.E6_AC_ChargeCode = chargeCode.PK;
			cost.E6_OSCostAmount = 100m;
			cost.E6_ApportionmentMethod = "SHP";
			aPInvoice.ImportAllApportionmentsFromCosting();
			aPInvoice.Lines[0].AL_ReverseDate = reverseDate;

			Factory.Save();

			ApportionmentListing newAppCollection = new ApportionmentListing(Factory, consol);
			newAppCollection.CostsCollection.Load();
			AssertEquals(1, newAppCollection.CostsCollection.Count);

			Accrual reversedAccrual = Factory.Load<Accrual>(accrualPK);
			AssertEquals("Accrual Reversed Date", reverseDate == ZDateTime.MinSmallDateTimeValue ? postDate : aPInvoice.Lines[0].AL_ReverseDate,
				reversedAccrual.AL_ReverseDate);
		}

