		#region TEST: Bring Forward Against Creditor

		public void TestBringForwardWithMultipleChargesIfChargeForTheCreditorExists()
		{
			Job job1 = CreateJob("Z00001000", LocalClient, 0M, null, 0M);
			Charge charge1_1 = CreateCharge(job1, CC1, "Charge Code 1", AUD, 200M, null, AUD, 150M, LocalClient);
			Charge charge1_2 = CreateCharge(job1, CC1, "Charge Code 1", AUD, 100M, Creditor1, AUD, 150M, LocalClient);
			Charge charge1_3 = CreateCharge(job1, CC1, "Charge Code 1", AUD, 300M, null, AUD, 150M, LocalClient);
			Factory.Save();

			AccTransactionLines accrual1_1 = charge1_1.Accrual;
			AccTransactionLines accrual1_2 = charge1_2.Accrual;
			AccTransactionLines accrual1_3 = charge1_3.Accrual;

			APInvoice invoice = CreateAPInvoice("Z1000", Creditor1, AUD, 1M, "Invoice Z1000");
			APInvoiceLine line1 = CreateAPInvoiceLine(invoice, job1, CC1, AUD, 1M, "Charge Code 1", 80M, false);

			GetTransformer(Factory).Transform(invoice);

			AssertEquals("Accrual1_1 Reversed", true, accrual1_1.AL_ReverseDate.IsValid);
			AssertEquals("Accrual1_2 Reversed", true, accrual1_2.AL_ReverseDate.IsValid);
			AssertEquals("Accrual1_3 Reversed", true, accrual1_3.AL_ReverseDate.IsValid);

			AssertEquals("Job1 Charge Count", 4, job1.Charges.Count);

			AssertCostChargeValues(job1.Charges[0], CC1, "Charge Code 1", null, false, AUD, 1m, 500M, 500M, null, 0M, null, 0M,
				"", ZDateTime.Empty, ZDateTime.Empty);
			AssertSellChargeValues(job1.Charges[0], CC1, "Charge Code 1", LocalClient, false, AUD, 1m, 150M, 150m, GST1, 15M, WHTFREE1, 0M);

			AssertCostChargeValues(job1.Charges[1], CC1, "Charge Code 1", Creditor1, true, AUD, 1m, 80M, 80m, GST1, 8M, WHTFREE1, 0M,
				"Z1000", ZDateTime.Today, ZDateTime.Today.AddMonths(1));
			AssertSellChargeValues(job1.Charges[1], CC1, "Charge Code 1", LocalClient, false, AUD, 1m, 150M, 150m, GST1, 15M, WHTFREE1, 0M);

			AssertCostChargeValues(job1.Charges[2], CC1, "Charge Code 1", null, false, AUD, 1m, 0M, 0M, null, 0M, null, 0M,
