		#region Tests with Multiple Apportionmnet Charges with same charge code and creditor 

		/*
		 *	CCC = Number of apportioned charges WITH Creditor
		 *	CCNC = Number of apportioned charges WITHOUT Creditor
		 *	SCC = Number of unapportioned charges WITH Creditor
		 *	SCNC = Number of unapportioned charges WITHOUT Creditor
		 *	
		 *	Scenario#			CCC		CCNC	SCC		SCNC		Comment
		 *	----------------------------------------------------------------------------------------------------------------------------------------------------
				1				 1		 1		 0		 0			1 CCC have a creditor that matches with the creditor of the AP Invoice.
				2				 0		 2		 0		 0
				3				 2		 2		 0		 0			2 CCC have the same creditor as the AP Invoice.
				4				 4		 2		 0		 0			2 CCC have the same creditor as the AP Invoice. Other 2 CCC have different creditor.
				5				 2		 2		 1		 0			2 CCC have the same creditor as the AP Invoice.
				6				 2		 2		 0		 1			2 CCC have the same creditor as the AP Invoice.
				7				 4		 2		 2		 1			2 CCC have the same creditor as the AP Invoice. Other 2 CCC have different creditor.
				8				 2		 0		 1		 1			2 CCC have a creditor that doesn't match with the AP Invoice creditor. 1 SCC has the same creditor as AP Invoice.
				9				 2		 0		 0		 0			2 CCC have a creditor that doesn't match with the AP Invoice creditor.
		*/

		public void TestBringForwardMultipleApportionmentChargeWithSameChargeCodeAndCredior_Case1()
		{
			var job1 = CreateJob("Z00001001", LocalClient, 0M, null, 0M);
			var job2 = CreateJob("Z00001002", LocalClient, 0M, null, 0M);

			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			Factory.Save();
			var shipment1 = consol.Shipments.AddNew();
			var shipment2 = consol.Shipments.AddNew();

			job1.JH_ParentID = shipment1.PK;
			job2.JH_ParentID = shipment2.PK;

			var apps = new ApportionmentListing(Factory, consol);
			apps.LoadChildShipmentsAndAcquireMutexesWhereRequired();
			apps.IsActivated = true;

			AddCost(apps, 100m, Creditor1);
			AddCost(apps, 200m, null);
			Factory.Save();

			var invoiceNumber = "0000001";
			CreateAPInvoice(invoiceNumber, consol);
			Factory.Save();

			job1.Charges.Reload(true);
			job2.Charges.Reload(true);
			apps.CostsCollection.Reload(true);

			AssertEquals("Job1 Charge Count", 3, job1.Charges.Count);
			AssertCostChargeValues(job1.Charges[0], CC1, "Charge Code 1", Creditor1, true, AUD, 1m, 25m, 25m, GST1, 2.50M, WHTFREE1, 0M, invoiceNumber);
			AssertCostChargeValues(job1.Charges[1], CC1, "Charge Code 1", null, false, AUD, 1m, 100m, 100M, null, 0M, null, 0M, "");
			AssertCostChargeValues(job1.Charges[2], CC1, "Charge Code 1", Creditor1, false, AUD, 1m, 25m, 25m, GST1, 2.50m, WHTFREE1, 0M, "");

			AssertEquals("Job2 Charge Count", 3, job2.Charges.Count);
			AssertCostChargeValues(job2.Charges[0], CC1, "Charge Code 1", Creditor1, true, AUD, 1m, 25m, 25m, GST1, 2.50M, WHTFREE1, 0M, invoiceNumber);
			AssertCostChargeValues(job2.Charges[1], CC1, "Charge Code 1", null, false, AUD, 1m, 100M, 100M, null, 0M, null, 0M, "");
			AssertCostChargeValues(job2.Charges[2], CC1, "Charge Code 1", Creditor1, false, AUD, 1m, 25m, 25M, GST1, 2.50M, WHTFREE1, 0M, "");

			AssertEquals("Cost Collection", 3, apps.CostsCollection.Count);
			AssertConsolCost(apps.CostsCollection[0], CC1, 50m, Creditor1, true);
			AssertConsolCost(apps.CostsCollection[1], CC1, 200m, null, false);
			AssertConsolCost(apps.CostsCollection[2], CC1, 50m, Creditor1, false);
		}

