			AssertEquals("Job1 Charge Count", 3, job1.Charges.Count);
			AssertCostChargeValues(job1.Charges[0], CC1, "Charge Code 1", Creditor2, false, AUD, 1m, 250m, 250m, GST1, 25M, WHTFREE1, 0M, "");
			AssertCostChargeValues(job1.Charges[1], CC1, "Charge Code 1", Creditor2, false, AUD, 1m, 300m, 300m, GST1, 30M, WHTFREE1, 0M, "");
			AssertCostChargeValues(job1.Charges[2], CC1, "Charge Code 1", Creditor1, true, AUD, 1m, 25m, 25m, GST1, 2.50M, WHTFREE1, 0M, invoiceNumber);

			AssertEquals("Job2 Charge Count", 3, job2.Charges.Count);
			AssertCostChargeValues(job2.Charges[0], CC1, "Charge Code 1", Creditor2, false, AUD, 1m, 250m, 250m, GST1, 25M, WHTFREE1, 0M, "");
			AssertCostChargeValues(job2.Charges[1], CC1, "Charge Code 1", Creditor2, false, AUD, 1m, 300m, 300m, GST1, 30M, WHTFREE1, 0M, "");
			AssertCostChargeValues(job2.Charges[2], CC1, "Charge Code 1", Creditor1, true, AUD, 1m, 25m, 25m, GST1, 2.50M, WHTFREE1, 0M, invoiceNumber);

			AssertEquals("Cost Collection", 2, apps.CostsCollection.Count);
			AssertConsolCost(apps.CostsCollection[0], CC1, 500m, Creditor2, false);
			AssertConsolCost(apps.CostsCollection[1], CC1, 600m, Creditor2, false);
		}

		void AddCost(ApportionmentListing apps, ZDecimal amount, OrgHeader creditor, int? sequence = null)
		{
			var cost = apps.CostsCollection.TryAddNew();
			cost.E6_OSCostAmount = amount;
			cost.E6_AC_ChargeCode = CC1.PK;
			cost.E6_ApportionmentMethod = "SHP";
			cost.E6_OH_Creditor = creditor?.PK ?? ZGuid.Empty;
			cost.E6_Sequence = sequence ?? 0;
		}

		void AddShipmentLevelCharge(Job job, ZDecimal amount, OrgHeader creditor, short? sequence = null)
		{
			var shipmentLevelCharge = job.Charges.AddNew();
			shipmentLevelCharge.JR_AC = CC1.PK;
			shipmentLevelCharge.JR_OSCostAmt = amount;
			shipmentLevelCharge.JR_OH_CostAccount = creditor?.PK ?? ZGuid.Empty;
			shipmentLevelCharge.JR_DisplaySequence = sequence ?? 0;
		}

		void CreateAPInvoice(string invoiceNumber, ForwardingConsol consol)
		{
			var invoice = (APInvoice)Factory.New(GetInvoiceType());
			invoice.SubmittedFromInvoicingForm = true;
			invoice.AH_TransactionNum = invoiceNumber;
			invoice.AH_RX_NKTransactionCurrency = AUD.RX_Code;
			invoice.AH_OH = Creditor1.PK;

			var invoiceCost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			invoiceCost.E6_AC_ChargeCode = CC1.PK;
			invoiceCost.E6_ApportionmentMethod = "SHP";
			invoiceCost.IsFinal = false;
			invoiceCost.E6_OSCostAmount = 50m;
			invoiceCost.SetIsUsedForApportionment();
			invoice.ImportAllApportionmentsFromCosting();
		}

