		public void TestUpdateChargesForChangedApprovedInvoice()
		{
			Job job1 = CreateJob("Z00001000", LocalClient, 5M, null, 0M);
			CreateExchangeRate(job1, USD, .7M);
			Charge charge1_1 = CreateCharge(job1, CC1, "Charge Code 1", AUD, 100M, Creditor1, AUD, 150M, LocalClient);
			Charge charge1_2 = CreateCharge(job1, CC1, "Charge Code 1", AUD, 300M, null, AUD, 400M, Agent);
			Factory.Save();

			AccTransactionLines accrual1_1 = charge1_1.Accrual;
			AccTransactionLines accrual1_2 = charge1_2.Accrual;

			APInvoice invoice = CreateAPInvoice("Z1000", Creditor1, AUD, 1M, "Invoice Z1000");
			APInvoiceLine line11 = CreateAPInvoiceLine(invoice, job1, CC1, AUD, 1M, "Charge Code 1", 380M, false);
			line11.AL_ReverseDate = ZDateTime.Now.AddDays(10);
			line11.AL_AC = TestObjectCreator.CC1.PK;
			line11.AL_OSExTaxAmount = 380M;
			line11.AL_LineType = new AccTransactionLinesCompatibilityMatrixTestHelper().GetCompatibleLineType(invoice.AH_Ledger, invoice.AH_TransactionType);
			invoice.SubmittedFromInvoicingForm = true;

			invoice.Factory.Save();

			ZDateTime accrual1_1_AL_ReverseDate = accrual1_1.AL_ReverseDate;
			ZDateTime accrual1_2_AL_ReverseDate = accrual1_2.AL_ReverseDate;
			AssertEquals("Accrual1_1 Reversed", true, accrual1_1.AL_ReverseDate.IsValid);
			AssertEquals("Accrual1_2 Reversed", true, accrual1_2.AL_ReverseDate.IsValid);
			AssertEquals("Accrual1_1 Reversed Date", line11.AL_ReverseDate.Date, accrual1_1.AL_ReverseDate.Date);
			AssertEquals("Accrual1_2 Reversed Date", line11.AL_ReverseDate.Date, accrual1_2.AL_ReverseDate.Date);
			AssertEquals("Charge Count", 2, job1.Charges.Count);

			AssertCostChargeValues(charge1_1, CC1, "Charge Code 1", Creditor1, true, AUD, 1m, 380m, 380m, GST1, 38M, WHTFREE1, 0M,
				"Z1000", ZDateTime.Today, ZDateTime.Today.AddMonths(1));
			AssertSellChargeValues(charge1_1, CC1, "Charge Code 1", LocalClient, false, AUD, 1m, 150m, 150M, GST1, 15M, WHTFREE1, 0M);

			AssertCostChargeValues(charge1_2, CC1, "Charge Code 1", null, false, AUD, 1m, 20m, 20m, null, 0M, null, 0M,
				"", ZDateTime.Empty, ZDateTime.Empty);
			AssertSellChargeValues(charge1_2, CC1, "Charge Code 1", Agent, false, AUD, 1m, 400m, 400M, GST1, 40M, WHTFREE1, 0M);

			if (invoice.AH_Ledger == ZArchitecture.Core.LedgerTypes.UnapprovedPayableTransactions)
			{
				UnapprovedTransactionConverter converter = new UnapprovedTransactionConverter(Factory);
				invoice = (APInvoice)converter.ConvertToAP(invoice, false);
				invoice.AH_TransactionNum = "Z999";
				invoice.AH_OH = Creditor2.PK;
				invoice.Lines[0].AL_OSExTaxAmount = 200M;
				invoice.Lines[0].AL_LineType = new AccTransactionLinesCompatibilityMatrixTestHelper().GetCompatibleLineType(invoice.AH_Ledger, invoice.AH_TransactionType);

				invoice.Factory.Save();

				AssertEquals("Accrual1_1 Reversed", accrual1_1_AL_ReverseDate, accrual1_1.AL_ReverseDate);
				AssertEquals("Accrual1_2 Reversed", accrual1_2_AL_ReverseDate, accrual1_2.AL_ReverseDate);
				AssertEquals("Charge Count", 2, job1.Charges.Count);

				AssertCostChargeValues(charge1_1, CC1, "Charge Code 1", Creditor2, true, AUD, 1m, 200m, 200m, GST1, 20M, WHTFREE1, 0M,
					"Z999", ZDateTime.Today, ZDateTime.Today);
				AssertSellChargeValues(charge1_1, CC1, "Charge Code 1", LocalClient, false, AUD, 1m, 150m, 150M, GST1, 15M, WHTFREE1, 0M);

				AssertCostChargeValues(charge1_2, CC1, "Charge Code 1", null, false, AUD, 1m, 20m, 20m, null, 0M, null, 0M,
					"", ZDateTime.Empty, ZDateTime.Empty);
				AssertSellChargeValues(charge1_2, CC1, "Charge Code 1", Agent, false, AUD, 1m, 400m, 400M, GST1, 40M, WHTFREE1, 0M);

				invoice = CreateAPInvoice("Z8000", Creditor1, USD, 100M, "Invoice Z8000");
				UAInvoiceLine line1 = (UAInvoiceLine)invoice.Lines.AddNew();
				line1.AL_ReverseDate = ZDateTime.Now.AddDays(10);
				line1.AL_JH = job1.PK;
				line1.AL_AC = TestObjectCreator.CC1.PK;
				line1.AL_OSExTaxAmount = 100M;
				line1.AL_LineType = new AccTransactionLinesCompatibilityMatrixTestHelper().GetCompatibleLineType(invoice.AH_Ledger, invoice.AH_TransactionType);
				invoice.SubmittedFromInvoicingForm = true;
				job1.ExchangeRates[0].JF_RX_NKRateCurrency = GBP.RX_Code;
				job1.ExchangeRates[0].JF_BaseRate = 0.7m;

				invoice.Factory.Save();

				converter = new UnapprovedTransactionConverter(Factory);
				invoice = (APInvoice)converter.ConvertToAP(invoice, false);
				invoice.AH_TransactionNum = "Z666";
				invoice.AH_OH = Creditor2.PK;
				invoice.Lines[0].AL_OSExTaxAmount = 200M;
				invoice.Lines[0].AL_ExchangeRate = 112M;
				invoice.Lines[0].AL_JH = job1.PK;
				invoice.Lines[0].AL_AC = CC1.PK;
				invoice.Lines[0].AL_RX_NKTransactionCurrency = GBP.RX_Code;
				invoice.Lines[0].AL_LineType = new AccTransactionLinesCompatibilityMatrixTestHelper().GetCompatibleLineType(invoice.AH_Ledger, invoice.AH_TransactionType);

				invoice.Factory.Save();

				//AssertEquals("Buy Rate must equal to Exchange rate because IsInvoicingBaseApproving is false", 112M, Job1.ExchangeRates[0].JF_BaseRate);
			}
		}

		#region TEST: Updates Charges with Different Creditor as Invoice Creditor

		public void TestUpdatesChargesWithDifferentCreditorWithoutBringForwardWorksAsBefore()
		{
			using (AccountingConfigurationRegistry.Instance.BringForwardAgainstCreditor.SetTemporaryValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, false))
			{
				Job job1 = CreateJob("Z00001000", LocalClient, 5M, null, 0M);
				Charge charge1_1 = CreateCharge(job1, CC1, "Charge Code 1", AUD, 50M, Creditor1, AUD, 50M, LocalClient);
				Charge charge1_2 = CreateCharge(job1, CC1, "Charge Code 1", AUD, 100M, null, AUD, 100M, Agent);
				Charge charge1_3 = CreateCharge(job1, CC1, "Charge Code 1", AUD, 150M, Creditor2, AUD, 150M, Agent);
				Factory.Save();

				AccTransactionLines accrual1_1 = charge1_1.Accrual;
				AccTransactionLines accrual1_2 = charge1_2.Accrual;
				AccTransactionLines accrual1_3 = charge1_3.Accrual;

				APInvoice invoice = CreateAPInvoice("Z1000", Creditor1, USD, 0.65M, "Invoice Z1000");
				APInvoiceLine line1 = CreateAPInvoiceLine(invoice, job1, CC1, USD, 0.65M, "Charge Code 1", 50M, false);
				line1.OriginalJobCharge = charge1_3;

				GetTransformer(Factory).Transform(invoice);

				AssertEquals("Accrual1_1 not Reversed", false, accrual1_1.AL_ReverseDate.IsValid);
				AssertEquals("Accrual1_2 not Reversed", false, accrual1_2.AL_ReverseDate.IsValid);
				AssertEquals("Accrual1_3 Reversed", true, accrual1_3.AL_ReverseDate.IsValid);
				AssertEquals("Charge Count", 4, job1.Charges.Count);

				AssertCostChargeValues(charge1_1, CC1, "Charge Code 1", Creditor1, false, AUD, 1m, 50M, 50M, GST1, 5M, WHTFREE1, 0M,
					"", ZDateTime.Empty, ZDateTime.Empty);
				AssertSellChargeValues(charge1_1, CC1, "Charge Code 1", LocalClient, false, AUD, 1m, 50m, 50M, GST1, 5M, WHTFREE1, 0M);

				AssertCostChargeValues(charge1_2, CC1, "Charge Code 1", null, false, AUD, 1m, 100M, 100M, null, 0M, null, 0M,
					"", ZDateTime.Empty, ZDateTime.Empty);
				AssertSellChargeValues(charge1_2, CC1, "Charge Code 1", Agent, false, AUD, 1m, 100m, 100m, GST1, 10M, WHTFREE1, 0M);

				AssertCostChargeValues(charge1_3, CC1, "Charge Code 1", Creditor1, true, USD, 0.65m, 50m, 76.92m, GST1, 5M, WHTFREE1, 0M,
					"Z1000", ZDateTime.Today, ZDateTime.Today.AddMonths(1));
				AssertSellChargeValues(charge1_3, CC1, "Charge Code 1", Agent, false, AUD, 1m, 150m, 150m, GST1, 15M, WHTFREE1, 0M);

				AssertCostChargeValues(job1.Charges[3], CC1, "Charge Code 1", null, false, AUD, 1m, 73.08M, 73.08M, null, 0M, null, 0M,
					"", ZDateTime.Empty, ZDateTime.Empty);
				AssertSellChargeValues(job1.Charges[3], CC1, "Charge Code 1", LocalClient, false, AUD, 1m, 0, 0, GST1, 0, WHTFREE1, 0M);
			}
		}

		public void TestBringForwardWithMultipleChargesWithDifferentCreditor()
		{
			Job job1 = CreateJob("Z00001000", LocalClient, 0M, null, 0M);
			Charge charge1_1 = CreateCharge(job1, CC1, "Charge Code 1", AUD, 200M, null, AUD, 150M, LocalClient);
			Charge charge1_2 = CreateCharge(job1, CC1, "Charge Code 1", AUD, 100M, Creditor1, AUD, 150M, LocalClient);
			Charge charge1_3 = CreateCharge(job1, CC1, "Charge Code 1", AUD, 300M, null, AUD, 150M, LocalClient);
			Charge charge1_4 = CreateCharge(job1, CC1, "Charge Code 1", AUD, 100M, Creditor2, AUD, 150M, LocalClient);
			Charge charge1_5 = CreateCharge(job1, CC1, "Charge Code 1", AUD, 100M, Creditor1, AUD, 150M, LocalClient);
			Factory.Save();

			AccTransactionLines accrual1_1 = charge1_1.Accrual;
			AccTransactionLines accrual1_2 = charge1_2.Accrual;
			AccTransactionLines accrual1_3 = charge1_3.Accrual;
			AccTransactionLines accrual1_4 = charge1_4.Accrual;
			AccTransactionLines accrual1_5 = charge1_5.Accrual;

			APInvoice invoice = CreateAPInvoice("Z1000", Creditor1, AUD, 1M, "Invoice Z1000");
			APInvoiceLine line1 = CreateAPInvoiceLine(invoice, job1, CC1, AUD, 1M, "Charge Code 1", 80M, false);
			line1.OriginalJobCharge = charge1_4;

			GetTransformer(Factory).Transform(invoice);

			AssertEquals("Accrual1_1 not Reversed", false, accrual1_1.AL_ReverseDate.IsValid);
			AssertEquals("Accrual1_2 not Reversed", false, accrual1_2.AL_ReverseDate.IsValid);
			AssertEquals("Accrual1_3 not Reversed", false, accrual1_3.AL_ReverseDate.IsValid);
			AssertEquals("Accrual1_4 Reversed", true, accrual1_4.AL_ReverseDate.IsValid);
			AssertEquals("Accrual1_5 not Reversed", false, accrual1_5.AL_ReverseDate.IsValid);
			AssertEquals("Job1 Charge Count", 6, job1.Charges.Count);

			AssertCostChargeValues(job1.Charges[0], CC1, "Charge Code 1", null, false, AUD, 1m, 200M, 200M, null, 0M, null, 0M,
				"", ZDateTime.Empty, ZDateTime.Empty);
			AssertSellChargeValues(job1.Charges[0], CC1, "Charge Code 1", LocalClient, false, AUD, 1m, 150M, 150m, GST1, 15M, WHTFREE1, 0M);

			AssertCostChargeValues(job1.Charges[1], CC1, "Charge Code 1", Creditor1, false, AUD, 1m, 100M, 100M, GST1, 10M, WHTFREE1, 0M,
				"", ZDateTime.Empty, ZDateTime.Empty);
			AssertSellChargeValues(job1.Charges[1], CC1, "Charge Code 1", LocalClient, false, AUD, 1m, 150M, 150m, GST1, 15M, WHTFREE1, 0M);

			AssertCostChargeValues(job1.Charges[2], CC1, "Charge Code 1", null, false, AUD, 1m, 300M, 300M, null, 0M, null, 0M,
				"", ZDateTime.Empty, ZDateTime.Empty);
			AssertSellChargeValues(job1.Charges[2], CC1, "Charge Code 1", LocalClient, false, AUD, 1m, 150M, 150m, GST1, 15M, WHTFREE1, 0M);

			AssertCostChargeValues(job1.Charges[3], CC1, "Charge Code 1", Creditor1, true, AUD, 1m, 80M, 80m, GST1, 8M, WHTFREE1, 0M,
				"Z1000", ZDateTime.Today, ZDateTime.Today.AddMonths(1));
			AssertSellChargeValues(job1.Charges[3], CC1, "Charge Code 1", LocalClient, false, AUD, 1m, 150M, 150m, GST1, 15M, WHTFREE1, 0M);

			AssertCostChargeValues(job1.Charges[4], CC1, "Charge Code 1", Creditor1, false, AUD, 1m, 100M, 100M, GST1, 10M, WHTFREE1, 0M,
				"", ZDateTime.Empty, ZDateTime.Empty);
			AssertSellChargeValues(job1.Charges[4], CC1, "Charge Code 1", LocalClient, false, AUD, 1m, 150M, 150m, GST1, 15M, WHTFREE1, 0M);

			AssertCostChargeValues(job1.Charges[5], CC1, "Charge Code 1", Creditor1, false, AUD, 1m, 20M, 20M, GST1, 2M, WHTFREE1, 0M,
				"", ZDateTime.Empty, ZDateTime.Empty);
			AssertSellChargeValues(job1.Charges[5], CC1, "Charge Code 1", LocalClient, false, AUD, 1m, 0M, 0M, GST1, 0M, WHTFREE1, 0M);
		}

