		public void TestUpdateChargesWithApportionmentRelatedChargesFromPositiveAndNegativeCreditNote_WithNegativeAccrualsBehaviour()
		{
			AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);

			ForwardingConsol consol = Factory.NewWithValidTestData<ForwardingConsol>();
			ForwardingShipment shipment = consol.Shipments.AddNew();
			Job job = TestObjectCreator.CreateJob(shipment);

			TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, TestObjectCreator.LocalCurrency, 1M, -90.00m);

			Factory.Save();

			BusinessObjectFactory newFactory = new BusinessObjectFactory();
			APCreditNote creditNote = (APCreditNote)newFactory.New(GetCreditNoteType());
			creditNote.SubmittedFromInvoicingForm = true;
			creditNote.AH_OH = LocalClient.PK;
			creditNote.AH_TransactionNum = "123";

			JobConsolCost invoiceCost = creditNote.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			invoiceCost.E6_AC_ChargeCode = TestObjectCreator.CC1.PK;
			invoiceCost.E6_OSCostAmount = 200m;
			invoiceCost.E6_ApportionmentMethod = "SHP";
			invoiceCost.ApportionmentCharges.Cast<ApportionSplitCharge>().ForEach(c => c.RelatedApportionChargeFromDB = null);

			invoiceCost = creditNote.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			invoiceCost.E6_AC_ChargeCode = TestObjectCreator.CC1.PK;
			invoiceCost.E6_OSCostAmount = -90m;
			invoiceCost.E6_ApportionmentMethod = "SHP";
			creditNote.ImportAllApportionmentsFromCosting();
			invoiceCost.ApportionmentCharges.Cast<ApportionSplitCharge>().ForEach(c => c.RelatedApportionChargeFromDB = null);

			newFactory.Save();

			job.Charges.Reload(true);
			AssertEquals(2, job.Charges.Count);

			var sortedCharge = job.Charges.Cast<Charge>().OrderBy(x => x.JR_OSCostAmt).ToArray();
			Charge charge1 = sortedCharge[0];
			Charge charge2 = sortedCharge[1];

			AssertNotNull("Should have Cost or UACost", charge1.APLine);
			Assert("Should be FK to one of the lines in the invoice", creditNote.Lines.Contains(charge1.APLine.PK));
			AssertEquals(-200M, charge1.JR_OSCostAmt);

			AssertNotNull("Should have Cost or UACost", charge2.APLine);
			Assert("Should be FK to one of the lines in the invoice", creditNote.Lines.Contains(charge2.APLine.PK));
			AssertEquals(90M, charge2.JR_OSCostAmt);
		}

		public void TestUpdateChargesWithApportionmentRelatedChargesFromPositiveAndNegativeCreditNote_WithNegativeAccrualsBehaviourWithoutFinal()
		{
			AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);

			ForwardingConsol consol = Factory.NewWithValidTestData<ForwardingConsol>();
			ForwardingShipment shipment = consol.Shipments.AddNew();
			Job job = TestObjectCreator.CreateJob(shipment);

			TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, TestObjectCreator.LocalCurrency, 1M, -90.00m);
			TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.ManualJobAccrualChargeCode, TestObjectCreator.LocalCurrency, 1M, -180.00m);

			Factory.Save();

			BusinessObjectFactory newFactory = new BusinessObjectFactory();
			APCreditNote creditNote = (APCreditNote)newFactory.New(GetCreditNoteType());
			creditNote.SubmittedFromInvoicingForm = true;
			creditNote.AH_OH = LocalClient.PK;
			creditNote.AH_TransactionNum = "123";

			JobConsolCost invoiceCost = creditNote.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			invoiceCost.IsFinal = false;
			invoiceCost.E6_AC_ChargeCode = TestObjectCreator.CC1.PK;
			invoiceCost.E6_OSCostAmount = 200m;
			invoiceCost.E6_ApportionmentMethod = "SHP";
			invoiceCost.ApportionmentCharges.Cast<ApportionSplitCharge>().ForEach(c => c.RelatedApportionChargeFromDB = null);

			invoiceCost = creditNote.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			invoiceCost.IsFinal = false;
			invoiceCost.E6_AC_ChargeCode = TestObjectCreator.CC1.PK;
			invoiceCost.E6_OSCostAmount = -90m;
			invoiceCost.E6_ApportionmentMethod = "SHP";
			invoiceCost.ApportionmentCharges.Cast<ApportionSplitCharge>().ForEach(c => c.RelatedApportionChargeFromDB = null);

			JobConsolCost invoiceCostMJA = creditNote.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			invoiceCostMJA.IsFinal = false;
			invoiceCostMJA.E6_AC_ChargeCode = TestObjectCreator.ManualJobAccrualChargeCode.PK;
			invoiceCostMJA.E6_OSCostAmount = 300m;
			invoiceCostMJA.E6_ApportionmentMethod = "SHP";
			invoiceCostMJA.ApportionmentCharges.Cast<ApportionSplitCharge>().ForEach(c => c.RelatedApportionChargeFromDB = null);

			invoiceCostMJA = creditNote.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			invoiceCostMJA.IsFinal = false;
			invoiceCostMJA.E6_AC_ChargeCode = TestObjectCreator.ManualJobAccrualChargeCode.PK;
			invoiceCostMJA.E6_OSCostAmount = -180m;
			invoiceCostMJA.E6_ApportionmentMethod = "SHP";

			creditNote.ImportAllApportionmentsFromCosting();
			invoiceCost.ApportionmentCharges.Cast<ApportionSplitCharge>().ForEach(c => c.RelatedApportionChargeFromDB = null);
			invoiceCostMJA.ApportionmentCharges.Cast<ApportionSplitCharge>().ForEach(c => c.RelatedApportionChargeFromDB = null);

			creditNote.ImportAllApportionmentsFromCosting();

			newFactory.Save();

			job.Charges.Reload(true);

			AssertEquals(6, job.Charges.Count);

			var sortedCharge = job.Charges.Cast<Charge>().OrderBy(x => x.ChargeType).ThenBy(x => x.JR_OSCostAmt).ToArray();
			Charge charge1MJA = sortedCharge[0];
			Charge charge2MJA = sortedCharge[1];
			Charge charge3MJA = sortedCharge[2];
			Charge charge1MRG = sortedCharge[3];
			Charge charge2MRG = sortedCharge[4];
			Charge charge3MRG = sortedCharge[5];

			AssertNotNull("Should have Cost or UACost", charge1MJA.APLine);
			Assert("Should be FK to one of the lines in the invoice", creditNote.Lines.Contains(charge1MJA.APLine.PK));
			AssertEquals(-300M, charge1MJA.JR_OSCostAmt);

			AssertNotNull("Should have Accrual for the carry forward ApportionSplitCharge", charge2MJA.Accrual);
			AssertEquals(120M, charge2MJA.JR_OSCostAmt);

			AssertNotNull("Should have Cost or UACost", charge3MJA.APLine);
			Assert("Should be FK to one of the lines in the invoice", creditNote.Lines.Contains(charge3MJA.APLine.PK));
			AssertEquals(180M, charge3MJA.JR_OSCostAmt);

			AssertNotNull("Should have Cost or UACost", charge1MRG.APLine);
			Assert("Should be FK to one of the lines in the invoice", creditNote.Lines.Contains(charge1MRG.APLine.PK));
			AssertEquals(-200M, charge1MRG.JR_OSCostAmt);

			AssertNotNull("Should have Cost or UACost", charge2MRG.APLine);
			Assert("Should be FK to one of the lines in the invoice", creditNote.Lines.Contains(charge2MRG.APLine.PK));
			AssertEquals(90M, charge2MRG.JR_OSCostAmt);

			AssertNotNull("Should have Accrual for the carry forward ApportionSplitCharge", charge3MRG.Accrual);
			AssertEquals(110M, charge3MRG.JR_OSCostAmt);
		}

