		#region TEST: Update Accrual AL_ReverseDate From Invoice Line ReverseDate (Recognition Date)

		public void TestReverseAccrualDateWithInvoiceLineReverseDateForConsolCost()
		{
			ZDateTime arrivalDate = ZDateTime.Today;
			ZDateTime departureDate = ZDateTime.Today.AddDays(-10);

			TestObjectCreator.CreateTestPeriods(arrivalDate);
			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting = valuesForTest.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting.Mode = Core.Constants.TransportModes.All;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);

			var shipment = TestObjectCreator.CreateShipment("S0001");
			shipment.JS_E_ARV = arrivalDate;
			shipment.JS_E_DEP = departureDate;
			ForwardingConsol consol = Factory.New<ForwardingConsol>();
			consol.Shipments.Add(shipment);
			Factory.Save();

			Job job = TestObjectCreator.CreateJob(shipment, false);
			ApportionmentListing apportionments = new ApportionmentListing(Factory, consol);
			JobConsolCost consolCost = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, 100M);
			job.ApplyRevenueRecognitionDate(consolCost.ApportionmentCharges[0]);
			Factory.Save();

			AssertEquals("Consol cost charge should be created.", 1, job.Charges.Count);
			Charge charge1 = job.Charges[0];

			Charge charge2 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 100M, null, TestObjectCreator.AUD, 100M, null);
			AssertEquals("Precondition: revenue recognition date should be set", arrivalDate, job.GetRevenueRecognitionDate(setting.RecognitionDateOptionCode));

			Charge charge3 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 100M, null, TestObjectCreator.AUD, 100M, null);

			Factory.Save();

			Accrual accrual1 = charge1.Accrual;
			Accrual accrual2 = charge2.Accrual;
			Accrual accrual3 = charge3.Accrual;

			AssertNotNull("Pre Condition Accrual should not be null", accrual1);
			AssertNotNull("Pre Condition Accrual should not be null", accrual2);
			AssertNotNull("Pre Condition Accrual should not be null", accrual3);

			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualDepartureDate;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			job.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();

			ZDateTime postDate = ZDateTime.Now.AddDays(-10);

			APInvoice invoice = CreateAPInvoice("INV1", TestObjectCreator.AALSHI, TestObjectCreator.AUD, 1M, "Desc");
			invoice.AH_PostDate = postDate;

			JobConsolCost consolCostInInvoice = TestObjectCreator.CreateConsolCost(invoice, consol, TestObjectCreator.CC1, 100M);
			consolCostInInvoice.IsFinal = false;
			invoice.ImportAllApportionmentsFromCosting();

			AssertEquals("invoice.Lines.Count", 1, invoice.Lines.Count);
			job.ApplyRevenueRecognitionDate(invoice.Lines[0]);

			GetTransformer(Factory).Transform(invoice);

			AssertEquals("Job1 Charge Count", 3, job.Charges.Count);

			AssertEquals("Job Console Cost Charge Amount Should be Equals to Invoice Line Amount", 100M, charge1.JR_OSCostAmt);
			AssertEquals("Charge Amount Should NOT Be changed", 100M, charge2.JR_OSCostAmt);
			AssertEquals("Charge Amount Should NOT Be changed", 100M, charge3.JR_OSCostAmt);

			AssertEquals("Accrual Reverse Date Should be departure date Because Revenue Recognition method changed Before Transforming Invoice", departureDate, accrual1.AL_ReverseDate);
			AssertEquals("Accrual Reverse Date Should NOT be departure date Because this accrual isn't changed during transform", ZDateTime.Empty, accrual2.AL_ReverseDate);
			AssertEquals("Accrual Reverse Date Should NOT be departure date Because this accrual isn't changed during transform", ZDateTime.Empty, accrual3.AL_ReverseDate);
		}

