			var charge1 = TestObjectCreator.CreateCharge(job, disbursementChargeCode, 1M, 1M);
			var charge2 = TestObjectCreator.CreateCharge(job, disbursementChargeCode, 2M, 2M);
			var charge3 = TestObjectCreator.CreateCharge(job, disbursementChargeCode, 3M, 3M);
			charge1.JR_GE = TestObjectCreator.FESDepartment.PK;
			charge2.JR_GE = TestObjectCreator.FESDepartment.PK;
