			Assert("charge2 cost is not posted", !charge2.IsCostPosted);
			AssertEquals("charge2 cost amount should be summed up", 4M, charge2.JR_OSCostAmt);
			AssertEquals("charge2 sell amount should not change", 2M, charge2.JR_OSSellAmt);

			Assert("charge3 cost is not posted", !charge3.IsCostPosted);
			AssertEquals("charge3 cost amount is set 0", 0M, charge3.JR_OSCostAmt);
			AssertEquals("charge3 sell amount should not change", 3M, charge3.JR_OSSellAmt);
