		public void TestCreateWIPAndCopyAddressAndContact()
		{
			var job = CreateJob("JOB1", null, 0, null, 0);
			var charge = CreateCharge(job, CC7, null, TestObjectCreator.AUD, 0, Creditor1, TestObjectCreator.AUD, 100, LocalClient);
			charge.JR_OSSellAmt = 100;
			charge.JR_OSCostAmt = 0;
			var expectedAddress = TestObjectCreator.CreateAddress(charge.SellAccount);
			var expectedContact = TestObjectCreator.CreateContact(charge.SellAccount);
			charge.JR_OA_SellInvoiceAddress = expectedAddress.PK;
			charge.JR_OC_SellInvoiceContact = expectedContact.PK;
			PostChargeRevenue(charge, "INV1");
			AssertEquals(0m, charge.JR_OSCostAmt);
			AssertEquals(100m, charge.JR_OSSellAmt);
			Factory.Save();

			var invoice = CreateAPInvoice("INV2", Creditor1, TestObjectCreator.AUD, 1, "Invoice Z1000");
			CreateAPInvoiceLine(invoice, job, CC7, TestObjectCreator.AUD, 1, null, 380, false);

			GetTransformer(Factory).Transform(invoice);

			AssertEquals("Charge Count", 2, job.Charges.Count);

			var chargeToTest = charge;
			AssertCollectionContains("Tested charge is in Job.Charges", chargeToTest, job.Charges);
			AssertCostChargeValues(chargeToTest, CC7, null, Creditor1, true, TestObjectCreator.AUD, 1, 380, 380, GSTFREE1, 0, WHTFREE1, 0, "INV2", ZDateTime.Today, ZDateTime.Today.AddMonths(1));
			AssertSellChargeValues(chargeToTest, CC7, null, LocalClient, true, TestObjectCreator.AUD, 1, 100, 100, GSTFREE1, 0, WHTFREE1, 0, expectedAddress, expectedContact);

			chargeToTest = FindCreatedCharge(job, new[] { charge });
			AssertCollectionContains("Tested charge is in Job.Charges", chargeToTest, job.Charges);
			AssertCostChargeValues(chargeToTest, CC7, null, null, false, AUD, 1, 0, 0, null, 0, null, 0, "", ZDateTime.Empty, ZDateTime.Empty);
			AssertSellChargeValues(chargeToTest, CC7, null, LocalClient, false, AUD, 1, 380, 380, GSTFREE1, 0, WHTFREE1, 0, expectedAddress, expectedContact);
		}

		public void TestIfAtLeastOneChargeHasCostAmountThisCantBeTreatedAsNoCostExist()
		{
			using (AccountingConfigurationRegistry.Instance.BringForwardAgainstCreditor.SetTemporaryValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, false))
			{
				AssertIfAtLeastOneChargeHasCostAmountThisCantBeTreatedAsNoCostExist(false, false);
				AssertIfAtLeastOneChargeHasCostAmountThisCantBeTreatedAsNoCostExist(false, true);
				AssertIfAtLeastOneChargeHasCostAmountThisCantBeTreatedAsNoCostExist(true, false);
				AssertIfAtLeastOneChargeHasCostAmountThisCantBeTreatedAsNoCostExist(true, true);
			}
		}

		void AssertIfAtLeastOneChargeHasCostAmountThisCantBeTreatedAsNoCostExist(bool isNegativeAccrualBehaviourEnabled, bool doesAnyChargeHasNonZeroCostAmount)
		{
			AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, isNegativeAccrualBehaviourEnabled);

			var jobNumber = (++currentInvoiceNumber).ToString();
			var job = CreateJob(jobNumber, LocalClient, 0, null, 0);
			var chargeCurrency = GBP;
			var chargeExRate = 1.5m;
			CreateExchangeRate(job, chargeCurrency, chargeExRate);

			var expectedUnchangedOSCostAmount = doesAnyChargeHasNonZeroCostAmount ? 30m : 0;
			var charge1 = CreateCharge(job, CC7, null, chargeCurrency, 0, Creditor1, chargeCurrency, 0, LocalClient);
			AssertEquals(0m, charge1.JR_OSCostAmt);
			AssertEquals(0m, charge1.JR_OSSellAmt);
			var charge2 = CreateCharge(job, CC7, null, chargeCurrency, expectedUnchangedOSCostAmount, Creditor1, chargeCurrency, 0, LocalClient);
			AssertEquals(expectedUnchangedOSCostAmount, charge2.JR_OSCostAmt);
			AssertEquals(0m, charge2.JR_OSSellAmt);

			Factory.Save();

			var invoiceCurrency = USD;
			var invoiceExRate = .5m;
			var expectedLineOSAmount = 380m;

			InvoicingBase invoice;

			if (isNegativeAccrualBehaviourEnabled)
			{
				invoice = CreateAPCreditNote(jobNumber, Creditor1, invoiceCurrency, invoiceExRate, "Invoice Z1000");
				CreateAPCreditNoteLine((APCreditNote)invoice, job, CC7, invoiceCurrency, invoiceExRate, null, expectedLineOSAmount, false);
			}
			else
			{
				invoice = CreateAPInvoice(jobNumber, Creditor1, invoiceCurrency, invoiceExRate, "Invoice Z1000");
				CreateAPInvoiceLine((APInvoice)invoice, job, CC7, invoiceCurrency, invoiceExRate, null, expectedLineOSAmount, false);
			}

			GetTransformer(Factory).Transform(invoice);

			var expectedUnchangedLocalCostAmount = expectedUnchangedOSCostAmount / chargeExRate;
			var expectedOSCostAmount = expectedLineOSAmount * (isNegativeAccrualBehaviourEnabled ? -1 : 1);
			var expectedLocalCostAmount = expectedOSCostAmount / invoiceExRate;
			var expectedLocalCostCaryForwardAmount = expectedLocalCostAmount - expectedUnchangedLocalCostAmount;
			var expectedLocalSellAmount = doesAnyChargeHasNonZeroCostAmount ? 0m : expectedLocalCostCaryForwardAmount;

			Charge chargeToTest;

			bool carryCostForwardToAnotherCharge = doesAnyChargeHasNonZeroCostAmount && AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.Value;
			AssertEquals("Charge Count", carryCostForwardToAnotherCharge ? 2 : 1, job.Charges.Count);

			chargeToTest = charge1;
			AssertCollectionContains("Tested charge is in Job.Charges", chargeToTest, job.Charges);
			AssertCostChargeValues(chargeToTest, CC7, null, Creditor1, true, invoiceCurrency, invoiceExRate, expectedOSCostAmount, expectedLocalCostAmount, GSTFREE1, 0, WHTFREE1, 0,
				jobNumber, ZDateTime.Today, ZDateTime.Today.AddMonths(1));
			AssertSellChargeValues(chargeToTest, CC7, null, LocalClient, false, chargeCurrency, chargeExRate, expectedLocalSellAmount * chargeExRate, expectedLocalSellAmount, GSTFREE1, 0, WHTFREE1, 0);

			if (carryCostForwardToAnotherCharge)
			{
				chargeToTest = charge2;
				AssertCollectionContains("Tested charge is in Job.Charges", chargeToTest, job.Charges);
				AssertCostChargeValues(chargeToTest, CC7, null, null, false, AUD, 1, -expectedLocalCostCaryForwardAmount, -expectedLocalCostCaryForwardAmount, null, 0, null, 0, "", ZDateTime.Empty, ZDateTime.Empty);
				AssertSellChargeValues(chargeToTest, CC7, null, LocalClient, false, chargeCurrency, chargeExRate, 0, 0, GSTFREE1, 0, WHTFREE1, 0);
			}

			ReleaseFactory();
		}

