		public void TestCreateWIPForExistedChargeWithZeroAmounts_WithNegativeAccrualsBehaviour()
		{
			AssertCreateWIPForExistedChargeWithZeroAmountsByAccrualSignBehaviour(true);
		}

		void AssertCreateWIPForExistedChargeWithZeroAmountsByAccrualSignBehaviour(bool isNegativeAccrualBehaviourEnabled)
		{
			AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, isNegativeAccrualBehaviourEnabled);
			AssertCreateWIPForExistedChargeWithZeroAmountsByTransactionType(isNegativeAccrualBehaviourEnabled, postCreditNote: false, negativeDbAmount: false);
			AssertCreateWIPForExistedChargeWithZeroAmountsByTransactionType(isNegativeAccrualBehaviourEnabled, postCreditNote: false, negativeDbAmount: true);
			AssertCreateWIPForExistedChargeWithZeroAmountsByTransactionType(isNegativeAccrualBehaviourEnabled, postCreditNote: true, negativeDbAmount: false);
			AssertCreateWIPForExistedChargeWithZeroAmountsByTransactionType(isNegativeAccrualBehaviourEnabled, postCreditNote: true, negativeDbAmount: true);
		}

		void AssertCreateWIPForExistedChargeWithZeroAmountsByTransactionType(bool isNegativeAccrualBehaviorEnabled, bool postCreditNote, bool negativeDbAmount)
		{
			AssertCreateWIPForExistedChargeWithZeroAmountsByAmountOfZeroCharges(isNegativeAccrualBehaviorEnabled, postCreditNote, negativeDbAmount,
				multipleCharges: false);
			AssertCreateWIPForExistedChargeWithZeroAmountsByAmountOfZeroCharges(isNegativeAccrualBehaviorEnabled, postCreditNote, negativeDbAmount,
				multipleCharges: false, isRevenuePostedForAllCharges: true);
			AssertCreateWIPForExistedChargeWithZeroAmountsByAmountOfZeroCharges(isNegativeAccrualBehaviorEnabled, postCreditNote, negativeDbAmount,
				multipleCharges: true);
			AssertCreateWIPForExistedChargeWithZeroAmountsByAmountOfZeroCharges(isNegativeAccrualBehaviorEnabled, postCreditNote, negativeDbAmount,
				multipleCharges: true, isRevenuePostedForFirstChargeOnly: true);
			AssertCreateWIPForExistedChargeWithZeroAmountsByAmountOfZeroCharges(isNegativeAccrualBehaviorEnabled, postCreditNote, negativeDbAmount,
				multipleCharges: true, isRevenuePostedForAllCharges: true);
		}

		void AssertCreateWIPForExistedChargeWithZeroAmountsByAmountOfZeroCharges(bool isNegativeAccrualBehaviorEnabled, bool postCreditNote, bool negativeDbAmount, bool multipleCharges,
			bool isRevenuePostedForFirstChargeOnly = false, bool isRevenuePostedForAllCharges = false)
		{
			bool isNewChargeCreated = postCreditNote && !isNegativeAccrualBehaviorEnabled;
			bool? isSellAmountSet_DefaultForAll = null;
			if (negativeDbAmount && (isNewChargeCreated || !isNegativeAccrualBehaviorEnabled))
			{
				isSellAmountSet_DefaultForAll = false;
			}

			bool isCarryForwardCost = negativeDbAmount && !isNegativeAccrualBehaviorEnabled;

			AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsFinal.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, false);
			AssertCreateWIPForExistedChargeWithZeroAmounts(postCreditNote, negativeDbAmount, multipleCharges, isNewChargeCreated, isRevenuePostedForFirstChargeOnly, isRevenuePostedForAllCharges,
				isCarryForwardCost, isFinal: false, isSellAmountSet: isSellAmountSet_DefaultForAll ?? true);

			bool createWIPWhenCostIsFinal = true;
			AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsFinal.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, createWIPWhenCostIsFinal);
			AssertCreateWIPForExistedChargeWithZeroAmounts(postCreditNote, negativeDbAmount, multipleCharges, isNewChargeCreated, isRevenuePostedForFirstChargeOnly, isRevenuePostedForAllCharges,
			isCarryForwardCost: false, isFinal: true, isSellAmountSet: isSellAmountSet_DefaultForAll ?? createWIPWhenCostIsFinal);

			createWIPWhenCostIsFinal = false;
			AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsFinal.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, createWIPWhenCostIsFinal);
			AssertCreateWIPForExistedChargeWithZeroAmounts(postCreditNote, negativeDbAmount, multipleCharges, isNewChargeCreated, isRevenuePostedForFirstChargeOnly, isRevenuePostedForAllCharges,
				isCarryForwardCost: false, isFinal: true, isSellAmountSet: isSellAmountSet_DefaultForAll ?? createWIPWhenCostIsFinal);
		}

		void AssertCreateWIPForExistedChargeWithZeroAmounts(bool postCreditNote = false, bool negativeDbAmount = false, bool multipleCharges = false, bool isNewChargeCreated = false,
			bool isRevenuePostedForFirstChargeOnly = false, bool isRevenuePostedForAllCharges = false, bool isCarryForwardCost = false,
			bool isFinal = false, bool isSellAmountSet = false)
		{
			if (isRevenuePostedForFirstChargeOnly && isRevenuePostedForAllCharges)
			{
				Fail("isRevenuePostedForFirstChargeOnly and isRevenuePostedForAllCharges can't be true together");
			}
			if (isRevenuePostedForFirstChargeOnly && !multipleCharges)
			{
				isRevenuePostedForFirstChargeOnly = false;
				isRevenuePostedForAllCharges = true;
			}

			LocalClient.CompanyData.OB_RX_NKARDDefltCurrency = ZString.Empty;
			LocalClient.CompanyData.OB_RX_NKAPDefltCurrency = ZString.Empty;
			var jobNumber = (++currentInvoiceNumber).ToString();
			var job = CreateJob(jobNumber, LocalClient, 0, null, 0);
			var chargeCurrency = GBP;
			var chargeExRate = 1.5m;
			CreateExchangeRate(job, chargeCurrency, chargeExRate);

			int arInvoiceNumber = 0;
			decimal expectedOSRevenueAmount = 45;
			decimal expectedUnchangedOSSellAmountForFirstCharge = 15;
			var charge = CreateCharge(job, CC7, null, chargeCurrency, 0, Creditor1, chargeCurrency, expectedUnchangedOSSellAmountForFirstCharge, LocalClient);
			charge.JR_OSCostAmt = 0;
			AssertEquals(0M, charge.JR_OSCostAmt);
			AssertEquals(expectedUnchangedOSSellAmountForFirstCharge, charge.JR_OSSellAmt);
			if (isRevenuePostedForFirstChargeOnly || isRevenuePostedForAllCharges)
			{
				charge.JR_OSSellAmt = expectedOSRevenueAmount;
				charge.JR_OSCostAmt = 0;
				PostChargeRevenue(charge, jobNumber + (++arInvoiceNumber).ToString());
				AssertEquals(0M, charge.JR_OSCostAmt);
				AssertEquals(expectedOSRevenueAmount, charge.JR_OSSellAmt);
			}
			List<Charge> chargesExisted = new List<Charge>();
			chargesExisted.Add(charge);
			if (multipleCharges)
			{
				int additionalChargeCount = 2;
				for (int i = 1; i <= additionalChargeCount; i++)
				{
					charge = CreateCharge(job, CC7, null, chargeCurrency, 0, Creditor1, chargeCurrency, 0, LocalClient);
					charge.JR_OSCostAmt = 0;
					AssertEquals(0M, charge.JR_OSCostAmt);
					AssertEquals(0M, charge.JR_OSSellAmt);
					if (isRevenuePostedForAllCharges)
					{
						charge.JR_OSSellAmt = expectedOSRevenueAmount;
						charge.JR_OSCostAmt = 0;
						PostChargeRevenue(charge, jobNumber + (++arInvoiceNumber).ToString());
						AssertEquals(0M, charge.JR_OSCostAmt);
						AssertEquals(expectedOSRevenueAmount, charge.JR_OSSellAmt);
					}
					chargesExisted.Add(charge);
				}
			}
			Factory.Save();

			int multiplier = negativeDbAmount != postCreditNote ? -1 : 1;
			var invoiceCurrency = USD;
			var invoiceExRate = .5m;
			decimal expectedLineOSAmount = 380 * multiplier;
			InvoicingBase invoice;
			if (postCreditNote)
			{
				invoice = CreateAPCreditNote(jobNumber, Creditor1, invoiceCurrency, invoiceExRate, "Invoice Z1000");
				CreateAPCreditNoteLine((APCreditNote)invoice, job, CC7, invoiceCurrency, invoiceExRate, null, expectedLineOSAmount, false, isFinal);
			}
			else
			{
				invoice = CreateAPInvoice(jobNumber, Creditor1, invoiceCurrency, invoiceExRate, "Invoice Z1000");
				CreateAPInvoiceLine((APInvoice)invoice, job, CC7, invoiceCurrency, invoiceExRate, null, expectedLineOSAmount, isFinal);
			}

			GetTransformer(Factory).Transform(invoice);

			bool isSellPosted = isRevenuePostedForFirstChargeOnly || isRevenuePostedForAllCharges;
			expectedUnchangedOSSellAmountForFirstCharge = isSellPosted ? expectedOSRevenueAmount : expectedUnchangedOSSellAmountForFirstCharge;
			var expectedUnchangedLocalSellAmountForFirstCharge = expectedUnchangedOSSellAmountForFirstCharge / chargeExRate;
			var expectedUnchangedOSSellAmount = isSellPosted ? expectedOSRevenueAmount : 0M;
			var expectedUnchangedLocalSellAmount = expectedUnchangedOSSellAmount / chargeExRate;

			var expectedOSCostAmount = expectedLineOSAmount * (postCreditNote ? -1 : 1);
			var expectedLocalCostAmount = expectedOSCostAmount / invoiceExRate;
			var expectedLocalSellAmount = isSellAmountSet ? expectedLocalCostAmount : 0;
			var expectedLocalSellAmountForFirstExistedCharge = expectedLocalSellAmount + expectedUnchangedLocalSellAmountForFirstCharge;

			Charge chargeToTest;
			if (isNewChargeCreated)
			{
				AssertEquals("Charge Count", chargesExisted.Count + 1, job.Charges.Count);
				var currentExpectedUnchangedOSSellAmount = expectedUnchangedOSSellAmountForFirstCharge;
				var currentExpectedUnchangedLocalSellAmount = expectedUnchangedLocalSellAmountForFirstCharge;
				foreach (var chargeExisted in chargesExisted)
				{
					chargeToTest = chargeExisted;
					AssertCollectionContains("Tested charge is in Job.Charges", chargeToTest, job.Charges);
					AssertCostChargeValues(chargeToTest, CC7, null, Creditor1, false, chargeCurrency, chargeExRate, 0, 0, GSTFREE1, 0, WHTFREE1, 0, "", ZDateTime.Empty, ZDateTime.Empty);
					AssertSellChargeValues(chargeToTest, CC7, null, LocalClient, isSellPosted, chargeCurrency, chargeExRate, currentExpectedUnchangedOSSellAmount, currentExpectedUnchangedLocalSellAmount, GSTFREE1, 0, WHTFREE1, 0);

					currentExpectedUnchangedOSSellAmount = expectedUnchangedOSSellAmount;
					currentExpectedUnchangedLocalSellAmount = expectedUnchangedLocalSellAmount;
					if (isRevenuePostedForFirstChargeOnly)
					{
						currentExpectedUnchangedOSSellAmount = 0;
						currentExpectedUnchangedLocalSellAmount = 0;
						isSellPosted = false;
					}
				}
				chargeToTest = FindCreatedCharge(job, chargesExisted);
				AssertCollectionContains("Tested charge is in Job.Charges", chargeToTest, job.Charges);
				AssertCostChargeValues(chargeToTest, CC7, null, Creditor1, true, invoiceCurrency, invoiceExRate, expectedOSCostAmount, expectedLocalCostAmount, GSTFREE1, 0, WHTFREE1, 0,
					jobNumber, ZDateTime.Today, ZDateTime.Today.AddMonths(1));
				AssertSellChargeValues(chargeToTest, CC7, null, LocalClient, false, invoiceCurrency, invoiceExRate, expectedLocalSellAmount * invoiceExRate, expectedLocalSellAmount, GSTFREE1, 0, WHTFREE1, 0);
			}
			else if (isRevenuePostedForFirstChargeOnly)
			{
				bool isSecondChargeExpected = isSellAmountSet || isCarryForwardCost;
				int expectedChargeCount = 1;
				if (isSecondChargeExpected)
				{
					expectedChargeCount++;
				}

				AssertEquals("Charge Count", expectedChargeCount, job.Charges.Count);

				chargeToTest = chargesExisted[0];
				AssertCollectionContains("Tested charge is in Job.Charges", chargeToTest, job.Charges);
				AssertCostChargeValues(chargeToTest, CC7, null, Creditor1, true, invoiceCurrency, invoiceExRate, expectedOSCostAmount, expectedLocalCostAmount, GSTFREE1, 0, WHTFREE1, 0,
					jobNumber, ZDateTime.Today, ZDateTime.Today.AddMonths(1));
				AssertSellChargeValues(chargeToTest, CC7, null, LocalClient, isSellPosted, chargeCurrency, chargeExRate, expectedUnchangedOSSellAmountForFirstCharge, expectedUnchangedLocalSellAmountForFirstCharge, GSTFREE1, 0, WHTFREE1, 0);

				if (isSecondChargeExpected)
				{
					if (multipleCharges)
					{
						chargeToTest = chargesExisted[1];
						AssertCollectionContains("Tested charge is in Job.Charges", chargeToTest, job.Charges);
						if (isSellAmountSet)
						{
							AssertCostChargeValues(chargeToTest, CC7, null, null, false, chargeCurrency, chargeExRate, 0, 0, null, 0, null, 0, "", ZDateTime.Empty, ZDateTime.Empty);
							AssertSellChargeValues(chargeToTest, CC7, null, LocalClient, false, chargeCurrency, chargeExRate, expectedLocalSellAmount * chargeExRate, expectedLocalSellAmount, GSTFREE1, 0, WHTFREE1, 0);
						}
						else if (isCarryForwardCost)
						{
							AssertCostChargeValues(chargeToTest, CC7, null, null, false, AUD, 1, -expectedLocalCostAmount, -expectedLocalCostAmount, null, 0, null, 0, "", ZDateTime.Empty, ZDateTime.Empty);
							AssertSellChargeValues(chargeToTest, CC7, null, LocalClient, false, chargeCurrency, chargeExRate, 0, 0, GSTFREE1, 0, WHTFREE1, 0);
						}
					}
				}
			}
			else if (isRevenuePostedForAllCharges)
			{
				bool isAdditionalChargeCreated = isSellAmountSet || (isCarryForwardCost && !multipleCharges);
				int expectedChargeCount = chargesExisted.Count;
				if (isAdditionalChargeCreated)
				{
					expectedChargeCount++;
				}

				AssertEquals("Charge Count", expectedChargeCount, job.Charges.Count);

				int chargeIndex = 0;
				foreach (var chargeExisted in chargesExisted)
				{
					chargeToTest = chargeExisted;
					AssertCollectionContains("Tested charge is in Job.Charges", chargeToTest, job.Charges);

					if (chargeIndex == 0)
					{
						AssertCostChargeValues(chargeToTest, CC7, null, Creditor1, true, invoiceCurrency, invoiceExRate, expectedOSCostAmount, expectedLocalCostAmount, GSTFREE1, 0, WHTFREE1, 0,
							jobNumber, ZDateTime.Today, ZDateTime.Today.AddMonths(1));
					}
					else if (chargeIndex == 1 && isCarryForwardCost && multipleCharges)
					{
						AssertCostChargeValues(chargeToTest, CC7, null, null, false, AUD, 1, -expectedLocalCostAmount, -expectedLocalCostAmount, null, 0, null, 0, "", ZDateTime.Empty, ZDateTime.Empty);
					}
					else
					{
						AssertCostChargeValues(chargeToTest, CC7, null, null, false, chargeCurrency, chargeExRate, 0, 0, null, 0, null, 0, "", ZDateTime.Empty, ZDateTime.Empty);
					}

					var currentExpectedUnchangedOSSellAmount = chargeIndex == 0 ? expectedUnchangedOSSellAmountForFirstCharge : expectedUnchangedOSSellAmount;
					var currentExpectedUnchangedLocalSellAmount = chargeIndex == 0 ? expectedUnchangedLocalSellAmountForFirstCharge : expectedUnchangedLocalSellAmount;
					AssertSellChargeValues(chargeToTest, CC7, null, LocalClient, isSellPosted, chargeCurrency, chargeExRate, currentExpectedUnchangedOSSellAmount, currentExpectedUnchangedLocalSellAmount, GSTFREE1, 0, WHTFREE1, 0);

					chargeIndex++;
				}
				if (isAdditionalChargeCreated)
				{
					chargeToTest = FindCreatedCharge(job, chargesExisted);
					AssertCollectionContains("Tested charge is in Job.Charges", chargeToTest, job.Charges);
					if (isSellAmountSet)
					{
						AssertCostChargeValues(chargeToTest, CC7, null, null, false, AUD, 1, 0, 0, null, 0, null, 0, "", ZDateTime.Empty, ZDateTime.Empty);
						AssertSellChargeValues(chargeToTest, CC7, null, LocalClient, false, AUD, 1, expectedLocalSellAmount, expectedLocalSellAmount, GSTFREE1, 0, WHTFREE1, 0);
					}
					else if (isCarryForwardCost && !multipleCharges)
					{
						AssertCostChargeValues(chargeToTest, CC7, null, null, false, AUD, 1, -expectedLocalCostAmount, -expectedLocalCostAmount, null, 0, null, 0, "", ZDateTime.Empty, ZDateTime.Empty);
						AssertSellChargeValues(chargeToTest, CC7, null, LocalClient, false, AUD, 1, 0, 0, GSTFREE1, 0, WHTFREE1, 0);
					}
				}
			}
			else
			{
				AssertEquals("Charge Count", isCarryForwardCost ? 2 : 1, job.Charges.Count);

				chargeToTest = chargesExisted[0];
				AssertCollectionContains("Tested charge is in Job.Charges", chargeToTest, job.Charges);
				AssertCostChargeValues(chargeToTest, CC7, null, Creditor1, true, invoiceCurrency, invoiceExRate, expectedOSCostAmount, expectedLocalCostAmount, GSTFREE1, 0, WHTFREE1, 0,
					jobNumber, ZDateTime.Today, ZDateTime.Today.AddMonths(1));
				AssertSellChargeValues(chargeToTest, CC7, null, LocalClient, false, chargeCurrency, chargeExRate, expectedLocalSellAmountForFirstExistedCharge * chargeExRate, expectedLocalSellAmountForFirstExistedCharge, GSTFREE1, 0, WHTFREE1, 0);

				if (isCarryForwardCost)
				{
					chargeToTest = multipleCharges ? chargesExisted[1] : FindCreatedCharge(job, chargesExisted);
					AssertCollectionContains("Tested charge is in Job.Charges", chargeToTest, job.Charges);
					AssertCostChargeValues(chargeToTest, CC7, null, null, false, AUD, 1, -expectedLocalCostAmount, -expectedLocalCostAmount, null, 0, null, 0, "", ZDateTime.Empty, ZDateTime.Empty);
					if (multipleCharges)
					{
						AssertSellChargeValues(chargeToTest, CC7, null, LocalClient, false, chargeCurrency, chargeExRate, 0, 0, GSTFREE1, 0, WHTFREE1, 0);
					}
					else
					{
						AssertSellChargeValues(chargeToTest, CC7, null, LocalClient, false, AUD, 1, 0, 0, GSTFREE1, 0, WHTFREE1, 0);
					}
				}
			}

			ReleaseFactory();
		}

		Charge FindCreatedCharge(Job job, IEnumerable<Charge> chargesExisted)
		{
			var chargesCreated = job.Charges.Find(new ZQuery(JobChargeSchema.PK, SQLComparisonOperator.NotEqual, chargesExisted.Select(x => x.PK)));
			AssertEquals("Amount of created charges", 1, chargesCreated.Length);

			return (Charge)chargesCreated[0];
		}

		#endregion

		[TestDate(2013, 2, 20, 10, 50, 00)]
		public void TestCopyConsolCostFields()
		{
			using (AccountingConfigurationRegistry.Instance.BringForwardAgainstCreditor.SetTemporaryValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, false))
			using (AccountingMasterFilesRegistry.Instance.EnableTaxBranchReporting.SetTemporaryValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, true))
			{
				var shipment = TestObjectCreator.CreateShipment("S0001");
				shipment.JS_INCO = Constants.IncoTerms.CostAndFreight;
				var consol = Factory.New<ForwardingConsol>();
				consol.Shipments.Add(shipment);
				Factory.Save();

				var job = TestObjectCreator.CreateJob(shipment, false);

				var apportionments = new ApportionmentListing(Factory, consol);
				var consolCost = apportionments.CostsCollection.TryAddNew();
				consolCost.E6_AC_ChargeCode = TestObjectCreator.CC1.PK;

				// Fields under test that should be copied to >>
				consolCost.E6_OH_Creditor = TestObjectCreator.AALSHI.PK;
				consolCost.E6_RX_NKCurrency = Enterprise.Core.Constants.CurrencyCodes.Australia;
				consolCost.E6_RX_NKCurrency = "USD";
				consolCost.E6_ExchangeRate = 1.1m;
				consolCost.E6_OSCostAmount = 11m;
				AssertEquals("precondition on E6_LocalCostAmount", 10m, consolCost.E6_LocalCostAmount); // This gets calcualted because the JobConsolCostCollection causes there to be a calculation strategy
				consolCost.E6_PPDCLT = Enterprise.Core.Constants.DomesticPaymentTerms.Prepaid;
				consolCost.E6_GB_CostTaxBranch = GlbBranch.CurrentBranch.PK;
				consolCost.E6_AT_TaxRate = TestObjectCreator.GST1.PK;
				consolCost.E6_A9_VATClass = TestObjectCreator.TaxMsg1.PK;
				AssertEquals("precondition on E6_OSGSTAmount_Calc", 1.1m, consolCost.E6_OSGSTAmount_Calc); // This gets calcualted because the JobConsolCostCollection causes there to be a calculation strategy
				consolCost.E6_InvoiceNum = "I001";
				consolCost.E6_InvoiceDate = ZDateTime.Now;
				consolCost.E6_DocumentReceivedDate = ZDateTime.Now;
				consolCost.E6_PaymentDate = ZDateTime.Now;
				consolCost.E6_CostReference = "CR001";
				consolCost.E6_ApportionmentMethod = AllocationMethod.ChargeableUnits;
				consolCost.E6_CostGovtChargeCode = "S00987";
				consolCost.E6_SellGovtChargeCode = "S00987";
				consolCost.E6_SupplyType = "DSB";
				// << end fields under test
				Factory.Save();

				var factory2 = new BusinessObjectFactory();
				var testObjectCreator2 = new TestObjectCreator(factory2);

				var invoice =
					testObjectCreator2.CreateAPInvoice<APInvoice>("T001", TestObjectCreator.AUD, 1m, 0m, 0m, 0m, 0m, 0m, 0m);
				invoice.AH_OH = TestObjectCreator.AALSHI.PK;
				invoice.SubmittedFromInvoicingForm = true;
				invoice.AH_TransactionNum = "I002";
				invoice.AH_PostDate = ZDateTime.Now.AddDays(1);
				invoice.AH_InvoiceDate = ZDateTime.Now.AddDays(1);
				invoice.AH_DocumentReceivedDate = ZDateTime.Now.AddDays(1);
				invoice.AH_GB_TaxBranch = TestObjectCreator.NonCurrentBranch.PK;

				shipment.JS_INCO = Constants.IncoTerms.ExWorks;

				var updatingConsolCost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
				updatingConsolCost.E6_AC_ChargeCode = TestObjectCreator.CC1.PK;

				// Fields under test that should be copied to >>
				updatingConsolCost.E6_OH_Creditor = TestObjectCreator.ABIGAS.PK;
				updatingConsolCost.E6_RX_NKCurrency = Enterprise.Core.Constants.CurrencyCodes.Brazil;
				updatingConsolCost.E6_ExchangeRate = 1.2m;
				updatingConsolCost.E6_OSCostAmount = 24m;
				updatingConsolCost.E6_LocalCostAmount =
					20m; // This is BYO because the APInvoiceConsolCostCollection means no calculation strategy
				updatingConsolCost.E6_PPDCLT = Enterprise.Accounting.Integration.PrepaidCollectList.Codes.All;
				updatingConsolCost.E6_SupplyType = "LOC";
				updatingConsolCost.E6_GB_CostTaxBranch = TestObjectCreator.NonCurrentBranch.PK;
				updatingConsolCost.E6_AT_TaxRate = TestObjectCreator.GSTFREE1.PK;
				updatingConsolCost.E6_A9_VATClass = TestObjectCreator.TaxMsg2.PK;
				updatingConsolCost.E6_OSGSTAmount_Calc =
					0m; // This is BYO because the APInvoiceConsolCostCollection means no calculation strategy
				updatingConsolCost.E6_InvoiceNum = "I002";
				updatingConsolCost.E6_InvoiceDate = ZDateTime.Now.AddDays(1);
				updatingConsolCost.E6_DocumentReceivedDate = ZDateTime.Now.AddDays(1);
				updatingConsolCost.E6_PaymentDate = ZDateTime.Now.AddDays(1);
				updatingConsolCost.E6_CostReference = "CR002";
				updatingConsolCost.E6_ApportionmentMethod = AllocationMethod.Revenue;
				updatingConsolCost.E6_CostGovtChargeCode = "S00988";
				updatingConsolCost.E6_SellGovtChargeCode = "S00988";
				// << end fields under test

				invoice.ImportAllApportionmentsFromCosting();
				GetTransformer(factory2).Transform(invoice);
				var consolCostReloaded = factory2.Load<JobConsolCost>(consolCost.PK);

				AssertEquals(consolCostReloaded.E6_OH_Creditor, TestObjectCreator.ABIGAS.PK);
				AssertEquals(consolCostReloaded.E6_RX_NKCurrency, Enterprise.Core.Constants.CurrencyCodes.Brazil);
				AssertEquals(consolCostReloaded.E6_ExchangeRate, 1.2m);
				AssertEquals(consolCostReloaded.E6_OSCostAmount, 24m);
				AssertEquals(consolCostReloaded.E6_LocalCostAmount, 20m);
				AssertEquals(consolCostReloaded.E6_PPDCLT, Enterprise.Accounting.Integration.PrepaidCollectList.Codes.All);
				AssertEquals(consolCostReloaded.E6_AT_TaxRate, TestObjectCreator.GSTFREE1.PK);
				AssertEquals(consolCostReloaded.E6_A9_VATClass, TestObjectCreator.TaxMsg2.PK);
				AssertEquals(consolCostReloaded.E6_OSGSTAmount_Calc, 0m);
				AssertEquals(consolCostReloaded.E6_InvoiceNum, "I002");
				AssertEquals(consolCostReloaded.E6_InvoiceDate, ZDateTime.Now.AddDays(1));
				AssertEquals(consolCostReloaded.E6_DocumentReceivedDate, ZDateTime.Now.AddDays(1));
				AssertEquals(consolCostReloaded.E6_PaymentDate, ZDateTime.Now.AddDays(1));
				AssertEquals(consolCostReloaded.E6_CostReference, "CR002");
				AssertEquals(consolCostReloaded.E6_ApportionmentMethod, AllocationMethod.Revenue);
				AssertEquals(consolCostReloaded.E6_CostGovtChargeCode, "S00988");
				AssertEquals(consolCostReloaded.E6_SellGovtChargeCode, "S00988");
				AssertEquals(consolCostReloaded.E6_SupplyType, "LOC");
				AssertEquals(consolCostReloaded.E6_GB_CostTaxBranch, TestObjectCreator.NonCurrentBranch.PK);
			}
		}

		#region TestCreateCarryForwardChargeInOSCurrency

		public void TestCreateCarryForwardChargeInOSCurrencyWithRegistryOn()
		{
			ForwardingShipment shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = TestObjectCreator.LocalClient2.PK;
			shipment.ConsignorDocumentaryAddress.OrganisationPK = TestObjectCreator.LocalClient.PK;
			shipment.JS_INCO = Constants.IncoTerms.ExWorks;
			Job job = new Job.Loader(shipment).TryCreateWithoutMutexForTestOnly();

			job.JH_GE = GlbDepartment.CurrentDepartment.PK;

			var fREIGHT = TestObjectCreator.CC1.PK;
			var bAF = TestObjectCreator.CC2.PK;

			var aALSHI = TestObjectCreator.AALSHI.PK;
			var aBIGAS = TestObjectCreator.ABIGAS.PK;

			Charge charge1 = job.Charges.AddNew();
			charge1.JR_OH_CostAccount = aALSHI;
			charge1.JR_AC = fREIGHT;
			charge1.JR_RX_NKCostCurrency = USD.RX_Code;
			charge1.CostExchangeRate.SetBuyRate_ForTestOnly(0.9000m);
			charge1.JR_OSCostAmt = 100m;

			Charge charge2 = job.Charges.AddNew();
			charge2.JR_OH_CostAccount = aBIGAS;
			charge2.JR_AC = bAF;
			charge2.JR_RX_NKCostCurrency = GBP.RX_Code;
			charge2.CostExchangeRate.SetBuyRate_ForTestOnly(0.7130m);
			charge2.JR_OSCostAmt = 100m;

			Factory.Save();

			APInvoice invoice = Factory.New<APInvoice>();
			invoice.AH_OH = aALSHI;
			invoice.SubmittedFromInvoicingForm = true;
			invoice.AH_RX_NKTransactionCurrency = AUD.RX_Code;
			invoice.AH_ExchangeRate = 1.0m;

			APInvoiceLine line1 = (APInvoiceLine)invoice.Lines.AddNew();
			line1.AL_JH = job.PK;
			line1.AL_AC = fREIGHT;
			line1.AL_RX_NKTransactionCurrency = USD.RX_Code;
			line1.AL_ExchangeRate = 0.9000m;
			line1.AL_OSExTaxAmount = 50m;

			APInvoiceLine line2 = (APInvoiceLine)invoice.Lines.AddNew();
			line2.AL_JH = job.PK;
			line2.AL_AC = bAF;
			line2.AL_RX_NKTransactionCurrency = GBP.RX_Code;
			line2.AL_ExchangeRate = 0.7130m;
			line2.AL_OSExTaxAmount = 50m;

			new TransactionLineJobChargeTransformer(Factory).Transform(invoice);

			Assert("Job should have 4 charges now", job.Charges.Count == 4);
			var charges = job.Charges.ToArray<Charge>();
			AssertChargesContainsCharge(charges, fREIGHT, aALSHI, USD.RX_Code, 0.9000m, 50m, 55.56m);
			AssertChargesContainsCharge(charges, fREIGHT, aALSHI, USD.RX_Code, 0.9000m, 50m, 55.55m);
			AssertChargesContainsCharge(charges, bAF, aBIGAS, GBP.RX_Code, 0.7130m, 100m, 140.25m);
			AssertChargesContainsCharge(charges, bAF, aALSHI, GBP.RX_Code, 0.7130m, 50m, 70.13m);
		}

		public void TestCreateCarryForwardChargeInOSCurrencyWithRegistryOff()
		{
			var originalValue = AccountingConfigurationRegistry.Instance.BringForwardAgainstCreditor.GetValueWithoutFallback(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty);

			ForwardingShipment shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = TestObjectCreator.LocalClient2.PK;
			shipment.ConsignorDocumentaryAddress.OrganisationPK = TestObjectCreator.LocalClient.PK;
			shipment.JS_INCO = Constants.IncoTerms.ExWorks;
			Job job = new Job.Loader(shipment).TryCreateWithoutMutexForTestOnly();

			job.JH_GE = GlbDepartment.CurrentDepartment.PK;

			var fREIGHT = TestObjectCreator.CC1.PK;
			var bAF = TestObjectCreator.CC2.PK;

			var aALSHI = TestObjectCreator.AALSHI.PK;
			var aBIGAS = TestObjectCreator.ABIGAS.PK;

			Charge charge1 = job.Charges.AddNew();
			charge1.JR_OH_CostAccount = aALSHI;
			charge1.JR_AC = fREIGHT;
			charge1.JR_RX_NKCostCurrency = USD.RX_Code;
			charge1.CostExchangeRate.SetBuyRate_ForTestOnly(0.9000m);
			charge1.JR_OSCostAmt = 100m;

			Charge charge2 = job.Charges.AddNew();
			charge2.JR_OH_CostAccount = aBIGAS;
			charge2.JR_AC = bAF;
			charge2.JR_RX_NKCostCurrency = GBP.RX_Code;
			charge2.CostExchangeRate.SetBuyRate_ForTestOnly(0.7130m);
			charge2.JR_OSCostAmt = 100m;

			Factory.Save();

			APInvoice invoice = Factory.New<APInvoice>();
			invoice.AH_OH = aALSHI;
			invoice.SubmittedFromInvoicingForm = true;
			invoice.AH_RX_NKTransactionCurrency = AUD.RX_Code;
			invoice.AH_ExchangeRate = 1.0m;

			APInvoiceLine line1 = (APInvoiceLine)invoice.Lines.AddNew();
			line1.AL_JH = job.PK;
			line1.AL_AC = fREIGHT;
			line1.AL_RX_NKTransactionCurrency = USD.RX_Code;
			line1.AL_ExchangeRate = 0.9000m;
			line1.AL_OSExTaxAmount = 50m;

			APInvoiceLine line2 = (APInvoiceLine)invoice.Lines.AddNew();
			line2.AL_JH = job.PK;
			line2.AL_AC = bAF;
			line2.AL_RX_NKTransactionCurrency = GBP.RX_Code;
			line2.AL_ExchangeRate = 0.7130m;
			line2.AL_OSExTaxAmount = 50m;

			try
			{
				AccountingConfigurationRegistry.Instance.BringForwardAgainstCreditor.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, false);
				new TransactionLineJobChargeTransformer(Factory).Transform(invoice);
			}
			finally
			{
				AccountingConfigurationRegistry.Instance.BringForwardAgainstCreditor.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, originalValue);
			}

