			Charge charge2 = job.Charges.AddNew();
			charge2.JR_OH_CostAccount = aBIGAS;
			charge2.JR_AC = fREIGHT;
			charge2.JR_RX_NKCostCurrency = GBP.RX_Code;
			charge2.CostExchangeRate.SetBuyRate_ForTestOnly(0.7130m);
			charge2.JR_OSCostAmt = 100m;

			Charge charge3 = job.Charges.AddNew();
			charge3.JR_OH_CostAccount = aALSHI;
			charge3.JR_AC = bAF;
			charge3.JR_RX_NKCostCurrency = GBP.RX_Code;
			charge3.CostExchangeRate.SetBuyRate_ForTestOnly(0.7130m);
			charge3.JR_OSCostAmt = 50m;

