			charge1.CostExchangeRate.SetBuyRate_ForTestOnly(0.9000m);

			Charge charge2 = job.Charges.AddNew();
			charge2.JR_OH_CostAccount = aBIGAS;
			charge2.JR_AC = bAF;
			charge2.JR_RX_NKCostCurrency = GBP.RX_Code;
			job.ExchangeRates[1].JF_BaseRate = 0m; //reset to 0 as for test default is always 1m
			charge2.JR_OSCostAmt = 100m;
			charge2.CostExchangeRate.SetBuyRate_ForTestOnly(0.7130m);

			foreach (ExchangeRate rate in job.ExchangeRates)
			{
				if (rate.JF_RX_NKRateCurrency == "USD")
				{
					rate.JF_BaseRate = 0.9000m;
				}

				if (rate.JF_RX_NKRateCurrency == "GBP")
				{
					rate.JF_BaseRate = 0.7130m;
				}
			}

			Factory.Save();

			APInvoice invoice = Factory.New<APInvoice>();
			invoice.AH_OH = aALSHI;
			invoice.SubmittedFromInvoicingForm = true;
			invoice.AH_RX_NKTransactionCurrency = AUD.RX_Code;
			invoice.AH_ExchangeRate = 1.0m;

			APInvoiceLine line1 = (APInvoiceLine)invoice.Lines.AddNew();
			line1.AL_JH = job.PK;
			line1.AL_AC = fREIGHT;
			line1.AL_RX_NKTransactionCurrency = USD.RX_Code;
			line1.AL_ExchangeRate = 0.9100m;
			line1.AL_OSExTaxAmount = 50m;

			APInvoiceLine line2 = (APInvoiceLine)invoice.Lines.AddNew();
			line2.AL_JH = job.PK;
			line2.AL_AC = bAF;
			line2.AL_RX_NKTransactionCurrency = GBP.RX_Code;
			line2.AL_ExchangeRate = 0.7230;
			line2.AL_OSExTaxAmount = 50m;

			new TransactionLineJobChargeTransformer(Factory).Transform(invoice);

			Assert("Job should have 4 charges now", job.Charges.Count == 4);
			var charges = job.Charges.ToArray<Charge>();
			AssertChargesContainsCharge(charges, fREIGHT, aALSHI, USD.RX_Code, 0.9100m, 50.00m, 54.95m, LocalClient.PK, AUD.RX_Code, 1.0000m, 0.00m, 0.00m);
			AssertChargesContainsCharge(charges, bAF, aBIGAS, GBP.RX_Code, 0.7130m, 100.00m, 140.25m, LocalClient.PK, AUD.RX_Code, 1.0000m, 140.25m, 140.25m);
			AssertChargesContainsCharge(charges, fREIGHT, aALSHI, AUD.RX_Code, 1.0000m, 56.16m, 56.16m, LocalClient.PK, AUD.RX_Code, 1.0000m, 0.00m, 0.00m);
			AssertChargesContainsCharge(charges, bAF, aALSHI, GBP.RX_Code, 0.7230m, 50.00m, 69.16m, LocalClient.PK, AUD.RX_Code, 1.0000m, 69.16m, 69.16m);
			//70.13m, 70.13m -no more possible as exchange rate 0.7130 exists for another creditor - ABIGAS, for we have a different creditor - AALSHI - on line 4 
			//we pick up the generic exchange rate having value 0.7230m. I think this behavior is more correct and consistent (e.g compare 2d and 4th charges)
		}

