			var shipmentJob = new Job.Loader(shipment1).TryLoadOrCreateWithoutMutexForTestOnly();
			var shipmentLevelCharge = shipmentJob.Charges.AddNew();
			shipmentLevelCharge.JR_OH_CostAccount = ZGuid.Empty;
			shipmentLevelCharge.JR_AC = fRT;
			shipmentLevelCharge.JR_RX_NKCostCurrency = USD.RX_Code;
			shipmentLevelCharge.CostExchangeRate.SetBaseRate(1.2500m);
			AssertEquals(1.2500m, shipmentLevelCharge.JR_OSCostExRate);
			shipmentLevelCharge.JR_OSCostAmt = 88.00m;
			shipmentLevelCharge.RevenueExchangeRate.SetBaseRate(1.2500m);
			AssertEquals(1.2500m, shipmentLevelCharge.JR_OSSellExRate);
			shipmentLevelCharge.JR_OSSellAmt = 88.00m;

			shipmentJob.ExchangeRates[0].JF_BaseRate = 1.2500m;

			Factory.Save();

			shipmentJob.Reload();
			Assert("shipment should have 2 charges now", shipmentJob.Charges.Count == 2);
			var charges = shipmentJob.Charges.ToArray<Charge>();
			AssertChargesContainsCharge(charges, fRT, aALSHI, USD.RX_Code, 1.2m, 100m, 83.34m);
			AssertChargesContainsCharge(charges, fRT, ZGuid.Empty, USD.RX_Code, 1.25m, 88m, 70.4m);

			var invoice = Factory.NewWithValidTestData<APInvoice>();
			invoice.AH_OH = aALSHI;
			invoice.SubmittedFromInvoicingForm = true;
			invoice.AH_RX_NKTransactionCurrency = USD.RX_Code;
			invoice.AH_ExchangeRate = 1.210m;

			var invoiceConsolCosting = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			invoiceConsolCosting.IsFinal = false;
			invoiceConsolCosting.E6_AC_ChargeCode = fRT;
			invoiceConsolCosting.E6_OSCostAmount = 180m;
			invoiceConsolCosting.E6_ApportionmentMethod = "SHP";
			invoiceConsolCosting.E6_OH_Creditor = aALSHI;

			invoice.ImportSingleCost(invoiceConsolCosting, (InvoicingLineBase)invoice.Lines.AddNew());
			AssertEquals("3 Lines should be imported", 3, invoice.Lines.Count);

			foreach (InvoicingLineBase line in invoice.Lines)
			{
				AssertEquals(line.AL_AC, consolCost.E6_AC_ChargeCode);
				AssertEquals(line.AL_RX_NKTransactionCurrency, consolCost.E6_RX_NKCurrency);
				AssertEquals(line.AL_ExchangeRate, invoice.AH_ExchangeRate);
				AssertEquals(line.AL_OSExTaxAmount, invoiceConsolCosting.E6_OSCostAmount / 3);
			}

			Factory.Save();

			shipmentJob.Charges.Reload(true);
			AssertEquals("Job should have 3 charges now", 3, shipmentJob.Charges.Count);
			charges = shipmentJob.Charges.ToArray<Charge>();

			AssertChargesContainsCharge(charges, fRT, aALSHI, USD.RX_Code, 1.2100m, 60.00m, 49.58m, ZGuid.Empty, USD.RX_Code, 1.2500m, 100.00m, 80.00m);
			AssertChargesContainsCharge(charges, fRT, ZGuid.Empty, USD.RX_Code, 1.2500m, 88.00m, 70.40m, ZGuid.Empty, USD.RX_Code, 1.2500m, 88.00m, 70.40m);
			AssertChargesContainsCharge(charges, fRT, aALSHI, AUD.RX_Code, 1.0000m, 33.75m, 33.75m, ZGuid.Empty, AUD.RX_Code, 1.0000m, 0.00m, 0.00m);
		}

