			dep.GE_Misc = false;
			Factory.Save();

			var local = TestObjectCreator.LocalClient.PK;

			var fRT = TestObjectCreator.CC1.PK;
			var aALSHI = TestObjectCreator.AALSHI.PK;
			var aBIGAS = TestObjectCreator.ABIGAS.PK;

			AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsGreaterThanAccrual.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);

			var consol = Factory.NewWithValidTestData<ForwardingConsol>();

			var shipment1 = consol.Shipments.AddNew();
			var shipment2 = consol.Shipments.AddNew();
			var shipment3 = consol.Shipments.AddNew();

			var shipmentJob = new Job.Loader(shipment1).TryLoadOrCreateWithoutMutexForTestOnly();
			var shipmentJob2 = new Job.Loader(shipment2).TryLoadOrCreateWithoutMutexForTestOnly();
			var shipmentJob3 = new Job.Loader(shipment3).TryLoadOrCreateWithoutMutexForTestOnly();

			shipmentJob.LocalChargesPK = local;

			Factory.Save();

			var appListing = new ApportionmentListing(Factory, consol);
			var consolCost = appListing.CostsCollection.TryAddNew();
			consolCost.E6_OH_Creditor = aALSHI;
			consolCost.E6_AC_ChargeCode = fRT;
			consolCost.E6_RX_NKCurrency = USD.RX_Code;
			consolCost.E6_ExchangeRate = 1.2000m;
			consolCost.E6_OSCostAmount = 300m;
			consolCost.E6_ApportionmentMethod = "SHP";

			Factory.Save();

			shipmentJob.LocalCharges?.CompanyData.AccCFXConfigurations.SetUplifts("ALL", "ALL", "ALL", 10m);
			shipmentJob.AgentCollect?.CompanyData.AccCFXConfigurations.SetUplifts("ALL", "ALL", "ALL", 5m);
			shipmentJob.Charges[0].JR_OH_SellAccount = local;
			shipmentJob2.Charges[0].JR_OH_SellAccount = local;
			shipmentJob3.Charges[0].JR_OH_SellAccount = local;

			shipmentJob.Charges[0].JR_RX_NKSellCurrency = USD.RX_Code;
			shipmentJob.Charges[0].JR_OSSellAmt = 100m;

			shipmentJob.ExchangeRates[0].JF_BaseRate = 1.100m;

			Factory.Save();

			Assert("shipment should have 1 charges now", shipmentJob.Charges.Count == 1);
			var charges = shipmentJob.Charges.ToArray<Charge>();
			AssertChargesContainsCharge(charges, fRT, aALSHI, USD.RX_Code, 1.2m, 100m, 83.34m, local, USD.RX_Code, 0.99m, 100m, 101.01m);

			var invoice = Factory.New<APInvoice>();
			invoice.AH_OH = aALSHI;
			invoice.SubmittedFromInvoicingForm = true;
			invoice.AH_RX_NKTransactionCurrency = USD.RX_Code;
			invoice.AH_ExchangeRate = 1.3m;

			var invoiceConsolCosting = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			invoiceConsolCosting.IsFinal = false;
			invoiceConsolCosting.E6_AC_ChargeCode = fRT;
			invoiceConsolCosting.E6_OSCostAmount = 600m;
			invoiceConsolCosting.E6_ApportionmentMethod = "SHP";
			invoiceConsolCosting.E6_OH_Creditor = aALSHI;

			invoice.ImportSingleCost(invoiceConsolCosting, (InvoicingLineBase)invoice.Lines.AddNew());
			AssertEquals("3 Lines should be imported", 3, invoice.Lines.Count);

			foreach (InvoicingLineBase line in invoice.Lines)
			{
				AssertEquals(line.AL_AC, consolCost.E6_AC_ChargeCode);
				AssertEquals(line.AL_RX_NKTransactionCurrency, consolCost.E6_RX_NKCurrency);
				AssertEquals(line.AL_ExchangeRate, invoice.AH_ExchangeRate);
				AssertEquals(line.AL_OSExTaxAmount, invoiceConsolCosting.E6_OSCostAmount / 3);
			}

			new TransactionLineJobChargeTransformer(Factory).Transform(invoice);

			shipmentJob.Reload();
			Assert("Job should have 2 charges now", shipmentJob.Charges.Count == 2);

			charges = shipmentJob.Charges.ToArray<Charge>();

			AssertChargesContainsCharge(charges, fRT, aALSHI, USD.RX_Code, 1.3000m, 200.00m, 153.84m, LocalClient.PK, USD.RX_Code, 0.9900m, 100.00m, 101.01m);
			AssertChargesContainsCharge(charges, fRT, ZGuid.Empty, AUD.RX_Code, 1.0000m, 0.00m, 0.00m, LocalClient.PK, AUD.RX_Code, 1.0000m, 70.51m, 70.51m);
		}

