		#region TestCreateCarryForwardChargeHelper
		void GenerateAssertChargesContainsChargeCodes(Charge[] charges, string testName)
		{
			System.Diagnostics.Debug.Print("\r\n ### " + testName);

			ZString emptyZGuid = "ZGuid.Empty";

			foreach (var charge in charges)
			{
				var assert = charge != null ? string.Format(
					//@"AssertChargesContainsCharge(charges, FRT, AALSHI, USD.RX_Code, 1.2m, 200m, 166.67m, AALSHI, USD.RX_Code, 0.99m, 100m, 101.01m);"
					@"AssertChargesContainsCharge(charges, {0}, {1},    {2}.RX_Code, {3:F4}m, {4:F2}m, {5:F2}m,    {6},    {7}.RX_Code, {8:F4}m,  {9:F2}m, {10:F2}m); //IsCostPosted:{11}, IsRevPosted:{12}"
				,

				charge.ChargeCode.AC_Code == "ZZCC1" ? "FRT" : "BAF",    //0
				charge.CostAccount != null ? charge.CostAccount.OH_Code : emptyZGuid, //1
				charge.JR_RX_NKCostCurrency, //2
				charge.JR_OSCostExRate, //3
				charge.JR_OSCostAmt, //4
				charge.JR_LocalCostAmt, //5

				charge.SellAccount != null ? charge.SellAccount.OH_Code : emptyZGuid, //6
				charge.JR_RX_NKSellCurrency, //7
				charge.JR_OSSellExRate, //8
				charge.JR_OSSellAmt, //9
				charge.JR_LocalSellAmt, //10
				charge.IsCostPosted, //11
				charge.IsRevenuePosted //12
				) : "null";

				System.Diagnostics.Debug.Print(assert);
			}
		}

		void AssertChargesContainsCharge(Charge[] charges, ZGuid jR_AC
			, ZGuid jR_OH_CostAccount, ZString jR_RX_NKCostCurrency, decimal jR_OSCostExRate, decimal jR_OSCostAmt, decimal jR_LocalCostAmt)
		{
			for (var i = 0; i < charges.Length; i++)
			{
				var charge = charges[i];

				if (charge != null && charge.JR_AC == jR_AC
					&& charge.JR_RX_NKCostCurrency == jR_RX_NKCostCurrency
					&& charge.JR_OSCostExRate == jR_OSCostExRate
					&& charge.JR_OSCostAmt == jR_OSCostAmt
					&& charge.JR_OH_CostAccount == jR_OH_CostAccount
					&& charge.JR_LocalCostAmt == jR_LocalCostAmt)
				{
					charges[i] = null;
					return;
				}
			}

			GenerateAssertChargesContainsChargeCodes(charges, "AssertChargesContainsCharge");
			Assert("the ChargeCollection should contain the charge", false);
		}

		Charge AssertChargesContainsCharge(Charge[] charges, ZGuid jR_AC
			, ZGuid jR_OH_CostAccount, ZString jR_RX_NKCostCurrency, decimal jR_OSCostExRate, decimal jR_OSCostAmt, decimal jR_LocalCostAmt, bool isCostPosted)
		{
			for (var i = 0; i < charges.Length; i++)
			{
				var charge = charges[i];

				if (charge != null && charge.JR_AC == jR_AC
					&& charge.JR_RX_NKCostCurrency == jR_RX_NKCostCurrency
					&& charge.JR_OSCostExRate == jR_OSCostExRate
					&& charge.JR_OSCostAmt == jR_OSCostAmt
					&& charge.JR_OH_CostAccount == jR_OH_CostAccount
					&& charge.JR_LocalCostAmt == jR_LocalCostAmt
					&& charge.IsCostPosted == isCostPosted)
				{
					var result = charges[i];
					charges[i] = null;
					return result;
				}
			}

			GenerateAssertChargesContainsChargeCodes(charges, "AssertChargesContainsCharge");
			Assert("the ChargeCollection should contain the charge", false);
			return null;
		}

		Charge AssertChargesContainsCharge(Charge[] charges, ZGuid jR_AC
			, ZGuid jR_OH_CostAccount, ZString jR_RX_NKCostCurrency, decimal jR_OSCostExRate, decimal jR_OSCostAmt, decimal jR_LocalCostAmt
			, ZGuid jR_OH_SellAccount, ZString jR_RX_NKSellCurrency, decimal jR_OSSellExRate, decimal jR_OSSellAmt, decimal jR_LocalSellAmt)
		{
			for (var i = 0; i < charges.Length; i++)
			{
				var charge = charges[i];
				if (charge != null && charge.JR_AC == jR_AC
					&& charge.JR_RX_NKCostCurrency == jR_RX_NKCostCurrency
					&& charge.JR_OSCostExRate == jR_OSCostExRate
					&& charge.JR_OSCostAmt == jR_OSCostAmt
					&& charge.JR_OH_CostAccount == jR_OH_CostAccount
					&& charge.JR_LocalCostAmt == jR_LocalCostAmt

					&& charge.JR_RX_NKSellCurrency == jR_RX_NKSellCurrency
					&& charge.JR_OSSellExRate == jR_OSSellExRate
					&& charge.JR_OSSellAmt == jR_OSSellAmt
					&& charge.JR_OH_SellAccount == jR_OH_SellAccount
					&& charge.JR_LocalSellAmt == jR_LocalSellAmt

					)
				{
					var result = charges[i];
					charges[i] = null;
					return result;
				}
			}

			GenerateAssertChargesContainsChargeCodes(charges, "AssertChargesContainsCharge");
			Assert("the ChargeCollection should contain the charge", false);
			return null;
		}

		Charge AssertChargesContainsCharge(Charge[] charges, ZGuid jR_AC
			, ZGuid jR_OH_CostAccount, ZString jR_RX_NKCostCurrency, decimal jR_OSCostExRate, decimal jR_OSCostAmt, decimal jR_LocalCostAmt
			, ZGuid jR_OH_SellAccount, ZString jR_RX_NKSellCurrency, decimal jR_OSSellExRate, decimal jR_OSSellAmt, decimal jR_LocalSellAmt
			, bool isCostPosted, bool isRevenuePosted, string relatedJobNumber = null)
		{
			var charge = AssertChargesContainsCharge(charges, jR_AC, jR_OH_CostAccount, jR_RX_NKCostCurrency, jR_OSCostExRate, jR_OSCostAmt, jR_LocalCostAmt
			, jR_OH_SellAccount, jR_RX_NKSellCurrency, jR_OSSellExRate, jR_OSSellAmt, jR_LocalSellAmt);

			AssertEquals(isCostPosted, charge.IsCostPosted);
			AssertEquals(isRevenuePosted, charge.IsRevenuePosted);
			AssertEquals(relatedJobNumber ?? ZString.Empty, charge.JR_Calc_RelatedJobNumber);

			return charge;
		}

