		public void TestCreateCarryForwardChargeInOSCurrencyForImportedJobCharge_CarryForwardAmountGreaterThanZero()
		{
			AccountingConfigurationRegistry.Instance.CarryForwardAccrualBasedOnOSAmountWhereCSTCurrencyEqualsACRCurrency.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);

			var shipment = TestObjectCreator.CreateShipment("S00000001", true);
			var job = TestObjectCreator.CreateJob(shipment, false);
			var exchangeRate = job.ExchangeRates.AddNew();
			exchangeRate.JF_RX_NKRateCurrency = "USD";
			exchangeRate.JF_OH_Org = Creditor1.PK;
			exchangeRate.JF_OrgType = ExchangeRateOrgTypeEnum.Creditor.ToCode();
			exchangeRate.JF_BaseRate = 0.7M;
			var charge = CreateCharge(job, CC1, "Desc", USD, 100m, Creditor1, USD, 0m, LocalClient);
			Factory.Save();

			var invoice = CreateAPInvoice("INV001", Creditor1, TestObjectCreator.USD, 0.8M, "Test Invoice");
			var invoiceLine = (InvoicingLineBase)invoice.Lines.AddNew();
			invoiceLine.AL_JH = job.PK;
			invoice.ImportJobChargesIntoInvoice(new[] { charge }, invoiceLine);
			invoiceLine.AL_OSExTaxAmount = 90M;
			GetTransformer(Factory).Transform(invoice);

			var charges = job.Charges.ToArray<Charge>();
			AssertEquals(2, charges.Length);
			AssertChargesContainsCharge(charges, CC1.PK, Creditor1.PK, "USD", 0.8M, 90M, 112.5M);
			AssertChargesContainsCharge(charges, CC1.PK, Creditor1.PK, "USD", 0.8M, 10M, 12.5M);
		}

