		#region APInvoicePostingExchangeRateOption

		[TestDate(2015, 1, 1)]
		public void TestAPInvoicePostingExchangeRateOptionWithShipment()
		{
			using (PostingExRateRegistryAP.SetTemporaryValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, "INV"))
			using (AccountingConfigurationRegistry.Instance.BringForwardAgainstCreditor.SetTemporaryValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, false))
			{
				//today's rate & tomorrow's rate
				TestObjectCreator.CreateUSDBuyRate(2.1111m, new DateTime(2015, 01, 01));
				TestObjectCreator.CreateUSDBuyRate(4.1111m, new DateTime(2015, 01, 02));

				var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
				shipment.ConsigneeDocumentaryAddress.OrganisationPK = TestObjectCreator.LocalClient2.PK;
				shipment.ConsignorDocumentaryAddress.OrganisationPK = TestObjectCreator.LocalClient.PK;
				shipment.JS_INCO = Constants.IncoTerms.ExWorks;
				var job = new Job.Loader(shipment).TryCreateWithoutMutexForTestOnly();

				job.JH_GE = GlbDepartment.CurrentDepartment.PK;

				var fREIGHT = TestObjectCreator.CC1.PK;
				var bAF = TestObjectCreator.CC2.PK;

				var aALSHI = TestObjectCreator.AALSHI.PK;
				var aBIGAS = TestObjectCreator.ABIGAS.PK;

				var charge1 = job.Charges.AddNew();
				charge1.JR_OH_CostAccount = aALSHI;
				charge1.JR_AC = fREIGHT;
				charge1.JR_RX_NKCostCurrency = USD.RX_Code;
				AssertEquals("should be today's rate", 2.1111m, charge1.JR_OSCostExRate);
				charge1.JR_OSCostAmt = 100m;

				Factory.Save();

				var jobRate = ((IExchangeRateProvider)job).GetExchangeRate(TestObjectCreator.USD.RX_Code, aALSHI, ExchangeRateValidLedgerEnum.AP);
				AssertEquals("rate should be today's rate.", 2.1111m, jobRate.Rate);

				var invoice = Factory.New<APInvoice>();
				invoice.AH_OH = aALSHI;
				invoice.AH_InvoiceDate = new DateTime(2015, 01, 02);
				invoice.SubmittedFromInvoicingForm = true;
				invoice.AH_RX_NKTransactionCurrency = "USD";
				AssertEquals("should be tomorrow's rate", 4.1111m, invoice.AH_ExchangeRate);

				var line1 = (APInvoiceLine)invoice.Lines.AddNew();
				line1.AL_JH = job.PK;
				line1.AL_AC = fREIGHT;
				line1.AL_RX_NKTransactionCurrency = "USD";
				AssertEquals("should be tomorrow's rate", 4.1111m, line1.AL_ExchangeRate);
				line1.AL_OSExTaxAmount = 50m;

				new TransactionLineJobChargeTransformer(Factory).Transform(invoice);

				Assert("Job should have 2 charges now", job.Charges.Count == 2);
				var charges = job.Charges.ToArray<Charge>();

				//should be today's rate
				jobRate = ((IExchangeRateProvider)job).GetExchangeRate(TestObjectCreator.USD.RX_Code, aALSHI, ExchangeRateValidLedgerEnum.AP);
				AssertEquals("should be tomorrow's rate now", 4.1111m, jobRate.Rate);
				AssertChargesContainsCharge(charges, fREIGHT, aALSHI, USD.RX_Code, 4.1111m, 50m, 12.16m);
				AssertChargesContainsCharge(charges, fREIGHT, ZGuid.Empty, USD.RX_Code, 4.1111m, 50m, 12.16m); //carry forward charge
				ExchangeRateReader.GetReaderInstance().ClearCache();
			}
		}

		[TestDate(2015, 1, 1)]
		public void TestARAPInvoicePostingExchangeRateOptionWithConsolCosting()
		{
			ExchangeRateReader.GetReaderInstance().ClearCache();
			PostingExRateRegistryAP.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, "INV");

			//today's rate & tomorrow's rate
			TestObjectCreator.CreateUSDBuyRate(2m, new DateTime(2015, 01, 01));
			TestObjectCreator.CreateUSDBuyRate(4m, new DateTime(2015, 01, 02));

			var dep = Factory.Load<GlbDepartment>(Env.CurrentDepartment.PK);
			dep.GE_Misc = false;
			Factory.Save();

			var fRT = TestObjectCreator.CC1.PK;
			var aALSHI = TestObjectCreator.AALSHI.PK;

			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			var shipment1 = consol.Shipments.AddNew();
			var shipment2 = consol.Shipments.AddNew();
			var shipment3 = consol.Shipments.AddNew();

			var appListing = new ApportionmentListing(Factory, consol);
			var consolCost = appListing.CostsCollection.TryAddNew();
			consolCost.E6_OH_Creditor = aALSHI;
			consolCost.E6_AC_ChargeCode = fRT;
			consolCost.E6_RX_NKCurrency = USD.RX_Code;
			AssertEquals("should be today's rate", 2m, consolCost.E6_ExchangeRate);
			consolCost.E6_OSCostAmount = 300m;
			consolCost.E6_ApportionmentMethod = "SHP";

			var shipmentJob = new Job.Loader(shipment1).TryLoadOrCreateWithoutMutexForTestOnly();
			Factory.Save();

			shipmentJob.Reload();
			Assert("shipment should have 1 charges now", shipmentJob.Charges.Count == 1);
			var shipmentCharge = shipmentJob.Charges[0];
			AssertEquals("USD", shipmentCharge.JR_CostCurrency);
			AssertEquals("should be today's rate", 2m, shipmentCharge.JR_OSCostExRate);

			var invoice = Factory.NewWithValidTestData<APInvoice>();
			invoice.AH_OH = aALSHI;
			invoice.AH_InvoiceDate = new DateTime(2015, 01, 02);
			invoice.SubmittedFromInvoicingForm = true;
			invoice.AH_RX_NKTransactionCurrency = USD.RX_Code;
			AssertEquals("should be tomorrow's rate", 4m, invoice.AH_ExchangeRate);

			var invoiceConsolCosting = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			invoiceConsolCosting.IsFinal = false;
			invoiceConsolCosting.E6_AC_ChargeCode = fRT;
			invoiceConsolCosting.E6_OSCostAmount = 180m;
			invoiceConsolCosting.E6_ApportionmentMethod = "SHP";
			invoiceConsolCosting.E6_OH_Creditor = aALSHI;

			invoice.ImportSingleCost(invoiceConsolCosting, (InvoicingLineBase)invoice.Lines.AddNew());
			AssertEquals("3 Lines should be imported", 3, invoice.Lines.Count);

			foreach (InvoicingLineBase line in invoice.Lines)
			{
				AssertEquals(line.AL_AC, consolCost.E6_AC_ChargeCode);
				AssertEquals(line.AL_RX_NKTransactionCurrency, "USD");
				AssertEquals(line.AL_ExchangeRate, 4m);
				AssertEquals(line.AL_OSExTaxAmount, invoiceConsolCosting.E6_OSCostAmount / 3);
			}

			Factory.Save();

			AssertEquals("USD", consolCost.E6_RX_NKCurrency);
			AssertEquals("consol's rate should be updated", 4m, consolCost.E6_ExchangeRate);
			AssertEquals(180m, consolCost.E6_OSCostAmount);

			shipmentJob.Charges.Reload(true);

			Assert("shipment should have 2 charges now", shipmentJob.Charges.Count == 2);
			var shipmentCharge1 = shipmentJob.Charges[0];
			var shipmentCharge2 = shipmentJob.Charges[1];

			AssertEquals("USD", shipmentCharge1.JR_CostCurrency);
			AssertEquals(4m, shipmentCharge1.JR_OSCostExRate);

			AssertEquals("USD", shipmentCharge2.JR_CostCurrency); //carry forward charge
			AssertEquals(4m, shipmentCharge2.JR_OSCostExRate);

			ExchangeRateReader.GetReaderInstance().ClearCache();
		}

