		public void TestIsOnlyOneOSCurrencyAndRateNullRef()
		{
			var creator = new TestObjectCreator(Factory);
			var chargeCode = creator.CC1;
			chargeCode.AC_MarginPercentage = 80m;
			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			consol.Shipments.AddNew();

			Factory.Save();

			var apps = new ApportionmentListing(Factory, consol);
			var consolCost = apps.CostsCollection.TryAddNew();
			consolCost.E6_AC_ChargeCode = chargeCode.PK;
			consolCost.E6_OSCostAmount = 100m;

			Factory.Save();

			var jobPK = consolCost.ApportionmentCharges[0].JR_JH;
			var accrualQuery = new ZQuery(AccTransactionLinesSchema.AL_JH, jobPK);
			accrualQuery.AddToFilter(AccTransactionLinesSchema.AL_GC, GlbCompany.CurrentCompany.PK);
			accrualQuery.AddToFilter(JoinCondition.And, AccTransactionLinesSchema.AL_LineAmount, 100m);

			var accruals = Factory.Load<Accrual>(accrualQuery);
			AssertEquals(1, accruals.Length);
			var accrualPK = accruals[0].PK;
			AssertEquals(100m, accruals[0].AL_LineAmount);
			AssertEquals(ZDateTime.Empty, accruals[0].AL_ReverseDate);

			var postDate = ZDateTime.Now.AddDays(-10);

			var apInvoice = (APInvoice)Factory.New(GetInvoiceType());
			apInvoice.AH_PostDate = postDate;
			apInvoice.SubmittedFromInvoicingForm = true;
			apInvoice.AH_OH = creator.AALSHI.PK;
			apInvoice.AH_TransactionNum = "INV1";
			apInvoice.AH_RX_NKTransactionCurrency = creator.USD.RX_Code;
			apInvoice.AH_ExchangeRate = 0.7m;
			apInvoice.AH_InvoiceDate = ZDateTime.Now;
			apInvoice.AH_DueDate = ZDateTime.Now.AddDays(2);

			var compatibleLineType = new AccTransactionLinesCompatibilityMatrixTestHelper().GetCompatibleLineType(apInvoice.AH_Ledger, apInvoice.AH_TransactionType);

			var cost = apInvoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			cost.E6_AC_ChargeCode = chargeCode.PK;
			cost.E6_OSCostAmount = 100m;
			cost.E6_ApportionmentMethod = "SHP";
			apInvoice.ImportAllApportionmentsFromCosting();
			apInvoice.Lines[0].AL_AG = TestObjectCreator.GLHeader1.PK;
			apInvoice.Lines[0].AL_ReverseDate = ZDateTime.MinSmallDateTimeValue;
			apInvoice.Lines[0].AL_LineType = compatibleLineType;
			apInvoice.Lines.Add(Factory.NewWithValidTestData<APInvoiceLine>());
			apInvoice.Lines[1].AL_AG = TestObjectCreator.GLHeader1.PK;
			apInvoice.Lines[1].AL_AC = ZGuid.Empty;
			apInvoice.Lines[1].AL_LineType = compatibleLineType;
			AssertNoExceptionThrown(Factory.Save);
		}

