		public void TestNewChargeIsCreatedWhenSpecificChargeChangedToApportionment()
		{
			var consol = TestObjectCreator.CreateConsol();
			var shipment = TestObjectCreator.CreateShipment("S00001", consol);
			var job = TestObjectCreator.CreateJob(shipment, false);
			var charge = TestObjectCreator.CreateCharge(job);
			Factory.Save();

			var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), "INV1", organisation: Creditor1);
			invoice.SubmittedFromInvoicingForm = true;
			invoice.ImportJobChargesIntoInvoice(new[] { charge }, (InvoicingLineBase)invoice.Lines.AddNew(), false);

			invoice.RunPreSaveValidation();
			AssertNoErrors(invoice);

			var newFactoryTestObjectCreator = new TestObjectCreator(new BusinessObjectFactory());
			var newFactoryConsol = newFactoryTestObjectCreator.Factory.Load<ForwardingConsol>(consol.PK);
			newFactoryTestObjectCreator.CreateConsolCost(newFactoryConsol, CC1, 100);
			newFactoryTestObjectCreator.Factory.Save();
			Assert("Precondition: JR_IsApportioned", charge.JR_IsApportioned);
			AssertEquals("Precondition: Charges.Count", 1, job.Charges.Count);

			invoice.Factory.Save();

			AssertEquals(2, job.Charges.Count);
			var charges = job.Charges.ToArray<Charge>();

			AssertChargesContainsCharge(charges, CC1.PK, ZGuid.Empty, AUD.Code, 1m, 100m, 100m, false);
			AssertChargesContainsCharge(charges, CC1.PK, Creditor1.PK, AUD.Code, 1m, 100m, 100m, true);
		}

