					AssertChargesContainsCharge(charges, chargeCode.PK, ZGuid.Empty, "AUD", 1m, 200m, 200m, false);
					AssertChargesContainsCharge(charges, chargeCode.PK, Creditor1.PK, "AUD", 1m, 300m, 300m, true);
				}
			}
		}

