		public void TestPostConsolCostWithSameChargeCodeWithDifferentCreditorsCstGreaterThanAllAcr()
		{
			AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsGreaterThanAccrual.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);

			var dep = Factory.Load<GlbDepartment>(Env.CurrentDepartment.PK);
			dep.GE_Misc = false;
			Factory.Save();

			var fRT = TestObjectCreator.CC1;
			var creditor1 = TestObjectCreator.AALSHI;
			var creditor2 = TestObjectCreator.ABIGAS;

			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			consol.Shipments.AddNew();
			consol.Shipments.AddNew();

			var appListing = new ApportionmentListing(Factory, consol);
			var consolCost1 = TestObjectCreator.CreateConsolCost(consol, fRT, 500, creditor1, "SHP", appListing);
			var consolCost2 = TestObjectCreator.CreateConsolCost(consol, fRT, 200, creditor2, "SHP", appListing);
			var consolCost3 = TestObjectCreator.CreateConsolCost(consol, fRT, 100, null, "SHP", appListing);

			Factory.Save();

			foreach (ForwardingShipment shipment in consol.Shipments)
			{
				var shipmentJob = new Job.Loader(shipment).TryLoadOrCreateWithoutMutexForTestOnly();
				AssertEquals(3, shipmentJob.Charges.Count);
				var charges = shipmentJob.Charges.ToArray<Charge>();

				AssertChargesContainsCharge(charges, fRT.PK, creditor1.PK, "AUD", 1m, 250m, 250m, false);
				AssertChargesContainsCharge(charges, fRT.PK, creditor2.PK, "AUD", 1m, 100m, 100m, false);
				AssertChargesContainsCharge(charges, fRT.PK, ZGuid.Empty, "AUD", 1m, 50m, 50m, false);
			}

			AssertConsolCost(consolCost1, fRT, 500m, creditor1, false);
			AssertConsolCost(consolCost2, fRT, 200m, creditor2, false);
			AssertConsolCost(consolCost3, fRT, 100m, null, false);

			Factory.Save();

			var invoice = Factory.NewWithValidTestData<APInvoice>();
			invoice.AH_OH = creditor1.PK;
			invoice.SubmittedFromInvoicingForm = true;
			invoice.AH_RX_NKTransactionCurrency = "AUD";
			invoice.AH_ExchangeRate = 1m;

			var invoiceConsolCost1 = TestObjectCreator.CreateConsolCost(invoice, consol, fRT, 750, creditor1);
			invoiceConsolCost1.IsFinal = false;

			invoice.ImportAllApportionmentsFromCosting();
			AssertEquals(2, invoice.Lines.Count);
			AssertEquals(-375m, invoice.Lines[0].AL_LineAmount);
			AssertEquals(-375m, invoice.Lines[1].AL_LineAmount);

			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			var consolInNewFactory = newFactory.Load<ForwardingConsol>(consol.PK);
			var consolCostsAfterSave = consolInNewFactory.GetApportionments().CostsCollection;

			AssertEquals(3, consolCostsAfterSave.Count);
			AssertConsolCost(consolCostsAfterSave[0], fRT, 750m, creditor1, true);
			AssertConsolCost(consolCostsAfterSave[1], fRT, 200m, creditor2, false);
			AssertConsolCost(consolCostsAfterSave[2], fRT, 100m, null, false);

			foreach (ForwardingShipment shipment in consolInNewFactory.Shipments)
			{
				var shipmentJob = new Job.Loader(shipment).TryLoadOrCreateWithoutMutexForTestOnly();
				AssertEquals(4, shipmentJob.Charges.Count);
				var charges = shipmentJob.Charges.ToArray<Charge>();

				var charge1 = AssertChargesContainsCharge(charges, fRT.PK, creditor2.PK, "AUD", 1m, 100m, 100m,
											ZGuid.Empty, "AUD", 1m, 100m, 100m); //unchanged
				Assert(!charge1.IsCostPosted);
				Assert(!charge1.IsRevenuePosted);
				Assert(charge1.JR_IsApportioned);

				var charge2 = AssertChargesContainsCharge(charges, fRT.PK, creditor1.PK, "AUD", 1m, 375m, 375m,
											 ZGuid.Empty, "AUD", 1m, 250m, 250m); //250->375
				Assert(charge2.IsCostPosted);
				Assert(!charge2.IsRevenuePosted);
				Assert(charge2.JR_IsApportioned);

				var charge3 = AssertChargesContainsCharge(charges, fRT.PK, ZGuid.Empty, "AUD", 1m, 50m, 50m,
											ZGuid.Empty, "AUD", 1m, 50m, 50m); //unchanged
				Assert(!charge3.IsCostPosted);
				Assert(!charge3.IsRevenuePosted);
				Assert(charge3.JR_IsApportioned);

				var charge4 = AssertChargesContainsCharge(charges, fRT.PK, ZGuid.Empty, "AUD", 1m, 0m, 0m,
											ZGuid.Empty, "AUD", 1m, 125m, 125m); // 375 - 250
				Assert(!charge4.IsCostPosted);
				Assert(!charge4.IsRevenuePosted);
				Assert(!charge4.JR_IsApportioned);
			}
		}

		[DisableZeroExchangeRateOverriding]
		public void TestPostConsolCostWithSameChargeCodeWithDifferentCreditorsCstGreaterThanAcrWithDiffExRate()
		{
			ExchangeRateReader.GetReaderInstance().ClearCache();

			AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsGreaterThanAccrual.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);

			var dep = Factory.Load<GlbDepartment>(Env.CurrentDepartment.PK);
			dep.GE_Misc = false;
			Factory.Save();

			var fRT = TestObjectCreator.CC1;
			var creditor1 = TestObjectCreator.AALSHI;
			var creditor2 = TestObjectCreator.ABIGAS;

			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			consol.Shipments.AddNew();

			var appListing = new ApportionmentListing(Factory, consol);
			var consolCost1 = TestObjectCreator.CreateConsolCost(consol, fRT, 500, creditor1, "SHP", appListing);
			var consolCost2 = TestObjectCreator.CreateConsolCost(consol, fRT, 200, creditor2, "SHP", appListing);
			var consolCost3 = TestObjectCreator.CreateConsolCost(consol, fRT, 100, null, "SHP", appListing);

			consolCost1.E6_RX_NKCurrency = consolCost2.E6_RX_NKCurrency = consolCost3.E6_RX_NKCurrency = "USD";
			consolCost1.E6_ExchangeRate = consolCost2.E6_ExchangeRate = consolCost3.E6_ExchangeRate = 1.5m;

			Factory.Save();

			var shipmentJob1 = new Job.Loader(consol.Shipments[0]).TryLoadOrCreateWithoutMutexForTestOnly();
			AssertEquals(3, shipmentJob1.Charges.Count);
			var charges = shipmentJob1.Charges.ToArray<Charge>();
			AssertChargesContainsCharge(charges, fRT.PK, creditor1.PK, "USD", 1.5m, 500m, 333.33m, ZGuid.Empty, "USD", 1.5m, 500m, 333.33m);
			AssertChargesContainsCharge(charges, fRT.PK, creditor2.PK, "USD", 1.5m, 200m, 133.33m, ZGuid.Empty, "USD", 1.5m, 200m, 133.33m);
			AssertChargesContainsCharge(charges, fRT.PK, ZGuid.Empty, "USD", 1.5m, 100m, 66.67m, ZGuid.Empty, "USD", 1.5m, 100m, 66.67m);

			Factory.Save();

			var invoice = Factory.NewWithValidTestData<APInvoice>();
			invoice.AH_OH = creditor1.PK;
			invoice.SubmittedFromInvoicingForm = true;
			invoice.AH_RX_NKTransactionCurrency = "USD";
			invoice.AH_ExchangeRate = 1.6m;

			var invoiceConsolCost1 = TestObjectCreator.CreateConsolCost(invoice, consol, fRT, 550, creditor1);
			invoiceConsolCost1.E6_RX_NKCurrency = "USD";
			invoiceConsolCost1.E6_ExchangeRate = 1.6;
			invoiceConsolCost1.E6_OSCostAmount = 550m;
			AssertEquals(343.75m, invoiceConsolCost1.E6_LocalCostAmount);

			invoiceConsolCost1.IsFinal = false;

			invoice.ImportAllApportionmentsFromCosting();
			AssertEquals(1, invoice.Lines.Count);

			AssertEquals(-343.75m, invoice.Lines[0].AL_LineAmount);
			AssertEquals("USD", invoice.Lines[0].AL_RX_NKTransactionCurrency);
			AssertEquals(550m, invoice.Lines[0].AL_OSExTaxAmount);
			AssertEquals(1.6m, invoice.Lines[0].AL_ExchangeRate);

			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			var consolInNewFactory = newFactory.Load<ForwardingConsol>(consol.PK);
			var consolCostsAfterSave = consolInNewFactory.GetApportionments().CostsCollection;

			AssertEquals(3, consolCostsAfterSave.Count);
			AssertConsolCost(consolCostsAfterSave[0], fRT, 550m, creditor1, true, "USD", 1.6m, 343.75m);
			AssertConsolCost(consolCostsAfterSave[1], fRT, 200m, creditor2, false, "USD", 1.5m, 133.33m);
			AssertConsolCost(consolCostsAfterSave[2], fRT, 100m, null, false, "USD", 1.5m, 66.67m);

			shipmentJob1 = new Job.Loader(consolInNewFactory.Shipments[0]).TryLoadOrCreateWithoutMutexForTestOnly();
			AssertEquals(4, shipmentJob1.Charges.Count);
			charges = shipmentJob1.Charges.ToArray<Charge>();

			var charge = AssertChargesContainsCharge(charges, fRT.PK, creditor1.PK, "USD", 1.6000m, 550.00m, 343.75m, ZGuid.Empty, "USD", 1.5000m, 500.00m, 333.33m);
			AssertEquals(true, charge.IsCostPosted && !charge.IsRevenuePosted);
			charge = AssertChargesContainsCharge(charges, fRT.PK, creditor2.PK, "USD", 1.5000m, 200.00m, 133.33m, ZGuid.Empty, "USD", 1.5000m, 200.00m, 133.33m);
			AssertEquals(true, !charge.IsCostPosted && !charge.IsRevenuePosted);
			charge = AssertChargesContainsCharge(charges, fRT.PK, ZGuid.Empty, "USD", 1.5000m, 100.00m, 66.67m, ZGuid.Empty, "USD", 1.5000m, 100.00m, 66.67m);
			AssertEquals(true, !charge.IsCostPosted && !charge.IsRevenuePosted);
			charge = AssertChargesContainsCharge(charges, fRT.PK, ZGuid.Empty, "AUD", 1.0000m, 0m, 0m, ZGuid.Empty, "AUD", 1.0000m, 10.42m, 10.42m);
			AssertEquals(true, !charge.IsCostPosted && !charge.IsRevenuePosted);

			ExchangeRateReader.GetReaderInstance().ClearCache();
		}

