		public void TestPostConsolCostWithSameChargeCode_ImportedConsolCostHasDifferentSignWithExisting()
		{
			ApportionmentListing appListing = null;
			Job job = null;
			ZGuid[] consolCostPKsBeforePost, chargePKsBeforePost;
			SetUpTestPostConsolCostWithSameChargeCode_ImportedConsolCostHasDifferentSignWithExisting(false, out appListing, out job, out consolCostPKsBeforePost, out chargePKsBeforePost);

			AssertEquals("We create a new consol cost", 3, appListing.CostsCollection.Count);
			var newConsolCost = appListing.CostsCollection.Cast<JobConsolCost>().First(x => !consolCostPKsBeforePost.Contains(x.PK));
			AssertEquals(-10M, newConsolCost.E6_LocalCostAmount);
			AssertEquals("Carry Forward Consol Cost", 1, appListing.CostsCollection.Cast<JobConsolCost>().Count(x => x.E6_LocalCostAmount == 15M));
			AssertEquals("Remain unchanged", 1, appListing.CostsCollection.Cast<JobConsolCost>().Count(x => x.E6_LocalCostAmount == 4M));

			job.Charges.Reload(true);
			AssertEquals("We create a new apportioned charge and push the carry forward amount to others", 3, job.Charges.Count);
			var newCharge = job.Charges.Cast<JobCharge>().First(x => !chargePKsBeforePost.Contains(x.PK));
			AssertEquals(-10M, newCharge.JR_LocalCostAmt);
			AssertEquals("Add the carry forward amount to the charge with same creditor, 5 - (-10) = 15", TestObjectCreator.AALSHI.PK, job.Charges.Cast<JobCharge>().First(x => x.JR_LocalCostAmt == 15M).JR_OH_CostAccount);
			AssertEquals("Add the carry forward amount to the charge which is linked to a new consol cost, 5 - (-10) = 15", false, job.Charges.Cast<JobCharge>().First(x => x.JR_LocalCostAmt == 15M).JR_E6.IsEmpty);
			AssertEquals("Remain unchanged", 1, job.Charges.Cast<JobCharge>().Count(x => x.JR_LocalCostAmt == 4M));
		}

		public void TestPostConsolCostWithSameChargeCode_ImportedConsolCostHasDifferentSignWithExisting_IsFinal()
		{
			ApportionmentListing appListing = null;
			Job job = null;
			ZGuid[] existingConsolCostPKs, existingChargePKs;
			SetUpTestPostConsolCostWithSameChargeCode_ImportedConsolCostHasDifferentSignWithExisting(true, out appListing, out job, out existingConsolCostPKs, out existingChargePKs);

			AssertEquals("We create a new consol cost, delete the redundant ones", 1, appListing.CostsCollection.Count);
			var newConsolCost = appListing.CostsCollection[0];
			AssertCollectionNotContains("Current consol cost is newly created", newConsolCost.PK, existingConsolCostPKs);
			AssertEquals(-10M, newConsolCost.E6_LocalCostAmount);

			AssertEquals("We create a new apportioned charge, reverse and delete the redundant ones", 1, job.Charges.Count);
			var newCharge = job.Charges[0];
			AssertCollectionNotContains("Current apportioned charge is newly created", newCharge.PK, existingChargePKs);
			AssertEquals(-10M, newCharge.JR_LocalCostAmt);
			AssertEquals("The newly created charge should be apportioned from the newly created consol cost", newConsolCost.PK, newCharge.JR_E6);
		}

		void SetUpTestPostConsolCostWithSameChargeCode_ImportedConsolCostHasDifferentSignWithExisting(bool isFinal, out ApportionmentListing appListing, out Job job, out ZGuid[] consolCostPKsBeforePost, out ZGuid[] chargePKsBeforePost)
		{
			AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, false);

			var consol = TestObjectCreator.CreateConsol(consolNum: "C001");
			var shipment = TestObjectCreator.CreateShipment("S001", consol);
			appListing = new ApportionmentListing(Factory, consol);
			var consolCost1 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC11, 5M, TestObjectCreator.AALSHI, "MAN", appListing);
			var consolCost2 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC11, 4M, null, "MAN", appListing);
			consolCostPKsBeforePost = new ZGuid[] { consolCost1.PK, consolCost2.PK };
			Factory.Save();

			job = shipment.Job as Job;
			AssertEquals(2, job.Charges.Count);
			job.Charges.Cast<Charge>().ForEach(x => x.JR_LocalSellAmt = 0M);
			chargePKsBeforePost = job.Charges.Cast<Charge>().Select(x => x.PK).ToArray();
			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			var newTestObjectCreator = new TestObjectCreator(newFactory);

			var invoice = newTestObjectCreator.CreateInvoice(typeof(APInvoice), GlbCompany.CurrentCompany.LocalCurrency, 1M, TestObjectCreator.AALSHI);
			invoice.SubmittedFromInvoicingForm = true;
			var testConsolCost = newTestObjectCreator.CreateConsolCost(invoice, consol, TestObjectCreator.CC11, -10M, TestObjectCreator.AALSHI);
			testConsolCost.IsFinal = isFinal;
			invoice.ImportAllApportionmentsFromCosting();
			AssertEquals(1, invoice.Lines.Count);
			AssertEquals("Should be equal to the charge amount", -10M, invoice.Lines[0].AL_LocalExTaxAmount);
			AssertEquals(isFinal, invoice.Lines[0].AL_IsFinalCharge);

			var line = newTestObjectCreator.CreateInvoiceLine(invoice, GlbCompany.CurrentCompany.LocalCurrency, 1M, 12M, 0M, 0M, 12M, 0M, 0M);
			line.AL_AG = newTestObjectCreator.GLHeader1.PK;
			line.AL_JH = ZGuid.Empty;

			AssertNoExceptionThrown("We won't post charge related to other consol cost. All posted consol costs are defined after SynchroniseCosts", newFactory.Save);
		}

		public void TestPostConsolCostWithSameChargeCode_NotPostingChargeRelatedToAnotherConsolCost()
		{
			ApportionmentListing appListing;
			Job job1, job2;
			ZGuid[] consolCostPKsBeforePost, chargePKsBeforePost;
			SetUpTestPostConsolCostWithSameChargeCode_NotPostingChargeRelatedToAnotherConsolCost(false, out appListing, out job1, out job2, out consolCostPKsBeforePost, out chargePKsBeforePost);

			AssertEquals(3, appListing.CostsCollection.Count);
			var consolCost2 = appListing.CostsCollection.Cast<JobConsolCost>().FirstOrDefault(x => x.E6_LocalCostAmount == 8M);
			AssertNotNull("A new consol cost has been Posted with amount 8", consolCost2);
			var consolCost3 = appListing.CostsCollection.Cast<JobConsolCost>().FirstOrDefault(x => x.E6_LocalCostAmount == 12M);
			AssertNotNull("Existing consol cost with amount 20 has been updated to amount (20-8)=12", consolCost3);
			var consolCost4 = appListing.CostsCollection.Cast<JobConsolCost>().FirstOrDefault(x => x.E6_LocalCostAmount == 10M);
			AssertNotNull("Existing consol cost with amount 10 remains unchanged", consolCost4);

			var sortedCharges = job1.Charges.Cast<Charge>().OrderBy(x => x.JR_OSCostAmt).ToArray();
			AssertEquals("Job 1 Charges remained unchanged", 2, sortedCharges.Length);
			AssertCollectionContains("Remain unchanged", sortedCharges[0].PK, chargePKsBeforePost);
			AssertCollectionContains("Remain unchanged", sortedCharges[1].PK, chargePKsBeforePost);
			AssertEquals("Remain unchanged", 4M, sortedCharges[0].JR_LocalCostAmt);
			AssertEquals("Remain unchanged", 10M, sortedCharges[1].JR_LocalCostAmt);

			AssertEquals("We create a new apportioned charge in shipment2", 2, job2.Charges.Count);
			var previousCharge = job2.Charges.Cast<JobCharge>().First(x => chargePKsBeforePost.Contains(x.PK));
			AssertEquals("The amount of the charge has been changed from 16 to 8, 16 + (0 - 8) = 8", 8M, previousCharge.JR_LocalCostAmt);
			var newCharge = job2.Charges.Cast<JobCharge>().First(x => !chargePKsBeforePost.Contains(x.PK));
			AssertEquals("The amount of the charge has been changed from 0 to 8", 8M, newCharge.JR_LocalCostAmt);
			AssertEquals("The newly created charge should be apportioned from the correct consol cost", consolCost2.PK, newCharge.JR_E6);
		}

		public void TestPostConsolCostWithSameChargeCode_NotPostingChargeRelatedToAnotherConsolCost_IsFinal()
		{
			ApportionmentListing appListing;
			Job job1, job2;
			ZGuid[] consolCostPKsBeforePost, chargePKsBeforePost;
			SetUpTestPostConsolCostWithSameChargeCode_NotPostingChargeRelatedToAnotherConsolCost(true, out appListing, out job1, out job2, out consolCostPKsBeforePost, out chargePKsBeforePost);

			AssertEquals(3, appListing.CostsCollection.Count);
			var consolCost2 = appListing.CostsCollection.Cast<JobConsolCost>().FirstOrDefault(x => x.E6_LocalCostAmount == 8M);
			AssertNotNull("A new consol cost with amount 8 is posted", consolCost2);
			var consolCost3 = appListing.CostsCollection.Cast<JobConsolCost>().FirstOrDefault(x => x.E6_LocalCostAmount == 4M);
			AssertNotNull("Existing consol cost with amount 20 is updated to 4, as Job 2's apporiton charge is posted as final", consolCost3);
			var consolCost4 = appListing.CostsCollection.Cast<JobConsolCost>().FirstOrDefault(x => x.E6_LocalCostAmount == 10M);
			AssertNotNull("Existing consol cost with amount 10 remains unchanged", consolCost4);

			var sortedCharges = job1.Charges.Cast<Charge>().OrderBy(x => x.JR_OSCostAmt).ToArray();
			AssertEquals("Job 1 Charges remained unchanged", 2, sortedCharges.Length);
			AssertCollectionContains("Remain unchanged", sortedCharges[0].PK, chargePKsBeforePost);
			AssertCollectionContains("Remain unchanged", sortedCharges[1].PK, chargePKsBeforePost);
			AssertEquals("Remain unchanged", 4M, sortedCharges[0].JR_LocalCostAmt);
			AssertEquals("Remain unchanged", 10M, sortedCharges[1].JR_LocalCostAmt);

			AssertEquals("We create a new apportioned charge, reverse and delete the redundant ones in shipment2", 1, job2.Charges.Count);
			var newCharge = job2.Charges[0];
			AssertCollectionNotContains("Current apportioned charge is newly created", newCharge.PK, chargePKsBeforePost);
			AssertEquals(8M, newCharge.JR_LocalCostAmt);
			AssertEquals("The newly created charge should be apportioned from the correct consol cost", consolCost2.PK, newCharge.JR_E6);
		}

		void SetUpTestPostConsolCostWithSameChargeCode_NotPostingChargeRelatedToAnotherConsolCost(bool isFinal, out ApportionmentListing appListing, out Job job1, out Job job2, out ZGuid[] consolCostPKsBeforePost, out ZGuid[] chargePKsBeforePost)
		{
			var consol = TestObjectCreator.CreateConsol(consolNum: "C001");
			var shipment1 = TestObjectCreator.CreateShipment("S001", consol);
			var shipment2 = TestObjectCreator.CreateShipment("S002", consol);
			appListing = new ApportionmentListing(Factory, consol);
			var consolCost1 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC11, 20M, null, "MAN", appListing);
			var consolCost2 = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC11, 10M, TestObjectCreator.AALSHI, "MAN", appListing);
			consolCost1.ApportionmentCharges[0].JR_OSCostAmt = 4m;
			consolCost1.ApportionmentCharges[1].JR_OSCostAmt = 16m;
			consolCostPKsBeforePost = new ZGuid[] { consolCost1.PK, consolCost2.PK };
			var charge1InConsol = consolCost2.ApportionmentCharges.Cast<ApportionSplitCharge>().First(x => x.JR_JobNumber == shipment1.JobNumber);
			var charge2InConsol = consolCost2.ApportionmentCharges.Cast<ApportionSplitCharge>().First(x => x.JR_JobNumber == shipment2.JobNumber);
			charge1InConsol.JR_IsUsedForApportionment = true;
			charge2InConsol.JR_IsUsedForApportionment = false;
			AssertEquals(10M, charge1InConsol.JR_OSCostAmt);
			AssertEquals(0M, charge2InConsol.JR_OSCostAmt);
			Factory.Save();

			job1 = shipment1.Job as Job;
			AssertEquals(2, job1.Charges.Count);
			job1.Charges.Cast<Charge>().ForEach(x => x.JR_LocalSellAmt = 0M);
			job2 = shipment2.Job as Job;
			AssertEquals(1, job2.Charges.Count);
			job2.Charges.Cast<Charge>().ForEach(x => x.JR_LocalSellAmt = 0M);
			chargePKsBeforePost = job1.Charges.Cast<Charge>().Union(job2.Charges.Cast<Charge>()).Select(x => x.PK).ToArray();
			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			var newTestObjectCreator = new TestObjectCreator(newFactory);

			var invoice = newTestObjectCreator.CreateInvoice(typeof(APInvoice), GlbCompany.CurrentCompany.LocalCurrency, 1M, TestObjectCreator.AALSHI);
			invoice.SubmittedFromInvoicingForm = true;
			var testConsolCost = newTestObjectCreator.CreateConsolCost(invoice, consol, TestObjectCreator.CC11, 8M, TestObjectCreator.AALSHI);
			var charge1InInvoice = testConsolCost.ApportionmentCharges.Cast<ApportionSplitCharge>().First(x => x.JR_JobNumber == shipment1.JobNumber);
			var charge2InInvoice = testConsolCost.ApportionmentCharges.Cast<ApportionSplitCharge>().First(x => x.JR_JobNumber == shipment2.JobNumber);
			charge1InInvoice.JR_IsUsedForApportionment = false;
			charge2InInvoice.JR_IsUsedForApportionment = true;
			charge2InInvoice.IsFinal = isFinal;
			AssertEquals(0M, charge1InInvoice.JR_OSCostAmt);
			AssertEquals(8M, charge2InInvoice.JR_OSCostAmt);

			invoice.ImportAllApportionmentsFromCosting();
			AssertEquals(1, invoice.Lines.Count);
			AssertEquals("Should be equal to the charge amount", 8M, invoice.Lines[0].AL_LocalExTaxAmount);
			AssertEquals(isFinal, invoice.Lines[0].AL_IsFinalCharge);

			AssertNoExceptionThrown("We won't post charge related to other consol cost. All posted consol costs are defined after SynchroniseCosts", newFactory.Save);
		}

