		//existing shipment charge
		public void TestPostConsolCostWithSameChargeCodeWithCarryForwardChargeWithExistingShipmentCharge_ManualInput()
		{
			var consol = CreateConsolWithConsolCostWithSameChargeCode();

			var fRT = TestObjectCreator.CC1;
			var creditor1 = TestObjectCreator.AALSHI;
			var creditor2 = TestObjectCreator.ABIGAS;
			var cost1 = consol.GetApportionments().CostsCollection[0];
			var cost2 = consol.GetApportionments().CostsCollection[1];
			var cost3 = consol.GetApportionments().CostsCollection[2];

			AssertConsolCost(cost1, fRT, 300m, creditor1, false);
			AssertConsolCost(cost2, fRT, 600m, creditor2, false);
			AssertConsolCost(cost3, fRT, 900m, null, false);

			//add local charge
			var shipment1Job = new Job.Loader(consol.Shipments[0]).TryLoadOrCreateWithoutMutexForTestOnly();
			var charge1 = TestObjectCreator.CreateCharge(shipment1Job, fRT, 10, 10);
			charge1.JR_OH_CostAccount = creditor1.PK;
			charge1.JR_OH_SellAccount = ZGuid.Empty;

			var shipment2Job = new Job.Loader(consol.Shipments[1]).TryLoadOrCreateWithoutMutexForTestOnly();
