		public void TestGetPossibleChargesToCalculateCarryForwardAmountAndUpdateNotUseApportionmentChargesLinkedToDifferentConsol()
		{
			var gstRate = TestObjectCreator.CreateTaxRate("GST19", "GST 19 Percent", 19);
			var dsbChargeCode = TestObjectCreator.CreateChargeCode("DSB", "Description", Core.Constants.ChargeType.Disbursement, 100.00m, gstRate, null, "ALL");
			Factory.Save();

			var consol1 = TestObjectCreator.CreateConsol(consolNum: "C001");
			var shipment1 = TestObjectCreator.CreateShipment("S001", consol1);
			var appListing1 = new ApportionmentListing(Factory, consol1);
			var consolCost1 = TestObjectCreator.CreateConsolCost(consol1, dsbChargeCode, 0.09M, TestObjectCreator.AALSHI, "MAN", appListing1);

			AssertEquals(1, consolCost1.ApportionmentCharges.Count);
			AssertEquals(0.09M, consolCost1.ApportionmentCharges[0].JR_LocalCostAmt);
			AssertEquals(0.02M, consolCost1.ApportionmentCharges[0].JR_Cost_LocalGSTAmount);

			var consol2 = TestObjectCreator.CreateConsol("CNSHA", "USCHA", "C002");
			consol2.Shipments.Add(shipment1);
			var shipment2 = TestObjectCreator.CreateShipment("S002", consol2);
			var appListing2 = new ApportionmentListing(Factory, consol2);
			var consolCost2 = TestObjectCreator.CreateConsolCost(consol2, dsbChargeCode, 770.00M, TestObjectCreator.AALSHI, "MAN", appListing2);

			AssertEquals(2, consolCost2.ApportionmentCharges.Count);

			consolCost2.ApportionmentCharges[0].JR_OSCostAmt = 128.93M;
			consolCost2.ApportionmentCharges[1].JR_OSCostAmt = 641.07M;

			AssertEquals(24.50M, consolCost2.ApportionmentCharges[0].JR_Cost_LocalGSTAmount);
			AssertEquals(121.80M, consolCost2.ApportionmentCharges[1].JR_Cost_LocalGSTAmount);

			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			var newTestObjectCreator = new TestObjectCreator(newFactory);

			var invoice = newTestObjectCreator.CreateInvoice(typeof(APInvoice), GlbCompany.CurrentCompany.LocalCurrency, 1M, TestObjectCreator.AALSHI);
			invoice.SubmittedFromInvoicingForm = true;
			var testConsolCost = newTestObjectCreator.CreateConsolCost(invoice, consol1, dsbChargeCode, 0.10M, TestObjectCreator.AALSHI);
			testConsolCost.IsFinal = false;
			invoice.ImportAllApportionmentsFromCosting();
			AssertEquals(1, invoice.Lines.Count);
			AssertEquals("Should be equal to the charge amount", 0.10M, invoice.Lines[0].AL_LocalExTaxAmount);
			AssertEquals("Should be equal to the charge gst amount", 0.02M, invoice.Lines[0].AL_OSTaxAmount);

			AssertNoExceptionThrown("Invoice should be posted without Critical Validation Error as we would not use Apportionment Charges linked to a different Consol", newFactory.Save);

			Assert("Should be posted", consolCost1.IsPosted);
			AssertEquals("Should be updated from the invoice line amount", 0.10M, consolCost1.ApportionmentCharges[0].JR_LocalCostAmt);
			AssertEquals("Should be updated from the invoice line gst amount", 0.02M, consolCost1.ApportionmentCharges[0].JR_Cost_LocalGSTAmount);

			Assert("Should not be posted", !consolCost2.IsPosted);
			AssertEquals("Should not be changed", 128.93M, consolCost2.ApportionmentCharges[0].JR_OSCostAmt);
			AssertEquals("Should not be changed", 24.50M, consolCost2.ApportionmentCharges[0].JR_Cost_LocalGSTAmount);
			AssertEquals("Should not be changed", 641.07M, consolCost2.ApportionmentCharges[1].JR_OSCostAmt);
			AssertEquals("Should not be changed", 121.80M, consolCost2.ApportionmentCharges[1].JR_Cost_LocalGSTAmount);
		}

		public void TestWIPCreationWhenNewApportionChargeIsCreated_CarryForwardAmomuntIsNonZero()
		{
			//Enable using Accrual Amounts from other similar charges for the same Creditor, Charge Code, Branch and Department
			AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsGreaterThanAccrual.SetValue(EnvProxy.Instance.CurrentCompany.PK, Guid.Empty, Guid.Empty, true);

			var chargeCode1 = TestObjectCreator.CreateChargeCode("CC1", "Charge Code 1", Core.Constants.ChargeType.Margin, 100, TestObjectCreator.FREECAPGST, TestObjectCreator.WHTFREE1);
			Factory.Save();

			var consol1 = TestObjectCreator.CreateConsol(consolNum: "C001");
			var shipment1 = TestObjectCreator.CreateShipment("S001", consol1);
			var shipment2 = TestObjectCreator.CreateShipment("S002", consol1);

			ApportionmentListing apps = new ApportionmentListing(Factory, consol1);

			var cost1 = CreateCost(150M, TestObjectCreator.AALSHI);
			cost1.ApportionmentCharges[0].JR_OSCostAmt = 50M;
			cost1.ApportionmentCharges[1].JR_OSCostAmt = 100M;
			cost1.E6_Sequence = cost1.ApportionmentCharges[0].JR_DisplaySequence = cost1.ApportionmentCharges[1].JR_DisplaySequence = 1;

			var cost2 = CreateCost(200M, TestObjectCreator.AALSHI);
			cost2.ApportionmentCharges[0].JR_OSCostAmt = 0M;
			cost2.ApportionmentCharges[1].JR_OSCostAmt = 200M;
			cost2.ApportionmentCharges[0].JR_IsUsedForApportionment = false;
			cost2.E6_Sequence = cost2.ApportionmentCharges[0].JR_DisplaySequence = cost2.ApportionmentCharges[1].JR_DisplaySequence = 2;

			var cost3 = CreateCost(75m, null);
			cost3.ApportionmentCharges[0].JR_OSCostAmt = 25m;
			cost3.ApportionmentCharges[1].JR_OSCostAmt = 50m;
			cost3.E6_Sequence = cost3.ApportionmentCharges[0].JR_DisplaySequence = cost3.ApportionmentCharges[1].JR_DisplaySequence = 3;

			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			var newTestObjectCreator = new TestObjectCreator(newFactory);

			var invoice = newTestObjectCreator.CreateInvoice(typeof(APInvoice), GlbCompany.CurrentCompany.LocalCurrency, 1M, TestObjectCreator.AALSHI);
			invoice.SubmittedFromInvoicingForm = true;

			var testConsolCost = newTestObjectCreator.CreateConsolCost(invoice, consol1, chargeCode1, 176M, TestObjectCreator.AALSHI);
			testConsolCost.IsFinal = false;
			invoice.ImportAllApportionmentsFromCosting();
			AssertEquals(2, invoice.Lines.Count);
			AssertEquals("Should be equal to the charge amount", 88M, invoice.Lines[0].AL_LocalExTaxAmount);
			AssertEquals("Should be equal to the charge amount", 88M, invoice.Lines[1].AL_LocalExTaxAmount);
			AssertEquals("Should be equal to the charge gst amount", 0M, invoice.Lines[0].AL_OSTaxAmount);
			AssertEquals("Should be equal to the charge gst amount", 0M, invoice.Lines[1].AL_OSTaxAmount);

			newFactory.Save();

			var shipment1JobCharges = newFactory.Load<Job>(shipment1.Job.PK).Charges.Cast<JobCharge>().OrderBy(x => x.JR_DisplaySequence).ToList();
			AssertJobCharge(shipment1JobCharges[0], new ZString("AUD"), 1M, 88M, 88M, new ZString("AUD"), 1M, 50M, 50M, true);
			AssertJobCharge(shipment1JobCharges[1], new ZString("AUD"), 1M, 0M, 0M, new ZString("AUD"), 1M, 38M, 38M, false);

			var shipment2JobCharges = newFactory.Load<Job>(shipment2.Job.PK).Charges.Cast<JobCharge>().OrderBy(x => x.JR_DisplaySequence).ToList();
			AssertJobCharge(shipment2JobCharges[0], new ZString("AUD"), 1M, 88M, 88M, new ZString("AUD"), 1M, 100M, 100M, true);
			AssertJobCharge(shipment2JobCharges[1], new ZString("AUD"), 1M, 212M, 212M, new ZString("AUD"), 1M, 200M, 200M, false);
			AssertJobCharge(shipment2JobCharges[2], new ZString("AUD"), 1M, 50M, 50M, new ZString("AUD"), 1M, 50M, 50M, false);

			var consol1Reloaded = newFactory.Load<ForwardingConsol>(consol1.PK);
			var consolCostsReloaded = consol1Reloaded.GetApportionments().CostsCollection.Cast<JobConsolCost>().OrderBy(x => x.E6_Sequence).ToList();
			AssertEquals("Consol Cost Count", 3, consolCostsReloaded.Count);
			AssertConsolCost(consolCostsReloaded[0], "AUD", 1M, 176M, 176M, true);
			AssertConsolCost(consolCostsReloaded[1], "AUD", 1M, 212M, 212M, false);
			AssertConsolCost(consolCostsReloaded[2], "AUD", 1M, 50M, 50M, false);

			JobConsolCost CreateCost(ZDecimal amount, OrgHeader creditor)
			{
				JobConsolCost cost = apps.CostsCollection.TryAddNew();
				cost.E6_AC_ChargeCode = chargeCode1.PK;
				cost.E6_RX_NKCurrency = AUD.RX_Code;
				cost.E6_ExchangeRate = 1m;
				cost.E6_OSCostAmount = amount;
				cost.E6_ApportionmentMethod = "MAN";
				cost.E6_OH_Creditor = creditor == null ? ZGuid.Empty : creditor.PK;
				return cost;
			}
		}

