			accountingCVInfoCollectionHelperMock.Verify(x => x.AddInfo_CarryForwardChargeAmountWithDifferentSigns(It.IsNotNull<Charge>(), invoiceLine, It.Is<TransactionLineJobChargeTransformer.AmountWrapper>(y => y.InfoCollectionID == amountWrapperInfoCollectionID[0]), 60, 60, It.IsAny<Func<ZString>>()));
			AssertMultilineASCIIEquals(expectedInfo_CarryForwardChargeAmountWithDifferentSigns, actualInfo_CarryForwardChargeAmountWithDifferentSigns);
		}

		public void TestGetAccountingCVInfoCollectionHelper_AddInfoForCarryForwardChargeAmountWithDifferentSigns_WhenUpdateForMultipleCharges()
		{
			var shipment = TestObjectCreator.CreateShipment("S0001001", true);
			var job = TestObjectCreator.CreateJob(shipment);
			CreateExchangeRate(job, USD, 1M);
			var jobCharge1 = CreateCharge(job, TestObjectCreator.CC1, "Charge Code 1", USD, 80M, Creditor1, USD, 80M, LocalClient);
			var jobCharge2 = CreateCharge(job, TestObjectCreator.CC1, "Charge Code 1", USD, 20M, null, USD, 20M, null);
			Factory.Save();

			var invoice = CreateAPInvoice("INV1111", Creditor1, USD, 1M, "Invoice INV1111");
			var invoiceLine = CreateAPInvoiceLine(invoice, job, CC1, USD, 1M, "Charge Code 1", 60M, false);//Carry Forward Amount = 100 - 60 = 40M, Carry Forward Charge (Creditor) => 80 - 60 = 20
			AssertEquals("Invoice Lines", 1, invoice.Lines.Count);
			var jobCharges = job.Charges.ToArray<Charge>();
			AssertEquals("Precondition: Multiple Charges", 2, job.Charges.Count);

			ZString expectedInfo_APInvoiceLinePostingCarryForwardAmountWithDifferentSigns = @"IsCarryForwardAccrualBasedOnOSAmount: False
shouldUseOSCurrencyAndLineExchangeRate: N
invoiceAmountInLocalCurrency: 60
chargeAmoutInLocalCurrency: 80
invoiceAmountInForeignCurrency: 60
chargeAmoutInForeignCurrency: 80.0000";
			ZString expectedInfo_CarryForwardChargeAmountWithDifferentSigns = @"jobExchangeRate: 1.000000000
shouldUseJobExchangeRate: False";

			var accountingCVDependencyFactoryMock = new Mock<IAccountingCriticalValidationDependencyFactory>();
			var accountingCVInfoCollectionHelperMock = new Mock<IAccountingCriticalValidationInfoCollectionHelper>();
			ObjectFactory.Substitute(accountingCVDependencyFactoryMock.Object);
			accountingCVDependencyFactoryMock.Setup(x => x.GetAccountingCriticalValidationInfoCollectionHelper()).Returns(accountingCVInfoCollectionHelperMock.Object);

			List<ZGuid> amountWrapperInfoCollectionID = new List<ZGuid>();
			var actualInfo_APInvoiceLinePostingCarryForwardAmountWithDifferentSigns = ZString.Empty;
			var actualInfo_CarryForwardChargeAmountWithDifferentSigns = ZString.Empty;
			accountingCVInfoCollectionHelperMock.Setup(x => x.AddInfo_APInvoiceLinePostingCarryForwardAmountWithDifferentSigns(It.IsAny<ZGuid>(), invoiceLine, It.IsAny<Charge[]>(), It.IsAny<ZDecimal>(), It.IsAny<ZDecimal>(), It.IsAny<Func<ZString>>()))
				.Callback<ZGuid, InvoicingLineBase, Charge[], ZDecimal, ZDecimal, Func<ZString>>
				(
					(carryForwardAmountID, aPInvoiceLine, associatedCharges, localAmount, oSAmount, getMoreInfo) =>
					{
						amountWrapperInfoCollectionID.Add(carryForwardAmountID);
						actualInfo_APInvoiceLinePostingCarryForwardAmountWithDifferentSigns = getMoreInfo();
					}
				);

			accountingCVInfoCollectionHelperMock.Setup(x => x.AddInfo_CarryForwardChargeAmountWithDifferentSigns(It.IsAny<Charge>(), invoiceLine, It.IsAny<TransactionLineJobChargeTransformer.AmountWrapper>(), 20, 20, It.IsAny<Func<ZString>>()))
				.Callback<Charge, InvoicingLineBase, TransactionLineJobChargeTransformer.AmountWrapper, ZDecimal, ZDecimal, Func<ZString>>
				(
					(charge, aPInvoiceLine, amountWrapper, localAmount, oSAmount, getMoreInfo) =>
					{
						actualInfo_CarryForwardChargeAmountWithDifferentSigns = getMoreInfo();
					}
				);

			GetTransformer(Factory).Transform(invoice);

			accountingCVInfoCollectionHelperMock.Verify(x => x.AddInfo_APInvoiceLinePostingCarryForwardAmountWithDifferentSigns(It.IsAny<ZGuid>(), It.IsAny<InvoicingLineBase>(), It.IsAny<Charge[]>(), It.IsAny<ZDecimal>(), It.IsAny<ZDecimal>(), It.IsAny<Func<ZString>>()), Times.Exactly(2));
			accountingCVInfoCollectionHelperMock.Verify(x => x.AddInfo_APInvoiceLinePostingCarryForwardAmountWithDifferentSigns(It.IsAny<ZGuid>(), invoiceLine, It.IsAny<Charge[]>(), 40, 40, It.IsAny<Func<ZString>>()));
			accountingCVInfoCollectionHelperMock.Verify(x => x.AddInfo_APInvoiceLinePostingCarryForwardAmountWithDifferentSigns(It.IsAny<ZGuid>(), invoiceLine, It.IsAny<Charge[]>(), 20, 20, It.IsAny<Func<ZString>>()));
			AssertMultilineASCIIEquals(expectedInfo_APInvoiceLinePostingCarryForwardAmountWithDifferentSigns, actualInfo_APInvoiceLinePostingCarryForwardAmountWithDifferentSigns);

			accountingCVInfoCollectionHelperMock.Verify(x => x.AddInfo_CarryForwardChargeAmountWithDifferentSigns(It.IsAny<Charge>(), It.IsAny<InvoicingLineBase>(), It.IsAny<TransactionLineJobChargeTransformer.AmountWrapper>(), It.IsAny<ZDecimal>(), It.IsAny<ZDecimal>(), It.IsAny<Func<ZString>>()), Times.Once);
			accountingCVInfoCollectionHelperMock.Verify(x => x.AddInfo_CarryForwardChargeAmountWithDifferentSigns(It.IsNotNull<Charge>(), invoiceLine, It.Is<TransactionLineJobChargeTransformer.AmountWrapper>(y => y.InfoCollectionID == amountWrapperInfoCollectionID[1]), 20, 20, It.IsAny<Func<ZString>>()));
			AssertMultilineASCIIEquals(expectedInfo_CarryForwardChargeAmountWithDifferentSigns, actualInfo_CarryForwardChargeAmountWithDifferentSigns);
		}

