		/// <summary>
		/// Negative ACR behaviour = OFF 
		/// Negative Reaccrual behaviour shouldn't trigger
		/// </summary>
		public void TestNegativeReAccrual_NegativeACRBehaviourisOff()
		{
			using (AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, false))
			{
				var shipment = TestObjectCreator.CreateShipment("S001");
				var job = TestObjectCreator.CreateJob(shipment);
				CreateExchangeRate(job, USD, 1M);
				CreateCharge(job, CC1, "Charge Code 1", USD, -150M, Creditor1, USD, -150M, LocalClient);
				Factory.Save();

				APInvoice invoice = CreateAPInvoice("Z1000", Creditor1, USD, 1M, "Invoice Z1000");
				CreateAPInvoiceLine(invoice, job, CC1, USD, 1M, "Charge Code 1", -100M, false).AL_IsFinalCharge = false;
				CreateAPInvoiceLine(invoice, job, CC2, USD, 1M, "Charge Code 1", 120M, false).AL_IsFinalCharge = false;

				GetTransformer(Factory).Transform(invoice);

				var sortedCharges = job.Charges.Cast<JobCharge>().OrderBy(x => x.JR_OSCostAmt).ToArray();
				AssertEquals("Charge Count", 3, sortedCharges.Length);
				AssertJobCharge(sortedCharges[0], Creditor1.PK, USD.RX_Code, 1M, -150M, -150M, USD.RX_Code, 1M, -150M, -150M, false);
				AssertJobCharge(sortedCharges[1], Creditor1.PK, USD.RX_Code, 1M, -100M, -100M, USD.RX_Code, 1M, 0M, 0M, true);
				AssertJobCharge(sortedCharges[2], Creditor1.PK, USD.RX_Code, 1M, 120M, 120M, USD.RX_Code, 1M, 120M, 120M, true);
			}
		}

