		/// Negative ACR behaviour = ON, Allocated To Creditor = ON, 
		/// All accrued costs for a given Job + Charge Code + Branch + Department are Negative = NO, All costs to be posted for the same Job + Charge Code + Branch + Department are Negative = YES
		/// ACR amount is greater than the CST amount. But Carry Forward ACR amount is negative. 
		/// Negative Reaccrual behaviour shouldn't trigger and WIP should get created as ACR amount is negative.
		/// CreateWIPWhenCostIsGreaterThanAccrual = YES
		/// </summary>
		public void TestNegativeReAccrual_MixtureOfPostiveAndNegativeACRAmounts_CarryForwardAmountIsNegative()
		{
			using (AccountingConfigurationRegistry.Instance.BringForwardAgainstCreditor.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			using (AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			using (AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsGreaterThanAccrual.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				var shipment = TestObjectCreator.CreateShipment("S001");
				var job = TestObjectCreator.CreateJob(shipment);
				CreateExchangeRate(job, USD, 1M);
				CreateCharge(job, CC1, "Charge Code 1", USD, -100M, Creditor1, USD, -100M, LocalClient).JR_DisplaySequence = 1;
				CreateCharge(job, CC1, "Charge Code 1", USD, -150M, null, USD, -150M, LocalClient).JR_DisplaySequence = 2;
				CreateCharge(job, CC1, "Charge Code 1", USD, 75M, null, USD, 75M, LocalClient).JR_DisplaySequence = 3;
				Factory.Save();

				var creditNote = CreateAPCreditNote("Z1000", Creditor1, USD, 1M, "Invoice Z1000");
				CreateAPCreditNoteLine(creditNote, job, CC1, USD, 1M, "Charge Code 1", 88M, false).AL_IsFinalCharge = false;
				GetTransformer(Factory).Transform(creditNote);

				var sortedCharges = job.Charges.Cast<JobCharge>().OrderBy(x => x.JR_OSCostAmt).ThenBy(x => x.JR_DisplaySequence).ToArray();
				AssertEquals("Charge Count", 3, sortedCharges.Length);
				AssertJobCharge(sortedCharges[0], Creditor1.PK, USD.RX_Code, 1M, -88M, -88M, USD.RX_Code, 1M, -13M, -13M, true);
				AssertJobCharge(sortedCharges[1], ZGuid.Empty, USD.RX_Code, 1M, 0M, 0M, USD.RX_Code, 1M, -150M, -150M, false);
				AssertJobCharge(sortedCharges[2], ZGuid.Empty, USD.RX_Code, 1M, 0M, 0M, USD.RX_Code, 1M, 75M, 75M, false);
			}
		}

		/// <summary>
		/// Negative ACR behaviour = ON, Allocated To Creditor = ON, 
		/// All accrued costs for a given Job + Charge Code + Branch + Department are Negative = NO, All costs to be posted for the same Job + Charge Code + Branch + Department are Negative = YES
		/// Job Charge Apportioned = NO
		/// CST is less than ACR 
		/// User imported the Charge for Posting.
		/// Negative Reaccrual behaviour should trigger and carry forward should happen
		/// </summary>
		public void TestNegativeReAccrual_MixtureOfPositiveAndNegativeACR_SpecificChargeIsPosted()
		{
			var fRT = TestObjectCreator.FRT;
			var shipment = TestObjectCreator.CreateShipment("S00001", true);
			var job = TestObjectCreator.CreateJob(shipment);
			var charge1 = CreateCharge(job, CC1, "Charge Code 1", USD, -100M, Creditor1, USD, -100M, LocalClient);
			var charge2 = CreateCharge(job, CC1, "Charge Code 1", USD, -150M, Creditor1, USD, -150M, LocalClient);
			var charge3 = CreateCharge(job, CC1, "Charge Code 1", USD, 75M, null, USD, 75M, LocalClient);
			charge1.JR_GE = TestObjectCreator.FESDepartment.PK;
			charge2.JR_GE = TestObjectCreator.FESDepartment.PK;
			charge3.JR_GE = TestObjectCreator.FESDepartment.PK;
			Factory.Save();

			var creditNote = CreateAPCreditNote("Z1000", Creditor1, USD, 1M, "Invoice Z1000");
			var creditNoteLine = CreateAPCreditNoteLine(creditNote, job, CC1, USD, 1M, "Charge Code 1", 120M, false);
			creditNoteLine.AL_JH = job.PK;
			creditNoteLine.AL_IsFinalCharge = false;
			creditNote.ImportJobChargesIntoInvoice(new[] { charge2 }, creditNoteLine);
			creditNoteLine.AL_OSExTaxAmount = 120M;
			GetTransformer(Factory).Transform(creditNote);

			AssertEquals(4, job.Charges.Count);
			var charges = job.Charges.ToArray<Charge>();

			AssertJobCharge(charges[0], Creditor1.PK, USD.RX_Code, 1M, -100M, -100M, USD.RX_Code, 1M, -100M, -100M, false);
			AssertJobCharge(charges[1], Creditor1.PK, USD.RX_Code, 1M, -120M, -120M, USD.RX_Code, 1M, -150M, -150M, true);
			AssertJobCharge(charges[2], ZGuid.Empty, USD.RX_Code, 1M, 75M, 75M, USD.RX_Code, 1M, 75M, 75M, false);
			AssertJobCharge(charges[3], Creditor1.PK, USD.RX_Code, 1M, -30M, -30M, USD.RX_Code, 1M, 0M, 0M, false);
		}

