		/// <summary>
		/// Negative ACR behaviour = ON, Allocated To Creditor = ON, 
		/// All accrued costs for a given Job + Charge Code + Branch + Department are Negative = YES, All costs to be posted for the same Job + Charge Code + Branch + Department are Negative = YES
		/// Job Charge Apportioned = YES
		/// One Consol Cost for each charge code and creditor combination
		/// Negative Reaccrual behaviour should trigger
		/// </summary>
		public void TestNegativeReAccrual_BothNegativeACRBehaviourAndAllocatedToCreditorAreON_Apportioned_Case1()
		{
			using (AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			using (AccountingConfigurationRegistry.Instance.BringForwardAgainstCreditor.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				var consol1 = TestObjectCreator.CreateConsol(consolNum: "C001");
				var shipment1 = TestObjectCreator.CreateShipment("S001", consol1);
				var shipment2 = TestObjectCreator.CreateShipment("S002", consol1);
				var shipment3 = TestObjectCreator.CreateShipment("S003", consol1);

				ApportionmentListing apps = new ApportionmentListing(Factory, consol1);

				var cost1 = TestObjectCreator.CreateConsolCost(consol1, CC1, USD, 1M, -275M, TestObjectCreator.Creditor1, "MAN", apps);
				setApportionedAmount(cost1, -125M, -100M, -50M);

				var cost2 = TestObjectCreator.CreateConsolCost(consol1, CC1, USD, 1M, -150M, TestObjectCreator.Creditor2, "MAN", apps);
				setApportionedAmount(cost2, -50M, -75M, -25M);

				var cost3 = TestObjectCreator.CreateConsolCost(consol1, CC1, USD, 1M, -71M, null, "MAN", apps);
				setApportionedAmount(cost3, -26M, -30M, -15M);

				Factory.Save();

				var newFactory = new BusinessObjectFactory();
				var newTestObjectCreator = new TestObjectCreator(newFactory);

				var creditNote = newTestObjectCreator.CreateAPCreditNote("CRD001", TestObjectCreator.Creditor1, USD, 1M, "Desc 01");
				creditNote.SubmittedFromInvoicingForm = true;
				var testConsolCost = newTestObjectCreator.CreateConsolCost(creditNote, consol1, CC1, 300M, TestObjectCreator.Creditor1);
				testConsolCost.E6_AT_TaxRate = newTestObjectCreator.GSTFREE1.PK;
				testConsolCost.IsFinal = false;
				testConsolCost.E6_ApportionmentMethod = "MAN";
				setApportionedAmount(testConsolCost,
									 100M,  // CST is less than specific Creditor ACR 
									 125M,  // CST is More than specific Creditor ACR but less than the total of Specific and Blank Creditor ACR
									 75M);  // CST is More than total ACR
				creditNote.ImportAllApportionmentsFromCosting();
				AssertEquals(3, creditNote.Lines.Count);
				var lines = creditNote.Lines.Cast<InvoicingLineBase>().OrderBy(x => x.AL_LocalExTaxAmount).ToList();
				AssertEquals("Should be equal to the charge amount", 75M, lines[0].AL_LocalExTaxAmount);
				AssertEquals("Should be equal to the charge amount", 100M, lines[1].AL_LocalExTaxAmount);
				AssertEquals("Should be equal to the charge amount", 125M, lines[2].AL_LocalExTaxAmount);
				AssertEquals("Should be equal to the charge gst amount", 0M, lines[0].AL_OSTaxAmount);
				AssertEquals("Should be equal to the charge gst amount", 0M, lines[1].AL_OSTaxAmount);
				AssertEquals("Should be equal to the charge gst amount", 0M, lines[2].AL_OSTaxAmount);

				newFactory.Save();

				var shipment1JobCharges = ReloadShipmentCharges(shipment1.Job.PK);
				AssertEquals("Shipment1 Charges Count", 4, shipment1JobCharges.Count);
				AssertJobCharge(shipment1JobCharges[0], Creditor1.PK, USD.RX_Code, 1M, -100M, -100M, USD.RX_Code, 1M, -125M, -125M, true);
				AssertJobCharge(shipment1JobCharges[1], Creditor2.PK, USD.RX_Code, 1M, -50M, -50M, USD.RX_Code, 1M, -50M, -50M, false);
				AssertJobCharge(shipment1JobCharges[2], ZGuid.Empty, USD.RX_Code, 1M, -26M, -26M, USD.RX_Code, 1M, -26M, -26M, false);
				AssertJobCharge(shipment1JobCharges[3], Creditor1.PK, USD.RX_Code, 1M, -25M, -25M, AUD.RX_Code, 1M, 0M, 0M, false);

				var shipment2JobCharges = ReloadShipmentCharges(shipment2.Job.PK);
				AssertEquals("Shipment2 Charges Count", 3, shipment2JobCharges.Count);
				AssertJobCharge(shipment2JobCharges[0], Creditor1.PK, USD.RX_Code, 1M, -125M, -125M, USD.RX_Code, 1M, -100M, -100M, true);
				AssertJobCharge(shipment2JobCharges[1], Creditor2.PK, USD.RX_Code, 1M, -75M, -75M, USD.RX_Code, 1M, -75M, -75M, false);
				AssertJobCharge(shipment2JobCharges[2], ZGuid.Empty, USD.RX_Code, 1M, -30M, -30M, USD.RX_Code, 1M, -30M, -30M, false);

				var shipment3JobCharges = ReloadShipmentCharges(shipment3.Job.PK);
				AssertEquals("Shipment3 Charges Count", 3, shipment3JobCharges.Count);
				AssertJobCharge(shipment3JobCharges[0], Creditor1.PK, USD.RX_Code, 1M, -75M, -75M, USD.RX_Code, 1M, -50M, -50M, true);
				AssertJobCharge(shipment3JobCharges[1], Creditor2.PK, USD.RX_Code, 1M, -25M, -25M, USD.RX_Code, 1M, -25M, -25M, false);
				AssertJobCharge(shipment3JobCharges[2], ZGuid.Empty, USD.RX_Code, 1M, -15M, -15M, USD.RX_Code, 1M, -15M, -15M, false);

				var consol1Reloaded = newFactory.Load<ForwardingConsol>(consol1.PK);
				var consolCostsReloaded = consol1Reloaded.GetApportionments().CostsCollection.Cast<JobConsolCost>().OrderBy(x => x.E6_OSCostAmount).ToList();
				AssertEquals("ConsolCost Count", 4, consolCostsReloaded.Count);
				AssertConsolCost(consolCostsReloaded[0], "USD", 1M, -300M, -300M, true);
				AssertConsolCost(consolCostsReloaded[1], "USD", 1M, -150M, -150M, false);
				AssertConsolCost(consolCostsReloaded[2], "USD", 1M, -71M, -71M, false);
				AssertConsolCost(consolCostsReloaded[3], "USD", 1M, -25M, -25M, false);

				void setApportionedAmount(JobConsolCost cost, ZDecimal amount1, ZDecimal amount2, ZDecimal amount3)
				{
					cost.E6_AT_TaxRate = TestObjectCreator.GSTFREE1.PK;
					var shipment1Charge = cost.ApportionmentCharges.FindChargeForJob(shipment1);
					var shipment2Charge = cost.ApportionmentCharges.FindChargeForJob(shipment2);
					var shipment3Charge = cost.ApportionmentCharges.FindChargeForJob(shipment3);
					shipment1Charge.JR_OSCostAmt = amount1;
					shipment2Charge.JR_OSCostAmt = amount2;
					shipment3Charge.JR_OSCostAmt = amount3;
					shipment1Charge.JR_IsUsedForApportionment = true;
					shipment2Charge.JR_IsUsedForApportionment = true;
					shipment3Charge.JR_IsUsedForApportionment = true;
				}

				List<JobCharge> ReloadShipmentCharges(ZGuid jobPK)
				{
					var job = newFactory.Load<Job>(jobPK);
					job.Charges.Reload(true);
					var shipmentJobCharges = job.Charges.Cast<JobCharge>().OrderBy(x => x.JR_OSCostAmt).ToList();
					return shipmentJobCharges;
				}
			}
		}

		/// <summary>
		/// Negative ACR behaviour = ON, Allocated To Creditor = ON, 
		/// All accrued costs for a given Job + Charge Code + Branch + Department are Negative = YES, All costs to be posted for the same Job + Charge Code + Branch + Department are Negative = YES
		/// Job Charge Apportioned = YES
