		public void TestNegativeReAccrual_BothNegativeACRBehaviourAndAllocatedToCreditorAreON_Apportioned_Case1_2()
		{
			using (AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			using (AccountingConfigurationRegistry.Instance.BringForwardAgainstCreditor.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				var consol1 = TestObjectCreator.CreateConsol(consolNum: "C001");
				var shipment1 = TestObjectCreator.CreateShipment("S001", consol1);

				ApportionmentListing apps = new ApportionmentListing(Factory, consol1);

				var cost1 = TestObjectCreator.CreateConsolCost(consol1, CC1, USD, 1M, -100M, TestObjectCreator.Creditor1, "MAN", apps);
				setApportionedAmount(cost1, -100M);

				var cost2 = TestObjectCreator.CreateConsolCost(consol1, CC1, USD, 1M, -200M, TestObjectCreator.Creditor1, "MAN", apps);
				setApportionedAmount(cost2, -200M);

				var cost3 = TestObjectCreator.CreateConsolCost(consol1, CC1, USD, 1M, -300M, TestObjectCreator.Creditor1, "MAN", apps);
				setApportionedAmount(cost3, -300M);

				Factory.Save();

				var newFactory = new BusinessObjectFactory();
				var newTestObjectCreator = new TestObjectCreator(newFactory);

				var creditNote = newTestObjectCreator.CreateAPCreditNote("CRD001", TestObjectCreator.Creditor1, USD, 1M, "Desc 01");
				creditNote.SubmittedFromInvoicingForm = true;

				var testConsolCost1 = newTestObjectCreator.CreateConsolCost(creditNote, consol1, CC1, 88, TestObjectCreator.Creditor1);
				testConsolCost1.E6_AT_TaxRate = newTestObjectCreator.GSTFREE1.PK;
				testConsolCost1.IsFinal = false;
				testConsolCost1.E6_ApportionmentMethod = "MAN";
				setApportionedAmount(testConsolCost1,
									 88M);

				var testConsolCost2 = newTestObjectCreator.CreateConsolCost(creditNote, consol1, CC1, 256, TestObjectCreator.Creditor1);
				testConsolCost2.E6_AT_TaxRate = newTestObjectCreator.GSTFREE1.PK;
				testConsolCost2.IsFinal = false;
				testConsolCost2.E6_ApportionmentMethod = "MAN";
				setApportionedAmount(testConsolCost2,
									 256M);

				creditNote.ImportAllApportionmentsFromCosting();
				AssertEquals(2, creditNote.Lines.Count);
				var lines = creditNote.Lines.Cast<InvoicingLineBase>().OrderBy(x => x.AL_LocalExTaxAmount).ToList();
				AssertEquals("Should be equal to the charge amount", 88M, lines[0].AL_LocalExTaxAmount);
				AssertEquals("Should be equal to the charge amount", 256M, lines[1].AL_LocalExTaxAmount);

				newFactory.Save();

				var shipment1JobCharges = newFactory.Load<Job>(shipment1.Job.PK).Charges.Cast<JobCharge>().OrderBy(x => x.JR_OSCostAmt).OrderBy(x => x.JR_OSSellAmt).ToList();
				AssertEquals("Shipment1 Charges Count", 3, shipment1JobCharges.Count);
				AssertJobCharge(shipment1JobCharges[0], Creditor1.PK, USD.RX_Code, 1M, -256M, -256M, USD.RX_Code, 1M, -300M, -300M, true);
				AssertJobCharge(shipment1JobCharges[1], Creditor1.PK, USD.RX_Code, 1M, -256M, -256M, USD.RX_Code, 1M, -200M, -200M, false);
				AssertJobCharge(shipment1JobCharges[2], Creditor1.PK, USD.RX_Code, 1M, -88M, -88M, USD.RX_Code, 1M, -100M, -100M, true);

				var consol1Reloaded = newFactory.Load<ForwardingConsol>(consol1.PK);
				var consolCostsReloaded = consol1Reloaded.GetApportionments().CostsCollection.Cast<JobConsolCost>().OrderBy(x => x.E6_OSCostAmount).ThenBy(x => x.E6_InvoiceNum).ToList();
				AssertEquals("ConsolCost Count", 3, consolCostsReloaded.Count);
				AssertConsolCost(consolCostsReloaded[0], "USD", 1M, -256M, -256M, false);
				AssertConsolCost(consolCostsReloaded[1], "USD", 1M, -256M, -256M, true);
				AssertConsolCost(consolCostsReloaded[2], "USD", 1M, -88M, -88M, true);

				void setApportionedAmount(JobConsolCost cost, ZDecimal amount1)
				{
					cost.E6_AT_TaxRate = TestObjectCreator.GSTFREE1.PK;
					var shipment1Charge = cost.ApportionmentCharges.FindChargeForJob(shipment1);
					shipment1Charge.JR_OSCostAmt = amount1;
					shipment1Charge.JR_IsUsedForApportionment = true;
				}
			}
		}

