		public void TestNoJobOnEmptyRelatedShipmentsAfterCarryForwardConsolCostCreation()
		{
			var consol1 = TestObjectCreator.CreateConsol(consolNum: "C001");

			var shipment1 = TestObjectCreator.CreateShipment("S001", consol1);
			var shipment2 = TestObjectCreator.CreateShipment("S002", consol1);
			var shipment3 = TestObjectCreator.CreateShipment("S003", consol1);

			ApportionmentListing apps = new ApportionmentListing(Factory, consol1);

			var cost1 = TestObjectCreator.CreateConsolCost(consol1, CC1, AUD, 1M, 150M, TestObjectCreator.Creditor1, "MAN", apps);
			SetApportionedAmount(cost1,
				shipment1, shipment2, shipment3,
				100M, 50M, 0M);

			Factory.Save();

			var apInvoice = CreateInvoiceByImportingFromConsolCost(Factory, "INV001",
													consol1, 176M, AUD, 1M, false,
													shipment1, shipment2, shipment3,
													88M, 88M, 0M,
													null);

			var lines = apInvoice.Lines.Cast<APInvoiceLine>().OrderBy(x => x.AL_LocalExTaxAmount).ToArray();
			SetInvoiceLineToFinal(lines.Where(x => x.AL_JH == shipment1.Job.PK).FirstOrDefault(), false);
			SetInvoiceLineToFinal(apInvoice.Lines.Cast<APInvoiceLine>().FirstOrDefault(x => x.AL_JH == shipment2.Job.PK), false);

			Factory.Save();

			var job1 = new Job.Loader(shipment1).Load();
			var job2 = new Job.Loader(shipment2).Load();
			var job3 = new Job.Loader(shipment3).Load();
			AssertNotNull(job1);
			AssertNotNull(job2);
			AssertNull(job3);
		}

		/// <summary>
		/// WI00112082 SPE - Carry Forwad Consol Cost Accruals as Consol Costs 20171124.xlsx\sheet:Design 1\SCENARIO 01 & 02 Combined
		/// </summary>
		public void TestCarryForwardAtConsolCostLevel_Case1()
		{
			using (AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsGreaterThanAccrual.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			using (AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			using (AccountingConfigurationRegistry.Instance.BringForwardAgainstCreditor.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				var consol1 = TestObjectCreator.CreateConsol(consolNum: "C001");

				var shipment1 = TestObjectCreator.CreateShipment("S001", consol1);
				var job = TestObjectCreator.CreateJob(shipment1);
				CreateCharge(job, CC1, "Charge Code 1", AUD, 50M, Creditor1, AUD, 50M, LocalClient);

				var shipment2 = TestObjectCreator.CreateShipment("S002", consol1);
				var shipment3 = TestObjectCreator.CreateShipment("S003", consol1);

				ApportionmentListing apps = new ApportionmentListing(Factory, consol1);

				var cost1 = TestObjectCreator.CreateConsolCost(consol1, CC1, AUD, 1M, 500M, TestObjectCreator.Creditor1, "MAN", apps);
				SetApportionedAmount(cost1,
					shipment1, shipment2, shipment3,
					200M, 0M, 300M);

				var cost2 = TestObjectCreator.CreateConsolCost(consol1, CC1, AUD, 1M, 300M, TestObjectCreator.Creditor1, "MAN", apps);
				SetApportionedAmount(cost2,
					shipment1, shipment2, shipment3,
					100M, 200M, 0M);

				Factory.Save();

				var newFactory = new BusinessObjectFactory();
				var apInvoice = CreateInvoiceByImportingFromConsolCost(newFactory, "INV001",
														consol1, 400M, AUD, 1M, false,
														shipment1, shipment2, shipment3,
														180M, 0M, 220M,
														cost1);

				var lines = apInvoice.Lines.Cast<APInvoiceLine>().OrderBy(x => x.AL_LocalExTaxAmount).ToArray();
				SetInvoiceLineToFinal(lines.FirstOrDefault(x => x.AL_JH == shipment1.Job.PK), true);
				SetInvoiceLineToFinal(apInvoice.Lines.Cast<APInvoiceLine>().FirstOrDefault(x => x.AL_JH == shipment3.Job.PK), false);
				AssertEquals(2, apInvoice.Lines.Count);

				newFactory.Save();

				AssertEquals("Should be equal to the charge amount", 180M, lines[0].AL_LocalExTaxAmount);
				AssertEquals("Should be equal to the charge amount", 220M, lines[1].AL_LocalExTaxAmount);
				AssertEquals("Should be equal to the charge gst amount", 0M, lines[0].AL_OSTaxAmount);
				AssertEquals("Should be equal to the charge gst amount", 0M, lines[1].AL_OSTaxAmount);

				var consol1Reloaded = newFactory.Load<ForwardingConsol>(consol1.PK);
				var consolCostsReloaded = consol1Reloaded.GetApportionments().CostsCollection.Cast<JobConsolCost>().OrderBy(x => x.E6_OSCostAmount).ToList();
				AssertEquals("ConsolCost Count", 3, consolCostsReloaded.Count);
				AssertConsolCost(consolCostsReloaded[0], "AUD", 1M, 80M, 80M, false);
				AssertConsolCost(consolCostsReloaded[1], "AUD", 1M, 300M, 300M, false);
				AssertConsolCost(consolCostsReloaded[2], "AUD", 1M, 400M, 400M, true);

				var shipment1JobCharges = newFactory.Load<Charge>(new ZQuery(JobChargeSchema.JR_JH, shipment1.Job.PK)).OrderBy(x => x.JR_OSCostAmt).ToList();
				AssertEquals("Shipment1 Charges Count", 3, shipment1JobCharges.Count);
				AssertJobCharge(shipment1JobCharges[0], Creditor1.PK, AUD.RX_Code, 1M, 50M, 50M, AUD.RX_Code, 1M, 50M, 50M, false);
				AssertApportionJobCharge(shipment1JobCharges[1], Creditor1.PK, AUD.RX_Code, 1M, 100M, 100M, AUD.RX_Code, 1M, 100M, 100M, false, cost2.PK);
				AssertApportionJobCharge(shipment1JobCharges[2], Creditor1.PK, AUD.RX_Code, 1M, 180M, 180M, AUD.RX_Code, 1M, 200M, 200M, true, cost1.PK);

				var shipment2JobCharges = newFactory.Load<Charge>(new ZQuery(JobChargeSchema.JR_JH, shipment2.Job.PK)).OrderBy(x => x.JR_OSCostAmt).ToList();
				AssertEquals("Shipment2 Charges Count", 1, shipment2JobCharges.Count);
				AssertApportionJobCharge(shipment2JobCharges[0], Creditor1.PK, AUD.RX_Code, 1M, 200M, 200M, AUD.RX_Code, 1M, 200M, 200M, false, cost2.PK);

				var shipment3JobCharges = newFactory.Load<Charge>(new ZQuery(JobChargeSchema.JR_JH, shipment3.Job.PK)).OrderBy(x => x.JR_OSCostAmt).ToList();
				AssertEquals("Shipment3 Charges Count", 2, shipment3JobCharges.Count);
				AssertApportionJobCharge(shipment3JobCharges[0], Creditor1.PK, AUD.RX_Code, 1M, 80M, 80M, AUD.RX_Code, 1M, 0M, 0M, false, consolCostsReloaded[0].PK);
				AssertApportionJobCharge(shipment3JobCharges[1], Creditor1.PK, AUD.RX_Code, 1M, 220M, 220M, AUD.RX_Code, 1M, 300M, 300M, true, cost1.PK);

				newFactory = new BusinessObjectFactory();
				var apInvoice2 = CreateInvoiceByImportingFromConsolCost(newFactory, "INV002",
														consol1, 335M, AUD, 1M, false,
														shipment1, shipment2, shipment3,
														125M, 210M, 0M,
														cost1);

				SetInvoiceLineToFinal(apInvoice2.Lines.Cast<APInvoiceLine>().FirstOrDefault(x => x.AL_JH == shipment1.Job.PK), false);
				SetInvoiceLineToFinal(apInvoice2.Lines.Cast<APInvoiceLine>().FirstOrDefault(x => x.AL_JH == shipment2.Job.PK), true);
				AssertEquals(2, apInvoice2.Lines.Count);
				newFactory.Save();

				consol1Reloaded = newFactory.Load<ForwardingConsol>(consol1.PK);
				consolCostsReloaded = consol1Reloaded.GetApportionments().CostsCollection.Cast<JobConsolCost>().OrderBy(x => x.E6_OSCostAmount).ToList();
				AssertEquals("ConsolCost Count", 3, consolCostsReloaded.Count);
				AssertConsolCost(consolCostsReloaded[0], "AUD", 1M, 80M, 80M, false);
				AssertConsolCost(consolCostsReloaded[1], "AUD", 1M, 335M, 335M, true);
				AssertConsolCost(consolCostsReloaded[2], "AUD", 1M, 400M, 400M, true);

				shipment1JobCharges = newFactory.Load<Charge>(new ZQuery(JobChargeSchema.JR_JH, shipment1.Job.PK)).OrderBy(x => x.JR_OSCostAmt).ToList();
				AssertEquals("Shipment1 Charges Count", 4, shipment1JobCharges.Count);
				AssertApportionJobCharge(shipment1JobCharges[0], ZGuid.Empty, AUD.RX_Code, 1M, 0M, 0M, AUD.RX_Code, 1M, 25M, 25M, false, ZGuid.Empty);
				AssertApportionJobCharge(shipment1JobCharges[1], Creditor1.PK, AUD.RX_Code, 1M, 50M, 50M, AUD.RX_Code, 1M, 50M, 50M, false, ZGuid.Empty);
				AssertApportionJobCharge(shipment1JobCharges[2], Creditor1.PK, AUD.RX_Code, 1M, 125M, 125M, AUD.RX_Code, 1M, 100M, 100M, true, cost2.PK);
				AssertApportionJobCharge(shipment1JobCharges[3], Creditor1.PK, AUD.RX_Code, 1M, 180M, 180M, AUD.RX_Code, 1M, 200M, 200M, true, cost1.PK);

				shipment2JobCharges = newFactory.Load<Charge>(new ZQuery(JobChargeSchema.JR_JH, shipment2.Job.PK)).OrderBy(x => x.JR_OSCostAmt).ToList();
				AssertEquals("Shipment2 Charges Count", 1, shipment2JobCharges.Count);
				AssertApportionJobCharge(shipment2JobCharges[0], Creditor1.PK, AUD.RX_Code, 1M, 210M, 210M, AUD.RX_Code, 1M, 200M, 200M, true, cost2.PK);

				shipment3JobCharges = newFactory.Load<Charge>(new ZQuery(JobChargeSchema.JR_JH, shipment3.Job.PK)).OrderBy(x => x.JR_OSCostAmt).ToList();
				AssertEquals("Shipment3 Charges Count", 2, shipment3JobCharges.Count);
				AssertApportionJobCharge(shipment3JobCharges[0], Creditor1.PK, AUD.RX_Code, 1M, 80M, 80M, AUD.RX_Code, 1M, 0M, 0M, false, consolCostsReloaded[0].PK);
				AssertApportionJobCharge(shipment3JobCharges[1], Creditor1.PK, AUD.RX_Code, 1M, 220M, 220M, AUD.RX_Code, 1M, 300M, 300M, true, cost1.PK);
			}
		}

