			using (AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsGreaterThanAccrual.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			using (AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			using (AccountingConfigurationRegistry.Instance.BringForwardAgainstCreditor.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				var consol1 = TestObjectCreator.CreateConsol(consolNum: "C001");

				var shipment1 = TestObjectCreator.CreateShipment("S001", consol1);
				var job = TestObjectCreator.CreateJob(shipment1);
				CreateCharge(job, CC1, "Charge Code 1", AUD, 60M, Creditor1, AUD, 60M, LocalClient);
				CreateCharge(job, CC1, "Charge Code 1", AUD, 65M, null, AUD, 65M, LocalClient);

				var shipment2 = TestObjectCreator.CreateShipment("S002", consol1);
				ApportionmentListing apps = new ApportionmentListing(Factory, consol1);

				var cost1 = TestObjectCreator.CreateConsolCost(consol1, CC1, TestObjectCreator.EUR, 0.6M, 60M, TestObjectCreator.Creditor1, "MAN", apps);
				SetApportionedAmount(cost1,
					shipment1, shipment2, null,
					40M, 20M, 0M);

				var cost2 = TestObjectCreator.CreateConsolCost(consol1, CC1, USD, 0.8M, 80M, TestObjectCreator.Creditor1, "MAN", apps);
				SetApportionedAmount(cost2,
					shipment1, shipment2, null,
					53.33M, 26.67M, 0M);

				var cost3 = TestObjectCreator.CreateConsolCost(consol1, CC1, AUD, 1M, 100M, TestObjectCreator.Creditor1, "MAN", apps);
				SetApportionedAmount(cost3,
					shipment1, shipment2, null,
					66.67M, 33.33M, 0M);

				Factory.Save();

				var newFactory = new BusinessObjectFactory();
				var apInvoice = CreateInvoiceByImportingFromConsolCost(newFactory, "INV001",
														consol1, 56M, TestObjectCreator.EUR, 0.6M, false,
														shipment1, shipment2, null,
														37.33M, 18.67M, 0M,
														null);

				var lines = apInvoice.Lines.Cast<APInvoiceLine>().OrderBy(x => x.AL_LocalExTaxAmount).ToArray();
				SetInvoiceLineToFinal(lines.FirstOrDefault(x => x.AL_JH == shipment1.Job.PK), false);
				SetInvoiceLineToFinal(apInvoice.Lines.Cast<APInvoiceLine>().FirstOrDefault(x => x.AL_JH == shipment2.Job.PK), false);
				AssertEquals(2, apInvoice.Lines.Count);

				newFactory.Save();

				AssertEquals("Should be equal to the charge amount", 18.67M, lines[0].AL_OSExTaxAmount);
				AssertEquals("Should be equal to the charge amount", 37.33M, lines[1].AL_OSExTaxAmount);
				AssertEquals("Should be equal to the charge gst amount", 0M, lines[0].AL_OSTaxAmount);
				AssertEquals("Should be equal to the charge gst amount", 0M, lines[1].AL_OSTaxAmount);

				var consol1Reloaded = newFactory.Load<ForwardingConsol>(consol1.PK);
				var consolCostsReloaded = consol1Reloaded.GetApportionments().CostsCollection.Cast<JobConsolCost>().OrderBy(x => x.E6_OSCostAmount).ToList();
				AssertEquals("ConsolCost Count", 2, consolCostsReloaded.Count);
				AssertConsolCost(consolCostsReloaded[0], "EUR", 0.6M, 93.33M, 56M, true);
				AssertConsolCost(consolCostsReloaded[1], "AUD", 1M, 206.67M, 206.67M, false);

				var shipment1JobCharges = newFactory.Load<Charge>(new ZQuery(JobChargeSchema.JR_JH, shipment1.Job.PK)).OrderBy(x => x.JR_OSCostAmt).ThenBy(x => x.JR_OSSellAmt).ToList();
				AssertEquals("Shipment1 Charges Count", 6, shipment1JobCharges.Count);

				AssertApportionJobCharge(shipment1JobCharges[0], ZGuid.Empty, AUD.RX_Code, 1M, 0M, 0M, USD.RX_Code, 0.8M, 66.66M, 53.33M, false, ZGuid.Empty);
				AssertApportionJobCharge(shipment1JobCharges[1], ZGuid.Empty, AUD.RX_Code, 1M, 0M, 0M, AUD.RX_Code, 1M, 66.67M, 66.67M, false, ZGuid.Empty);
				AssertApportionJobCharge(shipment1JobCharges[2], Creditor1.PK, TestObjectCreator.EUR.RX_Code, 0.6M, 62.21M, 37.33M, TestObjectCreator.EUR.RX_Code, 0.6M, 66.67M, 40M, true, cost1.PK);
				AssertApportionJobCharge(shipment1JobCharges[3], Creditor1.PK, AUD.RX_Code, 1M, 60M, 60M, AUD.RX_Code, 1M, 60M, 60M, false, ZGuid.Empty);
				AssertApportionJobCharge(shipment1JobCharges[4], ZGuid.Empty, AUD.RX_Code, 1M, 65M, 65M, AUD.RX_Code, 1M, 65M, 65M, false, ZGuid.Empty);
				AssertApportionJobCharge(shipment1JobCharges[5], Creditor1.PK, AUD.RX_Code, 1M, 137.79M, 137.79M, AUD.RX_Code, 1M, 0M, 0M, false, consolCostsReloaded[1].PK);

				var shipment2JobCharges = newFactory.Load<Charge>(new ZQuery(JobChargeSchema.JR_JH, shipment2.Job.PK)).OrderBy(x => x.JR_OSCostAmt).ToList();
				AssertEquals("Shipment2 Charges Count", 4, shipment2JobCharges.Count);
				AssertApportionJobCharge(shipment2JobCharges[0], ZGuid.Empty, AUD.RX_Code, 1M, 0M, 0M, USD.RX_Code, 0.8M, 33.34M, 26.67M, false, ZGuid.Empty);
				AssertApportionJobCharge(shipment2JobCharges[1], ZGuid.Empty, AUD.RX_Code, 1M, 0M, 0M, AUD.RX_Code, 1M, 33.33M, 33.33M, false, ZGuid.Empty);
				AssertApportionJobCharge(shipment2JobCharges[2], Creditor1.PK, TestObjectCreator.EUR.RX_Code, 0.6M, 31.12M, 18.67M, TestObjectCreator.EUR.RX_Code, 0.6M, 33.33M, 20M, true, cost1.PK);
				AssertApportionJobCharge(shipment2JobCharges[3], Creditor1.PK, AUD.RX_Code, 1M, 68.88M, 68.88M, AUD.RX_Code, 1M, 0M, 0M, false, consolCostsReloaded[1].PK);
			}
		}

		public void TestCarryForwardAtConsolCostLevel_UnrecognizedAccrual()
		{
			var approvalValue = new CostVarianceApproval();
			approvalValue.AutoTickFinalFlag = false;
			using (AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsGreaterThanAccrual.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			using (AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			using (AccountingConfigurationRegistry.Instance.BringForwardAgainstCreditor.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			using (AccountingConfigurationRegistry.Instance.PayableFinalFlag.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, false))
			using (AccountingConfigurationRegistry.Instance.PayableFinalFlagForConsolCost.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, false))
			using (AccountingConfigurationRegistry.Instance.CostVarianceApproval.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, approvalValue))
			{
				var consol1 = TestObjectCreator.CreateConsol(consolNum: "C001");
				var shipment1 = TestObjectCreator.CreateShipment("S001", consol1);
				var apps = new ApportionmentListing(Factory, consol1);
				var cost1 = TestObjectCreator.CreateConsolCost(consol1, CC1, TestObjectCreator.AUD, 1M, 100M, null, "MAN", apps);
				SetApportionedAmount(cost1,
					shipment1, null, null,
					100M, 0M, 0M);
				Factory.Save();

				var newFactory = new BusinessObjectFactory();
				var apInvoice = CreateInvoiceByImportingFromConsolCost(newFactory, "INV001",
														consol1, 60M, TestObjectCreator.AUD	, 1M, false,
														shipment1, null, null,
														60M, 0M, 0M,
														null);

				var lines = apInvoice.Lines.Cast<APInvoiceLine>().OrderBy(x => x.AL_LocalExTaxAmount).ToArray();
				SetInvoiceLineToFinal(lines.FirstOrDefault(x => x.AL_JH == shipment1.Job.PK), false);
				AssertEquals(1, apInvoice.Lines.Count);
				newFactory.Save();

				AssertEquals("Should be equal to the charge amount", 60M, lines[0].AL_LocalExTaxAmount);
				AssertEquals("Should be equal to the charge gst amount", 0M, lines[0].AL_OSTaxAmount);

				var consol1Reloaded = newFactory.Load<ForwardingConsol>(consol1.PK);
				var consolCostsReloaded = consol1Reloaded.GetApportionments().CostsCollection.Cast<JobConsolCost>().OrderBy(x => x.E6_OSCostAmount).ToList();
				AssertEquals("ConsolCost Count", 2, consolCostsReloaded.Count);
				AssertConsolCost(consolCostsReloaded[0], "AUD", 1M, 40M, 40M, false);
				AssertConsolCost(consolCostsReloaded[1], "AUD", 1M, 60M, 60M, true);

				var shipment1JobCharges = newFactory.Load<Charge>(new ZQuery(JobChargeSchema.JR_JH, shipment1.Job.PK)).OrderBy(x => x.JR_OSCostAmt).ToList();
				AssertEquals("Shipment1 Charges Count", 2, shipment1JobCharges.Count);

				AssertApportionJobCharge(shipment1JobCharges[0], TestObjectCreator.Creditor1.PK, AUD.RX_Code, 1M, 40M, 40M, AUD.RX_Code, 1M, 0M, 0M, false, consolCostsReloaded[0].PK);
				AssertNotNull("Second Charge should have an accrual", shipment1JobCharges[0].APLine);
				AssertEquals("Second Charge should have an accrual", "ACR", shipment1JobCharges[0].APLine.AL_LineType);

				AssertApportionJobCharge(shipment1JobCharges[1], TestObjectCreator.Creditor1.PK, AUD.RX_Code, 1M, 60M, 60M, AUD.RX_Code, 1M, 100M, 100M, true, consolCostsReloaded[1].PK);
				AssertNotNull("Second Charge should have a cost", shipment1JobCharges[1].APLine);
				AssertEquals("Second Charge should have an accrual", "CST", shipment1JobCharges[1].APLine.AL_LineType);
			}
		}

