				AssertApportionJobCharge(shipment1JobCharges[2], TestObjectCreator.Creditor1.PK, AUD.RX_Code, 1M, -33M, -33M, AUD.RX_Code, 1M, -50M, -50M, true, consolCostsReloaded[2].PK);

