		public void TestCreateNewCharge_CostTaxBranch()
		{
			using (AccountingMasterFilesRegistry.Instance.EnableTaxBranchReporting.SetTemporaryValue(Env.CurrentCompanyPK, Guid.Empty, Guid.Empty, true))
			{
				var shipment = TestObjectCreator.CreateShipment("SHP001", false);
				var job = TestObjectCreator.CreateJob(shipment);
				Factory.Save();

				var invoice = TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoice), "INV001", TestObjectCreator.AUD, 1, 0, 0, 0, 0);
				invoice.AH_GB_TaxBranch = GlbBranch.CurrentBranch.PK;
				var line = invoice.Lines[0];
				line.AL_AC = TestObjectCreator.CC1.PK;
				line.AL_JH = job.PK;
				line.AL_GB_TaxBranch = GlbBranch.CurrentBranch.PK;

				var transformer = new TransactionLineJobChargeTransformer(Factory);
				AccountingConfigurationRegistry.Instance.EnableLocalChargeCodeDescriptionDefault.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);
				job.Charges.RemoveAll();
				transformer.CreateNewCharge(line, job);
				AssertEquals(GlbBranch.CurrentBranch.PK, job.Charges[0].JR_GB_CostTaxBranch);

				job.Charges.RemoveAll();
				line.AL_GB_TaxBranch = TestObjectCreator.NonCurrentBranch.PK;
				transformer.CreateNewCharge(line, job);
				AssertEquals(TestObjectCreator.NonCurrentBranch.PK, job.Charges[0].JR_GB_CostTaxBranch);
			}
		}

