		public void TestUpdateExistingCharge_CostTaxBranch_TaxRateOverride()
		{
			AccountingMasterFilesRegistry.Instance.EnableBranchLevelTaxOverrideRuleConfigurations.SetValue(Env.CurrentCompanyPK, Guid.Empty, Guid.Empty, true);
			AccountingMasterFilesRegistry.Instance.EnableTaxBranchReporting.SetValue(Env.CurrentCompanyPK, Guid.Empty, Guid.Empty, true);

			var chargeCode = TestObjectCreator.CreateChargeCode("CC01");
			TestObjectCreator.CreateTaxOverrides(chargeCode
				, taxOverride => {
					taxOverride.AO_JobType = "ALL";
					taxOverride.AO_GB = GlbBranch.CurrentBranch.PK;
					taxOverride.AO_AT = TestObjectCreator.SVAT1.PK;
				}
			);

			var shipment = TestObjectCreator.CreateShipment("SHP001", false);
			var job = TestObjectCreator.CreateJob(shipment);
			var charge = TestObjectCreator.CreateCharge(job, chargeCode, 10M, 15M);
			Factory.Save();

			var invoice = TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoice), "INV001", TestObjectCreator.AUD, 1, 0, 0, 0, 0);
			var line = invoice.Lines[0];
			line.AL_AC = chargeCode.PK;
			line.AL_JH = job.PK;
			line.AL_AT = TestObjectCreator.SVAT1.PK;

			TestObjectCreator.Creditor1.CompanyData.OB_APVATConfig = AccountingMasterFilesConstants.OrganisationTaxConfiguartionTypes.Default.Code;
			invoice.AH_OH = TestObjectCreator.Creditor1.PK;
			charge.JR_OH_CostAccount = TestObjectCreator.Creditor1.PK;

			var transformer = new TransactionLineJobChargeTransformer(Factory);
			AccountingConfigurationRegistry.Instance.EnableLocalChargeCodeDescriptionDefault.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);
			_ = transformer.ChargesToSearch;

			charge.JR_GB_CostTaxBranch = ZGuid.Empty;
			charge.JR_GB_CostTaxBranch = GlbBranch.CurrentBranch.PK;
			AssertEquals("Precondition, charge GST will be override to TestObjectCreator.SVAT1 when JR_GB_CostTaxBranch is CurrentBranch.", TestObjectCreator.SVAT1.PK, charge.JR_AT_CostGSTRate);

			charge.JR_GB_CostTaxBranch = ZGuid.Empty;
			charge.JR_AT_CostGSTRate = ZGuid.Empty;
			line.AL_GB_TaxBranch = GlbBranch.CurrentBranch.PK;
			line.AL_AT = TestObjectCreator.SVAT2.PK;
			transformer.UpdateExistingCharge(line, charge);
			AssertEquals("JR_GB_CostTaxBranch should be synchronized to AL_GB_TaxBranch.", GlbBranch.CurrentBranch.PK, charge.JR_GB_CostTaxBranch);
			AssertEquals("JR_AT_CostGSTRate should not be override to TestObjectCreator.SVAT1 when synchronized to CurrentBranch.", TestObjectCreator.SVAT2.PK, charge.JR_AT_CostGSTRate);
		}

