		public void TestUpdateCharges_CostTaxBranch_TaxRateOverride()
		{
			AccountingMasterFilesRegistry.Instance.EnableBranchLevelTaxOverrideRuleConfigurations.SetValue(Env.CurrentCompanyPK, Guid.Empty, Guid.Empty, true);
			AccountingMasterFilesRegistry.Instance.EnableTaxBranchReporting.SetValue(Env.CurrentCompanyPK, Guid.Empty, Guid.Empty, true);

			var chargeCode = TestObjectCreator.CreateChargeCode("CC01");
			TestObjectCreator.CreateTaxOverrides(chargeCode
				, taxOverride => {
					taxOverride.AO_JobType = "ALL";
					taxOverride.AO_GB = TestObjectCreator.NonCurrentBranch.PK;
					taxOverride.AO_AT = TestObjectCreator.SVAT1.PK;
				}
			);

			var consol = TestObjectCreator.CreateConsol();
			var shipment = TestObjectCreator.CreateShipment("S001", consol);
			var job = TestObjectCreator.CreateJob(shipment, false);
			Factory.Save();

			var consolCostToUpdate = TestObjectCreator.CreateConsolCost(consol, chargeCode, 100, TestObjectCreator.Creditor1);
			consolCostToUpdate.E6_GB_CostTaxBranch = GlbBranch.CurrentBranch.PK;

			AssertNotEquals("Pre-condition", TestObjectCreator.SVAT1.PK, consolCostToUpdate.E6_AT_TaxRate);

			var consolCostEntered = TestObjectCreator.CreateConsolCost(consol, chargeCode, 200, TestObjectCreator.Creditor1);
			consolCostEntered.E6_GB_CostTaxBranch = TestObjectCreator.NonCurrentBranch.PK;

			AssertEquals("Pre-condition", TestObjectCreator.SVAT1.PK, consolCostEntered.E6_AT_TaxRate);

			consolCostEntered.E6_AT_TaxRate = TestObjectCreator.SVAT2.PK;

			var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice));
			invoice.AH_OH = TestObjectCreator.Creditor1.PK;
			var line = TestObjectCreator.CreateInvoiceLine(invoice, 0M);
			line.AL_AC = chargeCode.PK;
			line.AL_JH = job.PK;
			line.AL_GB_TaxBranch = TestObjectCreator.NonCurrentBranch.PK;

			AssertEquals("Pre-condition", TestObjectCreator.SVAT1.PK, line.AL_AT);

			invoice.ImportSingleCost(consolCostEntered, line);

			var transformer = new TransactionLineJobChargeTransformer(Factory);
			transformer.UpdateCharges(invoice, consolCostToUpdate, consolCostEntered);
			AssertEquals(TestObjectCreator.SVAT2.PK, consolCostToUpdate.E6_AT_TaxRate);
			AssertEquals(TestObjectCreator.SVAT2.PK, invoice.Lines[0].ApportionmentChargeImportedFrom.JR_AT_CostGSTRate);
		}

