		public void TestCreateNewApportionedCharge_CarryLineDescription()
		{
			var consol = TestObjectCreator.CreateConsol();
			var shipment = TestObjectCreator.CreateShipment("S001", consol);
			var job = TestObjectCreator.CreateJob(shipment, false);

			TestObjectCreator.CC1.AC_Desc = "Default description";
			var consolCost = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, 200);

			var invoice = TestObjectCreator.CreateInvoice(typeof(APInvoice));
			var line = TestObjectCreator.CreateInvoiceLine(invoice, 0M);
			invoice.ImportSingleCost(consolCost, line);
			consolCost.ApportionmentCharges[0].JR_Desc = "Override Description";

			var transformer = new TransactionLineJobChargeTransformer(Factory);
			var electronicProcessingChargeProviderMock = new Mock<IElectronicProcessingChargeProvider>();
			electronicProcessingChargeProviderMock.Setup(x => x.ShouldCarryOverInvoiceLineDescriptionDuringIntercompanyInvoicePosting(It.IsAny<ZGuid>(), It.IsAny<ZGuid>())).Returns(false);
			using (ObjectFactory.Substitute(electronicProcessingChargeProviderMock.Object))
			{
				var charge = transformer.CreateNewApportionedCharge(job, consolCost.ApportionmentCharges[0], line, false);
				AssertEquals("Default description", charge.JR_Desc);
			}

			electronicProcessingChargeProviderMock.Setup(x => x.ShouldCarryOverInvoiceLineDescriptionDuringIntercompanyInvoicePosting(It.IsAny<ZGuid>(), It.IsAny<ZGuid>())).Returns(true);
			using (ObjectFactory.Substitute(electronicProcessingChargeProviderMock.Object))
			{
				var charge = transformer.CreateNewApportionedCharge(job, consolCost.ApportionmentCharges[0], line, false);
				AssertEquals("Override Description", charge.JR_Desc);
			}
		}

		public void TestCarryForward_SupplyType()
		{
			var consol1 = TestObjectCreator.CreateConsol(consolNum: "C001");
			var shipment1 = TestObjectCreator.CreateShipment("S001", consol1);
			var apps = new ApportionmentListing(Factory, consol1);

			var cost1 = TestObjectCreator.CreateConsolCost(consol1, CC1, TestObjectCreator.AUD, 1M, 150M, TestObjectCreator.Creditor1, "MAN", apps);
			SetApportionedAmount(cost1,
				shipment1, null, null,
				150M, 0M, 0M);
			cost1.E6_Sequence = 1;
			cost1.E6_SupplyType = "LOC";

			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			var apInvoice = CreateInvoiceByImportingFromConsolCost(newFactory, "INV001",
													consol1, 149M, TestObjectCreator.AUD, 1M, false,
													shipment1, null, null,
													149M, 0M, 0M,
													null);

			var lines = apInvoice.Lines.Cast<APInvoiceLine>().OrderBy(x => x.AL_LocalExTaxAmount).ToArray();
			SetInvoiceLineToFinal(lines.Where(x => x.AL_JH == shipment1.Job.PK).FirstOrDefault(), false);
			AssertEquals(1, apInvoice.Lines.Count);

			newFactory.Save();

			AssertEquals("Should be equal to the charge amount", 149M, lines[0].AL_OSExTaxAmount);
			AssertEquals("Should be equal to the charge gst amount", 0M, lines[0].AL_OSTaxAmount);

			var consol1Reloaded = newFactory.Load<ForwardingConsol>(consol1.PK);
			var consolCostsReloaded = consol1Reloaded.GetApportionments().CostsCollection.Cast<JobConsolCost>().OrderBy(x => x.E6_OSCostAmount).ToList();

			AssertEquals("Suply Type LOC should be carry forward  to new consol cost.", true, consolCostsReloaded.All(x => x.E6_SupplyType == "LOC"));
		}

