		public void TestCreateNewCharge_JR_CostTaxDate()
		{
			var chargeCode = TestObjectCreator.CreateChargeCode("CC01");

			var orgHeader = Factory.LoadTop1<OrgHeader>(new ZQuery(OrgHeaderSchema.OH_Code, "ABIGAS"));
			orgHeader.OH_RL_NKClosestPort = "AUBNE";

			var shipment = TestObjectCreator.CreateShipment("SHP001", false);
			shipment.JS_RL_NKDestination = "AUBNE";
			shipment.JS_RL_NKOrigin = "NZAKL";

			var job = TestObjectCreator.CreateJob(shipment);
			job.JH_OA_LocalChargesAddr = orgHeader.MainAddress.PK;
			Factory.Save();

			var invoice = TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoice), "INV001", TestObjectCreator.AUD, 1, 0, 0, 0, 0);
			var line = invoice.Lines[0];
			line.AL_AC = chargeCode.PK;
			line.AL_JH = job.PK;
			line.AL_AT = TestObjectCreator.GST1WithDates.PK;
			line.AL_TaxDate = ZDate.Today.AddDays(-1);
			line.AL_RX_NKTransactionCurrency = GlbCompany.CurrentCompany.GC_RX_NKLocalCurrency;

			var transformer = new TransactionLineJobChargeTransformer(Factory);
			AccountingConfigurationRegistry.Instance.EnableLocalChargeCodeDescriptionDefault.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);
			job.Charges.RemoveAll();
			transformer.CreateNewCharge(line, job);
			AssertEquals(ZDate.Today.AddDays(-1), job.Charges[0].JR_CostTaxDate);

			job.Charges.RemoveAll();
			line.AL_TaxDate = ZDate.Today.AddDays(5);
			transformer.CreateNewCharge(line, job);
			AssertEquals(ZDate.Today.AddDays(5), job.Charges[0].JR_CostTaxDate);
		}

