		public void TestNullReferenceExceptionOnDeletedChargeLinkedToLine()
		{
			var consol = TestObjectCreator.CreateConsol();
			var shipment = TestObjectCreator.CreateShipment("SHP001", consol);
			var shipment2 = TestObjectCreator.CreateShipment("SHP002", consol);
			TestObjectCreator.CreateJob(shipment, false);
			TestObjectCreator.CreateJob(shipment2, false);
			var consolCost = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, 258.456M, TestObjectCreator.AALSHI);
			Factory.Save();

			var apInvoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), TestObjectCreator.AUD);
			apInvoice.SubmittedFromInvoicingForm = true;
			apInvoice.AH_OH = TestObjectCreator.AALSHI.PK;

			var invoiceCost = TestObjectCreator.CreateConsolCost(apInvoice, consol, TestObjectCreator.CC1, 258.456M);
			apInvoice.ImportAllApportionmentsFromCosting();

			invoiceCost.ApportionmentCharges[0].Delete();
			invoiceCost.CalculationStrategy.UpdateApportionmentChargesListing();
			invoiceCost.ApportionmentCharges[1].JR_OSCostAmt = 10M;

			var expectedErrorMessage = "Exception due to charge linked to line deleted. We are here most likely because we post invoice ignoring validation errors. If so, to fix this particular issue add validation call and error check before invoice saving. To fix original issue investigate error key ApportionmentChargeImportedFromIsDeleted.";
			var exception = AssertExceptionThrown<NullReferenceException>(() => Factory.Save());
			Assert($"Message {expectedErrorMessage} should be part of error message {exception.Message}", exception.Message.Contains(expectedErrorMessage));

			ErrorReporter.Clear();
		}

		public void TestChargesImportedToAnIncompleteInviceIsNotConsideredForPosting()
		{
			var shipment = TestObjectCreator.CreateShipment("S0001");
			var job = TestObjectCreator.CreateJob(shipment);
			var charge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, 200M, 200M);
			var charge2 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, 200M, 200M);
			Factory.Save();

			var incompleteInvoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), "00001");
			var line = incompleteInvoice.Lines.AddNew() as InvoicingLineBase;
			incompleteInvoice.ImportJobChargesIntoInvoice(new[] { charge1 }, line, false);
			incompleteInvoice.SaveAsIncomplete();

			var newFactory = new BusinessObjectFactory();
			var invoice = newFactory.New<APInvoice>();
			invoice.AH_OH = TestObjectCreator.AALSHI.PK;
			invoice.SubmittedFromInvoicingForm = true;
			invoice.AH_RX_NKTransactionCurrency = AUD.RX_Code;
			invoice.AH_ExchangeRate = 1.0m;

			var line1 = (APInvoiceLine)invoice.Lines.AddNew();
			line1.AL_JH = job.PK;
			line1.AL_AC = TestObjectCreator.CC1.PK;
			line1.AL_RX_NKTransactionCurrency = AUD.RX_Code;
			line1.AL_OSExTaxAmount = 200m;

			new TransactionLineJobChargeTransformer(newFactory).Transform(invoice);

			var reloadedCharge1 = newFactory.Load<Charge>(charge1.PK);
			Assert(!reloadedCharge1.IsCostPosted);

			var postedCharge = newFactory.LoadTop1<Charge>(new ZQuery(JobChargeSchema.JR_AL_APLine, line1.PK));
			Assert(postedCharge.IsCostPosted);

			var reloadedCharge2 = newFactory.Load<Charge>(charge2.PK);
			Assert(reloadedCharge2.IsCostPosted);
		}

