			var charge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC2, 300M, 300M);
			var charge2 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC2, 400M, 400M);
			Factory.Save();

			var incompleteInvoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), "00001");
			var importer = new InvoicingBaseBulkConsolCostImporter(incompleteInvoice.ConsolCosting);
			importer.LoadConsolsCollection();
			importer.Import();
			incompleteInvoice.SaveAsIncomplete();

			var newFactory = new BusinessObjectFactory();
			var reloadedCharge = newFactory.Load<Charge>(charge1.PK);
