		[TestDate(2016, 04, 04, 12, 00, 00)]
		public void TestPostingUnspecifiedConsolCostingChargeButSomeIncompletedConsolCostChargesWithSameChargeCodeInDB()
		{
			var testingChargeCode = TestObjectCreator.CC1;
			var consol = TestObjectCreator.CreateConsol();
			var shipmentS0001 = TestObjectCreator.CreateShipment("S0001", consol);
			var shipmentS0002 = TestObjectCreator.CreateShipment("S0002", consol);
			var jobS0001 = TestObjectCreator.CreateJob(shipmentS0001);
			var jobS0002 = TestObjectCreator.CreateJob(shipmentS0002);
			Factory.Save();

			var cost_Incompleted1 = TestObjectCreator.CreateConsolCost(consol, testingChargeCode, 150, creditor: TestObjectCreator.Creditor1);
			var cost_Incompleted2 = TestObjectCreator.CreateConsolCost(consol, testingChargeCode, 250M, creditor: TestObjectCreator.Creditor1);
			AssertEquals("PreCondition, 2 shipments", 2, cost_Incompleted1.ApportionmentCharges.Count);
			AssertEquals("PreCondition, 2 shipments", 2, cost_Incompleted2.ApportionmentCharges.Count);
			Assert("PreCondition", cost_Incompleted1.ApportionmentCharges.Cast<ApportionSplitCharge>().All(x => x.JR_IsUsedForApportionment));
			Assert("PreCondition", cost_Incompleted2.ApportionmentCharges.Cast<ApportionSplitCharge>().All(x => x.JR_IsUsedForApportionment));
			Factory.Save();

			var incompleteInvoice = new TestObjectCreator(new BusinessObjectFactory()).CreateInvoice(typeof(APInvoice), "00001");
			var importer = new InvoicingBaseBulkConsolCostImporter(incompleteInvoice.ConsolCosting);
			importer.LoadConsolsCollection();
			importer.Import();
			incompleteInvoice.SaveAsIncomplete();

			CombineAssertions("PreCondition, IncompletedConsolCostCharges in DB.", () => {
				var invAttribs = new BusinessObjectFactory()
					.Load<JobConsolCostAttrib>(new ZQuery(JobConsolCostAttribSchema.E6A_Value, incompleteInvoice.PK.ToString().ToLower()))
					.ToArray();

				AssertEquals(2, invAttribs.Length);
				Assert(invAttribs.All(x => x.E6A_Name == JobChargeAttribTypeList.Codes.LinkedToIncompleteInvoice));
				Assert(invAttribs.Any(x => x.E6A_E6_JobConsolCost == cost_Incompleted1.PK));
				Assert(invAttribs.Any(x => x.E6A_E6_JobConsolCost == cost_Incompleted2.PK));
			});

			var cost_Candidate1 = TestObjectCreator.CreateConsolCost(consol, testingChargeCode, 350M, creditor: TestObjectCreator.Creditor1);
			var cost_Candidate2 = TestObjectCreator.CreateConsolCost(consol, testingChargeCode, 450M, creditor: TestObjectCreator.Creditor1);
			CombineAssertions("PreCondition, 2 apportionment charges for 2 shipments", () => {
				AssertEquals("[Consol Cost Candidate1]", 2, cost_Candidate1.ApportionmentCharges.Count);
				AssertEquals("[Consol Cost Candidate2]", 2, cost_Candidate2.ApportionmentCharges.Count);
			});
			CombineAssertions("PreCondition, apportion amount to all charges to watch how 'BaseIntegrationTransformer.Transform' do for unchosen charge(s).", () => {
				Assert("[Consol Cost Candidate1]", cost_Candidate1.ApportionmentCharges.Cast<ApportionSplitCharge>().All(x => x.JR_IsUsedForApportionment));
				Assert("[Consol Cost Candidate2]", cost_Candidate2.ApportionmentCharges.Cast<ApportionSplitCharge>().All(x => x.JR_IsUsedForApportionment));
			});
			Factory.Save();
			Assert("PreCondition, all the job charges have sell info to prevent from being deleted.", jobS0001.Charges.Cast<Charge>().All(x => !x.JR_LocalSellAmt.IsEmpty));
			Assert("PreCondition, all the job charges have sell info to prevent from being deleted.", jobS0002.Charges.Cast<Charge>().All(x => !x.JR_LocalSellAmt.IsEmpty));

			var newFactoryForInvoice = new BusinessObjectFactory();
			var apInvoice = CreateAPInvoice("Z1000", TestObjectCreator.Creditor1, AUD, 1m, "APINV1", factory: newFactoryForInvoice);

			var unspecifiedConsolCost = apInvoice.ConsolCosting.ConsolCosts.AddNew();
			unspecifiedConsolCost.SetE6_ParentIDAndE6_ParentTableCodeTogether(consol.CostSupporter.PK, consol.CostSupporter.Type);
			AssertEquals("PreCondition, 2 shipments", 2, unspecifiedConsolCost.ApportionmentCharges.Count);
			unspecifiedConsolCost.E6_AC_ChargeCode = testingChargeCode.PK;
			unspecifiedConsolCost.E6_AT_TaxRate = TestObjectCreator.GST1.PK;
			unspecifiedConsolCost.E6_OSCostAmount = 100m;
			unspecifiedConsolCost.E6_OSGSTAmount_Calc = 100m;
			unspecifiedConsolCost.E6_ApportionmentMethod = "SHP";
			unspecifiedConsolCost.E6_OH_Creditor = TestObjectCreator.Creditor1.PK;

			var apportionmentChargeS0001 = unspecifiedConsolCost.ApportionmentCharges.Where(x => x.JR_JH == jobS0001.PK).First();
			apportionmentChargeS0001.JR_IsUsedForApportionment = true;
			var apportionmentChargeS0002 = unspecifiedConsolCost.ApportionmentCharges.Where(x => x.JR_JH == jobS0002.PK).First();
			apportionmentChargeS0002.JR_IsUsedForApportionment = false;
			unspecifiedConsolCost.ApportionmentCharges.RemoveAndDelete(apportionmentChargeS0002);
			AssertEquals("PreCondition", 1, unspecifiedConsolCost.ApportionmentCharges.Count);
			AssertEquals("PreCondition", true, unspecifiedConsolCost.ApportionmentCharges[0].JR_IsUsedForApportionment);
			AssertEquals("PreCondition", jobS0001.PK, unspecifiedConsolCost.ApportionmentCharges[0].JR_JH);
			AssertEquals("PreCondition", 100m, unspecifiedConsolCost.ApportionmentCharges[0].JR_OSCostAmt);
			AssertEquals("PreCondition", 100m, unspecifiedConsolCost.ApportionmentCharges[0].JR_OSCostGSTAmt);

			AssertEquals("PreCondition", 1, apInvoice.ConsolCosting.ConsolCosts.Count);
			AssertNotEquals("PreCondition, the imported consol cost should be unspecified.", cost_Candidate1.PK, apInvoice.ConsolCosting.ConsolCosts[0].PK);
			AssertNotEquals("PreCondition, the imported consol cost should be unspecified.", cost_Candidate2.PK, apInvoice.ConsolCosting.ConsolCosts[0].PK);

			apInvoice.ImportAllApportionmentsFromCosting();
			AssertEquals("PreCondition", 1, apInvoice.Lines.Count);
			AssertEquals("PreCondition", -100m, apInvoice.Lines[0].AL_GSTVAT);
			AssertEquals("PreCondition", 100m, apInvoice.Lines[0].AL_OSExTaxAmount);
			AssertEquals("PreCondition", 4, jobS0001.Charges.Where(x => x.JR_E6.IsValid).Count());
			AssertEquals("PreCondition", 4, jobS0002.Charges.Where(x => x.JR_E6.IsValid).Count());

			GetTransformer(newFactoryForInvoice).Transform(apInvoice);
			AssertNoExceptionThrown(() => newFactoryForInvoice.Save());

			jobS0001 = newFactoryForInvoice.Load<Job>(jobS0001.PK);
			jobS0002 = newFactoryForInvoice.Load<Job>(jobS0002.PK);
			cost_Incompleted1 = newFactoryForInvoice.Load<JobConsolCost>(cost_Incompleted1.PK);
			cost_Incompleted2 = newFactoryForInvoice.Load<JobConsolCost>(cost_Incompleted2.PK);
			cost_Candidate1 = newFactoryForInvoice.Load<JobConsolCost>(cost_Candidate1.PK);
			cost_Candidate2 = newFactoryForInvoice.Load<JobConsolCost>(cost_Candidate2.PK);
			var matchedCandidateConsolCost = apInvoice.ConsolCosting.ConsolCosts[0];
			AssertNotEquals("PreCondition, none consol cost candidate was selected.", cost_Candidate1.PK, matchedCandidateConsolCost.PK);
			AssertNotEquals("PreCondition, none consol cost candidate was selected.", cost_Candidate2.PK, matchedCandidateConsolCost.PK);
			CombineAssertions("Consol Costs which was imported to incompleted invoice should not be changed.", () => {
				AssertEquals(2, cost_Incompleted1.ApportionmentCharges.Count);
				AssertEquals(2, cost_Incompleted2.ApportionmentCharges.Count);
			});
			CombineAssertions("Consol Costs candidates.", () => {
				AssertEquals(1, cost_Candidate1.ApportionmentCharges.Count);
				AssertEquals(1, cost_Candidate2.ApportionmentCharges.Count);
			});
			CombineAssertions("Job that is not apportioned.", () => {
				AssertEquals(4, jobS0002.Charges.Count);
				AssertEquals(4, jobS0002.Charges.Where(x => x.JR_E6.IsValid).Count());
				AssertEquals(true, jobS0002.Charges.Cast<Charge>().Any(x => x.JR_E6 == cost_Candidate1.PK));
				AssertEquals(true, jobS0002.Charges.Cast<Charge>().Any(x => x.JR_E6 == cost_Candidate2.PK));
			});
			CombineAssertions("Job that is apportioned.", () => {
				AssertEquals(5, jobS0001.Charges.Count);
				AssertEquals(3, jobS0001.Charges.Where(x => x.JR_E6.IsValid).Count());
				AssertEquals(false, jobS0001.Charges.Cast<Charge>().Any(x => x.JR_E6 == cost_Candidate1.PK));
				AssertEquals(false, jobS0001.Charges.Cast<Charge>().Any(x => x.JR_E6 == cost_Candidate2.PK));
				AssertEquals(true, jobS0001.Charges.Cast<Charge>().Any(x => x.JR_E6 == matchedCandidateConsolCost.PK));
			});
		}

		public void TestCarryForwardAtConsolCostLevelWhenAnExistingConsolCostImportedToAnIncompleteInvice()
		{
			using (AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsGreaterThanAccrual.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			using (AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			using (AccountingConfigurationRegistry.Instance.BringForwardAgainstCreditor.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				var consol1 = TestObjectCreator.CreateConsol(consolNum: "C001");

				var shipment1 = TestObjectCreator.CreateShipment("S001", consol1);
				var job = TestObjectCreator.CreateJob(shipment1);
				CreateCharge(job, CC1, "Charge Code 1", AUD, 50M, Creditor1, AUD, 50M, LocalClient);

				var shipment2 = TestObjectCreator.CreateShipment("S002", consol1);
				var shipment3 = TestObjectCreator.CreateShipment("S003", consol1);

				var apps = new ApportionmentListing(Factory, consol1);

				var cost1 = TestObjectCreator.CreateConsolCost(consol1, CC1, AUD, 1M, 500M, TestObjectCreator.Creditor1, "MAN", apps);
				cost1.E6_Sequence = 1;
				SetApportionedAmount(cost1,
					shipment1, shipment2, shipment3,
					200M, 0M, 300M);

				var cost2 = TestObjectCreator.CreateConsolCost(consol1, CC1, AUD, 1M, 300M, TestObjectCreator.Creditor1, "MAN", apps);
				cost2.E6_Sequence = 2;
				SetApportionedAmount(cost2,
					shipment1, shipment2, shipment3,
					100M, 200M, 0M);

				var cost3 = TestObjectCreator.CreateConsolCost(consol1, CC1, AUD, 1M, 600M, TestObjectCreator.Creditor1, "MAN", apps);
				cost3.E6_Sequence = 3;
				SetApportionedAmount(cost3,
					shipment1, shipment2, shipment3,
					150M, 250M, 200M);

				var cost4 = TestObjectCreator.CreateConsolCost(consol1, CC1, AUD, 1M, 800M, TestObjectCreator.Creditor1, "MAN", apps);
				cost4.E6_Sequence = 4;
				SetApportionedAmount(cost4,
					shipment1, shipment2, shipment3,
					300M, 300M, 200M);

				Factory.Save();

				//Create an Incomplete Invoice by importing a consol cost.
				var incompleteInvoiceFactory = new BusinessObjectFactory();
				var objectCreatorForIncompleteInvoiceFactory = new TestObjectCreator(incompleteInvoiceFactory);
				var incompleteInvoice = objectCreatorForIncompleteInvoiceFactory.CreateInvoice(typeof(APInvoice), "INC00001", organisation: TestObjectCreator.Creditor1);
				var importer = new InvoicingBaseBulkConsolCostImporter(incompleteInvoice.ConsolCosting);
				importer.LoadConsolsCollection();
				var consol = importer.ConsolsFilteredByViewingPermission.OfType<InvoicingBaseConsolForImporting>().First();
				consol.ConsolCostsFilteredByViewingPermission.OfType<InvoicingBaseConsolCostForImporting>().Where(c => c.PK != cost3.PK).ForEach(c => c.IsSelectedForImport = false);
				importer.Import();
				incompleteInvoice.ConsolCosting.ConsolCosts[0].E6_OSCostAmount = 430M;
				incompleteInvoice.ConsolCosting.ConsolCosts[0].IsFinal = false;
				SetApportionedAmount(incompleteInvoice.ConsolCosting.ConsolCosts[0],
					shipment1, shipment2, shipment3,
					120M, 180M, 130M);
				incompleteInvoice.ImportAllApportionmentsFromCosting();
				incompleteInvoice.SaveAsIncomplete();

				//Now post an AP Invoice
				var newFactory = new BusinessObjectFactory();
				var apInvoice = CreateInvoiceByImportingFromConsolCost(newFactory, "INV001",
														consol1, 450M, AUD, 1M, false,
														shipment1, shipment2, shipment3,
														190M, 0M, 260M,
														null);

				var lines = apInvoice.Lines.Cast<APInvoiceLine>().OrderBy(x => x.AL_LocalExTaxAmount).ToArray();
				AssertEquals(2, apInvoice.Lines.Count);
				newFactory.Save();

				AssertEquals("Should be equal to the charge amount", 190M, lines[0].AL_LocalExTaxAmount);
				AssertEquals("Should be equal to the charge amount", 260M, lines[1].AL_LocalExTaxAmount);
				AssertEquals("Should be equal to the charge gst amount", 0M, lines[0].AL_OSTaxAmount);
				AssertEquals("Should be equal to the charge gst amount", 0M, lines[1].AL_OSTaxAmount);

				var consol1Reloaded = newFactory.Load<ForwardingConsol>(consol1.PK);
				var consolCostsReloaded = consol1Reloaded.GetApportionments().CostsCollection.Cast<JobConsolCost>().OrderBy(x => x.E6_OSCostAmount).ToList();
				AssertEquals("ConsolCost Count", 4, consolCostsReloaded.Count);
				AssertConsolCost(consolCostsReloaded[0], "AUD", 1M, 300M, 300M, false);
				AssertConsolCost(consolCostsReloaded[1], "AUD", 1M, 450M, 450M, true);
				AssertConsolCost(consolCostsReloaded[2], "AUD", 1M, 600M, 600M, false);
				AssertConsolCost(consolCostsReloaded[3], "AUD", 1M, 850M, 850M, false);

				var shipment1JobCharges = newFactory.Load<Charge>(new ZQuery(JobChargeSchema.JR_JH, shipment1.Job.PK)).OrderBy(x => x.JR_OSCostAmt).ToList();
				AssertEquals("Shipment1 Charges Count", 5, shipment1JobCharges.Count);
				AssertJobCharge(shipment1JobCharges[0], ZGuid.Empty, AUD.RX_Code, 1M, 0M, 0M, AUD.RX_Code, 1M, 300M, 300M, false);
				AssertJobCharge(shipment1JobCharges[1], Creditor1.PK, AUD.RX_Code, 1M, 50M, 50M, AUD.RX_Code, 1M, 50M, 50M, false);
				AssertApportionJobCharge(shipment1JobCharges[2], Creditor1.PK, AUD.RX_Code, 1M, 150M, 150M, AUD.RX_Code, 1M, 150M, 150M, false, cost3.PK);
				AssertApportionJobCharge(shipment1JobCharges[3], Creditor1.PK, AUD.RX_Code, 1M, 190M, 190M, AUD.RX_Code, 1M, 200M, 200M, true, cost1.PK);
				AssertApportionJobCharge(shipment1JobCharges[4], Creditor1.PK, AUD.RX_Code, 1M, 410M, 410M, AUD.RX_Code, 1M, 100M, 100M, false, cost2.PK);

				var shipment2JobCharges = newFactory.Load<Charge>(new ZQuery(JobChargeSchema.JR_JH, shipment2.Job.PK)).OrderBy(x => x.JR_OSCostAmt).ToList();
				AssertEquals("Shipment2 Charges Count", 3, shipment2JobCharges.Count);
				AssertApportionJobCharge(shipment2JobCharges[0], Creditor1.PK, AUD.RX_Code, 1M, 200M, 200M, AUD.RX_Code, 1M, 200M, 200M, false, cost2.PK);
				AssertApportionJobCharge(shipment2JobCharges[1], Creditor1.PK, AUD.RX_Code, 1M, 250M, 250M, AUD.RX_Code, 1M, 250M, 250M, false, cost3.PK);
				AssertApportionJobCharge(shipment2JobCharges[2], Creditor1.PK, AUD.RX_Code, 1M, 300M, 300M, AUD.RX_Code, 1M, 300M, 300M, false, cost4.PK);

				var shipment3JobCharges = newFactory.Load<Charge>(new ZQuery(JobChargeSchema.JR_JH, shipment3.Job.PK)).OrderBy(x => x.JR_OSCostAmt).ToList();
				AssertEquals("Shipment3 Charges Count", 4, shipment3JobCharges.Count);
				AssertJobCharge(shipment3JobCharges[0], ZGuid.Empty, AUD.RX_Code, 1M, 0M, 0M, AUD.RX_Code, 1M, 200M, 200M, false);
				AssertApportionJobCharge(shipment3JobCharges[1], Creditor1.PK, AUD.RX_Code, 1M, 200M, 200M, AUD.RX_Code, 1M, 200M, 200M, false, cost3.PK);
				AssertApportionJobCharge(shipment3JobCharges[2], Creditor1.PK, AUD.RX_Code, 1M, 240M, 240M, AUD.RX_Code, 1M, 0M, 0M, false, cost2.PK);
				AssertApportionJobCharge(shipment3JobCharges[3], Creditor1.PK, AUD.RX_Code, 1M, 260M, 260M, AUD.RX_Code, 1M, 300M, 300M, true, cost1.PK);

				//Post the Incomplete invoice
				newFactory = new BusinessObjectFactory();
				var apInvoice2 = newFactory.Load<APInvoice>(incompleteInvoice.PK);
				apInvoice2.RestoreSavedData();
				apInvoice2.MoveFromIncompleteToPayableLedger();
				newFactory.Save();

				consol1Reloaded = newFactory.Load<ForwardingConsol>(consol1.PK);
				consolCostsReloaded = consol1Reloaded.GetApportionments().CostsCollection.Cast<JobConsolCost>().OrderBy(x => x.E6_OSCostAmount).ToList();
				AssertEquals("ConsolCost Count", 5, consolCostsReloaded.Count);
				AssertConsolCost(consolCostsReloaded[0], "AUD", 1M, 170M, 170M, false);
				AssertConsolCost(consolCostsReloaded[1], "AUD", 1M, 300M, 300M, false);
				AssertConsolCost(consolCostsReloaded[2], "AUD", 1M, 430M, 430M, true);
				AssertConsolCost(consolCostsReloaded[3], "AUD", 1M, 450M, 450M, true);
				AssertConsolCost(consolCostsReloaded[4], "AUD", 1M, 850M, 850M, false);

				shipment1JobCharges = newFactory.Load<Charge>(new ZQuery(JobChargeSchema.JR_JH, shipment1.Job.PK)).OrderBy(x => x.JR_OSCostAmt).ToList();
				AssertEquals("Shipment1 Charges Count", 6, shipment1JobCharges.Count);
				AssertJobCharge(shipment1JobCharges[0], ZGuid.Empty, AUD.RX_Code, 1M, 0M, 0M, AUD.RX_Code, 1M, 300M, 300M, false);
				AssertApportionJobCharge(shipment1JobCharges[1], Creditor1.PK, AUD.RX_Code, 1M, 30M, 30M, AUD.RX_Code, 1M, 0M, 0M, false, consolCostsReloaded[0].PK);
				AssertJobCharge(shipment1JobCharges[2], Creditor1.PK, AUD.RX_Code, 1M, 50M, 50M, AUD.RX_Code, 1M, 50M, 50M, false);
				AssertApportionJobCharge(shipment1JobCharges[3], Creditor1.PK, AUD.RX_Code, 1M, 120M, 120M, AUD.RX_Code, 1M, 150M, 150M, true, cost3.PK);
				AssertApportionJobCharge(shipment1JobCharges[4], Creditor1.PK, AUD.RX_Code, 1M, 190M, 190M, AUD.RX_Code, 1M, 200M, 200M, true, cost1.PK);
				AssertApportionJobCharge(shipment1JobCharges[5], Creditor1.PK, AUD.RX_Code, 1M, 410M, 410M, AUD.RX_Code, 1M, 100M, 100M, false, cost2.PK);

				shipment2JobCharges = newFactory.Load<Charge>(new ZQuery(JobChargeSchema.JR_JH, shipment2.Job.PK)).OrderBy(x => x.JR_OSCostAmt).ToList();
				AssertEquals("Shipment2 Charges Count", 4, shipment2JobCharges.Count);
				AssertApportionJobCharge(shipment2JobCharges[0], Creditor1.PK, AUD.RX_Code, 1M, 70M, 70M, AUD.RX_Code, 1M, 0M, 0M, false, consolCostsReloaded[0].PK);
				AssertApportionJobCharge(shipment2JobCharges[1], Creditor1.PK, AUD.RX_Code, 1M, 180M, 180M, AUD.RX_Code, 1M, 250M, 250M, true, cost3.PK);
				AssertApportionJobCharge(shipment2JobCharges[2], Creditor1.PK, AUD.RX_Code, 1M, 200M, 200M, AUD.RX_Code, 1M, 200M, 200M, false, cost2.PK);
				AssertApportionJobCharge(shipment2JobCharges[3], Creditor1.PK, AUD.RX_Code, 1M, 300M, 300M, AUD.RX_Code, 1M, 300M, 300M, false, cost4.PK);

				shipment3JobCharges = newFactory.Load<Charge>(new ZQuery(JobChargeSchema.JR_JH, shipment3.Job.PK)).OrderBy(x => x.JR_OSCostAmt).ToList();
				AssertEquals("Shipment3 Charges Count", 5, shipment3JobCharges.Count);
				AssertJobCharge(shipment3JobCharges[0], ZGuid.Empty, AUD.RX_Code, 1M, 0M, 0M, AUD.RX_Code, 1M, 200M, 200M, false);
				AssertApportionJobCharge(shipment3JobCharges[1], Creditor1.PK, AUD.RX_Code, 1M, 70M, 70M, AUD.RX_Code, 1M, 0M, 0M, false, consolCostsReloaded[0].PK);
				AssertApportionJobCharge(shipment3JobCharges[2], Creditor1.PK, AUD.RX_Code, 1M, 130M, 130M, AUD.RX_Code, 1M, 200M, 200M, true, cost3.PK);
				AssertApportionJobCharge(shipment3JobCharges[3], Creditor1.PK, AUD.RX_Code, 1M, 240M, 240M, AUD.RX_Code, 1M, 0M, 0M, false, cost2.PK);
				AssertApportionJobCharge(shipment3JobCharges[4], Creditor1.PK, AUD.RX_Code, 1M, 260M, 260M, AUD.RX_Code, 1M, 300M, 300M, true, cost1.PK);
			}
		}

		#region Carry Forward consol costs related tests when FPOS is NOT Empty

		public void TestCarryForwardAtConsolCostLevel_FPOS_AllCostsHaveSameFPOS()
		{
			using (PlaceOfSupplyHelper.SetPOSTypesEnabled_ForTestOnly(PlaceOfSupplyTypes.State.Code, PlaceOfSupplyTypes.PredefinedRule.Code))
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.India))
			using (GlbCompany.CurrentCompany.TemporarilySetCurrency("AUD"))
			{
				var fpos1 = new FPOSTuple { Code = "AN", Type = "STA" };
				var fpos2 = new FPOSTuple { Code = "AP", Type = "STA" };
				CarryForwardAtConsolCostLevel_FPOS_ExistingCarryForwardCharge(cost1FPOS: fpos1, cost2FPOS: fpos1, postedCost1FPOS: fpos1, postedCost2FPOS: fpos2);
			}
		}

		public void TestCarryForwardAtConsolCostLevel_FPOS_CostsHaveDifferentFPOS()
		{
			using (PlaceOfSupplyHelper.SetPOSTypesEnabled_ForTestOnly(PlaceOfSupplyTypes.State.Code, PlaceOfSupplyTypes.PredefinedRule.Code))
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.India))
			using (GlbCompany.CurrentCompany.TemporarilySetCurrency("AUD"))
			{
				var fpos1 = new FPOSTuple { Code = "AN", Type = "STA" };
				var fpos2 = new FPOSTuple { Code = "AP", Type = "STA" };
				var fpos3 = new FPOSTuple { Code = "AR", Type = "STA" };
				var fpos4 = new FPOSTuple { Code = "AS", Type = "STA" };
				CarryForwardAtConsolCostLevel_FPOS_ExistingCarryForwardCharge(cost1FPOS: fpos1, cost2FPOS: fpos2, postedCost1FPOS: fpos3, postedCost2FPOS: fpos4);
			}
		}

		void CarryForwardAtConsolCostLevel_FPOS_ExistingCarryForwardCharge(FPOSTuple cost1FPOS, FPOSTuple cost2FPOS, FPOSTuple postedCost1FPOS, FPOSTuple postedCost2FPOS)
		{
			using (AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsGreaterThanAccrual.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			using (AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			using (AccountingConfigurationRegistry.Instance.BringForwardAgainstCreditor.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				// To prevent defaulting POS by Branch OrgProxy
				GlbBranch.CurrentBranch.OrgProxy.MainAddress.OA_RL_NKRelatedPortCode = "";
				GlbBranch.CurrentBranch.OrgProxy.MainAddress.OA_RN_NKCountryCode = Core.Constants.CountryCodes.India;
				GlbBranch.CurrentBranch.OrgProxy.MainAddress.OA_State = "";
				GlbCompany.CurrentCompany.Factory.Save();

				// prevent defaulting POS from Orgs
				Creditor1.MainAddress.OA_RL_NKRelatedPortCode = "";
				Creditor1.MainAddress.OA_RN_NKCountryCode = Core.Constants.CountryCodes.India;
				Creditor1.MainAddress.OA_State = "";

				TestObjectCreator.Creditor1.MainAddress.OA_RL_NKRelatedPortCode = "";
				TestObjectCreator.Creditor1.MainAddress.OA_RN_NKCountryCode = Core.Constants.CountryCodes.India;
				TestObjectCreator.Creditor1.MainAddress.OA_State = "";

				#region Creating Consol Costs

				Creditor1.CompanyData.OB_APVATConfig = "DEF";
				Factory.Save();

			/*
				 BEFORE POSTING

				 Cost 	|	S001	|	S002	|	S003
				 --------------------------------------------------------------------
				 500	|	200		|	0		|	300
				 300	|	100		|	200		|	0
				
				 Shipment level charges
						|	50		|			|	
			 */

				var consol1 = TestObjectCreator.CreateConsol(consolNum: "C001");

				var shipment1 = TestObjectCreator.CreateShipment("S001", consol1);
				var job = TestObjectCreator.CreateJob(shipment1);
				CreateCharge(job, CC1, "Charge Code 1", AUD, 50M, Creditor1, AUD, 50M, LocalClient);

				var shipment2 = TestObjectCreator.CreateShipment("S002", consol1);
				var shipment3 = TestObjectCreator.CreateShipment("S003", consol1);

				ApportionmentListing apps = new ApportionmentListing(Factory, consol1);

				var cost1 = TestObjectCreator.CreateConsolCost(consol1, CC1, AUD, 1M, 500M, TestObjectCreator.Creditor1, "MAN", apps);
				SetApportionedAmountFPOSAndTaxRate(cost1,
					shipment1, shipment2, shipment3,
					200M, 0M, 300M, cost1FPOS.Code, TestObjectCreator.GST11);

				var cost2 = TestObjectCreator.CreateConsolCost(consol1, CC1, AUD, 1M, 300M, TestObjectCreator.Creditor1, "MAN", apps);
				SetApportionedAmountFPOSAndTaxRate(cost2,
					shipment1, shipment2, shipment3,
					100M, 200M, 0M, cost2FPOS.Code, TestObjectCreator.GST11);

				Factory.Save();

				#endregion

				#region First Invoice Posting

				var newFactory = new BusinessObjectFactory();
				var newTestObjectCreator = new TestObjectCreator(newFactory);
				var apInvoice = CreateInoivceByImportingFromConsolCost(newTestObjectCreator, "INV001",
														consol1, 400M, AUD, 1M, false,
														shipment1, shipment2, shipment3,
														180M, 0M, 220M,
														cost1, postedCost1FPOS.Code, newTestObjectCreator.GST11);

				var lines = apInvoice.Lines.Cast<APInvoiceLine>().OrderBy(x => x.AL_LocalExTaxAmount).ToArray();
				AssertEquals(2, apInvoice.Lines.Count);

				newFactory.Save();

				AssertEquals("Should be equal to the charge amount", 180M, lines[0].AL_LocalExTaxAmount);
				AssertEquals("Should be equal to the charge amount", 220M, lines[1].AL_LocalExTaxAmount);
				AssertEquals("Should be equal to the charge gst amount", newTestObjectCreator.GST11.PK, lines[0].AL_AT);
				AssertEquals("Should be equal to the charge gst amount", newTestObjectCreator.GST11.PK, lines[1].AL_AT);

			/*
				 AFTER POSTING FIRST INVOICE

				 Cost 	|	S001	|	S002	|	S003	| COMMENT
				 --------------------------------------------------------------------
				 400	|	180		|	0		|	220		| Posted cost
				 300	|	100		|	200		|	0		| Unposted cost
				 100	|	20		|	0		|	80		| Newly created carry forward charge

				 Shipment level charges
						|	50		|			|			| Unposted shipment level charge
			 */

				#region Assert Costs

				var consol1Reloaded = newFactory.Load<ForwardingConsol>(consol1.PK);
				var consolCostsReloaded = consol1Reloaded.GetApportionments().CostsCollection.Cast<JobConsolCost>().OrderBy(x => x.E6_OSCostAmount).ToList();
				AssertEquals("ConsolCost Count", 3, consolCostsReloaded.Count);

				var expectedAmount = new ExpectedValueWithMessage<decimal>() { ExpectedValue = 100M, AssertionMessage = "new Carry Forward Cost. (400 - 300) = 100" };
				var expectedIsPosted = new ExpectedValueWithMessage<bool>() { ExpectedValue = false, AssertionMessage = "Should not be posted." };
				var expectedFPOS = new ExpectedValueWithMessage<string>() { ExpectedValue = postedCost1FPOS.Code, AssertionMessage = "FPOS value will be taken from the FPOS of the imported cost" };
				var expectedFPOSType = new ExpectedValueWithMessage<string>() { ExpectedValue = postedCost1FPOS.Type, AssertionMessage = "FPOS Type value will be taken from the FPOS Type of the imported cost" };
				var expectedGSTRate = new ExpectedValueWithMessage<ZGuid>() { ExpectedValue = newTestObjectCreator.GST11.PK, AssertionMessage = "GST rate will be taken from the imported cost" };
				AssertConsolCost(consolCostsReloaded[0], "AUD", 1M, expectedAmount, expectedAmount, expectedIsPosted, expectedFPOS, expectedFPOSType, expectedGSTRate);

				expectedAmount = new ExpectedValueWithMessage<decimal>() { ExpectedValue = 300M, AssertionMessage = "Should not be included in Carry Forward calculation" };
				expectedIsPosted = new ExpectedValueWithMessage<bool>() { ExpectedValue = false, AssertionMessage = "Should not be posted." };
				expectedFPOS = new ExpectedValueWithMessage<string>() { ExpectedValue = cost2FPOS.Code, AssertionMessage = "FPOS value will remain same" };
				expectedFPOSType = new ExpectedValueWithMessage<string>() { ExpectedValue = cost2FPOS.Type, AssertionMessage = "FPOS Type value will remain same" };
				expectedGSTRate = new ExpectedValueWithMessage<ZGuid>() { ExpectedValue = newTestObjectCreator.GST11.PK, AssertionMessage = "GST rate will remain same" };
				AssertConsolCost(consolCostsReloaded[1], "AUD", 1M, expectedAmount, expectedAmount, expectedIsPosted, expectedFPOS, expectedFPOSType, expectedGSTRate);

				//Posted consol cost
				expectedAmount = new ExpectedValueWithMessage<decimal>() { ExpectedValue = 400M, AssertionMessage = "ACR amount was 500. Now posted with amount 400." };
				expectedIsPosted = new ExpectedValueWithMessage<bool>() { ExpectedValue = true, AssertionMessage = "Should be posted, as user selected to post it" };
				expectedFPOS = new ExpectedValueWithMessage<string>() { ExpectedValue = postedCost1FPOS.Code, AssertionMessage = "FPOS value will be taken from the imported cost" };
				expectedFPOSType = new ExpectedValueWithMessage<string>() { ExpectedValue = postedCost1FPOS.Type, AssertionMessage = "FPOS Type value will be taken from the imported cost" };
				expectedGSTRate = new ExpectedValueWithMessage<ZGuid>() { ExpectedValue = newTestObjectCreator.GST11.PK, AssertionMessage = "GST rate will be taken from the imported cost" };
				AssertConsolCost(consolCostsReloaded[2], "AUD", 1M, expectedAmount, expectedAmount, expectedIsPosted, expectedFPOS, expectedFPOSType, expectedGSTRate);

				#endregion

				#region Assert Job Charge

				//Shipment 01
				var shipment1JobCharges = newFactory.Load<Charge>(new ZQuery(JobChargeSchema.JR_JH, shipment1.Job.PK)).OrderBy(x => x.JR_OSCostAmt).ToList();
				AssertEquals("Shipment1 Charges Count", 4, shipment1JobCharges.Count);

				expectedAmount = new ExpectedValueWithMessage<decimal>() { ExpectedValue = 20M, AssertionMessage = "Newly created carry forward charge. (200-180)=20" };
				expectedIsPosted = new ExpectedValueWithMessage<bool>() { ExpectedValue = false, AssertionMessage = "Should not be posted" };
				var expectedSellAmount = new ExpectedValueWithMessage<decimal>() { ExpectedValue = 0M, AssertionMessage = "NO WIP" };
				var expectedCostPK = new ExpectedValueWithMessage<ZGuid>() { ExpectedValue = consolCostsReloaded[0].PK, AssertionMessage = "This is the PK of new carry forward consol cost" };
				expectedFPOS = new ExpectedValueWithMessage<string>() { ExpectedValue = postedCost1FPOS.Code, AssertionMessage = "FPOS value will be taken from the imported cost" };
				expectedFPOSType = new ExpectedValueWithMessage<string>() { ExpectedValue = postedCost1FPOS.Type, AssertionMessage = "FPOS Type value will be taken from the imported cost" };
				expectedGSTRate = new ExpectedValueWithMessage<ZGuid>() { ExpectedValue = newTestObjectCreator.GST11.PK, AssertionMessage = "GST rate will be taken from the imported cost" };
				AssertApportionJobCharge(shipment1JobCharges[0], Creditor1.PK, AUD.RX_Code, 1M, expectedAmount, expectedAmount, AUD.RX_Code, 1M, expectedSellAmount, expectedSellAmount, expectedIsPosted, expectedCostPK, expectedFPOS, expectedFPOSType, expectedGSTRate);

				expectedAmount = new ExpectedValueWithMessage<decimal>() { ExpectedValue = 50M, AssertionMessage = "It is a shipment level ACR. So, amount should not be changed" };
				expectedIsPosted = new ExpectedValueWithMessage<bool>() { ExpectedValue = false, AssertionMessage = "It is a shipment level ACR. So, should not be posted" };
				var expectedChargeFPOS = new ExpectedValueWithMessage<ZString>() { ExpectedValue = ZString.Empty, AssertionMessage = "FPOS value should remain empty" };
				var expectedChargeFPOSType = new ExpectedValueWithMessage<ZString>() { ExpectedValue = ZString.Empty, AssertionMessage = "FPOS Type value should remain empty" };
				expectedGSTRate = new ExpectedValueWithMessage<ZGuid>() { ExpectedValue = newTestObjectCreator.GST11.PK, AssertionMessage = "GST rate should remain the same" };
				AssertJobCharge(shipment1JobCharges[1], Creditor1.PK, AUD.RX_Code, 1M, expectedAmount, expectedAmount, AUD.RX_Code, 1M, expectedAmount, expectedAmount, expectedIsPosted, expectedChargeFPOS, expectedChargeFPOSType, expectedGSTRate);

				expectedAmount = new ExpectedValueWithMessage<decimal>() { ExpectedValue = 100M, AssertionMessage = "ACR amount should remain same, as it is not posted and not included in carry forward calculation" };
				expectedIsPosted = new ExpectedValueWithMessage<bool>() { ExpectedValue = false, AssertionMessage = "Should not be posted, as it is not linked to the posted cost" };
				expectedSellAmount = new ExpectedValueWithMessage<decimal>() { ExpectedValue = 100M, AssertionMessage = "WIP amount should remain same" };
				expectedCostPK = new ExpectedValueWithMessage<ZGuid>() { ExpectedValue = cost2.PK, AssertionMessage = "This is the PK of <cost2>" };
				expectedFPOS = new ExpectedValueWithMessage<string>() { ExpectedValue = cost2FPOS.Code, AssertionMessage = "FPOS value should remain same, as it is not posted and not included in carry forward calculation" };
				expectedFPOSType = new ExpectedValueWithMessage<string>() { ExpectedValue = cost2FPOS.Type, AssertionMessage = "FPOS Type value should remain same, as it is not posted and not included in carry forward calculation" };
				expectedGSTRate = new ExpectedValueWithMessage<ZGuid>() { ExpectedValue = newTestObjectCreator.GST11.PK, AssertionMessage = "GST rate should remain same, as it is not posted and not included in carry forward calculation" };
				AssertApportionJobCharge(shipment1JobCharges[2], Creditor1.PK, AUD.RX_Code, 1M, expectedAmount, expectedAmount, AUD.RX_Code, 1M, expectedSellAmount, expectedSellAmount, expectedIsPosted, expectedCostPK, expectedFPOS, expectedFPOSType, expectedGSTRate);

				expectedAmount = new ExpectedValueWithMessage<decimal>() { ExpectedValue = 180M, AssertionMessage = "Original ACR amount was 200. After posting it became 180 and thus creating a carry forward amount of 20 AUD" };
				expectedIsPosted = new ExpectedValueWithMessage<bool>() { ExpectedValue = true, AssertionMessage = "Should be posted, as user selected this cost for posting" };
				expectedSellAmount = new ExpectedValueWithMessage<decimal>() { ExpectedValue = 200M, AssertionMessage = "Original WIP amount was 200 and it should remain the same" };
				expectedCostPK = new ExpectedValueWithMessage<ZGuid>() { ExpectedValue = cost1.PK, AssertionMessage = "This is the PK of <cost1>" };
				expectedFPOS = new ExpectedValueWithMessage<string>() { ExpectedValue = postedCost1FPOS.Code, AssertionMessage = "Current FPOS value will be overridden by the FPOS of the imported cost" };
				expectedFPOSType = new ExpectedValueWithMessage<string>() { ExpectedValue = postedCost1FPOS.Type, AssertionMessage = "Current FPOS Type value will be overridden by the FPOS of the imported cost" };
				expectedGSTRate = new ExpectedValueWithMessage<ZGuid>() { ExpectedValue = newTestObjectCreator.GST11.PK, AssertionMessage = "GST rate should come from the imported cost" };
				AssertApportionJobCharge(shipment1JobCharges[3], Creditor1.PK, AUD.RX_Code, 1M, expectedAmount, expectedAmount, AUD.RX_Code, 1M, expectedSellAmount, expectedSellAmount, expectedIsPosted, expectedCostPK, expectedFPOS, expectedFPOSType, expectedGSTRate);

				//Shipment 02
