		public void TestCarryForwardAtConsolCostLevel_FPOS_AllCostsHaveSameFPOS_ManualInput()
		{
			using (PlaceOfSupplyHelper.SetPOSTypesEnabled_ForTestOnly(PlaceOfSupplyTypes.State.Code, PlaceOfSupplyTypes.PredefinedRule.Code))
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.India))
			using (GlbCompany.CurrentCompany.TemporarilySetCurrency("AUD"))
			{
				var fpos1 = new FPOSTuple { Code = "AN", Type = "STA" };
				var fpos2 = new FPOSTuple { Code = "AP", Type = "STA" };
				CarryForwardAtConsolCostLevel_FPOS_ExistingCarryForwardCharge_ManualInput(cost1FPOS: fpos1, cost2FPOS: fpos1, postedCost1FPOS: fpos1, postedCost2FPOS: fpos2);
			}
		}

		public void TestCarryForwardAtConsolCostLevel_FPOS_CostsHaveDifferentFPOS_ManualInput()
		{
			using (PlaceOfSupplyHelper.SetPOSTypesEnabled_ForTestOnly(PlaceOfSupplyTypes.State.Code, PlaceOfSupplyTypes.PredefinedRule.Code))
			using (GlbCompany.CurrentCompany.TemporarilySetCountry(Core.Constants.CountryCodes.India))
			using (GlbCompany.CurrentCompany.TemporarilySetCurrency("AUD"))
			{
				var fpos1 = new FPOSTuple { Code = "AN", Type = "STA" };
				var fpos2 = new FPOSTuple { Code = "AP", Type = "STA" };
				var fpos3 = new FPOSTuple { Code = "AR", Type = "STA" };
				var fpos4 = new FPOSTuple { Code = "AS", Type = "STA" };
				CarryForwardAtConsolCostLevel_FPOS_ExistingCarryForwardCharge_ManualInput(cost1FPOS: fpos1, cost2FPOS: fpos2, postedCost1FPOS: fpos3, postedCost2FPOS: fpos4);
			}
		}

		void CarryForwardAtConsolCostLevel_FPOS_ExistingCarryForwardCharge_ManualInput(FPOSTuple cost1FPOS, FPOSTuple cost2FPOS, FPOSTuple postedCost1FPOS, FPOSTuple postedCost2FPOS)
		{
			using (AccountingConfigurationRegistry.Instance.CreateWIPWhenCostIsGreaterThanAccrual.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			using (AccountingConfigurationRegistry.Instance.EnableNegativeAccrualBehaviors.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			using (AccountingConfigurationRegistry.Instance.BringForwardAgainstCreditor.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				// To prevent defaulting POS by Branch OrgProxy
				GlbBranch.CurrentBranch.OrgProxy.MainAddress.OA_RL_NKRelatedPortCode = "";
				GlbBranch.CurrentBranch.OrgProxy.MainAddress.OA_RN_NKCountryCode = Core.Constants.CountryCodes.India;
				GlbBranch.CurrentBranch.OrgProxy.MainAddress.OA_State = "";
				GlbCompany.CurrentCompany.Factory.Save();

				// To prevent defaulting POS by Org and duplicating Creditor1 code
				TestObjectCreator.Creditor1.OH_Code += "_";
				TestObjectCreator.Creditor1.MainAddress.OA_RL_NKRelatedPortCode = "";
				TestObjectCreator.Creditor1.MainAddress.OA_RN_NKCountryCode = Core.Constants.CountryCodes.India;
				TestObjectCreator.Creditor1.MainAddress.OA_State = "";

				#region Creating Consol Costs

				Creditor1.CompanyData.OB_APVATConfig = "DEF";
				Factory.Save();

			/*
				 BEFORE POSTING

				 Cost 	|	S001	|	S002	|	S003
				 --------------------------------------------------------------------
				 500	|	200		|	0		|	300
				 200	|	50		|	150		|	0
				
				 Shipment level charges
						|	40		|			|	
			 */

				var consol1 = TestObjectCreator.CreateConsol(consolNum: "C001");

				var shipment1 = TestObjectCreator.CreateShipment("S001", consol1);
				var job = TestObjectCreator.CreateJob(shipment1);
				CreateCharge(job, CC1, "Charge Code 1", AUD, 40M, Creditor1, AUD, 40M, LocalClient);

				var shipment2 = TestObjectCreator.CreateShipment("S002", consol1);
				var shipment3 = TestObjectCreator.CreateShipment("S003", consol1);

				ApportionmentListing apps = new ApportionmentListing(Factory, consol1);

				var cost1 = TestObjectCreator.CreateConsolCost(consol1, CC1, AUD, 1M, 500M, TestObjectCreator.Creditor1, "MAN", apps);
				SetApportionedAmountFPOSAndTaxRate(cost1,
					shipment1, shipment2, shipment3,
					200M, 0M, 300M, cost1FPOS.Code, TestObjectCreator.GST11);

				var cost2 = TestObjectCreator.CreateConsolCost(consol1, CC1, AUD, 1M, 200M, TestObjectCreator.Creditor1, "MAN", apps);
				SetApportionedAmountFPOSAndTaxRate(cost2,
					shipment1, shipment2, shipment3,
