		InvoicingBase CreateInvoiceByImportingFromConsolCost(BusinessObjectFactory newFactory, ZString transactionNum,
			ForwardingConsol consol, ZDecimal consolCostAmount, RefCurrency currency, ZDecimal exchangeRate, bool isCostFinal,
			ForwardingShipment shipment1, ForwardingShipment shipment2, ForwardingShipment shipment3,
			ZDecimal shipment1Amount, ZDecimal shipment2Amount, ZDecimal shipment3Amount,
			JobConsolCost cost = null)
		{
			var newTestObjectCreator = new TestObjectCreator(newFactory);
			return CreateInoivceByImportingFromConsolCost(newTestObjectCreator
				, transactionNum
				, consol
				, consolCostAmount
				, currency
				, exchangeRate
				, isCostFinal
				, shipment1
				, shipment2
				, shipment3
				, shipment1Amount
				, shipment2Amount
				, shipment3Amount
				, cost
				, ZString.Empty
				, null);
		}

		InvoicingBase CreateInoivceByImportingFromConsolCost(TestObjectCreator newTestObjectCreator, ZString transactionNum,
			ForwardingConsol consol, ZDecimal consolCostAmount, RefCurrency currency, ZDecimal exchangeRate, bool isCostFinal,
			ForwardingShipment shipment1, ForwardingShipment shipment2, ForwardingShipment shipment3,
			ZDecimal shipment1Amount, ZDecimal shipment2Amount, ZDecimal shipment3Amount,
			JobConsolCost cost, ZString fixedPlaceOfSupply, AccTaxRate taxRate)
		{
			var apInvoice = newTestObjectCreator.CreateInvoice(typeof(APInvoice), currency, exchangeRate, TestObjectCreator.Creditor1, ZDateTime.Today);
			apInvoice.SubmittedFromInvoicingForm = true;
			apInvoice.AH_TransactionNum = transactionNum;

			var testConsolCost = newTestObjectCreator.CreateConsolCost(apInvoice, consol, CC1, consolCostAmount, TestObjectCreator.Creditor1);
			testConsolCost.E6_PlaceOfSupply = fixedPlaceOfSupply;
			testConsolCost.E6_AT_TaxRate = taxRate?.PK ?? newTestObjectCreator.GSTFREE1.PK;
			testConsolCost.IsFinal = isCostFinal;
			testConsolCost.E6_ApportionmentMethod = "MAN";

			SetApportionedAmountFPOSAndTaxRate(testConsolCost,
				shipment1, shipment2, shipment3,
				shipment1Amount, shipment2Amount, shipment3Amount, fixedPlaceOfSupply, taxRate);

			if (cost != null)
			{
				testConsolCost.RelatedConsolCostPK = cost.PK;

				var appCharge1 = testConsolCost.ApportionmentCharges.FindChargeForJob(shipment1);
				var appCharge2 = testConsolCost.ApportionmentCharges.FindChargeForJob(shipment2);
				var appCharge3 = testConsolCost.ApportionmentCharges.FindChargeForJob(shipment3);

				appCharge1.RelatedApportionChargeFromDB = cost.ApportionmentCharges.FindChargeForJob(shipment1);
				appCharge2.RelatedApportionChargeFromDB = cost.ApportionmentCharges.FindChargeForJob(shipment2);
				appCharge3.RelatedApportionChargeFromDB = cost.ApportionmentCharges.FindChargeForJob(shipment3);
			}

			apInvoice.ImportAllApportionmentsFromCosting();

			return apInvoice;
		}

		APCreditNote CreateCreditNoteByImportingFromConsolCost(BusinessObjectFactory newFactory, ZString transactionNum,
			ForwardingConsol consol, ZDecimal consolCostAmount, RefCurrency currency, ZDecimal exchangeRate, bool isCostFinal,
			ForwardingShipment shipment1, ForwardingShipment shipment2, ForwardingShipment shipment3,
			ZDecimal shipment1Amount, ZDecimal shipment2Amount, ZDecimal shipment3Amount,
			JobConsolCost cost = null)
		{
			var newTestObjectCreator = new TestObjectCreator(newFactory);

			var apCreditNote = newTestObjectCreator.CreateAPCreditNote(transactionNum, TestObjectCreator.Creditor1, currency, exchangeRate, "Credit Note Desc");
			apCreditNote.SubmittedFromInvoicingForm = true;

			var testConsolCost = newTestObjectCreator.CreateConsolCost(apCreditNote, consol, CC1, consolCostAmount, TestObjectCreator.Creditor1);
			testConsolCost.E6_AT_TaxRate = newTestObjectCreator.GSTFREE1.PK;
			testConsolCost.IsFinal = isCostFinal;
			testConsolCost.E6_ApportionmentMethod = "MAN";

			SetApportionedAmount(testConsolCost,
				shipment1, shipment2, shipment3,
				shipment1Amount, shipment2Amount, shipment3Amount);

			if (cost != null)
			{
				testConsolCost.RelatedConsolCostPK = cost.PK;

				var appCharge1 = testConsolCost.ApportionmentCharges.FindChargeForJob(shipment1);
				var appCharge2 = testConsolCost.ApportionmentCharges.FindChargeForJob(shipment2);
				var appCharge3 = testConsolCost.ApportionmentCharges.FindChargeForJob(shipment3);

				appCharge1.RelatedApportionChargeFromDB = cost.ApportionmentCharges.FindChargeForJob(shipment1);
				appCharge2.RelatedApportionChargeFromDB = cost.ApportionmentCharges.FindChargeForJob(shipment2);
				appCharge3.RelatedApportionChargeFromDB = cost.ApportionmentCharges.FindChargeForJob(shipment3);
			}

			apCreditNote.ImportAllApportionmentsFromCosting();

			return apCreditNote;
		}

		void SetApportionedAmount(JobConsolCost pcost,
			ForwardingShipment shipment1, ForwardingShipment shipment2, ForwardingShipment shipment3,
			ZDecimal amount1, ZDecimal amount2, ZDecimal amount3)
		{
			SetApportionedAmountFPOSAndTaxRate(pcost, shipment1, shipment2, shipment3, amount1, amount2, amount3, ZString.Empty, null);
		}

		void SetApportionedAmountFPOSAndTaxRate(JobConsolCost pcost,
			ForwardingShipment shipment1, ForwardingShipment shipment2, ForwardingShipment shipment3,
			ZDecimal amount1, ZDecimal amount2, ZDecimal amount3, ZString fixedPlaceOfSupply, AccTaxRate taxRate)
		{
			Action<ForwardingShipment, ZDecimal> setShipmentValue = (shipment, amount) =>
			{
				if (shipment != null)
				{
					var shipmentCharge = pcost.ApportionmentCharges.FindChargeForJob(shipment);
					shipmentCharge.JR_RX_NKSellCurrency = shipmentCharge.JR_RX_NKCostCurrency;
					shipmentCharge.UpdateRevenueExchangeRate();
					shipmentCharge.RevenueExchangeRate?.SetBuyRate_ForTestOnly(shipmentCharge.JR_OSCostExRate);
					shipmentCharge.JR_OSCostAmt = shipmentCharge.JR_OSSellAmt = amount;
					shipmentCharge.JR_LocalSellAmt = shipmentCharge.JR_LocalCostAmt;
				}
			};

			pcost.E6_PlaceOfSupply = fixedPlaceOfSupply;
			pcost.E6_AT_TaxRate = taxRate?.PK ?? TestObjectCreator.GSTFREE1.PK;
			setShipmentValue(shipment1, amount1);
			setShipmentValue(shipment2, amount2);
			setShipmentValue(shipment3, amount3);
		}

		void SetInvoiceLineToFinal(APInvoiceLine line, bool isFinal = true)
		{
			using (line.StopChangingConsolRelatedLinesSuspender.GetSuspender())
			{
				line.AL_IsFinalCharge = isFinal;
			}
		}

		void AssertApportionJobCharge(JobCharge charge, ExpectedValueWithMessage<ZGuid> expectedCreditorPK, ExpectedValueWithMessage<ZString> expectedCostCurrency, ExpectedValueWithMessage<decimal> expectedCostExchnageRate, ExpectedValueWithMessage<decimal> expectedLocalCostAmount, ExpectedValueWithMessage<decimal> expectedOSCostAmount, ExpectedValueWithMessage<ZString> expectedSellCurrency, ExpectedValueWithMessage<decimal> expectedSellExchnageRate, ExpectedValueWithMessage<decimal> expectedLocalSellAmount, ExpectedValueWithMessage<decimal> expectedOSSellAmount, ExpectedValueWithMessage<bool> expectedCostPosted, ExpectedValueWithMessage<ZGuid> jR_E6, ExpectedValueWithMessage<string> fixedPlaceOfSupply, ExpectedValueWithMessage<string> fixedPlaceOfSupplyType, ExpectedValueWithMessage<ZGuid> taxRate)
		{
			AssertEquals(GetAssertionMessage(jR_E6.AssertionMessage, "JR_E6"), jR_E6.ExpectedValue, charge.JR_E6);
