		}

		void AssertJobCharge(JobCharge charge, ExpectedValueWithMessage<ZGuid> expectedCreditorPK, ExpectedValueWithMessage<ZString> expectedCostCurrency, ExpectedValueWithMessage<decimal> expectedCostExchnageRate, ExpectedValueWithMessage<decimal> expectedLocalCostAmount, ExpectedValueWithMessage<decimal> expectedOSCostAmount, ExpectedValueWithMessage<ZString> expectedSellCurrency, ExpectedValueWithMessage<decimal> expectedSellExchnageRate, ExpectedValueWithMessage<decimal> expectedLocalSellAmount, ExpectedValueWithMessage<decimal> expectedOSSellAmount, ExpectedValueWithMessage<bool> expectedCostPosted, ExpectedValueWithMessage<ZString> fixedPlaceOfSupply, ExpectedValueWithMessage<ZString> fixedPlaceOfSupplyType, ExpectedValueWithMessage<ZGuid> taxRate)
