		void AssertJobCharge(JobCharge charge, ExpectedValueWithMessage<ZGuid> expectedCreditorPK, ExpectedValueWithMessage<ZString> expectedCostCurrency, ExpectedValueWithMessage<decimal> expectedCostExchnageRate, ExpectedValueWithMessage<decimal> expectedLocalCostAmount, ExpectedValueWithMessage<decimal> expectedOSCostAmount, ExpectedValueWithMessage<ZString> expectedSellCurrency, ExpectedValueWithMessage<decimal> expectedSellExchnageRate, ExpectedValueWithMessage<decimal> expectedLocalSellAmount, ExpectedValueWithMessage<decimal> expectedOSSellAmount, ExpectedValueWithMessage<bool> expectedCostPosted)
		{
			AssertEquals(GetAssertionMessage(expectedCreditorPK.AssertionMessage, "Creditor"), expectedCreditorPK.ExpectedValue, charge.JR_OH_CostAccount);
			AssertJobCharge(charge, expectedCostCurrency, expectedCostExchnageRate, expectedLocalCostAmount, expectedOSCostAmount, expectedSellCurrency, expectedSellExchnageRate, expectedLocalSellAmount, expectedOSSellAmount, expectedCostPosted);
		}

		void AssertJobCharge(JobCharge charge, ExpectedValueWithMessage<ZString> expectedCostCurrency, ExpectedValueWithMessage<decimal> expectedCostExchangeRate, ExpectedValueWithMessage<decimal> expectedLocalCostAmount, ExpectedValueWithMessage<decimal> expectedOSCostAmount, ExpectedValueWithMessage<ZString> expectedSellCurrency, ExpectedValueWithMessage<decimal> expectedSellExchnageRate, ExpectedValueWithMessage<decimal> expectedLocalSellAmount, ExpectedValueWithMessage<decimal> expectedOSSellAmount, ExpectedValueWithMessage<bool> expectedCostPosted)
		{
			AssertEquals(GetAssertionMessage(expectedCostCurrency.AssertionMessage, "Cost Currency"), expectedCostCurrency.ExpectedValue, charge.JR_RX_NKCostCurrency);
			AssertCloseEnough(GetAssertionMessage(expectedCostExchangeRate.AssertionMessage, "Cost Exchange Rate"), (int)(expectedCostExchangeRate.ExpectedValue * 10000), (int)(charge.JR_OSCostExRate * 10000));
			AssertCloseEnough(GetAssertionMessage(expectedLocalCostAmount.AssertionMessage, "Local Cost Amount"), (int)(expectedLocalCostAmount.ExpectedValue * 100), (int)(charge.JR_LocalCostAmt * 100));
			AssertEquals(GetAssertionMessage(expectedOSCostAmount.AssertionMessage, "OS Cost Amount"), (int)(expectedOSCostAmount.ExpectedValue * 100), (int)(charge.JR_OSCostAmt * 100));

			AssertEquals(GetAssertionMessage(expectedSellCurrency.AssertionMessage, "Sell Currency"), expectedSellCurrency.ExpectedValue, charge.JR_RX_NKSellCurrency);
			AssertEquals(GetAssertionMessage(expectedSellExchnageRate.AssertionMessage, "Sell Exchange Rate"), expectedSellExchnageRate.ExpectedValue, charge.JR_OSSellExRate);
			AssertEquals(GetAssertionMessage(expectedLocalSellAmount.AssertionMessage, "Local Sell Amount"), expectedLocalSellAmount.ExpectedValue, charge.JR_LocalSellAmt);
			AssertEquals(GetAssertionMessage(expectedOSSellAmount.AssertionMessage, "OS Sell Amount"), expectedOSSellAmount.ExpectedValue, charge.JR_OSSellAmt);

			AssertEquals(GetAssertionMessage(expectedCostPosted.AssertionMessage, "IsCostPosted"), expectedCostPosted.ExpectedValue, charge.IsCostPosted);
			AssertEquals("IsRevenuePosted", false, charge.IsRevenuePosted);
		}

		ForwardingConsol CreateConsolWithConsolCostWithSameChargeCode()
		{
			var dep = Factory.Load<GlbDepartment>(Env.CurrentDepartment.PK);
			dep.GE_Misc = false;
			Factory.Save();

			var fRT = TestObjectCreator.CC1;
			var creditor1 = TestObjectCreator.AALSHI;
			var creditor2 = TestObjectCreator.ABIGAS;

			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			consol.Shipments.AddNew();
			consol.Shipments.AddNew();
			consol.Shipments.AddNew();

			var appListing = new ApportionmentListing(Factory, consol);
			var consolCost1 = TestObjectCreator.CreateConsolCost(consol, fRT, 300, creditor1, "SHP", appListing);
			var consolCost2 = TestObjectCreator.CreateConsolCost(consol, fRT, 600, creditor2, "SHP", appListing);
			var consolCost3 = TestObjectCreator.CreateConsolCost(consol, fRT, 900, null, "SHP", appListing);

			Factory.Save();

			foreach (ForwardingShipment shipment in consol.Shipments)
			{
				var shipmentJob = new Job.Loader(shipment).TryLoadOrCreateWithoutMutexForTestOnly();
				AssertEquals(3, shipmentJob.Charges.Count);
				var charges = shipmentJob.Charges.ToArray<Charge>();

				AssertChargesContainsCharge(charges, fRT.PK, creditor1.PK, "AUD", 1m, 100m, 100m, false);
				AssertChargesContainsCharge(charges, fRT.PK, creditor2.PK, "AUD", 1m, 200m, 200m, false);
				AssertChargesContainsCharge(charges, fRT.PK, ZGuid.Empty, "AUD", 1m, 300m, 300m, false);
			}

			Factory.Save();

			return consol;
		}

		void AssertConsolCost(JobConsolCost cost, ExpectedValueWithMessage<string> expectedCostCurrency, ExpectedValueWithMessage<decimal> expectedCostExchnageRate, ExpectedValueWithMessage<decimal> expectedLocalCostAmount, ExpectedValueWithMessage<decimal> expectedOSCostAmount, ExpectedValueWithMessage<bool> expectedCostPosted, ExpectedValueWithMessage<string> expectedFixedPlaceOfSupply, ExpectedValueWithMessage<string> expectedFixedPlaceOfSupplyType, ExpectedValueWithMessage<ZGuid> expectedTaxRate)
		{
			AssertConsolCost(cost, expectedCostCurrency, expectedCostExchnageRate, expectedLocalCostAmount, expectedOSCostAmount, expectedCostPosted);
			AssertEquals(GetAssertionMessage(expectedCostCurrency.AssertionMessage, "Place of Supply"), expectedFixedPlaceOfSupply.ExpectedValue, cost.E6_PlaceOfSupply);
			AssertEquals(GetAssertionMessage(expectedCostCurrency.AssertionMessage, "Place of Supply Type"), expectedFixedPlaceOfSupplyType.ExpectedValue, cost.E6_PlaceOfSupplyType);
			AssertEquals(GetAssertionMessage(expectedCostCurrency.AssertionMessage, "Tax Rate"), expectedTaxRate.ExpectedValue, cost.E6_AT_TaxRate);
		}

		void AssertConsolCost(JobConsolCost cost, ExpectedValueWithMessage<string> expectedCostCurrency, ExpectedValueWithMessage<decimal> expectedCostExchangeRate, ExpectedValueWithMessage<decimal> expectedLocalCostAmount, ExpectedValueWithMessage<decimal> expectedOSCostAmount, ExpectedValueWithMessage<bool> expectedCostPosted)
		{
			AssertEquals(GetAssertionMessage(expectedCostCurrency.AssertionMessage, "Cost Currency"), expectedCostCurrency.ExpectedValue, cost.E6_RX_NKCurrency);
			AssertEquals(GetAssertionMessage(expectedCostExchangeRate.AssertionMessage, "Cost Exchange Rate"), expectedCostExchangeRate.ExpectedValue, cost.E6_ExchangeRate);
			AssertEquals(GetAssertionMessage(expectedLocalCostAmount.AssertionMessage, "Local Cost Amount"), expectedLocalCostAmount.ExpectedValue, cost.E6_LocalCostAmount);
			AssertEquals(GetAssertionMessage(expectedOSCostAmount.AssertionMessage, "OS Cost Amount"), expectedOSCostAmount.ExpectedValue, cost.E6_OSCostAmount);
			AssertEquals(GetAssertionMessage(expectedCostPosted.AssertionMessage, "IsCostPosted"), expectedCostPosted.ExpectedValue, cost.IsPosted);
		}

		void AssertConsolCost(JobConsolCost consolCost, AccChargeCode chargeCode, ZDecimal oSCostAmount, OrgHeader creditor, ZBool isPosted,
			ZString currency, ZDecimal exRate, ZDecimal localCostAmount)
		{
			AssertConsolCostWithAssertionMessage(consolCost, chargeCode.PK, oSCostAmount, (creditor?.PK ?? ZGuid.Empty), isPosted, currency, exRate, localCostAmount);
		}

		void AssertConsolCostWithAssertionMessage(JobConsolCost consolCost, ExpectedValueWithMessage<ZGuid> chargeCodePK, ExpectedValueWithMessage<ZDecimal> oSCostAmount, ExpectedValueWithMessage<ZGuid> creditorPK, ExpectedValueWithMessage<ZBool> isPosted,
			ExpectedValueWithMessage<ZString> currency, ExpectedValueWithMessage<ZDecimal> exRate, ExpectedValueWithMessage<ZDecimal> localCostAmount)
		{
			AssertConsolCostWithAssertionMessage(consolCost, chargeCodePK, oSCostAmount, creditorPK, isPosted);
			AssertEquals(GetAssertionMessage(currency.AssertionMessage, consolCost.E6_RX_NKCurrencyInfo.HumanReadableName), currency.ExpectedValue, consolCost.E6_RX_NKCurrency);
			AssertEquals(GetAssertionMessage(exRate.AssertionMessage, consolCost.E6_ExchangeRateInfo.HumanReadableName), exRate.ExpectedValue, consolCost.E6_ExchangeRate);
			AssertEquals(GetAssertionMessage(localCostAmount.AssertionMessage, consolCost.E6_LocalCostAmountInfo.HumanReadableName), localCostAmount.ExpectedValue, consolCost.E6_LocalCostAmount);
		}

		void AssertConsolCost(JobConsolCost consolCost, AccChargeCode chargeCode, ZDecimal oSCostAmount, OrgHeader creditor, ZBool isPosted)
		{
			AssertConsolCostWithAssertionMessage(consolCost, chargeCode.PK, oSCostAmount, creditor?.PK ?? ZGuid.Empty, isPosted);
		}

		void AssertConsolCostWithAssertionMessage(JobConsolCost consolCost, ExpectedValueWithMessage<ZGuid> chargeCodePK, ExpectedValueWithMessage<ZDecimal> oSCostAmount, ExpectedValueWithMessage<ZGuid> creditorPK, ExpectedValueWithMessage<ZBool> isPosted)
		{
			AssertEquals(GetAssertionMessage(chargeCodePK.AssertionMessage, consolCost.E6_AC_ChargeCodeInfo.HumanReadableName), chargeCodePK.ExpectedValue, consolCost.E6_AC_ChargeCode);
			AssertEquals(GetAssertionMessage(oSCostAmount.AssertionMessage, consolCost.E6_OSCostAmountInfo.HumanReadableName), oSCostAmount.ExpectedValue, consolCost.E6_OSCostAmount);
			AssertEquals(GetAssertionMessage(creditorPK.AssertionMessage, consolCost.E6_OH_CreditorInfo.HumanReadableName), creditorPK.ExpectedValue, consolCost.Creditor?.PK ?? ZGuid.Empty);
			AssertEquals(GetAssertionMessage(isPosted.AssertionMessage, "Is Cost Posted"), isPosted.ExpectedValue, consolCost.IsPosted);
		}

		string GetAssertionMessage(string assertionMessage, string defaultAssertionMessage) => !string.IsNullOrEmpty(assertionMessage) ? assertionMessage : defaultAssertionMessage;

