		class ExpectedValueWithMessage<T>
		{
			public T ExpectedValue { get; set; }

			public string AssertionMessage { get; set; }

			public static implicit operator ExpectedValueWithMessage<T>(T b) =>
				new ExpectedValueWithMessage<T> { ExpectedValue = b, AssertionMessage = string.Empty };
