	public class TransactionLineJobChargeTransformerTestForUATransactions : TransactionLineJobChargeTransformerTest
	{
		[SuspendToTestReportJobChargeIsChangedByDifferentCompany]/*Accounting objects, such as JobCharge, need to be processed under the correct company context. If you want to process many companies, you need to do that one by one*/
		[TestDate(2013, 9, 20, 12, 32, 00)]
		public void TestApprovedFromOtherCompany()
		{
			Job job1 = CreateJob("Z00001000", LocalClient, 0M, null, 0M);   //5M - CFX get changed when we change branch and causes factory saving problem.
																			//For it does not really matter for this particular test case, just set it to 0m
			CreateExchangeRate(job1, USD, 1.23M);
			Factory.Save();

			var invoice = CreateAPInvoice("Z1000", Creditor1, USD, 1.230012M, "Invoice Z1000");

			var line1 = CreateAPInvoiceLine(invoice, job1, CC1, USD, 1.23M, "Charge Code 1", 100M, true);
			line1.AL_LineType = new AccTransactionLinesCompatibilityMatrixTestHelper().GetCompatibleLineType(invoice.AH_Ledger, invoice.AH_TransactionType);
			Charge charge1_1 = CreateCharge(job1, CC1, "Charge Code 1", USD, 100M, Creditor1, USD, 100M, LocalClient);
			charge1_1.JR_AL_APLine = line1.PK;

			invoice.Factory.Save();

			if (invoice.AH_Ledger == ZArchitecture.Core.LedgerTypes.UnapprovedPayableTransactions)
			{
				GlbCompany uSCompany = TestObjectCreator.CreateNewCompany("USC", "US");
				uSCompany.GC_IsReciprocal = true;
				GlbBranch uSBranch = TestObjectCreator.CreateNewBranch(uSCompany, "USB");
				Factory.Save();

				UnapprovedTransactionConverter converter = new UnapprovedTransactionConverter(Factory);
				invoice = (APInvoice)converter.ConvertToAP(invoice, false);

				using (new TemporaryUserContext() { BranchPK = uSBranch.PK.ToGuid() }.Set())
				{
					((Job)invoice.Job).ExchangeRates[0].InvokeChanged_ForTestsOnly();
					invoice.Factory.Save();
				}
			}

			AssertEquals("Charge Count", 1, job1.Charges.Count);
			AssertCostChargeValues(job1.Charges[0], CC1, "Charge Code 1", Creditor1, true, USD, 1.230012m, 100m, 81.3m, GST1, 10M, WHTFREE1, 0M,
				"Z1000", ZDateTime.Today, ZDateTime.Today.AddDays(30));
		}

		[TestDate(2016, 04, 04, 12, 00, 00)]
		public void TestApprovingOtherCompanyConsolAPInvoiceWithSameChargeCodeDoesNotOverrideExistingConsolCost()
		{
			var converter = new UnapprovedTransactionConverter(Factory);

			TestObjectCreator.CreateBranch("PRX", GlbCompany.CurrentCompany, TestObjectCreator.Agent);

			SetupDifferentCompanyAndBranch();
			TestObjectCreator.Agent.CompanyData.SetARTaxApplicable(true);
			TestObjectCreator.Agent.CompanyData.SetAPTaxApplicable(true);
			Factory.Save();

			var chargeCode1 = TestObjectCreator.CreateChargeCode("CC1", "Charge Code 1", Core.Constants.ChargeType.Margin, 100, TestObjectCreator.GST1, TestObjectCreator.WHTFREE1);
			var chargeCode2 = TestObjectCreator.CreateChargeCode("CC1", "Charge Code 1", Core.Constants.ChargeType.Margin, 100, TestObjectCreator.GST1, TestObjectCreator.WHTFREE1, differentCompany);
			Factory.Save();

			ExchangeRateReader.GetReaderInstance().ClearCache();

			var consol = Factory.New<ForwardingConsol>();
			consol.JK_UniqueConsignRef = "C00001000";
			consol.JK_TransportMode = "AIR";
			var forwardingShipment1 = consol.Shipments.AddNew();
			forwardingShipment1.JS_UniqueConsignRef = "S00002000";

			var apps = new ApportionmentListing(Factory, consol);
			var cost = apps.CostsCollection.TryAddNew();
			cost.E6_AC_ChargeCode = chargeCode1.PK;
			cost.E6_ApportionmentMethod = "SHP";
			cost.E6_OH_Creditor = TestObjectCreator.LocalClient.PK;
			cost.E6_ApportionToRelatedShipments = true;
			cost.E6_OSCostAmount = 2000.00m;
			Factory.Save();

			InvoicingBase transaction = null;
			var factory2 = new BusinessObjectFactory();
			using (Env.SetTemporaryUserContext(GlbStaff.CurrentUser.GS_LoginName, differentBranch.PK.ToGuid(), GlbDepartment.CurrentDepartment.PK.ToGuid()))
			{
				var agentInOtherCompany = factory2.Load<OrgHeader>(TestObjectCreator.Agent.PK);
				agentInOtherCompany.CompanyData.OB_IsDebtor = true;
				agentInOtherCompany.CompanyData.SetARTaxApplicable(true);
				agentInOtherCompany.CompanyData.SetAPTaxApplicable(true);
				GlbBranch.CurrentBranch.OrgProxy.CompanyData.SetARTaxApplicable(true);
				GlbBranch.CurrentBranch.OrgProxy.CompanyData.SetAPTaxApplicable(true);

				var consolInOtherCompany = factory2.Load<ForwardingConsol>(consol.PK);
				var job = createJob(factory2, "J00001000", differentBranch.PK, GlbDepartment.CurrentDepartment.PK.ToGuid(), factory2.NewWithValidTestData<OrgHeader>(), agentInOtherCompany);
				job.JH_ParentID = consolInOtherCompany.Shipments[0].PK;
				job.JH_ParentTableCode = "JS";

				var appsInOtherCompanyConsol = consolInOtherCompany.GetApportionments();
				var costsInOtherCompanyConsol = appsInOtherCompanyConsol.CostsCollection.TryAddNew();
				costsInOtherCompanyConsol.E6_AC_ChargeCode = chargeCode2.PK;
				costsInOtherCompanyConsol.E6_ApportionmentMethod = "SHP";
				costsInOtherCompanyConsol.E6_OH_Creditor = agentInOtherCompany.PK;
				costsInOtherCompanyConsol.E6_ApportionToRelatedShipments = true;
				costsInOtherCompanyConsol.E6_OSCostAmount = 3000.00m;
				factory2.Save();

				AssertEquals("Precondition: Cost is apportioned to the shipment job", 1, job.Charges.Count);
				job.Charges[0].JR_OH_SellAccount = agentInOtherCompany.PK;
				factory2.Save();

				var transactionCreator = new ConsolInvoicingPostManager(Factory, new[] { job }, consolInOtherCompany, appsInOtherCompanyConsol);
				var transactions = transactionCreator.CreateTransactions(JobInvoicingPostingOption.Agent);
				AssertEquals("Precondition: One AR transaction should have been created", 1, transactions.ARTransactionsCount);
				InvoicingBase[] arInvoices = transactions.GetAllARInvoicesAndCreditNotes();
				transaction = arInvoices[0];
				factory2.Save();
			}

			var invoiceInCurrentCompany = Factory.Load<ARInvoice>(transaction.PK);
			AssertNotNull("Precondition: Should found the invoice", invoiceInCurrentCompany);
			var convertedAPInvoice = converter.ConvertToAP(invoiceInCurrentCompany, false);
			convertedAPInvoice.AH_OH = TestObjectCreator.Agent.PK;
			convertedAPInvoice.Factory.Save();

			var costingBO = (BusinessObject)consol;
			costingBO.Factory.ClearCachedValue<ApportionmentListing>("ApportionmentListing|" + costingBO.PK.ToString());

			var costsAfterApprovingOtherCompanyInvoice = consol.GetApportionments().CostsCollection;
			AssertEquals("Approving other company consol APInvoice with same charge code should not override the existing cost as creditor is different", 2, costsAfterApprovingOtherCompanyInvoice.Count);
		}

