		public void SetupDifferentCompanyAndBranch()
		{
			differentCompany = TestObjectCreator.CreateNewCompany("ABC", "CN");
			differentBranch = TestObjectCreator.CreateNewBranch(differentCompany, "AB1");

			var differentCompanyOrgProxy = TestObjectCreator.CreateOrgHeader("ORGPROXYC", true, true);
			differentCompanyOrgProxy.OH_RL_NKClosestPort = differentBranch.GB_RL_NKHomePort;
			differentCompany.GC_OH_OrgProxy = differentCompanyOrgProxy.PK;

			var differentBranchOrgProxy = TestObjectCreator.CreateOrgHeader("ORGPROXYB", true, true);
			differentBranchOrgProxy.OH_RL_NKClosestPort = differentBranch.GB_RL_NKHomePort;
			differentBranch.GB_OH_OrgProxy = differentBranchOrgProxy.PK;
		}

