		protected void SetEditableFieldsForInvoice(InvoicingBase invoice,
			DateTime postDate, DateTime invoiceDate, DateTime dueDate, DateTime documentReceivedDate, string transactionNum)
		{
			invoice.AH_PostDate = postDate;
			invoice.AH_InvoiceDate = invoiceDate;
			invoice.AH_DocumentReceivedDate = documentReceivedDate;
			invoice.AH_DueDate = dueDate;
			invoice.AH_TransactionNum = transactionNum;
		}

		protected void TestEditingOfEditableFieldsBeforeApprovalOfJobRelatedInvoiceBase(Type invoiceType)
		{
			// --Arrange
			ForwardingShipment shipment = TestObjectCreator.CreateShipment("S00001234");
			var job = TestObjectCreator.CreateJob(shipment);
			var invoice = TestObjectCreator.CreateInvoice(invoiceType, TestObjectCreator.AUD, 1, TestObjectCreator.AALSHI);

			SetEditableFieldsForInvoice(invoice, new DateTime(2012, 06, 29), new DateTime(2012, 06, 29), new DateTime(2012, 07, 06), new DateTime(2012, 06, 29), "QXR178");
			invoice.SubmittedFromInvoicingForm = true;

			var invoiceLine = TestObjectCreator.CreateInvoiceLine(invoice, TestObjectCreator.AUD, 1, 0);
			invoiceLine.AL_AC = TestObjectCreator.CC1.PK;
			invoiceLine.AL_JH = job.PK;
			invoiceLine.AL_OSExTaxAmount = 20m;

			Factory.Save();

			// --Act
			BusinessObjectFactory factory2 = new BusinessObjectFactory();
			var invoiceReloaded = factory2.Load<InvoicingBase>(invoice.PK);
			var invoiceConverted = new UnapprovedTransactionConverter(factory2).ConvertToAP(invoiceReloaded, false);
			SetEditableFieldsForInvoice(invoiceConverted, new DateTime(2012, 06, 28), new DateTime(2012, 06, 27), new DateTime(2012, 07, 04), new DateTime(2012, 06, 26), "QXR183");
			invoiceConverted.Factory.Save();

			// --Assert
			BusinessObjectFactory factory3 = new BusinessObjectFactory();
			var assertInvoice = factory3.Load<InvoicingBase>(invoiceConverted.PK);
			var assertJob = factory3.Load<Job>(assertInvoice.Lines[0].AL_JH);
			var assertCharge = assertJob.Charges[0];

			AssertEquals(new DateTime(2012, 06, 27), assertCharge.JR_APInvoiceDate);
			AssertEquals(new DateTime(2012, 06, 26), assertCharge.JR_APDocumentReceivedDate);
			AssertEquals(new DateTime(2012, 07, 04), assertCharge.JR_PaymentDate);
			AssertEquals("QXR183", assertCharge.JR_APInvoiceNum);
		}

		protected void TestEditingOfEditableFieldsBeforeApprovalOfJobRelatedInvoiceBaseWithConsol(Type invoiceType)
		{
			// --Arrange
			var factory = new BusinessObjectFactory();
			var creator = new TestObjectCreator(factory);
			var consol = creator.CreateConsol("AUSYD", "NZAKL", "C001");
			var shipment = creator.CreateShipment("S0001", consol);
			factory.Save();

			var factory1 = new BusinessObjectFactory();
			var invoice = (InvoicingBase)factory1.NewWithValidTestData(invoiceType);
			invoice.SubmittedFromInvoicingForm = true;
			SetEditableFieldsForInvoice(invoice, new DateTime(2012, 06, 29), new DateTime(2012, 06, 29), new DateTime(2012, 07, 06), new DateTime(2012, 06, 29), "QXR178");
			JobConsolCost cost = invoice.ConsolCosting.ConsolCosts.TryAddNewForConsol_ForTestOnly(consol);
			cost.E6_AC_ChargeCode = creator.CC1.PK;
			cost.E6_OSCostAmount = 300m;
			invoice.ImportAllApportionmentsFromCosting();
			factory1.Save();

			var newCostShouldNotBeUsedForApproving = TestObjectCreator.CreateConsolCost(consol, cost.ChargeCode, cost.E6_OSCostAmount);
			newCostShouldNotBeUsedForApproving.Factory.Save();

			// --Act
			BusinessObjectFactory factory2 = new BusinessObjectFactory();
			InvoicingBase converted = new UnapprovedTransactionConverter(factory2).ConvertToAP(invoice, false);
			SetEditableFieldsForInvoice(converted, new DateTime(2012, 06, 28), new DateTime(2012, 06, 27), new DateTime(2012, 07, 04), new DateTime(2012, 06, 26), "QXR183");
			converted.Factory.Save();

			// --Assert
			try
			{
				BusinessObjectFactory factory3 = new BusinessObjectFactory();
				var assertInvoice = factory3.Load<InvoicingBase>(converted.PK);
				var assertJob1 = factory3.Load<Job>(converted.Lines[0].AL_JH);
				var assertCharge1 = assertJob1.Charges[0];
				var consolCost = factory3.Load<JobConsolCost>(assertCharge1.JR_E6);
				AssertEquals(new DateTime(2012, 06, 27), assertCharge1.JR_APInvoiceDate);
				AssertEquals(new DateTime(2012, 06, 26), assertCharge1.JR_APDocumentReceivedDate);
				AssertEquals(new DateTime(2012, 07, 04), assertCharge1.JR_PaymentDate);
				AssertEquals("QXR183", assertCharge1.JR_APInvoiceNum);
				AssertEquals(new DateTime(2012, 06, 27), consolCost.E6_InvoiceDate);
				AssertEquals(new DateTime(2012, 06, 26), consolCost.E6_DocumentReceivedDate);
				AssertEquals(new DateTime(2012, 07, 04), consolCost.E6_PaymentDate);
				AssertEquals("QXR183", consolCost.E6_InvoiceNum);

				AssertEquals(ZDateTime.Empty, newCostShouldNotBeUsedForApproving.E6_InvoiceDate);
				AssertEquals(ZDateTime.Empty, newCostShouldNotBeUsedForApproving.E6_DocumentReceivedDate);
				AssertEquals(ZDateTime.Empty, newCostShouldNotBeUsedForApproving.E6_PaymentDate);
				AssertEquals("", newCostShouldNotBeUsedForApproving.E6_InvoiceNum);
			}
			finally
			{
				converted.ClearApportionmentJobMutexes();
			}
		}

		#endregion
	}
